window.__FITA_SUBS={"e1": [{"s": 17.887, "e": 19.802, "en": "I, Olivia Winfield Foxworth,", "ko": "나, 올리비아 윈필드 폭스워스는", "it": true}, {"s": 19.932, "e": 24.067, "en": "do declare this to be my last\nwill and testament.", "ko": "이것이 나의 마지막\n유언임을 선언한다", "it": true}, {"s": 24.154, "e": 27.07, "en": "Some may have an idea\nof who I was.", "ko": "누군가는 내가 어떤 사람이었는지\n안다고 생각할지도 모른다", "it": true}, {"s": 27.201, "e": 29.029, "en": "A wife. A mother.", "ko": "아내, 어머니", "it": true}, {"s": 29.116, "e": 31.074, "en": "The grandmother.", "ko": "할머니", "it": true}, {"s": 31.205, "e": 33.598, "en": "A monster.", "ko": "괴물", "it": true}, {"s": 33.685, "e": 36.775, "en": "I only ask that you withhold\nfinal judgment", "ko": "다만 최종 판단은\n미뤄 주길 바란다", "it": true}, {"s": 36.906, "e": 39.604, "en": "until you know the true story.", "ko": "진짜 이야기를\n알게 될 때까지", "it": true}, {"s": 39.735, "e": 43.739, "en": "And knowing the truth,\njudge me if you dare.", "ko": "그리고 진실을 안 뒤에도\n감히 나를 심판할 수 있다면 그리하라", "it": true}, {"s": 44.827, "e": 48.004, "en": "And so now at long last...", "ko": "그럼 이제 마침내...", "it": true}, {"s": 50.224, "e": 52.226, "en": "This is my story.", "ko": "내 이야기를 시작하겠다", "it": true}, {"s": 56.795, "e": 60.669, "en": "\"A seven letter word\nfor righting a wrong.\"", "ko": "\"잘못을 바로잡는 일,\n일곱 글자\"", "it": false}, {"s": 60.756, "e": 61.887, "en": "Correct.", "ko": "맞아요", "it": false}, {"s": 61.974, "e": 63.324, "en": "No.", "ko": "아니", "it": false}, {"s": 65.413, "e": 66.37, "en": "Revenge.", "ko": "복수", "it": false}, {"s": 67.85, "e": 68.851, "en": "That's it.", "ko": "그거야", "it": false}, {"s": 68.938, "e": 70.374, "en": "My mother always said", "ko": "어머니는 늘 말씀하셨지", "it": false}, {"s": 70.505, "e": 73.986, "en": "the only thing that takes longer\nthan forgiveness is revenge.", "ko": "용서보다 더 오래 걸리는 건\n복수뿐이라고", "it": false}, {"s": 74.117, "e": 76.467, "en": "And she was right,\nit's now made me late.", "ko": "옳은 말씀이었어\n덕분에 늦었네", "it": false}, {"s": 76.598, "e": 78.513, "en": "To be continued\nin the evening.", "ko": "나머지는\n저녁에 하자", "it": false}, {"s": 82.908, "e": 84.91, "en": "Yes, work.", "ko": "그래, 일하러", "it": true}, {"s": 84.997, "e": 87.783, "en": "It was unusual for a woman\nat the time.", "ko": "당시 여자로서는\n드문 일이었다", "it": true}, {"s": 103.755, "e": 104.539, "en": "You're late.", "ko": "늦었구나", "it": false}, {"s": 104.626, "e": 106.106, "en": "Sorry Father.", "ko": "죄송해요, 아버지", "it": false}, {"s": 106.193, "e": 110.11, "en": "I flagged inconsistencies\nbetween ports of entry and exit.", "ko": "입항과 출항 기록이\n안 맞는 부분을 표시해 뒀어요", "it": false}, {"s": 110.197, "e": 111.85, "en": "We should confirm our bid\nby tomorrow.", "ko": "입찰가는 내일까지\n확정해야 해요", "it": false}, {"s": 111.937, "e": 112.938, "en": "Oh, thank you, dear.", "ko": "그래, 고맙다", "it": false}, {"s": 113.025, "e": 114.114, "en": "And could you take a look\nat this?", "ko": "이것도 한번\n봐 주겠니?", "it": false}, {"s": 114.201, "e": 115.115, "en": "Mm-hmm.", "ko": "음", "it": false}, {"s": 118.77, "e": 121.077, "en": "Expansion into\nthe Mediterranean?", "ko": "지중해로 사업을\n넓히자고요?", "it": false}, {"s": 121.208, "e": 122.383, "en": "It's currently a war zone.", "ko": "지금은 전쟁터잖아요", "it": false}, {"s": 122.47, "e": 124.036, "en": "Wars end.", "ko": "전쟁은 끝나기 마련이지", "it": false}, {"s": 124.167, "e": 127.475, "en": "And when they do, there will\nbe opportunities.", "ko": "끝나고 나면\n기회가 생길 거다", "it": false}, {"s": 127.562, "e": 130.13, "en": "I'll read tonight and get back\nto you in the morning.", "ko": "오늘 밤에 읽고\n아침에 말씀드릴게요", "it": false}, {"s": 130.26, "e": 131.827, "en": "Perhaps you could read\nthis afternoon.", "ko": "오후에 읽어 보면\n어떻겠니?", "it": false}, {"s": 131.914, "e": 134.786, "en": "An associate from Virginia will\nbe dining at the house tonight.", "ko": "버지니아에서 온 동업자가\n오늘 저녁 집에서 식사를 한다", "it": false}, {"s": 134.873, "e": 138.486, "en": "It's his proposition.\nI'd like you to join us.", "ko": "그 사람이 낸 제안이야\n너도 함께했으면 좋겠구나", "it": false}, {"s": 138.573, "e": 140.14, "en": "Very well.", "ko": "알겠어요", "it": false}, {"s": 140.227, "e": 143.926, "en": "He happens to be... unattached.", "ko": "그 사람이 마침... 미혼이란다", "it": false}, {"s": 145.884, "e": 148.191, "en": "Am I wanted at dinner for\nmy professional perspective", "ko": "저를 저녁에 부르시는 게\n사업 관점 때문인가요", "it": false}, {"s": 148.278, "e": 151.02, "en": "or for another of your failed\nattempts at matchmaking?", "ko": "아니면 또 실패할\n중매 때문인가요?", "it": false}, {"s": 151.107, "e": 154.066, "en": "If your business acumen\nhappens to attract a suitor", "ko": "네 사업 수완에\n구혼자가 끌린다 해도", "it": false}, {"s": 154.197, "e": 155.242, "en": "it's no fault of mine.", "ko": "그건 내 잘못이 아니지", "it": false}, {"s": 155.372, "e": 157.2, "en": "But it never has before.", "ko": "그런 적은 한 번도 없었잖아요", "it": false}, {"s": 157.287, "e": 159.028, "en": "I think I'll dine\nin my room tonight.", "ko": "오늘 저녁은\n방에서 먹을래요", "it": false}, {"s": 159.115, "e": 160.856, "en": "Well, your loss.", "ko": "그럼 네 손해다", "it": false}, {"s": 160.986, "e": 163.685, "en": "One cannot lose something\none has never possessed.", "ko": "가져 본 적도 없는 걸\n잃을 수는 없죠", "it": false}, {"s": 163.772, "e": 166.514, "en": "He's a Foxworth.", "ko": "폭스워스 집안 사람이다", "it": false}, {"s": 166.601, "e": 169.952, "en": "Sole heir to the Foxworth\nmining fortune.", "ko": "폭스워스 광산 재벌의\n유일한 상속자지", "it": false}, {"s": 170.039, "e": 171.345, "en": "The Malcolm Foxworth?", "ko": "그 맬컴 폭스워스요?", "it": false}, {"s": 171.432, "e": 172.433, "en": "Yes.", "ko": "그래", "it": false}, {"s": 173.782, "e": 175.697, "en": "What would he want with me?", "ko": "그런 사람이\n저한테 무슨 볼일이 있겠어요?", "it": false}, {"s": 175.784, "e": 177.351, "en": "Olivia, darling.", "ko": "올리비아, 얘야", "it": false}, {"s": 177.438, "e": 179.44, "en": "Father, I'm fine.", "ko": "아버지, 전 괜찮아요", "it": false}, {"s": 179.57, "e": 181.181, "en": "I'm happy.", "ko": "행복해요", "it": false}, {"s": 181.268, "e": 184.488, "en": "The time for romance\nhas long passed me by.", "ko": "연애할 나이는\n진작 지났어요", "it": false}, {"s": 184.575, "e": 189.189, "en": "Olivia, your mother always\nwanted you to find a husband.", "ko": "네 어머니는 늘\n네가 남편감을 찾길 바랐다", "it": false}, {"s": 195.499, "e": 197.327, "en": "What time?", "ko": "몇 시죠?", "it": false}, {"s": 202.724, "e": 204.16, "en": "Olivia, my darling.", "ko": "올리비아, 우리 딸", "it": false}, {"s": 204.291, "e": 206.989, "en": "I'd like you to meet an\nassociate of mine from Virginia.", "ko": "버지니아에서 온\n내 동업자를 소개하마", "it": false}, {"s": 207.119, "e": 209.731, "en": "I'm proud to present my\ndaughter, Olivia Winfield.", "ko": "자랑스러운 내 딸\n올리비아 윈필드입니다", "it": false}, {"s": 209.818, "e": 213.865, "en": "Olivia,\nMr. Malcolm Neil Foxworth.", "ko": "올리비아, 이쪽은\n맬컴 닐 폭스워스 씨다", "it": false}, {"s": 225.486, "e": 226.574, "en": "Charmed, Miss Winfield.", "ko": "반갑습니다, 윈필드 양", "it": false}, {"s": 226.661, "e": 229.533, "en": "The feeling is quite mutual,\nI'm sure.", "ko": "저야말로\n반갑습니다", "it": false}, {"s": 232.362, "e": 234.408, "en": "Who would be calling\nat this hour?", "ko": "이 시간에\n누가 왔지?", "it": false}, {"s": 236.845, "e": 238.542, "en": "Mr. John Amos.", "ko": "존 에이머스 님이\n오셨습니다", "it": false}, {"s": 240.065, "e": 241.545, "en": "Cousin Amos.", "ko": "에이머스 오빠", "it": false}, {"s": 241.676, "e": 244.766, "en": "How good of you to join us,\nand on such short notice.", "ko": "급하게 연락했는데도\n와 줘서 고맙구나", "it": false}, {"s": 244.896, "e": 247.986, "en": "Amos, my boy.\nAlways good to see you.", "ko": "에이머스, 왔구나\n언제 봐도 반갑다", "it": false}, {"s": 248.117, "e": 252.556, "en": "Meet an associate of mine,\nMr. Malcolm Foxworth.", "ko": "인사하거라, 내 동업자\n맬컴 폭스워스 씨다", "it": false}, {"s": 252.643, "e": 254.341, "en": "How do you do?", "ko": "처음 뵙겠습니다", "it": false}, {"s": 254.471, "e": 256.43, "en": "Exceedingly well.", "ko": "아주 반갑소", "it": false}, {"s": 260.651, "e": 262.784, "en": "Bless us,\nO Heavenly Father,", "ko": "하늘에 계신 아버지\n저희를 축복하시고", "it": false}, {"s": 262.914, "e": 265.787, "en": "for these thy gifts which\nwe are about to receive.", "ko": "저희가 받을 이 은혜로운\n음식에 감사하나이다", "it": false}, {"s": 265.874, "e": 267.397, "en": "Amen.", "ko": "아멘", "it": false}, {"s": 270.313, "e": 272.533, "en": "Thank you, Amos.", "ko": "고맙다, 에이머스", "it": false}, {"s": 272.62, "e": 276.188, "en": "My cousin here is getting\nhis doctorate in theology.", "ko": "내 조카는 신학 박사\n과정을 밟고 있지요", "it": false}, {"s": 276.319, "e": 280.062, "en": "Are you a religious man\nyourself, Mr. Foxworth?", "ko": "폭스워스 씨도\n신앙이 깊으신가요?", "it": false}, {"s": 280.192, "e": 285.372, "en": "I believe the religion,\nmuch like wealth and emotion,", "ko": "종교라는 건\n재산이나 감정과 마찬가지로", "it": false}, {"s": 285.459, "e": 290.29, "en": "is food for personal thought,\nnot for the dinner table.", "ko": "혼자 생각할 거리지\n식탁에 올릴 화제는 아니오", "it": false}, {"s": 294.119, "e": 296.731, "en": "You keep a lovely home,\nMiss Winfield.", "ko": "집을 아름답게\n꾸리시는군요, 윈필드 양", "it": false}, {"s": 296.861, "e": 299.864, "en": "I am fortunate enough to live\nin a lovely home, Mr. Foxworth,", "ko": "운 좋게 아름다운 집에\n살고는 있지만", "it": false}, {"s": 299.995, "e": 301.91, "en": "but I do not keep it.", "ko": "집을 꾸리는 사람은\n제가 아니에요", "it": false}, {"s": 304.304, "e": 307.176, "en": "I work with my father\nat our office downtown.", "ko": "시내 사무실에서\n아버지와 일하거든요", "it": false}, {"s": 309.352, "e": 311.136, "en": "Keeping the books.", "ko": "장부를 맡고 있어요", "it": false}, {"s": 311.223, "e": 313.008, "en": "Keeping them from whom?", "ko": "누구 몰래 맡으시는 거요?", "it": false}, {"s": 316.316, "e": 320.537, "en": "Cousin Olivia and my uncle\nare partners in business.", "ko": "올리비아와 삼촌은\n동업자 사이예요", "it": false}, {"s": 320.624, "e": 323.148, "en": "God did not give me a son,", "ko": "하나님은 내게\n아들을 주지 않으셨지만", "it": false}, {"s": 323.235, "e": 326.717, "en": "but fortune has given me\nsomething far greater.", "ko": "운명은 그보다 훨씬\n귀한 걸 주었소", "it": false}, {"s": 326.804, "e": 328.328, "en": "Thank you, Father.", "ko": "고마워요, 아버지", "it": false}, {"s": 329.764, "e": 331.679, "en": "For how long do we have\nthe pleasure", "ko": "얼마나 오래", "it": false}, {"s": 331.766, "e": 333.202, "en": "of hosting you in our city?", "ko": "저희 도시에 머무르시나요?", "it": false}, {"s": 333.333, "e": 337.119, "en": "I return to Foxworth\nHall tomorrow.", "ko": "내일 폭스워스 저택으로\n돌아가오", "it": false}, {"s": 337.249, "e": 338.686, "en": "That is my home in Virginia.", "ko": "버지니아에 있는\n내 집이오", "it": false}, {"s": 338.773, "e": 340.34, "en": "How terribly sad.", "ko": "정말 아쉽네요", "it": false}, {"s": 341.819, "e": 343.473, "en": "For us all.", "ko": "모두에게요", "it": false}, {"s": 345.823, "e": 348.652, "en": "I suppose we should get\ndown to it then.", "ko": "그럼 슬슬\n본론으로 들어갈까요?", "it": false}, {"s": 348.739, "e": 351.786, "en": "You're here to discuss business,\nare you not?", "ko": "사업 얘기를 하러\n오신 거잖아요", "it": false}, {"s": 354.266, "e": 355.703, "en": "Are you actually suggesting", "ko": "정말로 상선 함대를", "it": false}, {"s": 355.833, "e": 358.053, "en": "purchasing the merchant\nmarine fleet?", "ko": "사들이자는\n말씀이세요?", "it": false}, {"s": 358.183, "e": 360.925, "en": "Once the war comes\nto an end, yes.", "ko": "전쟁이 끝나면, 그렇소", "it": false}, {"s": 361.012, "e": 363.058, "en": "Postwar economies\nquickly turn.", "ko": "전후 경제는\n빠르게 뒤집히지", "it": false}, {"s": 363.145, "e": 363.841, "en": "It's history.", "ko": "역사가 증명하오", "it": false}, {"s": 363.928, "e": 365.234, "en": "It's predatory.", "ko": "약탈이나 다름없어요", "it": false}, {"s": 365.321, "e": 367.105, "en": "Surely taking advantage\nof a nation", "ko": "상처를 치유해야 할\n나라의 약점을", "it": false}, {"s": 367.236, "e": 369.891, "en": "in need of healing\nisn't appropriate.", "ko": "이용하는 건\n옳지 않아요", "it": false}, {"s": 370.021, "e": 373.416, "en": "Healing is the business\nof nurses.", "ko": "치유는\n간호사의 일이고", "it": false}, {"s": 373.503, "e": 376.419, "en": "Business is the business\nof men.", "ko": "사업은\n남자의 일이오", "it": false}, {"s": 376.506, "e": 377.507, "en": "Perhaps today.", "ko": "지금은 그렇겠죠", "it": false}, {"s": 377.638, "e": 379.074, "en": "But when women get the vote,", "ko": "하지만 여자가\n투표권을 얻고 나면", "it": false}, {"s": 379.161, "e": 382.512, "en": "business will be the business of\nhe or she who is most qualified.", "ko": "사업은 가장 유능한 사람의 몫이\n될 거예요, 남자든 여자든", "it": false}, {"s": 382.599, "e": 385.689, "en": "And your qualifications exceed\nthose of my own?", "ko": "그럼 당신 자격이\n나보다 낫단 말이오?", "it": false}, {"s": 385.82, "e": 391.303, "en": "I would never be so presumptuous\nas I know so little of you.", "ko": "그렇게 주제넘진 않아요\n당신을 잘 모르니까요", "it": false}, {"s": 391.391, "e": 395.046, "en": "Well, perhaps we should endeavor\nto change that.", "ko": "그럼 그걸 바꿔\n보면 어떻겠소?", "it": false}, {"s": 398.18, "e": 400.4, "en": "May I call on you tomorrow?", "ko": "내일 찾아가도 되겠소?", "it": false}, {"s": 402.532, "e": 403.968, "en": "Have you forgotten\nthat you're returning", "ko": "잊으셨어요?\n내일 아침에", "it": false}, {"s": 404.055, "e": 407.494, "en": "to Foxworth Hall\nin the morning?", "ko": "폭스워스 저택으로\n돌아가신다면서요", "it": false}, {"s": 407.581, "e": 409.409, "en": "Well, plans can change.", "ko": "계획은 바뀔 수 있소", "it": false}, {"s": 412.455, "e": 416.416, "en": "Much like ideas.", "ko": "생각처럼 말이오", "it": false}, {"s": 416.546, "e": 418.418, "en": "Wouldn't you agree,\nMiss Winfield?", "ko": "그렇지 않소,\n윈필드 양?", "it": false}, {"s": 430.734, "e": 435.043, "en": "For the first time in\nmy life I could not read,", "ko": "난생처음으로\n책을 읽을 수가 없었다", "it": true}, {"s": 435.173, "e": 437.828, "en": "because for the first time\nthe romance in my real life", "ko": "난생처음으로\n현실의 사랑이", "it": true}, {"s": 437.915, "e": 440.918, "en": "eclipsed that of the stories\non the pages.", "ko": "책 속 이야기보다\n더 눈부셨기 때문이다", "it": true}, {"s": 454.018, "e": 456.325, "en": "Miss Winfield,\nyou look lovely.", "ko": "윈필드 양,\n아름답군요", "it": false}, {"s": 459.502, "e": 460.46, "en": "For you.", "ko": "당신 거요", "it": false}, {"s": 467.858, "e": 469.512, "en": "For your work.", "ko": "일에 쓰시라고", "it": false}, {"s": 469.643, "e": 473.647, "en": "Perhaps we could talk\nmore about what it is\nthat you do on a walk.", "ko": "당신이 하는 일에 대해\n걸으면서 더 얘기해 볼까요?", "it": false}, {"s": 475.17, "e": 477.651, "en": "With your permission,\nof course.", "ko": "물론 허락해 준다면", "it": false}, {"s": 477.738, "e": 479.783, "en": "Thank you for asking,\nMr. Foxworth.", "ko": "물어봐 주셔서 고마워요,\n폭스워스 씨", "it": false}, {"s": 479.87, "e": 483.526, "en": "But you do not need anyone's\npermission but my own.", "ko": "하지만 제 허락 말고는\n누구 허락도 필요 없어요", "it": false}, {"s": 483.613, "e": 485.441, "en": "And you have it.", "ko": "그리고 허락할게요", "it": false}, {"s": 489.314, "e": 492.796, "en": "So, what do people\nmake of it?", "ko": "그래서 사람들은\n뭐라고들 하오?", "it": false}, {"s": 492.927, "e": 495.103, "en": "Oh, come now, you must know\nit is somewhat unorthodox", "ko": "모를 리 없잖소\n좀 별난 일이란 걸", "it": false}, {"s": 495.233, "e": 498.019, "en": "for a woman and her father\nto be partners in business.", "ko": "아버지와 딸이\n동업을 한다는 게", "it": false}, {"s": 498.106, "e": 499.76, "en": "You don't say.", "ko": "그러게 말이에요", "it": false}, {"s": 501.501, "e": 503.633, "en": "Do you enjoy challenging\nconventions?", "ko": "관습에 맞서는 걸\n즐기시오?", "it": false}, {"s": 503.764, "e": 505.156, "en": "Quite the contrary.", "ko": "오히려 반대예요", "it": false}, {"s": 505.243, "e": 507.55, "en": "I'd enjoy if I didn't have to.", "ko": "안 맞서도 되면\n좋겠어요", "it": false}, {"s": 507.681, "e": 510.988, "en": "People make a fuss until\nthey get into the work.", "ko": "사람들은 일을 겪어 보기\n전까지만 수군대요", "it": false}, {"s": 511.119, "e": 515.036, "en": "Once I prove myself,\nit gets easier.", "ko": "제 실력을 증명하고 나면\n좀 나아지죠", "it": false}, {"s": 519.301, "e": 522.217, "en": "I hope you don't\nfind me presumptuous,", "ko": "주제넘다고\n생각하지 않으면 좋겠는데", "it": false}, {"s": 522.347, "e": 525.002, "en": "but I put in a call\nto the club.", "ko": "클럽에 연락을\n넣어 뒀소", "it": false}, {"s": 525.133, "e": 527.048, "en": "We have a table for dinner.", "ko": "저녁 식사 자리를\n잡아 놨소", "it": false}, {"s": 528.353, "e": 529.964, "en": "Not at all.", "ko": "전혀요", "it": false}, {"s": 533.62, "e": 535.752, "en": "Do you have a large family?", "ko": "가족이 많으세요?", "it": false}, {"s": 535.839, "e": 539.06, "en": "I picture relatives\noverstaying their welcome.", "ko": "친척들이 우르르 와서\n눌러앉고", "it": false}, {"s": 539.147, "e": 543.064, "en": "Raucous holiday dinners\nout in the country.", "ko": "시골에서 떠들썩하게\n명절을 보낼 것 같아요", "it": false}, {"s": 543.194, "e": 545.457, "en": "Not at all.", "ko": "전혀 아니오", "it": false}, {"s": 545.588, "e": 549.2, "en": "My father has been traveling\nin retirement", "ko": "아버지는 은퇴하고\n여행 중이시고", "it": false}, {"s": 549.287, "e": 553.988, "en": "and my mother passed\nwhen I was five.", "ko": "어머니는 내가 다섯 살 때\n돌아가셨소", "it": false}, {"s": 554.118, "e": 557.861, "en": "So, now it's just me.", "ko": "그래서 이제 나 혼자요", "it": false}, {"s": 557.992, "e": 561.648, "en": "I'm sorry. You were just\na boy.", "ko": "안됐네요\n어린애였을 텐데", "it": false}, {"s": 561.778, "e": 563.737, "en": "It made me a man.", "ko": "그 일로 남자가 됐소", "it": false}, {"s": 569.699, "e": 571.527, "en": "Not half bad for the city.", "ko": "도시치곤\n나쁘지 않군", "it": false}, {"s": 571.658, "e": 575.139, "en": "Ahh. A country imperialist.", "ko": "시골 우월주의자시네요", "it": false}, {"s": 575.226, "e": 576.619, "en": "Mock me all you want", "ko": "얼마든지 놀리시오", "it": false}, {"s": 576.706, "e": 579.883, "en": "but we breed our own line of\nsheep at Foxworth Hall.", "ko": "폭스워스 저택에선\n양을 직접 기르오", "it": false}, {"s": 579.97, "e": 582.756, "en": "Best lamb you have\never tasted.", "ko": "당신이 먹어 본 것 중\n최고의 양고기일 거요", "it": false}, {"s": 582.886, "e": 584.627, "en": "Tell me about it,\nyour home.", "ko": "얘기해 주세요,\n당신 집에 대해", "it": false}, {"s": 584.714, "e": 588.588, "en": "This Foxworth Hall you speak of\nwith such affection.", "ko": "그토록 애정을 담아 말하는\n폭스워스 저택 말이에요", "it": false}, {"s": 588.675, "e": 593.027, "en": "It is more than a home.", "ko": "집 그 이상이오", "it": false}, {"s": 593.114, "e": 599.424, "en": "It is my family's history\nand its future.", "ko": "우리 가문의 역사이자\n미래지", "it": false}, {"s": 599.511, "e": 602.906, "en": "What do you see\nfor that future?", "ko": "그 미래에서\n뭘 보시나요?", "it": false}, {"s": 603.037, "e": 605.517, "en": "An empire.", "ko": "제국", "it": false}, {"s": 605.648, "e": 608.303, "en": "An empire it is then.", "ko": "그럼 제국으로 하죠", "it": false}, {"s": 621.011, "e": 621.838, "en": "It's a letter.", "ko": "편지예요", "it": false}, {"s": 621.925, "e": 624.406, "en": "You wrote it but forgot\nto sign.", "ko": "아버지가 쓰시고는\n서명을 깜빡하셨어요", "it": false}, {"s": 624.493, "e": 625.494, "en": "Did I?", "ko": "내가?", "it": false}, {"s": 625.625, "e": 626.887, "en": "Indeed.", "ko": "네", "it": false}, {"s": 626.974, "e": 628.802, "en": "Last night in fact.", "ko": "그것도 어젯밤에요", "it": false}, {"s": 628.889, "e": 630.151, "en": "It seems you had some questions", "ko": "궁금한 게\n좀 있으셨나 봐요", "it": false}, {"s": 630.238, "e": 633.937, "en": "for Mr. Foxworth's business\ncolleagues in Virginia.", "ko": "버지니아에 있는\n폭스워스 씨의 사업 동료들한테요", "it": false}, {"s": 634.024, "e": 636.984, "en": "His family, his background,\nhis character.", "ko": "가족, 집안 배경,\n성품까지", "it": false}, {"s": 637.071, "e": 640.378, "en": "It so happens you were really\nquite curious.", "ko": "아주 궁금하셨던\n모양이에요", "it": false}, {"s": 640.465, "e": 644.295, "en": "And why might I\nbe so curious?", "ko": "내가 왜 그렇게\n궁금했을까?", "it": false}, {"s": 644.426, "e": 646.558, "en": "Because if the letter came from\nme, I wouldn't get a response.", "ko": "제 이름으로 보내면\n답장이 안 올 테니까요", "it": false}, {"s": 646.689, "e": 650.693, "en": "But from you, a distinguished\ngentleman...", "ko": "하지만 존경받는 신사분이\n보내시면...", "it": false}, {"s": 650.824, "e": 652.347, "en": "Olivia.", "ko": "올리비아", "it": false}, {"s": 652.477, "e": 654.915, "en": "I know more about his house than\nI do about his flesh and blood.", "ko": "그 사람 집에 대해선 알아도\n가족에 대해선 아는 게 없어요", "it": false}, {"s": 655.045, "e": 656.917, "en": "Everybody has secrets.", "ko": "누구나 비밀은 있다", "it": false}, {"s": 657.047, "e": 659.136, "en": "Please, Father.", "ko": "제발요, 아버지", "it": false}, {"s": 659.223, "e": 661.791, "en": "I need to know what\nI'm getting myself into.", "ko": "제가 어떤 일에\n뛰어드는지 알아야겠어요", "it": false}, {"s": 661.878, "e": 663.532, "en": "Mr. Malcolm Foxworth.", "ko": "맬컴 폭스워스 씨", "it": false}, {"s": 670.234, "e": 672.41, "en": "But it was too late.", "ko": "하지만 이미 늦었다", "it": true}, {"s": 672.497, "e": 674.543, "en": "I was already in.", "ko": "나는 이미 빠져 있었다", "it": true}, {"s": 674.63, "e": 678.634, "en": "I was the Countess Ellen Olenska\non the arm of Mr. Archer,", "ko": "나는 아처 씨의 팔짱을 낀\n엘렌 올렌스카 백작부인이었다", "it": true}, {"s": 678.721, "e": 681.376, "en": "only he knocked on the door\nin the end.", "ko": "다만 결국 문을 두드린 건\n그였다", "it": true}, {"s": 682.638, "e": 684.901, "en": "I was Elizabeth Bennet\nwith Mr. Darcy,", "ko": "다아시 씨와 함께하는\n엘리자베스 베넷이었다", "it": true}, {"s": 685.032, "e": 687.687, "en": "only without the annoying\nsisters.", "ko": "성가신 자매들만\n빼고", "it": true}, {"s": 687.774, "e": 691.56, "en": "I was Jane Eyre capturing\nthe heart of Mr. Rochester,", "ko": "로체스터 씨의 마음을\n사로잡은 제인 에어였다", "it": true}, {"s": 691.691, "e": 694.476, "en": "only without ghosts\nin the attic.", "ko": "다락방의 유령만\n빼고", "it": true}, {"s": 696.086, "e": 698.828, "en": "We have received a response\nto your inquiry.", "ko": "문의한 것에\n답장이 왔다", "it": false}, {"s": 698.959, "e": 700.656, "en": "I was fooling myself.", "ko": "나는 나 자신을\n속이고 있었다", "it": true}, {"s": 705.835, "e": 707.358, "en": "This just confirms\neverything we know.", "ko": "우리가 아는 내용을\n확인해 줄 뿐이네요", "it": false}, {"s": 707.489, "e": 709.665, "en": "The business,\nFoxworth Hall.", "ko": "사업도,\n폭스워스 저택도", "it": false}, {"s": 709.752, "e": 711.406, "en": "Mmmhmm. Keep reading.", "ko": "계속 읽어 봐라", "it": false}, {"s": 714.235, "e": 716.28, "en": "-His mother.\n-Hm.", "ko": "-어머니 얘기가...\n-그래", "it": false}, {"s": 716.411, "e": 720.632, "en": "It appears she did not die\nwhen he was a boy.", "ko": "어머니가 어릴 때\n죽은 게 아니었구나", "it": false}, {"s": 720.763, "e": 722.634, "en": "Why would anyone lie\nabout such a thing?", "ko": "왜 그런 걸\n거짓말할까요?", "it": false}, {"s": 722.765, "e": 725.507, "en": "And if one would lie\nabout their own mother...", "ko": "자기 어머니에 대해서도\n거짓말을 하는 사람이라면...", "it": false}, {"s": 725.637, "e": 726.769, "en": "What else might he\nbe hiding?", "ko": "또 뭘 숨기고\n있을까요?", "it": false}, {"s": 726.9, "e": 728.162, "en": "Hmm.", "ko": "흠", "it": false}, {"s": 730.73, "e": 731.426, "en": "It's him.", "ko": "그 사람이에요", "it": false}, {"s": 731.556, "e": 733.036, "en": "Not a word.", "ko": "아무 말도 하지 마세요", "it": false}, {"s": 742.872, "e": 745.222, "en": "As I am not often courted,", "ko": "제가 구애를\n받아 본 적이 별로 없어서", "it": false}, {"s": 745.353, "e": 748.573, "en": "the steps to the dance\nwe've been doing", "ko": "우리가 추고 있는\n이 춤의 스텝이", "it": false}, {"s": 748.66, "e": 752.186, "en": "aren't always familiar.", "ko": "아직 익숙하지\n않아요", "it": false}, {"s": 752.316, "e": 757.844, "en": "And I'm not as trusting as\nothers you may have pursued.", "ko": "당신이 만나 온 다른 여자들만큼\n쉽게 믿지도 않고요", "it": false}, {"s": 760.716, "e": 768.419, "en": "Which is why I inquired\nas to your family's history.", "ko": "그래서 당신 집안 내력을\n알아봤어요", "it": false}, {"s": 770.639, "e": 772.119, "en": "I see.", "ko": "그렇군", "it": false}, {"s": 772.249, "e": 775.252, "en": "It has come to my attention\nthat your mother did not die", "ko": "알고 보니 당신 어머니는\n당신이 어릴 때", "it": false}, {"s": 775.339, "e": 777.037, "en": "when you were a child.", "ko": "돌아가신 게\n아니더군요", "it": false}, {"s": 778.516, "e": 782.346, "en": "In fact, I understand\nshe died quite recently.", "ko": "사실은 아주 최근에\n돌아가셨다고 들었어요", "it": false}, {"s": 782.477, "e": 785.001, "en": "I am very sorry for your loss,\nhowever...", "ko": "정말 안타까워요,\n하지만...", "it": false}, {"s": 785.088, "e": 788.788, "en": "There is nothing\nto be sorry about.", "ko": "안타까워할 것\n없소", "it": false}, {"s": 788.918, "e": 792.835, "en": "And I never should\nhave misled you.", "ko": "당신을 속이지\n말았어야 했는데", "it": false}, {"s": 792.922, "e": 794.489, "en": "When I was five years old,", "ko": "내가 다섯 살 때", "it": false}, {"s": 794.619, "e": 799.973, "en": "my mother abandoned\nmy father and me.", "ko": "어머니는 아버지와 나를\n버리고 떠났소", "it": false}, {"s": 800.06, "e": 804.934, "en": "I never heard from\nor about her again", "ko": "그 뒤로 소식 한 번\n들은 적 없다가", "it": false}, {"s": 805.021, "e": 808.068, "en": "until I learned of her death\nnot long ago.", "ko": "얼마 전에야\n죽었다는 걸 알았소", "it": false}, {"s": 811.158, "e": 815.64, "en": "When I said my mother died\nwhen I was a boy,", "ko": "어머니가 내가 어릴 때\n죽었다고 한 건", "it": false}, {"s": 815.727, "e": 817.512, "en": "I wasn't lying.", "ko": "거짓말이\n아니었소", "it": false}, {"s": 817.642, "e": 819.993, "en": "She did die.", "ko": "정말 죽었으니까", "it": false}, {"s": 820.08, "e": 822.169, "en": "At least to me.", "ko": "적어도 나한테는", "it": false}, {"s": 822.299, "e": 827.609, "en": "How horrid of me\nto have doubted you.", "ko": "당신을 의심하다니\n제가 너무 끔찍했어요", "it": false}, {"s": 827.696, "e": 829.829, "en": "I'm sure you can never\nforgive me, deservedly so.", "ko": "절대 용서 못 하시겠죠\n그래도 마땅해요", "it": false}, {"s": 829.916, "e": 831.352, "en": "There is nothing to forgive.", "ko": "용서할 것도 없소", "it": false}, {"s": 831.439, "e": 833.223, "en": "It is exactly that\ninquisitive nature", "ko": "바로 그 캐묻는\n성격이", "it": false}, {"s": 833.31, "e": 835.53, "en": "that I find so intriguing.", "ko": "내가 당신에게\n끌리는 이유니까", "it": false}, {"s": 840.013, "e": 843.538, "en": "When I learned of\nmy mother's death", "ko": "어머니가 죽었다는 걸\n알았을 때", "it": false}, {"s": 843.668, "e": 850.545, "en": "I realized that life is long\nwhen one is alone,", "ko": "혼자인 삶은\n길다는 걸 깨달았소", "it": false}, {"s": 850.632, "e": 852.286, "en": "and the price one pays\nfor happiness", "ko": "그리고 행복의\n대가는", "it": false}, {"s": 852.416, "e": 855.898, "en": "is time's quick passage.", "ko": "시간이 너무 빨리\n흐른다는 거요", "it": false}, {"s": 856.029, "e": 860.816, "en": "And upon meeting you, I lost\nall track of time.", "ko": "당신을 만난 뒤로\n시간 가는 줄 몰랐소", "it": false}, {"s": 860.947, "e": 867.388, "en": "Has it been a week, a month,\na moment, or a lifetime?", "ko": "일주일이었소? 한 달?\n한순간? 아니면 평생?", "it": false}, {"s": 873.568, "e": 876.484, "en": "Let's make it a lifetime,\nOlivia.", "ko": "평생으로 합시다,\n올리비아", "it": false}, {"s": 883.708, "e": 884.753, "en": "Oh.", "ko": "어머", "it": false}, {"s": 889.453, "e": 891.499, "en": "Will you marry me?", "ko": "나와 결혼해 주겠소?", "it": false}, {"s": 893.414, "e": 896.025, "en": "I am offering you my heart.", "ko": "내 마음을\n당신에게 바치겠소", "it": false}, {"s": 896.156, "e": 902.162, "en": "A heart that will surely break\nif you don't say something.", "ko": "당신이 아무 말도 안 하면\n그 마음은 부서질 거요", "it": false}, {"s": 902.249, "e": 903.685, "en": "Anything.", "ko": "뭐든 말해 주시오", "it": false}, {"s": 905.382, "e": 906.557, "en": "Yes.", "ko": "네", "it": false}, {"s": 906.906, "e": 907.907, "en": "Yes!", "ko": "좋아요!", "it": false}, {"s": 929.711, "e": 931.756, "en": "Could it really be true?", "ko": "정말 사실일까?", "it": true}, {"s": 931.843, "e": 934.846, "en": "I was to have all this.", "ko": "이 모든 게 내 것이 된다", "it": true}, {"s": 934.934, "e": 937.675, "en": "A home of my own.", "ko": "나만의 집", "it": true}, {"s": 937.806, "e": 940.417, "en": "A husband of my own.", "ko": "나만의 남편", "it": true}, {"s": 944.987, "e": 946.162, "en": "-Excuse the interruption.", "ko": "방해해서 미안해", "it": false}, {"s": 946.293, "e": 949.122, "en": "Ah, Amos.", "ko": "에이머스 오빠", "it": false}, {"s": 949.252, "e": 952.212, "en": "I know it's terribly improper\nof me to intrude.", "ko": "불쑥 찾아오는 게\n정말 실례인 줄은 알아", "it": false}, {"s": 952.342, "e": 953.648, "en": "Oh, nonsense.", "ko": "무슨 소리야", "it": false}, {"s": 953.778, "e": 955.302, "en": "Do come in.", "ko": "들어와", "it": false}, {"s": 968.837, "e": 972.232, "en": "A little something\nfor your special day.", "ko": "특별한 날을 위해\n작은 선물을 가져왔어", "it": false}, {"s": 975.496, "e": 978.499, "en": "\"Eternally united.\"\nHow lovely.", "ko": "\"영원히 하나로\"\n너무 예쁘다", "it": false}, {"s": 978.629, "e": 980.936, "en": "You and Mr. Foxworth,\nof course.", "ko": "물론 너와\n폭스워스 씨 얘기지", "it": false}, {"s": 984.287, "e": 987.377, "en": "I hope this reminds you to\nkeep up our correspondence", "ko": "버지니아에서 새 생활에\n자리 잡더라도", "it": false}, {"s": 987.464, "e": 990.206, "en": "once you've settled into\nyour new life in Virginia.", "ko": "이걸 보고 편지\n계속 주고받자는 거 잊지 마", "it": false}, {"s": 990.293, "e": 993.122, "en": "As if I'd need reminding.\nThank you.", "ko": "안 봐도 안 잊어\n고마워", "it": false}, {"s": 1000.129, "e": 1003.872, "en": "Are you sure this is\nwhat you want?", "ko": "정말 원하는 게\n이거 맞아?", "it": false}, {"s": 1005.569, "e": 1007.441, "en": "To marry Mr. Foxworth?", "ko": "폭스워스 씨와\n결혼하는 거", "it": false}, {"s": 1009.051, "e": 1010.009, "en": "It is.", "ko": "응", "it": false}, {"s": 1012.881, "e": 1015.275, "en": "Ah, there's my darling daughter.", "ko": "아, 우리 딸 여기 있구나", "it": false}, {"s": 1017.668, "e": 1019.844, "en": "I was just leaving.", "ko": "저는 막 가려던 참이었어요", "it": false}, {"s": 1019.931, "e": 1022.282, "en": "Thank you, again.", "ko": "다시 한번 고마워", "it": false}, {"s": 1027.591, "e": 1029.506, "en": "You look radiant.", "ko": "눈부시구나", "it": false}, {"s": 1029.593, "e": 1034.163, "en": "Can you believe it?\nMe, a bride.", "ko": "믿어지세요?\n제가 신부라니", "it": false}, {"s": 1034.25, "e": 1036.731, "en": "Now being a bride\nand being a wife", "ko": "그런데 신부가 되는 것과\n아내가 되는 건", "it": false}, {"s": 1036.818, "e": 1038.95, "en": "are two very\ndifferent things.", "ko": "아주 다른 일이란다", "it": false}, {"s": 1039.081, "e": 1040.169, "en": "People will look\nat you differently.", "ko": "사람들이 너를\n다르게 볼 거다", "it": false}, {"s": 1040.256, "e": 1042.824, "en": "Your husband will look\nat you differently.", "ko": "남편도 너를\n다르게 볼 거고", "it": false}, {"s": 1042.954, "e": 1046.393, "en": "But you must never look\nat yourself differently.", "ko": "하지만 너 자신을\n다르게 봐서는 안 된다", "it": false}, {"s": 1046.523, "e": 1049.396, "en": "You must never forget\nwho you are.", "ko": "네가 누군지\n절대 잊지 마라", "it": false}, {"s": 1049.483, "e": 1053.53, "en": "You have everything you need\nright here.", "ko": "필요한 건 전부\n여기 있단다", "it": false}, {"s": 1053.617, "e": 1055.576, "en": "Let your heart be\nyour compass.", "ko": "네 마음을\n나침반으로 삼아라", "it": false}, {"s": 1057.491, "e": 1060.015, "en": "But if you should ever\nlose your way...", "ko": "하지만 혹시\n길을 잃으면...", "it": false}, {"s": 1064.193, "e": 1066.369, "en": "From the man who always\ntaught me to study religion", "ko": "종교를 공부하되", "it": false}, {"s": 1066.5, "e": 1067.762, "en": "but not espouse it.", "ko": "믿지는 말라고\n가르치신 분이 이걸요?", "it": false}, {"s": 1067.849, "e": 1070.069, "en": "No, not from me.", "ko": "아니, 내가 주는 게 아니다", "it": false}, {"s": 1070.156, "e": 1071.418, "en": "From your mother.", "ko": "네 어머니가 주는 거다", "it": false}, {"s": 1071.548, "e": 1074.073, "en": "She always wanted you\nto have it.", "ko": "늘 너한테\n물려주고 싶어 했지", "it": false}, {"s": 1074.16, "e": 1081.08, "en": "And I thought well,\nif not now then when?", "ko": "지금이 아니면\n언제겠나 싶더구나", "it": false}, {"s": 1086.998, "e": 1089.523, "en": "You look just like her.", "ko": "네 어머니를 꼭 닮았구나", "it": false}, {"s": 1089.61, "e": 1091.96, "en": "I wish\nshe were here.", "ko": "엄마가\n여기 계시면 좋을 텐데", "it": false}, {"s": 1109.891, "e": 1111.24, "en": "Like many women in love,", "ko": "사랑에 빠진 많은 여자들처럼", "it": true}, {"s": 1111.371, "e": 1113.721, "en": "I never realized that\nthe blue sky I saw above", "ko": "나는 몰랐다\n머리 위의 푸른 하늘이", "it": true}, {"s": 1113.808, "e": 1117.768, "en": "was soon to turn\na dark shade of grey.", "ko": "곧 짙은 잿빛으로\n변하리란 것을", "it": true}, {"s": 1121.859, "e": 1125.428, "en": "I can't make out a thing.\nIt's so very dark.", "ko": "아무것도 안 보여요\n너무 어두워요", "it": false}, {"s": 1125.515, "e": 1127.517, "en": "You'll get used to it.", "ko": "곧 익숙해질 거요", "it": false}, {"s": 1127.648, "e": 1129.954, "en": "Foxworth Hall does not have\nthe electric light.", "ko": "폭스워스 저택엔\n전기가 들어오지 않소", "it": false}, {"s": 1130.085, "e": 1134.568, "en": "Well, that's romantic,\nI'm sure.", "ko": "낭만적이네요", "it": false}, {"s": 1134.698, "e": 1137.484, "en": "As is Venice, so I hear.", "ko": "베네치아도 그렇다던데요", "it": false}, {"s": 1140.182, "e": 1141.749, "en": "For our honeymoon.", "ko": "신혼여행 말이에요", "it": false}, {"s": 1141.836, "e": 1144.578, "en": "After the wedding party,\nof course.", "ko": "물론 피로연이\n끝난 뒤에요", "it": false}, {"s": 1144.708, "e": 1146.667, "en": "Yes, of course.", "ko": "그렇소, 물론이오", "it": false}, {"s": 1146.797, "e": 1148.451, "en": "We'll discuss our travel plans", "ko": "여행 계획은\n나중에 얘기합시다", "it": false}, {"s": 1148.538, "e": 1150.932, "en": "once you acclimate yourself\nto your new job.", "ko": "당신이 새 일에\n익숙해지고 나서 말이오", "it": false}, {"s": 1151.062, "e": 1155.154, "en": "I hardly think being mistress\nof the house constitutes a job.", "ko": "안주인 노릇이\n일이라고 할 것까지야", "it": false}, {"s": 1155.284, "e": 1158.766, "en": "Oh, you haven't seen\nFoxworth Hall yet.", "ko": "폭스워스 저택을\n아직 못 봐서 그렇소", "it": false}, {"s": 1158.896, "e": 1164.598, "en": "It is your domain now to run\nand manage as you like.", "ko": "이제부턴 당신 영역이니\n원하는 대로 꾸리고 관리하시오", "it": false}, {"s": 1164.728, "e": 1169.298, "en": "But I assure you it will require\nyour full-time supervision.", "ko": "하지만 하루 종일\n붙어서 살펴야 할 거요", "it": false}, {"s": 1169.385, "e": 1170.821, "en": "Do you understand?", "ko": "알아들었소?", "it": false}, {"s": 1174.695, "e": 1177.35, "en": "Welcome to Foxworth Hall.", "ko": "폭스워스 저택에 온 걸 환영하오", "it": false}, {"s": 1232.492, "e": 1234.537, "en": "Good evening, Mr. Foxworth.", "ko": "오셨습니까, 주인님", "it": false}, {"s": 1236.191, "e": 1237.41, "en": "Mrs. Foxworth.", "ko": "새 마님도 오셨네요", "it": false}, {"s": 1239.542, "e": 1240.935, "en": "Good evening.", "ko": "안녕하세요", "it": false}, {"s": 1241.675, "e": 1243.329, "en": "It's late.", "ko": "시간이 꽤 늦었네요", "it": false}, {"s": 1243.459, "e": 1245.505, "en": "You must want to retire.", "ko": "얼른 쉬고 싶으시겠지요", "it": false}, {"s": 1259.301, "e": 1261.085, "en": "You will be shown\nto your room.", "ko": "방으로 안내해 줄 거요", "it": false}, {"s": 1262.522, "e": 1264.35, "en": "Much awaits you here.", "ko": "여기서 할 일이 많을 거요", "it": false}, {"s": 1276.318, "e": 1278.015, "en": "This is Nella.", "ko": "얘는 넬라예요", "it": false}, {"s": 1278.146, "e": 1281.584, "en": "She'll see to whatever\nyou may require.", "ko": "필요한 건\n얘가 다 챙겨 드릴 거예요", "it": false}, {"s": 1281.715, "e": 1283.456, "en": "It's a pleasure to meet you.", "ko": "만나서 반가워요", "it": false}, {"s": 1283.586, "e": 1285.545, "en": "Right this way,\nMrs. Foxworth.", "ko": "이쪽입니다, 마님", "it": false}, {"s": 1328.892, "e": 1331.373, "en": "I hope you find everything\nto your liking.", "ko": "마음에 드시면\n좋겠습니다", "it": false}, {"s": 1331.504, "e": 1332.809, "en": "Thank you...", "ko": "고마워요...", "it": false}, {"s": 1333.332, "e": 1335.334, "en": "-Nella.\n-Nella.", "ko": "-넬라입니다\n-넬라", "it": false}, {"s": 1337.423, "e": 1341.601, "en": "If you need anything,\nanything at all.", "ko": "필요한 게 있으시면\n뭐든지", "it": false}, {"s": 1341.688, "e": 1343.646, "en": "Ring for me.", "ko": "종을 울려 주세요", "it": false}, {"s": 1351.132, "e": 1353.352, "en": "My wedding night.", "ko": "나의 첫날밤", "it": true}, {"s": 1353.439, "e": 1355.789, "en": "I was too young when my mother\ndied for her to prepare me", "ko": "어머니는 너무 일찍\n돌아가셔서 내게 알려 주지 못했다", "it": true}, {"s": 1355.919, "e": 1357.443, "en": "for the momentous occasion.", "ko": "그 중대한 순간에 대해", "it": true}, {"s": 1357.573, "e": 1360.054, "en": "But I had an idea\nof what was to happen.", "ko": "하지만 무슨 일이 일어날지\n짐작은 하고 있었다", "it": true}, {"s": 1360.184, "e": 1363.362, "en": "Lord knows I'd read\nenough books.", "ko": "책은\n지겹도록 읽었으니까", "it": true}, {"s": 1363.492, "e": 1364.928, "en": "But nothing could have\nprepared me", "ko": "하지만 그 무엇도\n나를 대비시키지 못했다", "it": true}, {"s": 1365.059, "e": 1367.061, "en": "for what did happen.", "ko": "실제로 일어난 일에는", "it": true}, {"s": 1375.722, "e": 1376.679, "en": "Nothing.", "ko": "아무것도", "it": true}, {"s": 1379.247, "e": 1381.162, "en": "He never came.", "ko": "그는 오지 않았다", "it": true}, {"s": 1404.403, "e": 1408.668, "en": "When will Mr. Foxworth\nbe arriving?", "ko": "남편은 언제\n내려오시죠?", "it": false}, {"s": 1408.755, "e": 1411.584, "en": "Mr. Foxworth already left\nfor town.", "ko": "주인님은 벌써\n시내 나가셨지요", "it": false}, {"s": 1414.325, "e": 1416.893, "en": "He had an early\nbusiness meeting.", "ko": "아침 일찍 회의가\n있으셨거든요", "it": false}, {"s": 1417.024, "e": 1418.504, "en": "Of course.", "ko": "그렇겠죠", "it": false}, {"s": 1418.591, "e": 1421.637, "en": "How silly of me. I must\nhave forgotten.", "ko": "내가 참 바보네요\n깜빡했나 봐요", "it": false}, {"s": 1421.768, "e": 1426.599, "en": "If you've finished, Mr. Foxworth\nrequested I show you something.", "ko": "식사 다 하셨으면, 주인님이\n보여 드리라고 하신 게 있어서요", "it": false}, {"s": 1435.912, "e": 1440.439, "en": "I couldn't ask for a more\nperfect wedding gift.", "ko": "이보다 완벽한\n결혼 선물은 없겠어요", "it": false}, {"s": 1440.526, "e": 1444.486, "en": "Malcolm knows I have\na passion for reading.", "ko": "맬컴은 내가 책을\n얼마나 좋아하는지 알거든요", "it": false}, {"s": 1444.573, "e": 1446.532, "en": "I'm sure you do.", "ko": "어련하시겠어요", "it": false}, {"s": 1450.84, "e": 1453.277, "en": "This way, Mrs. Foxworth.", "ko": "이쪽이에요, 마님", "it": false}, {"s": 1463.026, "e": 1467.335, "en": "This is what Mr. Foxworth\nwished for me to show you.", "ko": "주인님이 보여 드리라고\n하신 데예요", "it": false}, {"s": 1467.466, "e": 1469.511, "en": "Your office.", "ko": "마님 집무실이에요", "it": false}, {"s": 1469.598, "e": 1471.426, "en": "Mr. Foxworth would like you\nto conduct the business", "ko": "주인님은 폭스워스 저택 살림을", "it": false}, {"s": 1471.557, "e": 1475.169, "en": "of Foxworth Hall from here.", "ko": "여기서 맡아 주시길\n바라세요", "it": false}, {"s": 1475.299, "e": 1477.998, "en": "He said you may\nbegin immediately.", "ko": "당장 시작하셔도\n된다고 하셨고요", "it": false}, {"s": 1484.483, "e": 1486.833, "en": "Would you like to take me\non a tour of the house?", "ko": "저택 구경 좀\n시켜 줄래요?", "it": false}, {"s": 1486.92, "e": 1490.14, "en": "Oh, Mr. Foxworth doesn't like\npeople roaming about.", "ko": "주인님은 사람들이 이리저리\n돌아다니는 걸 싫어하세요", "it": false}, {"s": 1490.227, "e": 1493.274, "en": "I would hardly say his wife\nqualifies as \"people.\"", "ko": "그 사람의 아내까지\n\"사람들\"에 들어가진 않겠죠", "it": false}, {"s": 1493.404, "e": 1495.058, "en": "My apologies, Mrs. Foxworth.", "ko": "그거야 송구하게 됐네요, 마님", "it": false}, {"s": 1495.189, "e": 1496.364, "en": "Quite all right.", "ko": "괜찮아요", "it": false}, {"s": 1496.495, "e": 1497.496, "en": "Please.", "ko": "부탁해요", "it": false}, {"s": 1499.541, "e": 1503.066, "en": "Share with me some of\nthe family's history.", "ko": "이 집안 얘기 좀\n들려줘요", "it": false}, {"s": 1503.153, "e": 1505.155, "en": "Have you worked here long?", "ko": "여기서 오래 일했나요?", "it": false}, {"s": 1505.286, "e": 1508.158, "en": "My mother was employed here.", "ko": "우리 어머니가\n여기서 일했지요", "it": false}, {"s": 1508.245, "e": 1512.423, "en": "Foxworth Hall has been my home\nsince birth.", "ko": "폭스워스 저택은\n태어날 때부터 내 집이었어요", "it": false}, {"s": 1512.511, "e": 1517.472, "en": "I was raised here alongside\nMr. Garland Foxworth,", "ko": "갈랜드 폭스워스 님하고\n같이 컸지요", "it": false}, {"s": 1517.603, "e": 1519.43, "en": "your new father-in-law.", "ko": "마님 시아버님\n되시는 분이요", "it": false}, {"s": 1519.518, "e": 1521.868, "en": "Then you are perfectly suited\nto be my guide.", "ko": "그럼 안내인으로\n딱이네요", "it": false}, {"s": 1523.434, "e": 1524.914, "en": "Please.", "ko": "부탁해요", "it": false}, {"s": 1525.045, "e": 1526.699, "en": "How am I to conduct the business\nof Foxworth Hall", "ko": "내가 폭스워스 저택 살림을\n어떻게 꾸리겠어요", "it": false}, {"s": 1526.829, "e": 1529.005, "en": "if I'm not acquainted\nwith it myself?", "ko": "이 집도\n모르는데", "it": false}, {"s": 1529.092, "e": 1532.618, "en": "But I am afraid I'm needed\nin the kitchen.", "ko": "근데 어쩌나, 부엌에서\n날 찾을 텐데요", "it": false}, {"s": 1532.705, "e": 1534.184, "en": "Well then...", "ko": "그렇다면...", "it": false}, {"s": 1534.315, "e": 1537.623, "en": "You should get to it,\nshouldn't you?", "ko": "가 봐야겠네요,\n안 그래요?", "it": false}, {"s": 1537.71, "e": 1539.407, "en": "If you'll excuse me.", "ko": "그럼 이만 가 볼게요", "it": false}, {"s": 1557.599, "e": 1558.557, "en": "Nella.", "ko": "넬라", "it": false}, {"s": 1560.733, "e": 1562.43, "en": "Yes, Mrs. Foxworth.", "ko": "네, 마님", "it": false}, {"s": 1562.517, "e": 1565.259, "en": "I seem to be on a tour\nwithout a guide.", "ko": "안내인 없이\n구경을 하게 됐네요", "it": false}, {"s": 1565.346, "e": 1567.391, "en": "Will you show me around\nmy new home?", "ko": "새집 구경 좀\n시켜 줄래요?", "it": false}, {"s": 1571.787, "e": 1575.008, "en": "Is it always so dark\nin here?", "ko": "여긴 늘\n이렇게 어두워요?", "it": false}, {"s": 1575.095, "e": 1577.053, "en": "I suppose I'm used to it.", "ko": "전 익숙해서요", "it": false}, {"s": 1577.14, "e": 1578.881, "en": "My father always says\nthat someone's home", "ko": "우리 아버지는 늘\n집이란", "it": false}, {"s": 1579.012, "e": 1582.189, "en": "is a window into their soul\nsecond only to their eyes.", "ko": "눈 다음으로 그 사람의 영혼을\n보여 주는 창이라고 하세요", "it": false}, {"s": 1585.322, "e": 1586.933, "en": "I hope that's not true.", "ko": "그 말이 사실이\n아니면 좋겠어요", "it": false}, {"s": 1587.02, "e": 1592.199, "en": "I only meant, well, because\nmy home is rather modest.", "ko": "그러니까 제 말은,\n저희 집은 워낙 소박해서요", "it": false}, {"s": 1592.329, "e": 1595.028, "en": "A virtue that perhaps\nthe Foxworths could've used", "ko": "폭스워스 집안에\n좀 더 있었으면 좋았을", "it": false}, {"s": 1595.158, "e": 1596.769, "en": "a little more of, no?", "ko": "미덕이네요, 안 그래요?", "it": false}, {"s": 1603.732, "e": 1606.039, "en": "So, who were they?", "ko": "그래서, 어떤 사람들이었어요?", "it": false}, {"s": 1606.126, "e": 1609.042, "en": "Well, the first Mr. Foxworth\nmade his fortune in mining.", "ko": "초대 폭스워스 님은\n광산으로 재산을 모으셨어요", "it": false}, {"s": 1609.172, "e": 1610.739, "en": "I know all about that.", "ko": "그건 다 알아요", "it": false}, {"s": 1610.826, "e": 1612.567, "en": "I want to know who they were.", "ko": "어떤 사람들이었는지\n알고 싶어요", "it": false}, {"s": 1612.654, "e": 1614.264, "en": "What made them smile.", "ko": "뭘 보고 웃었는지", "it": false}, {"s": 1614.395, "e": 1616.005, "en": "How they passed their time.", "ko": "시간을 어떻게 보냈는지", "it": false}, {"s": 1616.136, "e": 1618.094, "en": "I really can't say.", "ko": "제가 말씀드리긴 어렵네요", "it": false}, {"s": 1618.181, "e": 1620.619, "en": "Because you don't know or\nbecause you won't tell me?", "ko": "몰라서예요,\n말 안 해 주는 거예요?", "it": false}, {"s": 1623.143, "e": 1626.102, "en": "A mystery I will have\nto solve myself then.", "ko": "그럼 수수께끼는\n내가 직접 풀어야겠네요", "it": false}, {"s": 1630.324, "e": 1633.327, "en": "Someday your portrait will hang\non these walls.", "ko": "언젠가 마님 초상화도\n이 벽에 걸리겠지요", "it": false}, {"s": 1633.457, "e": 1635.634, "en": "Well, I'll be sure to smile\nin mine.", "ko": "그럼 꼭\n웃는 얼굴로 그려야겠네요", "it": false}, {"s": 1637.853, "e": 1639.768, "en": "I hope you do.", "ko": "그러시길 바랍니다", "it": false}, {"s": 1648.647, "e": 1651.824, "en": "I had a dull house back\nin New London", "ko": "뉴런던에 있던\n내 집은 따분했는데", "it": false}, {"s": 1651.954, "e": 1654.827, "en": "that felt more alive\nthan these halls.", "ko": "그래도 여기보단\n생기가 있었어요", "it": false}, {"s": 1654.957, "e": 1657.264, "en": "Where's the color?\nWhere's the life?", "ko": "색은 다 어디 가고?\n생기는 다 어디 갔죠?", "it": false}, {"s": 1657.394, "e": 1660.31, "en": "Mr. Foxworth likes us to keep\neverything just as it is.", "ko": "주인님께선 뭐든 지금 그대로\n두기를 바라십니다", "it": false}, {"s": 1666.099, "e": 1668.057, "en": "I think I'm already lost.", "ko": "벌써 길을 잃은 것 같아요", "it": false}, {"s": 1668.144, "e": 1671.06, "en": "Foxworth Hall has a way\nof doing that to people.", "ko": "폭스워스 저택은\n사람을 그렇게 만들지요", "it": false}, {"s": 1671.147, "e": 1674.673, "en": "This is the East Wing.\nIt's rarely used these days.", "ko": "여긴 동쪽 별관이에요\n요즘은 거의 안 써요", "it": false}, {"s": 1675.848, "e": 1677.11, "en": "What's that?", "ko": "저건 뭐죠?", "it": false}, {"s": 1677.197, "e": 1680.243, "en": "A lock on the outside\nof a bedroom door.", "ko": "침실 문 바깥쪽에\n자물쇠가 있네요", "it": false}, {"s": 1680.374, "e": 1683.638, "en": "Is this where you keep\nthe misbehaved guests?", "ko": "말 안 듣는 손님을\n가둬 두는 곳인가요?", "it": false}, {"s": 1710.752, "e": 1712.232, "en": "We don't go there!", "ko": "거긴 안 돼요!", "it": false}, {"s": 1712.362, "e": 1713.886, "en": "And why not?", "ko": "왜요?", "it": false}, {"s": 1714.016, "e": 1716.149, "en": "Mr. Foxworth says\nit's off limits.", "ko": "주인님께서\n출입 금지라고 하셨어요", "it": false}, {"s": 1716.279, "e": 1718.629, "en": "And it may very well be\nbut surely not to me.", "ko": "그럴 수도 있겠지만\n나한테까지는 아니겠죠", "it": false}, {"s": 1718.76, "e": 1720.675, "en": "Or to you, as long\nas you're with me.", "ko": "나랑 같이 있으면\n당신도 괜찮고요", "it": false}, {"s": 1720.806, "e": 1723.069, "en": "I really shouldn't.", "ko": "정말 안 되는데요", "it": false}, {"s": 1723.199, "e": 1724.592, "en": "Please?", "ko": "부탁해요", "it": false}, {"s": 1724.679, "e": 1726.681, "en": "Very well.", "ko": "알겠습니다", "it": false}, {"s": 1726.812, "e": 1728.727, "en": "Thank you for the tour.", "ko": "구경시켜 줘서 고마워요", "it": false}, {"s": 1731.381, "e": 1733.819, "en": "Be careful up there.", "ko": "위에선 조심하세요", "it": false}, {"s": 1758.017, "e": 1759.888, "en": "I had finally found it.", "ko": "드디어 찾았다", "it": true}, {"s": 1759.975, "e": 1763.849, "en": "The place where families hide\ntheir stories and their secrets.", "ko": "가문이 이야기와 비밀을\n숨겨 두는 곳", "it": true}, {"s": 1766.765, "e": 1768.462, "en": "The attic.", "ko": "다락방", "it": true}, {"s": 1776.209, "e": 1778.777, "en": "Attics are where\nmemories go to die.", "ko": "다락방은\n추억이 죽으러 가는 곳이다", "it": true}, {"s": 1783.607, "e": 1786.48, "en": "I should've let them\nrest in peace.", "ko": "편히 잠들게\n내버려 뒀어야 했다", "it": true}, {"s": 1791.224, "e": 1794.618, "en": "But I was young and naive\nand I wanted answers.", "ko": "하지만 나는 어리고 순진했고\n답을 원했다", "it": true}, {"s": 1888.016, "e": 1890.584, "en": "The history of\nmy new family.", "ko": "내 새 가족의 역사", "it": true}, {"s": 1896.59, "e": 1900.072, "en": "Untouched for who knows\nhow long.", "ko": "얼마나 오랫동안\n손대지 않았을까", "it": true}, {"s": 1907.949, "e": 1910.082, "en": "Or so I thought.", "ko": "그렇게 생각했다", "it": true}, {"s": 1914.956, "e": 1916.697, "en": "No dust.", "ko": "먼지가 없네", "it": false}, {"s": 1916.784, "e": 1920.831, "en": "He was there recently,\nwhich means that was her,", "ko": "최근에 누가 왔었어\n그렇다면 이 사람은", "it": false}, {"s": 1920.962, "e": 1925.445, "en": "Malcolm's mother,\nCorrine Foxworth.", "ko": "맬컴의 어머니,\n코린 폭스워스", "it": false}, {"s": 1933.018, "e": 1938.806, "en": "Ah, ah, ah, ah!!!", "ko": "아, 아, 아!", "it": false}, {"s": 1944.159, "e": 1946.422, "en": "On that day I made a promise\nto myself.", "ko": "그날 나는\n나 자신과 약속했다", "it": true}, {"s": 1956.606, "e": 1959.305, "en": "I promised never to return\nto the attic again.", "ko": "다시는 다락방에\n오지 않겠다고", "it": true}, {"s": 1965.702, "e": 1968.967, "en": "It was a promise I'd keep\nfor nearly 30 years.", "ko": "그 약속은 거의 30년간\n지켜졌다", "it": true}, {"s": 1993.295, "e": 1994.644, "en": "Who gave you permission\nto come in here?", "ko": "누가 여기\n들어와도 된다고 했소?", "it": false}, {"s": 1995.863, "e": 1996.69, "en": "Oh, it's you.", "ko": "아, 당신이군요", "it": false}, {"s": 1996.82, "e": 1997.691, "en": "Get out!", "ko": "나와!", "it": false}, {"s": 2000.476, "e": 2001.521, "en": "Now!", "ko": "당장!", "it": false}, {"s": 2007.701, "e": 2009.616, "en": "I was exploring the attic\nwhen I fell", "ko": "다락방을 구경하다가\n넘어졌는데", "it": false}, {"s": 2009.703, "e": 2011.4, "en": "and I suppose I was\ndisoriented because I...", "ko": "정신이 없어서\n그만...", "it": false}, {"s": 2011.487, "e": 2014.534, "en": "My mother's personal possessions\nare in the attic.", "ko": "다락방에 있는 건\n어머니 유품이오", "it": false}, {"s": 2014.664, "e": 2016.231, "en": "They are not to be disturbed.", "ko": "아무도 손대선 안 되오", "it": false}, {"s": 2016.362, "e": 2017.885, "en": "-I didn't know.\n-Do you understand?", "ko": "-몰랐어요\n-알아들었소?", "it": false}, {"s": 2017.972, "e": 2019.495, "en": "Excuse me?", "ko": "네?", "it": false}, {"s": 2019.582, "e": 2020.888, "en": "Do you understand?", "ko": "알아들었냐고 물었소", "it": false}, {"s": 2022.585, "e": 2024.892, "en": "Yes, I understand.", "ko": "네, 알겠어요", "it": false}, {"s": 2030.071, "e": 2031.594, "en": "But why?", "ko": "그런데 왜요?", "it": false}, {"s": 2031.681, "e": 2034.771, "en": "I understand you keeping\nher things in the attic", "ko": "유품을 다락방에\n두는 건 이해해요", "it": false}, {"s": 2034.902, "e": 2037.513, "en": "but her room.", "ko": "그런데 방까지요?", "it": false}, {"s": 2037.644, "e": 2039.733, "en": "That's it, isn't it?", "ko": "그거죠, 그렇죠?", "it": false}, {"s": 2039.863, "e": 2043.041, "en": "You've never touched it,\nhave you?", "ko": "한 번도 손대지\n않은 거죠?", "it": false}, {"s": 2043.128, "e": 2046.0, "en": "Some things should be left\nas they are.", "ko": "있는 그대로\n둬야 하는 것도 있소", "it": false}, {"s": 2046.653, "e": 2048.35, "en": "What kind of person was she?", "ko": "어떤 분이셨어요?", "it": false}, {"s": 2050.091, "e": 2051.049, "en": "Frivolous.", "ko": "경박했소", "it": false}, {"s": 2053.094, "e": 2055.792, "en": "Self-indulgent.", "ko": "방종하고", "it": false}, {"s": 2055.923, "e": 2057.533, "en": "Narcissistic.", "ko": "자기밖에 몰랐소", "it": false}, {"s": 2060.493, "e": 2062.06, "en": "Beautiful.", "ko": "아름다웠고", "it": false}, {"s": 2064.54, "e": 2067.326, "en": "I'm assuming you saw\nher picture.", "ko": "어머니 초상화를 봤겠구려", "it": false}, {"s": 2067.413, "e": 2070.59, "en": "And what did you think?", "ko": "어떻게 생각했소?", "it": false}, {"s": 2070.72, "e": 2075.986, "en": "She was beautiful,\nyou're right.", "ko": "맞아요, 아름다우셨어요", "it": false}, {"s": 2076.117, "e": 2077.423, "en": "So beautiful.", "ko": "정말 너무 아름다우셨어요", "it": false}, {"s": 2079.555, "e": 2081.253, "en": "Did you see her clothes?", "ko": "어머니 옷도 봤소?", "it": false}, {"s": 2082.993, "e": 2084.43, "en": "Did you touch them?", "ko": "만져 봤소?", "it": false}, {"s": 2086.78, "e": 2088.39, "en": "How did they feel?", "ko": "느낌이 어땠소?", "it": false}, {"s": 2090.0, "e": 2092.699, "en": "I'm not sure what you mean?", "ko": "무슨 말씀이신지...", "it": false}, {"s": 2092.786, "e": 2095.223, "en": "How did they feel?", "ko": "느낌이 어땠냐고 물었소", "it": false}, {"s": 2095.354, "e": 2099.923, "en": "They felt... lovely.", "ko": "느낌이... 좋았어요", "it": false}, {"s": 2109.716, "e": 2115.113, "en": "Would you like to see her room?\nProperly this time.", "ko": "어머니 방을 보겠소?\n이번엔 제대로", "it": false}, {"s": 2133.87, "e": 2137.091, "en": "We spent many wonderful days\nin this room.", "ko": "우린 이 방에서\n행복한 날들을 많이 보냈소", "it": false}, {"s": 2137.222, "e": 2139.137, "en": "In your mother's bedroom.", "ko": "어머님 침실에서요?", "it": false}, {"s": 2147.841, "e": 2153.803, "en": "My father was away on business\nmuch of the time", "ko": "아버지는 사업 때문에\n집을 자주 비웠고", "it": false}, {"s": 2153.89, "e": 2155.065, "en": "and so my mother and I,", "ko": "그래서 어머니와 나는", "it": false}, {"s": 2155.196, "e": 2158.025, "en": "we only had each other\nfor companionship.", "ko": "서로밖에\n없었소", "it": false}, {"s": 2161.985, "e": 2167.6, "en": "That is we did, up until\nher 22nd birthday", "ko": "어머니의 스물두 번째\n생일까지는 말이오", "it": false}, {"s": 2167.687, "e": 2170.907, "en": "and I woke up to come give her\nher birthday gift.", "ko": "생일 선물을 드리려고\n아침에 일어났는데", "it": false}, {"s": 2170.994, "e": 2173.606, "en": "A music box.", "ko": "오르골이었소", "it": false}, {"s": 2173.736, "e": 2175.869, "en": "And she was gone.", "ko": "어머니가 사라졌더군", "it": false}, {"s": 2175.956, "e": 2178.567, "en": "I thought you said she left\nwhen you were five.", "ko": "다섯 살 때 떠나셨다고\n하지 않았어요?", "it": false}, {"s": 2178.654, "e": 2179.829, "en": "She did.", "ko": "맞소", "it": false}, {"s": 2179.916, "e": 2183.833, "en": "That would mean she was\nvery... young.", "ko": "그럼 어머님이\n아주... 젊으셨겠네요", "it": false}, {"s": 2183.92, "e": 2189.361, "en": "She used to sit here\nand put on her makeup", "ko": "어머니는 여기 앉아서\n화장을 하곤 했소", "it": false}, {"s": 2189.448, "e": 2191.232, "en": "before she was dressed.", "ko": "옷을 입기 전에", "it": false}, {"s": 2191.363, "e": 2196.498, "en": "And I would sit right here\nand watch,", "ko": "난 바로 여기 앉아서\n지켜봤지", "it": false}, {"s": 2196.585, "e": 2199.501, "en": "and tell her when it was\njust perfect.", "ko": "그리고 완벽해지면\n말씀드렸소", "it": false}, {"s": 2223.917, "e": 2226.789, "en": "I am so glad you don't\nwear makeup.", "ko": "당신이 화장을 안 해서\n정말 다행이오", "it": false}, {"s": 2226.92, "e": 2228.791, "en": "I actually do.", "ko": "사실 하는데요", "it": false}, {"s": 2228.922, "e": 2230.619, "en": "My mother always told me", "ko": "어머니가 늘 그러셨어요", "it": false}, {"s": 2230.75, "e": 2233.405, "en": "if people can tell you're\nwearing it then you're\nwearing it wrong.", "ko": "화장한 티가 나면\n잘못한 거라고요", "it": false}, {"s": 2235.711, "e": 2237.235, "en": "Take it off.", "ko": "지우시오", "it": false}, {"s": 2239.062, "e": 2240.368, "en": "Take it off.", "ko": "지우라고 했소", "it": false}, {"s": 2240.455, "e": 2242.414, "en": "I want to see you.", "ko": "당신 얼굴을 보고 싶소", "it": false}, {"s": 2251.597, "e": 2255.601, "en": "You won't be anything like her,\nwill you?", "ko": "당신은 어머니와\n조금도 닮지 않을 테지?", "it": false}, {"s": 2259.735, "e": 2262.608, "en": "You see? Just perfect.", "ko": "보시오, 완벽하잖소", "it": false}, {"s": 2271.878, "e": 2273.271, "en": "What are you doing?", "ko": "지금 뭐 하는 거요?", "it": false}, {"s": 2273.358, "e": 2275.751, "en": "I thought that's what wives do.", "ko": "아내라면\n이렇게 하는 줄 알았어요", "it": false}, {"s": 2276.622, "e": 2278.276, "en": "Please return to your room.", "ko": "당신 방으로 돌아가시오", "it": false}, {"s": 2281.67, "e": 2283.585, "en": "Do you understand?", "ko": "알아들었소?", "it": false}, {"s": 2294.944, "e": 2297.773, "en": "I had experienced many\nbad feelings throughout my life.", "ko": "살면서 나쁜 감정은\n수없이 겪어 봤다", "it": true}, {"s": 2297.86, "e": 2300.82, "en": "Self-loathing, guilt,\ninsecurity.", "ko": "자기혐오, 죄책감,\n불안", "it": true}, {"s": 2303.083, "e": 2305.651, "en": "But never before had\nI felt this.", "ko": "하지만 이런 감정은\n처음이었다", "it": true}, {"s": 2307.13, "e": 2308.175, "en": "Shame.", "ko": "수치심", "it": true}, {"s": 2310.873, "e": 2313.441, "en": "Sir, a telegram for you.", "ko": "주인님, 전보입니다", "it": false}, {"s": 2322.015, "e": 2324.539, "en": "The war has ended.", "ko": "전쟁이 끝났군", "it": false}, {"s": 2324.626, "e": 2327.281, "en": "Perhaps this is a sign\nof good things to come.", "ko": "앞으로 좋은 일이\n생길 징조일지도 몰라요", "it": false}, {"s": 2327.412, "e": 2329.239, "en": "Perhaps it was.", "ko": "어쩌면 정말 그랬다", "it": true}, {"s": 2329.327, "e": 2331.807, "en": "A new beginning\nin a new place.", "ko": "새로운 곳에서의\n새로운 시작", "it": true}, {"s": 2331.938, "e": 2334.593, "en": "Wonderful news, sir.", "ko": "좋은 소식이네요, 주인님", "it": false}, {"s": 2334.68, "e": 2336.682, "en": "Now, I beg your pardon,", "ko": "그런데 말씀드리기 뭣하지만", "it": false}, {"s": 2336.812, "e": 2341.469, "en": "but we still need to confirm\nthe menu for the wedding party.", "ko": "피로연 메뉴를\n아직 못 정했는데요", "it": false}, {"s": 2341.556, "e": 2343.689, "en": "Proceed as I instructed.", "ko": "내가 지시한 대로 해", "it": false}, {"s": 2347.562, "e": 2349.782, "en": "Mrs. Steiner.", "ko": "스타이너 부인", "it": false}, {"s": 2349.912, "e": 2351.871, "en": "I didn't dismiss you.", "ko": "아직 가라고\n안 했어요", "it": false}, {"s": 2355.309, "e": 2357.964, "en": "As you said, this house\nand its daily business", "ko": "당신 말대로 이 집과\n이 집의 살림은", "it": false}, {"s": 2358.051, "e": 2360.488, "en": "is my responsibility now.", "ko": "이제 내 책임이에요", "it": false}, {"s": 2360.619, "e": 2364.318, "en": "And our wedding party\nwill be in this house.", "ko": "우리 피로연도\n이 집에서 열리고요", "it": false}, {"s": 2364.405, "e": 2367.843, "en": "This is about more\nthan just our wedding.", "ko": "단순히 결혼 피로연이\n문제가 아니오", "it": false}, {"s": 2367.93, "e": 2369.845, "en": "This is about how we are seen.", "ko": "우리가 어떻게 보이느냐의\n문제요", "it": false}, {"s": 2369.976, "e": 2371.804, "en": "It is about the community", "ko": "사람들한테", "it": false}, {"s": 2371.891, "e": 2373.762, "en": "understanding that they have\na new mistress.", "ko": "이 집에 새 안주인이\n왔다는 걸 알리는 일이오", "it": false}, {"s": 2373.849, "e": 2376.199, "en": "Well then, who better\nto help them understand", "ko": "그렇다면 그걸 알리는 데", "it": false}, {"s": 2376.33, "e": 2378.637, "en": "than the new mistress herself?", "ko": "새 안주인보다\n더 나은 사람이 있겠어요?", "it": false}, {"s": 2378.767, "e": 2380.378, "en": "You can trust me.", "ko": "날 믿어요", "it": false}, {"s": 2383.729, "e": 2385.731, "en": "Well, I am already late\nfor work.", "ko": "난 벌써\n출근이 늦었소", "it": false}, {"s": 2389.256, "e": 2390.257, "en": "Very well.", "ko": "좋소", "it": false}, {"s": 2397.09, "e": 2399.875, "en": "All eyes will be upon us.", "ko": "모두가 우릴 지켜볼 거요", "it": false}, {"s": 2400.006, "e": 2402.574, "en": "We must not disappoint.", "ko": "실망시켜선 안 되오", "it": false}, {"s": 2402.661, "e": 2404.924, "en": "Spare no expense.", "ko": "돈은 아끼지 마시오", "it": false}, {"s": 2409.929, "e": 2414.934, "en": "I will be changing the menu,\namong other things.", "ko": "메뉴도 바꾸고,\n다른 것도 바꿀 거예요", "it": false}, {"s": 2423.333, "e": 2424.77, "en": "And so I began.", "ko": "그렇게 나는 시작했다", "it": true}, {"s": 2424.857, "e": 2426.032, "en": "Two weeks.", "ko": "2주", "it": true}, {"s": 2426.119, "e": 2428.382, "en": "Two weeks to plan\nmy own wedding party.", "ko": "내 피로연을\n준비할 시간 2주", "it": true}, {"s": 2428.469, "e": 2432.386, "en": "Two weeks to prove that\nI knew how to be a wife.", "ko": "아내 노릇을 할 줄 안다고\n증명할 시간 2주", "it": true}, {"s": 2432.473, "e": 2434.867, "en": "Bigger, I think.", "ko": "더 크게 하죠", "it": false}, {"s": 2434.954, "e": 2436.738, "en": "Mrs. Foxworth...", "ko": "마님...", "it": false}, {"s": 2436.825, "e": 2441.351, "en": "We have never had such robust\ndisplays of opulence", "ko": "이 집에서 이렇게\n요란하게 차려 본 적은", "it": false}, {"s": 2441.482, "e": 2442.788, "en": "at this house.", "ko": "한 번도 없었는데요", "it": false}, {"s": 2442.875, "e": 2443.963, "en": "Excellent.", "ko": "잘됐네요", "it": false}, {"s": 2444.05, "e": 2445.53, "en": "Then I'm on the right path.", "ko": "그럼 제대로\n가고 있는 거예요", "it": false}, {"s": 2445.617, "e": 2451.361, "en": "While the path may be correct,\nit's the destination I question.", "ko": "길이야 맞겠지만\n어디로 가는 길인지가 걱정이네요", "it": false}, {"s": 2451.449, "e": 2456.671, "en": "A certain amount of restraint is\nnecessary to maintain decorum.", "ko": "체면을 지키려면\n적당히 절제할 줄도 알아야지요", "it": false}, {"s": 2456.802, "e": 2458.673, "en": "While I do so appreciate\nyour counsel,", "ko": "조언은 정말\n고맙지만", "it": false}, {"s": 2458.804, "e": 2461.676, "en": "Mr. Foxworth said himself\nnot to disappoint.", "ko": "남편이 직접\n실망시키지 말라고 했어요", "it": false}, {"s": 2461.763, "e": 2464.723, "en": "Yes, but I really\nmust urge caution.", "ko": "그래도 조심하시라고\n말씀은 드려야겠네요", "it": false}, {"s": 2464.81, "e": 2467.421, "en": "If you must, Mrs. Steiner,\nthan I must ask your leave.", "ko": "꼭 그래야겠다면,\n그만 나가 주세요", "it": false}, {"s": 2467.552, "e": 2469.205, "en": "But we still have much\nto plan.", "ko": "아직 준비할 게\n산더미인데요", "it": false}, {"s": 2469.336, "e": 2471.033, "en": "I am well aware.", "ko": "나도 잘 알아요", "it": false}, {"s": 2471.12, "e": 2473.558, "en": "I will be planning it,\nwithout you.", "ko": "준비는 내가 할게요,\n당신 없이", "it": false}, {"s": 2473.688, "e": 2475.603, "en": "You are excused.", "ko": "나가 봐요", "it": false}, {"s": 2483.959, "e": 2484.96, "en": "Nella?", "ko": "넬라?", "it": false}, {"s": 2487.093, "e": 2489.051, "en": "What do you think\nof orchids?", "ko": "난초는\n어떻게 생각해요?", "it": false}, {"s": 2489.138, "e": 2490.749, "en": "They're lovely,\nMrs. Foxworth.", "ko": "예쁘네요, 마님", "it": false}, {"s": 2490.836, "e": 2493.186, "en": "I quite agree.\nJoin me Nella.", "ko": "나도 그래요\n같이 가요, 넬라", "it": false}, {"s": 2500.062, "e": 2501.89, "en": "A telegram for Mrs. Foxworth.", "ko": "마님께 전보가 왔습니다", "it": false}, {"s": 2502.021, "e": 2503.501, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 2530.092, "e": 2531.093, "en": "You did it.", "ko": "해내셨어요", "it": false}, {"s": 2531.224, "e": 2532.834, "en": "We did it.", "ko": "우리가 해낸 거죠", "it": false}, {"s": 2535.141, "e": 2536.534, "en": "Are you ready?", "ko": "준비되셨어요?", "it": false}, {"s": 2537.535, "e": 2538.536, "en": "I am.", "ko": "네", "it": false}, {"s": 2568.348, "e": 2576.095, "en": "I give you all my dear wife,\nMrs. Malcolm Neil Foxworth.", "ko": "여러분께 내 아내를 소개합니다\n맬컴 닐 폭스워스 부인입니다", "it": false}, {"s": 2580.665, "e": 2581.927, "en": "Cheers!", "ko": "건배!", "it": false}, {"s": 2606.908, "e": 2608.04, "en": "What are you wearing?", "ko": "그게 무슨 꼴이오?", "it": false}, {"s": 2608.127, "e": 2609.998, "en": "It's new, do you like it?", "ko": "새로 맞췄어요, 마음에 들어요?", "it": false}, {"s": 2610.085, "e": 2612.305, "en": "You look like a common\nprostitute.", "ko": "싸구려 창녀 같구려", "it": false}, {"s": 2619.878, "e": 2622.271, "en": "I wanted to look nice\nfor you.", "ko": "당신한테 예뻐 보이고\n싶었어요", "it": false}, {"s": 2622.402, "e": 2625.187, "en": "All the other women are wearing\ndresses like this nowadays.", "ko": "요즘 여자들은 다\n이런 드레스를 입어요", "it": false}, {"s": 2625.318, "e": 2629.278, "en": "That is precisely why I did not\nmarry one of these other women.", "ko": "그래서 내가 다른 여자들과\n결혼하지 않은 거요", "it": false}, {"s": 2629.365, "e": 2633.369, "en": "Your job is not to blend in.\nYour job is to stand out.", "ko": "당신은 섞여선 안 되오\n돋보여야지", "it": false}, {"s": 2633.456, "e": 2635.589, "en": "To set an example\nto the community.", "ko": "사람들한테\n본보기가 돼야 한단 말이오", "it": false}, {"s": 2635.676, "e": 2636.938, "en": "I was trying.", "ko": "노력했어요", "it": false}, {"s": 2637.069, "e": 2640.507, "en": "And flowers, Olivia.\nDear god.", "ko": "그리고 꽃 말이오, 올리비아\n맙소사", "it": false}, {"s": 2640.638, "e": 2643.945, "en": "Orchids in Virginia?\nIt's gauche.", "ko": "버지니아에서 난초라니?\n천박하기 짝이 없소", "it": false}, {"s": 2644.032, "e": 2646.121, "en": "You said to spare no expense.", "ko": "돈 아끼지 말라면서요", "it": false}, {"s": 2646.208, "e": 2648.646, "en": "Within the boundaries\nof propriety.", "ko": "체면을 지키는\n선에서 말이오", "it": false}, {"s": 2650.822, "e": 2651.997, "en": "I wanted to close\nmy eyes,", "ko": "눈을 감고 싶었다", "it": true}, {"s": 2652.084, "e": 2655.435, "en": "bury myself in the dark earth\nand die.", "ko": "검은 흙 속에 묻혀\n죽고 싶었다", "it": true}, {"s": 2655.565, "e": 2658.656, "en": "Short of that, I just wanted\nthe party to end.", "ko": "그게 안 된다면\n피로연이 끝나기만 바랐다", "it": true}, {"s": 2665.619, "e": 2668.143, "en": "Three hours later, it did.", "ko": "세 시간 뒤, 피로연은 끝났다", "it": true}, {"s": 2699.174, "e": 2701.046, "en": "Come with me.", "ko": "따라오시오", "it": false}, {"s": 2711.404, "e": 2714.886, "en": "What kind of man\nhad I married?", "ko": "나는 대체 어떤 남자와\n결혼한 걸까?", "it": true}, {"s": 2722.981, "e": 2726.898, "en": "A monster, it turns out,\nand not a man at all.", "ko": "알고 보니 괴물이었다\n남자도 아닌", "it": true}, {"s": 2736.211, "e": 2737.735, "en": "Lie down.", "ko": "누우시오", "it": false}, {"s": 2772.508, "e": 2775.12, "en": "Please, please...\nnot the...", "ko": "제발, 제발...\n거긴...", "it": false}, {"s": 2806.238, "e": 2809.11, "en": "Good morning, Mrs. Foxworth.", "ko": "일어나셨어요, 마님", "it": false}, {"s": 2809.197, "e": 2813.158, "en": "A change in plan for today.\nI'll be visiting my father.", "ko": "오늘 일정이 바뀌었어요\n아버지를 뵈러 갈 거예요", "it": false}, {"s": 2813.245, "e": 2816.074, "en": "It seems I've made the gravest\nof miscalculations", "ko": "아무래도 내가\n크게 오판한 것 같아요", "it": false}, {"s": 2816.161, "e": 2819.512, "en": "in the most important decision\nof my life.", "ko": "내 인생에서\n가장 중요한 결정에서요", "it": false}, {"s": 2819.642, "e": 2822.08, "en": "How long will you be staying?", "ko": "얼마나 계시다\n오실 건데요?", "it": false}, {"s": 2822.21, "e": 2823.69, "en": "Indefinitely.", "ko": "무기한이요", "it": false}, {"s": 2837.095, "e": 2839.01, "en": "I am off to the office.", "ko": "난 사무실에 가오", "it": false}, {"s": 2840.446, "e": 2842.361, "en": "I trust you slept well?", "ko": "잘 잤소?", "it": false}, {"s": 2844.363, "e": 2845.364, "en": "Very.", "ko": "아주요", "it": false}, {"s": 2847.801, "e": 2849.716, "en": "Well, I will see you tonight.", "ko": "그럼 저녁에 봅시다", "it": false}, {"s": 2865.775, "e": 2868.213, "en": "Your bags are in the car\nand I'll meet you out front.", "ko": "가방은 차에 실었습니다\n현관에서 기다리겠습니다", "it": false}, {"s": 2868.3, "e": 2869.214, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 2884.446, "e": 2885.36, "en": "It's him!", "ko": "그 사람이에요!", "it": false}, {"s": 2885.447, "e": 2887.188, "en": "He's coming back!", "ko": "돌아오나 봐요!", "it": false}, {"s": 2888.973, "e": 2890.583, "en": "That's not him.", "ko": "그 사람 아니에요", "it": false}, {"s": 2903.944, "e": 2905.293, "en": "Amos?", "ko": "에이머스 오빠?", "it": false}, {"s": 2905.38, "e": 2906.425, "en": "What are you doing here?", "ko": "여긴 웬일이야?", "it": false}, {"s": 2906.512, "e": 2908.993, "en": "Looking for you.\nYou've had me worried.", "ko": "너 찾으러 왔지\n걱정했잖아", "it": false}, {"s": 2909.123, "e": 2910.255, "en": "Whatever about?", "ko": "무슨 걱정을?", "it": false}, {"s": 2910.342, "e": 2911.778, "en": "You never responded\nto my telegrams.", "ko": "내 전보에\n답장을 안 했잖아", "it": false}, {"s": 2911.865, "e": 2913.562, "en": "I never received any.", "ko": "하나도 못 받았는데", "it": false}, {"s": 2915.869, "e": 2917.653, "en": "What is it?\nWhat's wrong?", "ko": "무슨 일이야?\n뭐가 잘못됐어?", "it": false}, {"s": 2917.784, "e": 2919.22, "en": "It's your father.", "ko": "삼촌 일이야", "it": false}, {"s": 2922.441, "e": 2925.4, "en": "I'm so sorry.", "ko": "정말 유감이야", "it": false}, {"s": 2925.487, "e": 2929.013, "en": "His cold quickly turned\nto pneumonia.", "ko": "감기가 순식간에\n폐렴으로 번졌어", "it": false}, {"s": 2929.1, "e": 2931.798, "en": "There was nothing\nto be done.", "ko": "손쓸 방법이\n없었어", "it": false}, {"s": 2934.801, "e": 2937.325, "en": "I'll return with you.", "ko": "같이 돌아갈게", "it": false}, {"s": 2937.456, "e": 2938.761, "en": "I'll have to take care\nof the house,", "ko": "집도 정리해야 하고", "it": false}, {"s": 2938.892, "e": 2940.067, "en": "settle his business affairs.", "ko": "아버지 사업도\n마무리해야 하잖아", "it": false}, {"s": 2940.154, "e": 2941.373, "en": "That won't be necessary.", "ko": "그럴 필요 없어", "it": false}, {"s": 2941.46, "e": 2942.896, "en": "Of course it is.", "ko": "당연히 필요하지", "it": false}, {"s": 2942.983, "e": 2949.294, "en": "Olivia, there is no house\nor business to return to.", "ko": "올리비아, 돌아갈 집도\n사업도 없어", "it": false}, {"s": 2949.424, "e": 2953.341, "en": "When I couldn't reach you, your\nfather's debtors came to me.", "ko": "너랑 연락이 안 되니까\n채권자들이 나한테 왔어", "it": false}, {"s": 2953.472, "e": 2955.039, "en": "What debt?", "ko": "무슨 빚?", "it": false}, {"s": 2955.126, "e": 2960.305, "en": "I learned that he hid certain\nunfortunate realities from you.", "ko": "삼촌이 너한테 숨긴\n사정이 있었더라", "it": false}, {"s": 2960.392, "e": 2964.526, "en": "Your father was deep in debt.\nThe house, the business.", "ko": "빚이 엄청났어\n집이며 사업이며", "it": false}, {"s": 2964.613, "e": 2966.92, "en": "It was all taken\nupon his death.", "ko": "돌아가시자마자\n전부 넘어갔어", "it": false}, {"s": 2967.051, "e": 2972.708, "en": "No. That's not possible.\nIt's simply not possible.", "ko": "아니야, 그럴 리 없어\n절대 그럴 리 없어", "it": false}, {"s": 2972.839, "e": 2974.449, "en": "I managed to save a few\nof your things.", "ko": "네 물건은 몇 개\n겨우 건졌어", "it": false}, {"s": 2974.536, "e": 2976.974, "en": "I had the servants take them\nto your room.", "ko": "하인들한테 네 방으로\n옮겨 두라고 했어", "it": false}, {"s": 2979.628, "e": 2982.153, "en": "What am I going to do now?", "ko": "이제 난 어떡해?", "it": false}, {"s": 2985.46, "e": 2990.248, "en": "God's loving grace\ngave you a new home", "ko": "주님의 은총으로\n옛 가족을 잃기 전에", "it": false}, {"s": 2990.335, "e": 2995.166, "en": "and a new family before\nyour old one was taken.", "ko": "새집과 새 가족을\n얻었잖아", "it": false}, {"s": 3000.084, "e": 3001.999, "en": "I am truly blessed.", "ko": "난 정말 축복받았네", "it": false}, {"s": 3048.088, "e": 3050.047, "en": "Thank you for coming.", "ko": "와 줘서 고마워", "it": false}, {"s": 3050.134, "e": 3052.353, "en": "I wish it were under\nhappier circumstances.", "ko": "더 좋은 일로\n왔으면 좋았을 텐데", "it": false}, {"s": 3052.44, "e": 3054.268, "en": "Next time it will be.", "ko": "다음엔 그럴 거야", "it": false}, {"s": 3054.399, "e": 3057.184, "en": "And I promise to be a better\ncorrespondent.", "ko": "편지도 더 자주 할게", "it": false}, {"s": 3057.271, "e": 3059.534, "en": "Nella, will you tell\nMrs. Steiner that I'll be", "ko": "넬라, 스타이너 부인한테\n전해 줄래요?", "it": false}, {"s": 3059.665, "e": 3062.581, "en": "picking up my own mail from\nthe post office from now on?", "ko": "앞으로 우편물은\n내가 직접 우체국에서 찾아오겠다고", "it": false}, {"s": 3062.711, "e": 3064.191, "en": "Yes, ma'am.", "ko": "네, 마님", "it": false}, {"s": 3065.149, "e": 3070.676, "en": "Your father, he's here with you.\nHe must be so proud.", "ko": "삼촌은 여기\n너랑 함께 계셔", "it": false}, {"s": 3070.763, "e": 3075.724, "en": "His daughter,\nmistress of this great house.", "ko": "딸이 이렇게 큰 저택의\n안주인이 됐으니 자랑스러우시겠지", "it": false}, {"s": 3093.655, "e": 3097.137, "en": "But I knew he wasn't\nthere with me.", "ko": "하지만 아버지가\n내 곁에 없다는 걸 알았다", "it": true}, {"s": 3097.224, "e": 3099.096, "en": "I knew I was alone.", "ko": "나는 혼자였다", "it": true}, {"s": 3103.143, "e": 3105.972, "en": "What I didn't know\nwas how I would survive.", "ko": "내가 몰랐던 건\n어떻게 살아남느냐였다", "it": true}, {"s": 3154.02, "e": 3155.456, "en": "I'm pregnant.", "ko": "임신했어요", "it": false}, {"s": 3169.514, "e": 3170.515, "en": "Corrine.", "ko": "코린", "it": false}, {"s": 3170.645, "e": 3172.56, "en": "What?", "ko": "네?", "it": false}, {"s": 3172.647, "e": 3174.954, "en": "That's her name.", "ko": "아이 이름이오", "it": false}, {"s": 3175.041, "e": 3177.522, "en": "And if it's a boy?", "ko": "아들이면요?", "it": false}, {"s": 3181.178, "e": 3182.527, "en": "It's not.", "ko": "아들 아니오", "it": false}, {"s": 3188.881, "e": 3191.318, "en": "It was 1919,\na time when husbands", "ko": "1919년이었다\n남편이 아내의 몸을", "it": true}, {"s": 3191.405, "e": 3194.452, "en": "could legally do as they wished\nwith their wives' bodies.", "ko": "법적으로 마음대로\n할 수 있던 시절이었다", "it": true}, {"s": 3194.539, "e": 3199.021, "en": "As much as I wanted to run away,\nI was trapped.", "ko": "아무리 도망치고 싶어도\n나는 갇혀 있었다", "it": true}, {"s": 3199.108, "e": 3201.981, "en": "And so I focused\non what was good.", "ko": "그래서 좋은 것에\n집중했다", "it": true}, {"s": 3202.111, "e": 3204.201, "en": "I was having a child.", "ko": "아이가 생긴 것이다", "it": true}, {"s": 3213.427, "e": 3214.907, "en": "You're doing well.", "ko": "잘하고 계세요", "it": false}, {"s": 3214.994, "e": 3216.822, "en": "All right, push!", "ko": "자, 힘주세요!", "it": false}, {"s": 3221.261, "e": 3222.871, "en": "Congratulations!", "ko": "축하드려요!", "it": false}, {"s": 3222.958, "e": 3225.657, "en": "You have a son.", "ko": "아들이에요", "it": false}, {"s": 3225.744, "e": 3227.528, "en": "Is he healthy?", "ko": "건강한가요?", "it": false}, {"s": 3227.615, "e": 3228.573, "en": "He's perfect.", "ko": "완벽해요", "it": false}, {"s": 3242.587, "e": 3243.414, "en": "Well?", "ko": "그래서?", "it": false}, {"s": 3243.501, "e": 3245.111, "en": "It's a boy.", "ko": "아들이에요", "it": false}, {"s": 3248.636, "e": 3251.422, "en": "And how soon can we try again\nfor a girl?", "ko": "딸은 언제 다시\n가질 수 있소?", "it": false}, {"s": 3264.043, "e": 3267.046, "en": "Freedom was\nno longer an option.", "ko": "자유는 더 이상\n선택지가 아니었다", "it": true}, {"s": 3267.176, "e": 3270.963, "en": "And so I soon learned\nto want something else.", "ko": "그래서 곧 다른 것을\n바라는 법을 배웠다", "it": true}, {"s": 3271.05, "e": 3273.313, "en": "A home for my child.", "ko": "내 아이를 위한 집", "it": true}, {"s": 3273.444, "e": 3275.359, "en": "Nella?", "ko": "넬라?", "it": false}, {"s": 3275.446, "e": 3276.969, "en": "Let's begin.", "ko": "시작하죠", "it": false}, {"s": 3280.581, "e": 3284.368, "en": "Foxworth Hall was made\nof cold stone and dark wood,", "ko": "폭스워스 저택은 차가운 돌과\n어두운 나무로 지어졌지만", "it": true}, {"s": 3284.498, "e": 3286.587, "en": "but that didn't mean I couldn't\nredecorate it", "ko": "그렇다고 내가\n다시 꾸미지 못할 건 없었다", "it": true}, {"s": 3286.718, "e": 3288.633, "en": "with warmth and love.", "ko": "따뜻함과 사랑으로", "it": true}, {"s": 3291.2, "e": 3293.812, "en": "A list of candidates\nfor the governess.", "ko": "가정교사\n후보 명단이오", "it": false}, {"s": 3293.899, "e": 3295.379, "en": "No, thank you.", "ko": "아뇨, 괜찮아요", "it": false}, {"s": 3295.466, "e": 3298.12, "en": "I'll be raising my son, myself.", "ko": "내 아들은\n내가 직접 키울 거예요", "it": false}, {"s": 3300.384, "e": 3304.649, "en": "Do as you want with him.\nBut our daughter will be mine.", "ko": "아들은 마음대로 하시오\n하지만 딸은 내 것이오", "it": false}, {"s": 3308.653, "e": 3311.438, "en": "Despite the dark shadow\nof my husband,", "ko": "남편이 드리운\n어두운 그림자 속에서도", "it": true}, {"s": 3311.525, "e": 3313.832, "en": "there was still light\nto be found.", "ko": "빛은\n여전히 있었다", "it": true}, {"s": 3313.919, "e": 3316.225, "en": "Yes, I was once again expecting.", "ko": "그래, 나는 다시\n아이를 가졌다", "it": true}, {"s": 3316.356, "e": 3319.272, "en": "Another child,\nanother chance for hope.", "ko": "또 하나의 아이,\n또 하나의 희망", "it": true}, {"s": 3319.403, "e": 3322.754, "en": "Yes. She'll do just fine.", "ko": "그래요, 이 아이로 할게요", "it": false}, {"s": 3322.841, "e": 3327.628, "en": "Do you happen to have others\nin different breeds and colors?", "ko": "다른 품종이나 색깔도\n있나요?", "it": false}, {"s": 3327.759, "e": 3329.674, "en": "Mrs. Foxworth, look!", "ko": "마님, 보세요!", "it": false}, {"s": 3329.804, "e": 3333.373, "en": "And hope was all around\nif you knew where to look.", "ko": "희망은 어디에나 있었다\n볼 줄만 안다면", "it": true}, {"s": 3333.46, "e": 3335.462, "en": "It's happening!", "ko": "나와요!", "it": false}, {"s": 3338.422, "e": 3340.685, "en": "That's it.\nThere we go.", "ko": "그렇죠\n잘하고 있어요", "it": false}, {"s": 3340.815, "e": 3342.121, "en": "There we go.", "ko": "잘하고 있어요", "it": false}, {"s": 3362.054, "e": 3363.36, "en": "Do we have a girl?", "ko": "딸인가요?", "it": false}, {"s": 3363.447, "e": 3364.752, "en": "You have a son.", "ko": "아들이에요", "it": false}, {"s": 3364.839, "e": 3368.93, "en": "Another healthy son,\nMr. Foxworth.", "ko": "이번에도 건강한 아들입니다,\n폭스워스 씨", "it": false}, {"s": 3369.061, "e": 3370.367, "en": "Congratulations.", "ko": "축하드립니다", "it": false}, {"s": 3373.805, "e": 3377.156, "en": "I'm sorry to tell you this,", "ko": "말씀드리기 죄송하지만", "it": false}, {"s": 3377.243, "e": 3379.854, "en": "but you won't be able to bear\nmore children.", "ko": "더는 아이를\n가지실 수 없습니다", "it": false}, {"s": 3381.682, "e": 3382.553, "en": "Huh.", "ko": "허", "it": false}, {"s": 3386.208, "e": 3389.908, "en": "Of course, you would deny me\nthe one thing that I want.", "ko": "역시 당신은\n내가 원하는 딱 하나를 안 주는구려", "it": false}, {"s": 3408.274, "e": 3410.232, "en": "And so it was only\nto be Joel, Mal, and me.", "ko": "그렇게 우리는\n말과 조엘, 나뿐이었다", "it": true}, {"s": 3410.319, "e": 3412.713, "en": "But oh, how I loved them.", "ko": "하지만 나는\n그 아이들을 얼마나 사랑했던가", "it": true}, {"s": 3414.323, "e": 3416.021, "en": "As much as I wanted\nmore children,", "ko": "아이를 더 갖고 싶었지만", "it": true}, {"s": 3416.151, "e": 3419.894, "en": "I felt myself lucky to have\ntwo perfect boys.", "ko": "완벽한 두 아들을 둔 것만으로도\n운이 좋다고 느꼈다", "it": true}, {"s": 3421.505, "e": 3422.854, "en": "And if we had to live\nin a prison,", "ko": "감옥에서\n살아야 한다면", "it": true}, {"s": 3422.941, "e": 3426.118, "en": "I made that prison\na palace.", "ko": "나는 그 감옥을\n궁전으로 만들었다", "it": true}, {"s": 3428.947, "e": 3433.342, "en": "My father and his new bride will\nbe returning to Foxworth Hall.", "ko": "아버지가 새 아내와\n폭스워스 저택으로 돌아오신다오", "it": false}, {"s": 3433.473, "e": 3434.822, "en": "New bride?", "ko": "새 아내요?", "it": false}, {"s": 3434.953, "e": 3436.65, "en": "Apparently so.", "ko": "그렇다는군", "it": false}, {"s": 3436.737, "e": 3438.435, "en": "Did you not know he was\nto be married?", "ko": "결혼하시는 줄\n몰랐어요?", "it": false}, {"s": 3438.522, "e": 3443.962, "en": "This new wife of his, she is not\nthe mistress of this house.", "ko": "아버지의 새 아내는\n이 집 안주인이 아니오", "it": false}, {"s": 3444.092, "e": 3445.616, "en": "You are.", "ko": "당신이오", "it": false}, {"s": 3445.703, "e": 3447.531, "en": "What difference does it make\nwho is the senior Mrs. Foxworth?", "ko": "누가 큰 폭스워스 부인이든\n무슨 상관이에요?", "it": false}, {"s": 3447.618, "e": 3449.358, "en": "All the difference.", "ko": "큰 상관이 있소", "it": false}, {"s": 3449.489, "e": 3451.926, "en": "I assure you.", "ko": "분명히 말해 두겠소", "it": false}, {"s": 3452.013, "e": 3455.582, "en": "Now, I am the master of\nthis house which makes you...", "ko": "이제 이 집 주인은 나요\n그러니 당신은...", "it": false}, {"s": 3456.844, "e": 3458.672, "en": "The mistress.", "ko": "안주인이죠", "it": false}, {"s": 3458.759, "e": 3460.805, "en": "So you understand.", "ko": "그렇소, 이제 알겠구려", "it": false}, {"s": 3462.807, "e": 3464.939, "en": "Do you understand?!", "ko": "알아들었소?!", "it": false}, {"s": 3465.81, "e": 3466.941, "en": "I do.", "ko": "네", "it": false}, {"s": 3468.16, "e": 3469.161, "en": "Good.", "ko": "됐소", "it": false}, {"s": 3481.042, "e": 3482.957, "en": "Remember who you are.", "ko": "네가 누군지 기억해", "it": false}, {"s": 3483.044, "e": 3487.353, "en": "Wait. Are you Olivia\nor am I?", "ko": "잠깐, 네가 올리비아야?\n내가 올리비아야?", "it": false}, {"s": 3504.718, "e": 3506.024, "en": "Malcolm, my boy.", "ko": "맬컴, 아들아", "it": false}, {"s": 3509.027, "e": 3510.028, "en": "Malcolm.", "ko": "맬컴", "it": false}, {"s": 3511.943, "e": 3513.684, "en": "Ah, Mrs. Steiner.", "ko": "아, 스타이너 부인", "it": false}, {"s": 3515.207, "e": 3517.122, "en": "Aren't you a sight\nfor sore eyes.", "ko": "보기만 해도\n반갑구먼", "it": false}, {"s": 3517.252, "e": 3519.211, "en": "Always good to have you home,\nMr. Foxworth.", "ko": "오셔서 얼마나 반가운지 몰라요,\n주인어른", "it": false}, {"s": 3519.298, "e": 3521.518, "en": "Good to be home.", "ko": "집에 오니 좋구나", "it": false}, {"s": 3522.519, "e": 3523.824, "en": "Alicia.", "ko": "앨리샤", "it": false}, {"s": 3523.911, "e": 3527.088, "en": "Come say hello to your stepson,\nMalcolm.", "ko": "와서 인사해,\n당신 의붓아들 맬컴이야", "it": false}, {"s": 3527.175, "e": 3530.048, "en": "Malcolm, your stepmother,\nAlicia.", "ko": "맬컴, 네 새어머니\n앨리샤다", "it": false}, {"s": 3533.704, "e": 3535.27, "en": "Now, I know what\nyou're thinking.", "ko": "무슨 생각 하는지\n다 안다", "it": false}, {"s": 3535.401, "e": 3537.708, "en": "You didn't know that we were\nwith child.", "ko": "아이가 생긴 줄은\n몰랐겠지", "it": false}, {"s": 3541.929, "e": 3549.937, "en": "This is Mrs. Foxworth.\nMrs. Malcolm Neil Foxworth.", "ko": "이쪽은 폭스워스 부인입니다\n맬컴 닐 폭스워스 부인", "it": false}, {"s": 3550.024, "e": 3550.982, "en": "Olivia.", "ko": "올리비아", "it": false}, {"s": 3551.939, "e": 3554.986, "en": "Olivia, welcome to our family.", "ko": "올리비아, 우리 가족이 된 걸\n환영해요", "it": false}, {"s": 3555.116, "e": 3557.249, "en": "I... why didn't you tell me\nhe was married?", "ko": "저기... 아들이 결혼한 걸\n왜 말 안 했어요?", "it": false}, {"s": 3557.379, "e": 3558.772, "en": "Simply I had no idea, my love.", "ko": "나도 전혀\n몰랐다니까, 여보", "it": false}, {"s": 3560.469, "e": 3561.819, "en": "He wrote only of business.", "ko": "편지엔 사업 얘기뿐이었어", "it": false}, {"s": 3561.906, "e": 3563.472, "en": "Well, not only are you married", "ko": "결혼만 한 게 아니라", "it": false}, {"s": 3563.56, "e": 3566.04, "en": "you've also made me\na grandfather.", "ko": "날 할아버지로\n만들어 줬구나", "it": false}, {"s": 3566.171, "e": 3567.128, "en": "Why didn't you tell me?", "ko": "왜 말 안 했느냐?", "it": false}, {"s": 3567.215, "e": 3569.174, "en": "Isn't it amusing\nhow one's priorities", "ko": "사람의 우선순위란", "it": false}, {"s": 3569.261, "e": 3571.742, "en": "reveal themselves in the most\nunusual ways.", "ko": "참 뜻밖의 데서\n드러나네요", "it": false}, {"s": 3571.829, "e": 3573.352, "en": "Yes. Well, it seems we have\nboth failed", "ko": "그러고 보니 우리 둘 다", "it": false}, {"s": 3573.439, "e": 3578.923, "en": "to disclose certain details....\nabout personal affairs.", "ko": "사적인 일은\n좀 숨긴 셈이네요", "it": false}, {"s": 3579.793, "e": 3580.794, "en": "Mrs. Foxworth.", "ko": "폭스워스 부인", "it": false}, {"s": 3580.881, "e": 3582.056, "en": "Yes?", "ko": "네?", "it": false}, {"s": 3585.146, "e": 3587.758, "en": "Dinner will be served shortly.", "ko": "곧 저녁 차려 드릴게요", "it": false}, {"s": 3590.63, "e": 3592.153, "en": "How do you two do it?", "ko": "두 분은 어떻게 그래요?", "it": false}, {"s": 3592.284, "e": 3593.502, "en": "Excuse me?", "ko": "네?", "it": false}, {"s": 3593.59, "e": 3595.461, "en": "Sit so far apart from\none another?", "ko": "그렇게 멀찍이\n떨어져 앉아서요", "it": false}, {"s": 3598.159, "e": 3599.639, "en": "We're still on our honeymoon.", "ko": "우린 아직 신혼이잖니", "it": false}, {"s": 3599.726, "e": 3601.162, "en": "When we've been married\nas long as they have", "ko": "우리도 저 애들만큼\n결혼 생활을 하고 나면", "it": false}, {"s": 3601.249, "e": 3602.816, "en": "we'll be sitting\nin separate rooms.", "ko": "각방에 앉아\n있겠지", "it": false}, {"s": 3602.947, "e": 3603.73, "en": "Never.", "ko": "절대 안 그래요", "it": false}, {"s": 3605.123, "e": 3607.516, "en": "Where exactly did you go\nfor your honeymoon?", "ko": "신혼여행은 정확히\n어디로 다녀오셨어요?", "it": false}, {"s": 3607.604, "e": 3610.824, "en": "I promised my bride\na world tour,", "ko": "신부한테 세계 일주를\n약속했고", "it": false}, {"s": 3610.955, "e": 3613.784, "en": "and a world tour she got.\nSix continents.", "ko": "약속대로 세계 일주를 했지\n여섯 대륙을", "it": false}, {"s": 3613.871, "e": 3616.177, "en": "Nearly two years.", "ko": "거의 2년 동안", "it": false}, {"s": 3616.264, "e": 3617.788, "en": "How nice.", "ko": "좋으셨겠네요", "it": false}, {"s": 3617.875, "e": 3620.573, "en": "Following through on promises\nof travel.", "ko": "여행 약속을\n다 지키시다니", "it": false}, {"s": 3622.009, "e": 3626.666, "en": "It's a long time to be away\nfrom one's responsibilities.", "ko": "책임을 내팽개치기엔\n긴 시간이군요", "it": false}, {"s": 3626.797, "e": 3629.843, "en": "-Take it from an old man.\n-You are not old.", "ko": "-늙은이 말 들어라\n-늙긴 누가 늙었다고요", "it": false}, {"s": 3629.93, "e": 3633.76, "en": "Life is too short to be focused\nsolely on responsibilities.", "ko": "책임만 붙들고 살기엔\n인생이 너무 짧다", "it": false}, {"s": 3633.847, "e": 3635.327, "en": "And too long to bear\nthe burden", "ko": "남이 저지른 일의\n뒷감당을 하며", "it": false}, {"s": 3635.414, "e": 3637.503, "en": "of another's mishandling\nof them.", "ko": "살기엔 너무 길고요", "it": false}, {"s": 3639.113, "e": 3640.854, "en": "Well, like everything else\nin life,", "ko": "글쎄, 인생의\n다른 모든 일처럼", "it": false}, {"s": 3640.941, "e": 3643.683, "en": "is moderation not the key?", "ko": "중용이 비결\n아닐까요?", "it": false}, {"s": 3643.814, "e": 3646.643, "en": "Wise beyond her years,\nis she not?", "ko": "나이보다\n현명하지 않니?", "it": false}, {"s": 3654.041, "e": 3657.436, "en": "Yes. Well, you will have\nto tell us all about it.", "ko": "네, 그럼\n다 얘기해 주셔야겠네요", "it": false}, {"s": 3657.523, "e": 3659.09, "en": "Your trip that is.", "ko": "여행 얘기요", "it": false}, {"s": 3659.22, "e": 3661.57, "en": "Oh, we wouldn't want to bore you\nwith the details.", "ko": "지루한 얘기로\n괴롭히고 싶진 않은데요", "it": false}, {"s": 3661.658, "e": 3664.922, "en": "Oh, on the contrary.\nWe want to listen.", "ko": "천만에요\n듣고 싶어요", "it": false}, {"s": 3665.052, "e": 3666.924, "en": "Don't we, Olivia?", "ko": "그렇지, 올리비아?", "it": false}, {"s": 3667.011, "e": 3670.449, "en": "As long as you will be the one\nwho tells it.", "ko": "당신이 얘기해\n준다면요", "it": false}, {"s": 3670.536, "e": 3672.843, "en": "Oh, how sweet.", "ko": "어머, 다정하기도 해라", "it": false}, {"s": 3675.062, "e": 3678.587, "en": "Well, let's hear it,\nperhaps over dessert.", "ko": "그럼 들어 보자\n디저트라도 먹으면서", "it": false}, {"s": 3678.718, "e": 3680.546, "en": "Alfresco?", "ko": "바깥에서 먹을까?", "it": false}, {"s": 3680.633, "e": 3682.548, "en": "What a wonderful idea.", "ko": "좋은 생각이에요", "it": false}, {"s": 3687.684, "e": 3690.556, "en": "See to it that the servants\nbring dessert to the veranda.", "ko": "하인들한테 디저트를\n베란다로 내오라고 하시오", "it": false}, {"s": 3690.687, "e": 3692.34, "en": "Understand?", "ko": "알아들었소?", "it": false}, {"s": 3692.427, "e": 3693.515, "en": "Yes.", "ko": "네", "it": false}, {"s": 3700.479, "e": 3703.569, "en": "\"Sit down please, sir.\"\nThe gondolier pleaded.", "ko": "\"손님, 제발 앉으세요\"\n곤돌라 사공이 애원했지", "it": false}, {"s": 3703.656, "e": 3705.049, "en": "You know your father,", "ko": "아버님 알잖니", "it": false}, {"s": 3705.179, "e": 3706.572, "en": "he'd had a great deal of wine", "ko": "와인을\n잔뜩 마시고는", "it": false}, {"s": 3706.659, "e": 3708.226, "en": "and thought he could walk\na tightrope.", "ko": "줄타기라도 할 수\n있다고 생각하신 거야", "it": false}, {"s": 3708.313, "e": 3710.619, "en": "I simply wanted to navigate.", "ko": "난 그냥 노를\n저어 보고 싶었을 뿐이야", "it": false}, {"s": 3710.75, "e": 3712.534, "en": "And then what do\nyou think happened?", "ko": "그래서 어떻게\n됐을 것 같아?", "it": false}, {"s": 3712.621, "e": 3713.884, "en": "He fell in.", "ko": "빠지셨어요?", "it": false}, {"s": 3717.148, "e": 3718.845, "en": "Well yes, exactly that.", "ko": "그래, 바로 그거야", "it": false}, {"s": 3718.976, "e": 3721.108, "en": "He fell in and it was complete\nchaos all around.", "ko": "물에 빠져서\n아주 난리가 났지", "it": false}, {"s": 3722.675, "e": 3724.721, "en": "Have you ever been to Venice?", "ko": "베네치아에\n가 본 적 있어요?", "it": false}, {"s": 3724.808, "e": 3726.287, "en": "I'm afraid not.", "ko": "아쉽게도 없어요", "it": false}, {"s": 3726.374, "e": 3728.463, "en": "Oh, but you must go.", "ko": "어머, 꼭 가 봐야 해요", "it": false}, {"s": 3728.55, "e": 3730.378, "en": "You can't stay locked up\nin this castle.", "ko": "이 성에만\n갇혀 있으면 안 돼요", "it": false}, {"s": 3730.465, "e": 3732.641, "en": "Are you keeping your princess\nlocked in the tower?", "ko": "공주님을 탑에\n가둬 두는 거야?", "it": false}, {"s": 3732.772, "e": 3736.645, "en": "You do not yet know my wife.\nShe is no princess.", "ko": "당신은 아직 내 아내를 모르오\n공주 같은 여자가 아니오", "it": false}, {"s": 3736.776, "e": 3738.604, "en": "Then a queen.", "ko": "그럼 여왕님이겠네", "it": false}, {"s": 3738.691, "e": 3740.867, "en": "Shall we my love? Hmm?", "ko": "이제 갈까, 여보?", "it": false}, {"s": 3740.954, "e": 3744.262, "en": "I think it might be time\nto head to Bedfordshire.", "ko": "슬슬 잠자리에\n들 시간인 것 같구나", "it": false}, {"s": 3744.349, "e": 3746.177, "en": "Mrs. Steiner will show you\nto your rooms.", "ko": "스타이너 부인이\n방으로 안내해 드릴 거예요", "it": false}, {"s": 3746.264, "e": 3749.136, "en": "Oh, that won't be necessary.\nWe'll be sharing.", "ko": "그럴 필요 없어요\n같이 쓸 거예요", "it": false}, {"s": 3749.267, "e": 3751.095, "en": "Sharing what?", "ko": "뭘 같이 쓴다는 거요?", "it": false}, {"s": 3751.225, "e": 3753.401, "en": "We'll be staying\nin the same room.", "ko": "같은 방에서\n지낼 거예요", "it": false}, {"s": 3757.492, "e": 3759.668, "en": "Really, father?", "ko": "정말이세요, 아버지?", "it": false}, {"s": 3759.756, "e": 3761.627, "en": "Oh, don't be such a bore, son.", "ko": "따분하게 굴지 마라, 아들아", "it": false}, {"s": 3761.714, "e": 3764.978, "en": "I just couldn't bear to be away\nfrom him all night.", "ko": "하룻밤도 이이랑\n떨어져 있을 수가 없어서요", "it": false}, {"s": 3765.065, "e": 3766.414, "en": "Well, then it's settled.", "ko": "그럼 정해졌네요", "it": false}, {"s": 3766.501, "e": 3768.677, "en": "Thank you so much\nfor a lovely evening.", "ko": "덕분에 즐거운\n저녁이었어요", "it": false}, {"s": 3768.808, "e": 3771.724, "en": "I cannot wait to do it\nall over again tomorrow.", "ko": "내일도 또\n이러고 싶네요", "it": false}, {"s": 3771.811, "e": 3774.596, "en": "Their joy only reminded\nme of my pain.", "ko": "그들의 기쁨은 내 고통을\n일깨울 뿐이었다", "it": true}, {"s": 3774.683, "e": 3776.468, "en": "A pain that would be\nthere tomorrow", "ko": "그 고통은\n내일도", "it": true}, {"s": 3776.598, "e": 3778.47, "en": "and all the days after that.", "ko": "그다음 날도\n계속될 것이었다", "it": true}, {"s": 3782.866, "e": 3783.867, "en": "Even in the darkest\nof nights,", "ko": "가장 어두운\n밤에도", "it": true}, {"s": 3783.997, "e": 3785.651, "en": "there was the promise\nof light to come.", "ko": "빛은 찾아온다는\n약속이 있었다", "it": true}, {"s": 3785.738, "e": 3789.655, "en": "So, I focused on that light,\nmy children.", "ko": "그래서 나는 그 빛에\n집중했다, 내 아이들에게", "it": true}, {"s": 3791.352, "e": 3792.919, "en": "I hope it's okay.", "ko": "괜찮으면 좋겠어요", "it": false}, {"s": 3794.442, "e": 3795.617, "en": "They're just so beautiful.", "ko": "너무 예뻐서요", "it": false}, {"s": 3795.748, "e": 3797.054, "en": "It's fine.", "ko": "괜찮아요", "it": false}, {"s": 3798.925, "e": 3802.624, "en": "I don't want to be,\nMrs. Foxworth.", "ko": "난 폭스워스 부인이\n되고 싶지 않아요", "it": false}, {"s": 3802.755, "e": 3807.281, "en": "Not, not in that way,\nat least.", "ko": "아니, 적어도\n그런 의미로는요", "it": false}, {"s": 3807.368, "e": 3810.11, "en": "You are mistress of this house\nand thank goodness you are,", "ko": "이 집 안주인은 당신이에요\n정말 다행이죠", "it": false}, {"s": 3810.241, "e": 3812.33, "en": "because I could never do it.", "ko": "나라면 절대\n못 했을 테니까요", "it": false}, {"s": 3812.46, "e": 3815.942, "en": "I am overwhelmed just thinking\nabout it.", "ko": "생각만 해도\n벅차요", "it": false}, {"s": 3816.029, "e": 3819.511, "en": "The only thing I ask of you\nis your friendship.", "ko": "내가 바라는 건\n당신 우정뿐이에요", "it": false}, {"s": 3819.641, "e": 3824.385, "en": "I've only been here a day\nand I am already lonely.", "ko": "여기 온 지 하루밖에 안 됐는데\n벌써 외로워요", "it": false}, {"s": 3824.472, "e": 3828.825, "en": "Well, it took you a day longer\nthan it took me when I arrived.", "ko": "난 여기 왔을 때\n하루 더 빨리 외로웠는데요", "it": false}, {"s": 3828.955, "e": 3833.09, "en": "I suppose I could use\na friend as well.", "ko": "나도 친구가\n필요했던 것 같아요", "it": false}, {"s": 3833.22, "e": 3834.569, "en": "Then it's settled.", "ko": "그럼 정해졌네요", "it": false}, {"s": 3834.7, "e": 3838.008, "en": "We're in this together.\nThe two Mrs. Foxworths.", "ko": "우리 같은 편이에요\n두 폭스워스 부인", "it": false}, {"s": 3838.095, "e": 3840.358, "en": "A word of advice.", "ko": "조언 하나 할게요", "it": false}, {"s": 3840.488, "e": 3844.536, "en": "Malcolm absolutely\nloathes hydrangeas.", "ko": "맬컴은 수국을\n질색해요", "it": false}, {"s": 3844.666, "e": 3847.017, "en": "-Oh.\n-Let's cut a few more.", "ko": "-어머\n-몇 송이 더 꺾어요", "it": false}, {"s": 3854.154, "e": 3855.982, "en": "What are these doing here?", "ko": "이게 왜 여기 있소?", "it": false}, {"s": 3859.899, "e": 3862.38, "en": "Olivia, you know how I feel\nabout this.", "ko": "올리비아, 내가 이걸\n어떻게 생각하는지 알잖소", "it": false}, {"s": 3865.122, "e": 3866.993, "en": "I thought you understood.", "ko": "알아들은 줄 알았는데", "it": false}, {"s": 3869.343, "e": 3871.258, "en": "I brought them in.", "ko": "내가 가져왔어요", "it": false}, {"s": 3871.345, "e": 3873.87, "en": "I can take them away\nif you'd like.", "ko": "원하면\n치울게요", "it": false}, {"s": 3873.957, "e": 3874.871, "en": "No.", "ko": "아니요", "it": false}, {"s": 3876.742, "e": 3878.962, "en": "Maybe they're not so bad", "ko": "그렇게 나쁘지\n않을지도 모르겠군", "it": false}, {"s": 3879.092, "e": 3883.009, "en": "when someone with an eye\nfor beauty picks them.", "ko": "아름다움을 볼 줄 아는\n사람이 꺾어 온 거라면", "it": false}, {"s": 3883.14, "e": 3885.969, "en": "As my affection for\nmy stepmother-in-law grew,", "ko": "시어머니와의 정이\n깊어질수록", "it": true}, {"s": 3886.056, "e": 3889.581, "en": "so did my husband's interest\nin his stepmother.", "ko": "남편도\n새어머니에게 끌렸다", "it": true}, {"s": 3891.191, "e": 3893.063, "en": "But things were soon\nto change.", "ko": "하지만 상황은 곧\n바뀌었다", "it": true}, {"s": 3898.068, "e": 3899.852, "en": "One more. One more.", "ko": "한 번 더요, 한 번 더", "it": false}, {"s": 3903.769, "e": 3905.553, "en": "Congratulations.", "ko": "축하드려요", "it": false}, {"s": 3905.64, "e": 3907.86, "en": "You have a son.", "ko": "아들이에요", "it": false}, {"s": 3909.079, "e": 3910.907, "en": "Congratulations, ma'am.", "ko": "축하드립니다, 사모님", "it": false}, {"s": 3912.082, "e": 3913.083, "en": "Oh.", "ko": "어머", "it": false}, {"s": 3921.961, "e": 3922.919, "en": "Garland!", "ko": "갈랜드!", "it": false}, {"s": 3926.966, "e": 3930.622, "en": "It's a boy.\nA perfect boy.", "ko": "아들이에요\n완벽한 아들", "it": false}, {"s": 3930.752, "e": 3933.233, "en": "Oh, my son.", "ko": "오, 내 아들", "it": false}, {"s": 3933.32, "e": 3936.584, "en": "My Christopher.\nWhy look at you.", "ko": "우리 크리스토퍼\n이것 좀 봐", "it": false}, {"s": 3938.108, "e": 3940.762, "en": "Oh my love, my love.", "ko": "오, 여보, 여보", "it": false}, {"s": 3940.849, "e": 3943.156, "en": "I'll give you two some time.", "ko": "두 분만의 시간을\n드릴게요", "it": false}, {"s": 3943.287, "e": 3945.028, "en": "As a family.", "ko": "가족끼리요", "it": false}, {"s": 3945.115, "e": 3948.292, "en": "Thank you for everything.", "ko": "정말 다 고마워요", "it": false}, {"s": 3967.441, "e": 3969.095, "en": "Mrs. Foxworth, do you have\na moment?", "ko": "마님, 잠깐\n시간 괜찮으세요?", "it": false}, {"s": 3969.182, "e": 3971.576, "en": "What is it, Nella?\nIs there something wrong?", "ko": "무슨 일이에요, 넬라?\n뭐가 잘못됐어요?", "it": false}, {"s": 3973.839, "e": 3975.536, "en": "It's the other Mrs. Foxworth.", "ko": "다른 폭스워스 부인\n일이에요", "it": false}, {"s": 3975.667, "e": 3977.843, "en": "I see how fond of her\nyou've become.", "ko": "마님께서 그분을 아끼시는 걸\n알고 있어요", "it": false}, {"s": 3977.974, "e": 3984.458, "en": "Yes. It's good to have a friend,\nanother friend.", "ko": "그래요, 친구가 생겨서 좋아요\n또 한 명의 친구가", "it": false}, {"s": 3984.545, "e": 3985.851, "en": "She's recovered so beautifully", "ko": "그분이 참 빨리\n회복하셨지요", "it": false}, {"s": 3985.938, "e": 3988.158, "en": "after the birth of Christopher\nlast year.", "ko": "작년에 크리스토퍼를\n낳고 나서요", "it": false}, {"s": 3988.245, "e": 3989.289, "en": "Yes.", "ko": "그래요", "it": false}, {"s": 3989.42, "e": 3992.118, "en": "That is the natural course\nof things.", "ko": "그게 자연스러운\n일이죠", "it": false}, {"s": 3993.598, "e": 3995.861, "en": "Is there something I can\nhelp you with?", "ko": "내가 뭐\n도와줄 게 있어요?", "it": false}, {"s": 3997.08, "e": 4000.866, "en": "Mr. Foxworth enjoys\nbeautiful things.", "ko": "주인님은 아름다운 걸\n좋아하세요", "it": false}, {"s": 4000.997, "e": 4003.086, "en": "Houses.", "ko": "집이며", "it": false}, {"s": 4003.173, "e": 4005.958, "en": "Art.", "ko": "그림이며", "it": false}, {"s": 4006.045, "e": 4007.09, "en": "Women.", "ko": "여자며", "it": false}, {"s": 4008.961, "e": 4012.486, "en": "Like I said. The other\nMrs. Foxworth,", "ko": "말씀드린 대로,\n다른 폭스워스 부인께서", "it": false}, {"s": 4012.573, "e": 4016.664, "en": "she's returned to her\nold self so quickly.", "ko": "너무 빨리 예전 모습을\n되찾으셨어요", "it": false}, {"s": 4016.795, "e": 4019.537, "en": "-Look out for her.\n-I will.", "ko": "-그분을 지켜 주세요\n-그럴게요", "it": false}, {"s": 4038.077, "e": 4039.992, "en": "It's even worse in here.", "ko": "여긴 더 덥네요", "it": false}, {"s": 4040.079, "e": 4042.429, "en": "Are Virginia summers\nalways this hot?", "ko": "버지니아 여름은\n늘 이렇게 더워요?", "it": false}, {"s": 4042.56, "e": 4044.823, "en": "Foxworth Hall is\nuniquely positioned", "ko": "폭스워스 저택은\n아주 독특하게 지어져서", "it": false}, {"s": 4044.91, "e": 4048.348, "en": "as an inferno in the summer\nand an icebox in the winter.", "ko": "여름엔 불지옥,\n겨울엔 얼음 창고예요", "it": false}, {"s": 4048.435, "e": 4051.786, "en": "Yet another of its remarkable\ngifts to us.", "ko": "우리한테 주는\n또 하나의 놀라운 선물이죠", "it": false}, {"s": 4051.917, "e": 4054.224, "en": "Well, I just put Christopher\ndown for his nap.", "ko": "크리스토퍼를 막\n낮잠 재웠어요", "it": false}, {"s": 4054.311, "e": 4056.487, "en": "Would you like to go\nfor a swim in the lake?", "ko": "호수에 수영하러\n갈래요?", "it": false}, {"s": 4056.574, "e": 4058.358, "en": "You go and cool off\nfor us both.", "ko": "우리 둘 몫까지\n시원하게 하고 와요", "it": false}, {"s": 4058.489, "e": 4060.578, "en": "I'd like to finish up here.", "ko": "난 이것 좀\n마무리할게요", "it": false}, {"s": 4060.665, "e": 4062.014, "en": "Of course.", "ko": "그래요", "it": false}, {"s": 4098.485, "e": 4100.096, "en": "Come in, Nella.", "ko": "들어와요, 넬라", "it": false}, {"s": 4103.621, "e": 4105.884, "en": "Good evening, Mrs. Foxworth.", "ko": "좋은 저녁이에요, 마님", "it": false}, {"s": 4106.014, "e": 4109.67, "en": "I'll be helping you until\nwe find Nella's replacement.", "ko": "넬라 대신할 사람 구할 때까지\n내가 시중들게요", "it": false}, {"s": 4109.801, "e": 4112.108, "en": "What are you talking about?\nWhere has she gone?", "ko": "무슨 소리예요?\n넬라는 어디 갔어요?", "it": false}, {"s": 4113.413, "e": 4115.981, "en": "Why Mr. Foxworth asked her\nto leave.", "ko": "아니, 주인님이\n내보내셨잖아요", "it": false}, {"s": 4116.112, "e": 4117.025, "en": "Did he?", "ko": "그 사람이?", "it": false}, {"s": 4117.113, "e": 4119.071, "en": "And why might he have\ndone that?", "ko": "왜 그랬을까요?", "it": false}, {"s": 4119.158, "e": 4121.334, "en": "I couldn't say, Mrs. Foxworth.", "ko": "내가 그걸 어찌 알겠어요, 마님", "it": false}, {"s": 4121.421, "e": 4124.25, "en": "Interesting how you're suddenly\nat a loss for words", "ko": "평소엔 그렇게 술술 나오던 말이", "it": false}, {"s": 4124.337, "e": 4127.297, "en": "when they usually come\nso very easily to you.", "ko": "갑자기 막히나 보네요", "it": false}, {"s": 4134.956, "e": 4136.001, "en": "Malcolm?", "ko": "맬컴?", "it": false}, {"s": 4143.704, "e": 4145.88, "en": "No!", "ko": "안 돼!", "it": false}, {"s": 4146.011, "e": 4147.143, "en": "What happened?", "ko": "무슨 일이에요?", "it": false}, {"s": 4147.273, "e": 4149.145, "en": "Whatever it is, it's none\nof your concern.", "ko": "무슨 일이든\n당신이 상관할 바 아니오", "it": false}, {"s": 4154.324, "e": 4155.76, "en": "Oh, my god!", "ko": "세상에!", "it": false}, {"s": 4157.327, "e": 4160.286, "en": "Call the doctor!\nCall the doctor!", "ko": "의사 불러요!\n의사 불러요!", "it": false}, {"s": 4160.417, "e": 4163.507, "en": "Oh my god, my love.", "ko": "세상에, 여보", "it": false}, {"s": 4163.594, "e": 4165.117, "en": "I'll call.", "ko": "내가 할게요", "it": false}, {"s": 4166.684, "e": 4168.294, "en": "What happened?", "ko": "무슨 일이에요?", "it": false}, {"s": 4168.381, "e": 4172.777, "en": "My love, please wake up.\nPlease. Don't leave me.", "ko": "여보, 제발 일어나요\n제발, 날 두고 가지 마요", "it": false}, {"s": 4199.325, "e": 4202.502, "en": "Hopefully, we'll have some\nanswers for the poor woman", "ko": "부검을 하면\n저 가엾은 분께", "it": false}, {"s": 4202.633, "e": 4204.548, "en": "after the autopsy.", "ko": "뭐라도 답을 드릴 수\n있을 겁니다", "it": false}, {"s": 4209.161, "e": 4210.684, "en": "The thing is, Doctor.", "ko": "그런데요, 선생님", "it": false}, {"s": 4210.771, "e": 4216.212, "en": "Well, Mrs. Foxworth has\nalready been through so much.", "ko": "폭스워스 부인이 이미\n너무 많은 일을 겪으셨잖아요", "it": false}, {"s": 4216.299, "e": 4219.476, "en": "I don't think she could handle\nthe idea of an autopsy.", "ko": "부검까지는\n감당 못 하실 것 같아요", "it": false}, {"s": 4219.563, "e": 4222.957, "en": "You see, would you be so kind", "ko": "그러니 부디", "it": false}, {"s": 4223.044, "e": 4226.613, "en": "not to put her through\neven more trauma?", "ko": "그분께 더 큰 상처는\n주지 말아 주시겠어요?", "it": false}, {"s": 4226.744, "e": 4229.225, "en": "I'm sure Mr. Foxworth and I\nwould find a way", "ko": "남편과 제가\n병원에 꼭", "it": false}, {"s": 4229.312, "e": 4231.662, "en": "to show our appreciation\nto your hospital.", "ko": "감사의 뜻을\n표하겠습니다", "it": false}, {"s": 4231.749, "e": 4235.579, "en": "I hear they're raising money\nfor a new emergent patient area.", "ko": "새 응급 병동 기금을\n모으고 있다고 들었어요", "it": false}, {"s": 4238.103, "e": 4239.104, "en": "Certainly.", "ko": "물론이죠", "it": false}, {"s": 4241.498, "e": 4243.064, "en": "-Thank you.\n-Thank you.", "ko": "-감사합니다\n-감사합니다", "it": false}, {"s": 4244.588, "e": 4247.547, "en": "-Good night, Mrs. Foxworth.\n-Good night.", "ko": "-안녕히 가세요, 부인\n-안녕히 가세요", "it": false}, {"s": 4257.949, "e": 4258.95, "en": "Olivia.", "ko": "올리비아", "it": false}, {"s": 4271.528, "e": 4276.707, "en": "And so Foxworth Hall\nclaimed its first victim.", "ko": "그렇게 폭스워스 저택은\n첫 번째 희생자를 삼켰다", "it": true}, {"s": 4276.794, "e": 4281.799, "en": "The only question was,\nwho would be next?", "ko": "남은 질문은 하나였다\n다음은 누구인가", "it": true}, {"s": 4283.627, "e": 4288.98, "en": "After a few months, it\nappeared to be Alicia.", "ko": "몇 달 뒤, 그건\n앨리샤인 것 같았다", "it": true}, {"s": 4290.198, "e": 4293.55, "en": "If you won't touch\nyour food downstairs", "ko": "아래층에서\n식사를 안 하겠다면", "it": false}, {"s": 4293.68, "e": 4296.64, "en": "I thought maybe you'd consider\nbreakfast in bed.", "ko": "침대에서 아침을\n먹는 건 어떨까 했어요", "it": false}, {"s": 4298.598, "e": 4301.688, "en": "Just a few more days of quiet,\nplease.", "ko": "며칠만 더 조용히\n있게 해 줘요", "it": false}, {"s": 4301.819, "e": 4305.823, "en": "It's been over four months\nof quiet.", "ko": "벌써 넉 달 넘게\n조용히 있었어요", "it": false}, {"s": 4305.91, "e": 4308.391, "en": "Olivia. My husband is dead.", "ko": "올리비아, 남편이 죽었어요", "it": false}, {"s": 4308.478, "e": 4310.654, "en": "But your son is not.", "ko": "하지만 아들은 살아 있잖아요", "it": false}, {"s": 4313.439, "e": 4314.832, "en": "He needs you.", "ko": "아이한텐 당신이 필요해요", "it": false}, {"s": 4316.007, "e": 4317.487, "en": "You don't understand.", "ko": "당신은 몰라요", "it": false}, {"s": 4317.574, "e": 4320.141, "en": "No, I don't.", "ko": "그래요, 몰라요", "it": false}, {"s": 4320.272, "e": 4322.448, "en": "And I can't unless\nyou tell me.", "ko": "말해 주지 않으면\n알 수가 없어요", "it": false}, {"s": 4322.579, "e": 4324.668, "en": "Help me understand.", "ko": "이해할 수 있게 해 줘요", "it": false}, {"s": 4326.147, "e": 4328.367, "en": "You must know.", "ko": "알고 있잖아요", "it": false}, {"s": 4328.454, "e": 4330.848, "en": "Surely you sensed it.", "ko": "분명 눈치챘을 거예요", "it": false}, {"s": 4333.546, "e": 4335.331, "en": "Must I say it?", "ko": "꼭 내 입으로 말해야 해요?", "it": false}, {"s": 4342.076, "e": 4344.035, "en": "Malcolm attacked me.", "ko": "맬컴이 날 덮쳤어요", "it": false}, {"s": 4345.906, "e": 4350.171, "en": "He came in here and he forced\nhimself on me.", "ko": "여기 들어와서\n억지로 날...", "it": false}, {"s": 4350.258, "e": 4354.306, "en": "I tried to resist\nbut he wouldn't stop.", "ko": "저항했지만\n멈추지 않았어요", "it": false}, {"s": 4354.437, "e": 4357.222, "en": "He just tore my nightgown\nwhen Garland walked in.", "ko": "잠옷을 찢고 있는데\n갈랜드가 들어왔어요", "it": false}, {"s": 4359.442, "e": 4364.403, "en": "Garland swung at Malcolm\nbut he was no match for him.", "ko": "갈랜드가 맬컴한테 주먹을 날렸지만\n상대가 안 됐어요", "it": false}, {"s": 4364.534, "e": 4367.841, "en": "But pinned him up against\nthe wall and...", "ko": "맬컴이 그이를\n벽에 밀어붙이고...", "it": false}, {"s": 4371.802, "e": 4373.543, "en": "held him there.", "ko": "그대로 붙잡고 있었어요", "it": false}, {"s": 4377.634, "e": 4379.549, "en": "You know what happened next.", "ko": "그다음은 알잖아요", "it": false}, {"s": 4382.16, "e": 4384.336, "en": "I'm sorry.", "ko": "미안해요", "it": false}, {"s": 4384.423, "e": 4387.513, "en": "Truly.", "ko": "정말로요", "it": false}, {"s": 4387.6, "e": 4389.559, "en": "But it's over now.", "ko": "하지만 이제 끝났어요", "it": false}, {"s": 4389.689, "e": 4393.954, "en": "Let's never speak of it again.", "ko": "다시는 그 얘기 하지 마요", "it": false}, {"s": 4394.085, "e": 4396.609, "en": "It's not over.", "ko": "안 끝났어요", "it": false}, {"s": 4396.696, "e": 4399.96, "en": "Malcolm's visits,\nthey didn't stop.", "ko": "맬컴은 계속\n찾아와요", "it": false}, {"s": 4400.091, "e": 4403.181, "en": "After Garland's death,\nMalcolm has come to you?", "ko": "갈랜드가 죽은 뒤에도\n맬컴이 찾아왔다고요?", "it": false}, {"s": 4403.311, "e": 4406.227, "en": "He told me if I resisted\nhe would hurt Christopher.", "ko": "거부하면 크리스토퍼를\n해치겠다고 했어요", "it": false}, {"s": 4409.056, "e": 4412.712, "en": "And then he would\nbecome different.", "ko": "그러고 나면\n사람이 달라져요", "it": false}, {"s": 4412.843, "e": 4415.628, "en": "Before he forced himself\non me,", "ko": "날 덮치기 전에", "it": false}, {"s": 4415.759, "e": 4418.544, "en": "I know this sounds strange,\nbut...", "ko": "이상하게 들리겠지만...", "it": false}, {"s": 4418.675, "e": 4420.851, "en": "He would take you\nto his mother's room?", "ko": "당신을\n어머니 방으로 데려갔죠?", "it": false}, {"s": 4421.417, "e": 4422.896, "en": "Yes.", "ko": "네", "it": false}, {"s": 4430.513, "e": 4432.515, "en": "You should go.", "ko": "떠나요", "it": false}, {"s": 4432.602, "e": 4433.603, "en": "What?", "ko": "네?", "it": false}, {"s": 4436.606, "e": 4437.998, "en": "You are my friend, Alicia", "ko": "앨리샤, 당신은 내 친구예요", "it": false}, {"s": 4438.085, "e": 4441.828, "en": "and it pains me to say this...\nbut go.", "ko": "이런 말 하기 괴롭지만...\n떠나요", "it": false}, {"s": 4441.959, "e": 4444.178, "en": "You have the freedom\nto leave this place.", "ko": "당신은 여길 떠날\n자유가 있잖아요", "it": false}, {"s": 4444.265, "e": 4448.356, "en": "Take your son and your\ninheritance and start over.", "ko": "아들이랑 유산을 챙겨서\n새로 시작해요", "it": false}, {"s": 4448.444, "e": 4454.928, "en": "You're young and beautiful\nand rich.", "ko": "젊고 아름답고\n돈도 있잖아요", "it": false}, {"s": 4455.059, "e": 4457.278, "en": "It's not too late for you.", "ko": "당신은 아직 늦지 않았어요", "it": false}, {"s": 4462.632, "e": 4464.329, "en": "But it is too late.", "ko": "아니, 이미 늦었어요", "it": false}, {"s": 4466.94, "e": 4468.638, "en": "I'm pregnant.", "ko": "임신했어요", "it": false}, {"s": 4472.555, "e": 4476.036, "en": "It's his, Olivia.", "ko": "그 사람 아이예요, 올리비아", "it": false}, {"s": 4476.123, "e": 4477.211, "en": "It's his.", "ko": "그 사람 아이라고요", "it": false}, {"s": 4542.668, "e": 4544.452, "en": "The only man who ever\nloved me once told me", "ko": "나를 진정으로 사랑했던 유일한 남자가\n언젠가 내게 말했다", "it": true}, {"s": 4544.583, "e": 4546.89, "en": "that everything I need\nis in my heart.", "ko": "필요한 건 전부\n내 마음속에 있다고", "it": true}, {"s": 4548.892, "e": 4550.546, "en": "It was my compass.", "ko": "그것이 내 나침반이라고", "it": true}, {"s": 4553.853, "e": 4557.814, "en": "In that moment I finally knew\nwhere it was pointing me.", "ko": "그 순간 나는 마침내\n나침반이 가리키는 곳을 알았다", "it": true}, {"s": 4557.944, "e": 4559.25, "en": "I need a knife.", "ko": "칼이 필요해요", "it": false}, {"s": 4568.476, "e": 4570.696, "en": "I wanted to cut\nhis throat.", "ko": "그의 목을\n따고 싶었다", "it": true}, {"s": 4584.536, "e": 4586.799, "en": "But since that\nwasn't an option,", "ko": "하지만 그럴 수는\n없었으니", "it": true}, {"s": 4586.886, "e": 4589.454, "en": "I had another plan.", "ko": "다른 계획이 있었다", "it": true}, {"s": 4590.89, "e": 4594.067, "en": "We'll be having\nthis for dinner.", "ko": "오늘 저녁은\n이걸로 하죠", "it": false}, {"s": 4594.198, "e": 4596.809, "en": "And I need a horse.", "ko": "그리고 말이 필요해요", "it": false}, {"s": 4596.896, "e": 4599.464, "en": "Not to kill, to ride.", "ko": "죽이려는 게 아니라\n타려고요", "it": false}, {"s": 4619.266, "e": 4620.92, "en": "Mrs. Foxworth!", "ko": "마님!", "it": false}, {"s": 4622.922, "e": 4624.489, "en": "Are you all right?", "ko": "괜찮으세요?", "it": false}, {"s": 4624.62, "e": 4625.446, "en": "Oh.", "ko": "아", "it": false}, {"s": 4625.533, "e": 4626.796, "en": "Yes.", "ko": "네", "it": false}, {"s": 4626.926, "e": 4628.928, "en": "Don't worry,\nit's not mine.", "ko": "걱정 말아요\n내 피 아니에요", "it": false}, {"s": 4629.015, "e": 4631.409, "en": "Nella, I need your help.", "ko": "넬라, 도와줘요", "it": false}, {"s": 4631.539, "e": 4634.107, "en": "I don't have time right now\nto explain everything.", "ko": "지금은 다 설명할\n시간이 없어요", "it": false}, {"s": 4634.194, "e": 4638.416, "en": "But you were treated very poorly\nand for that I'm truly sorry.", "ko": "그동안 부당한 대우를 받았죠\n정말 미안해요", "it": false}, {"s": 4638.546, "e": 4642.202, "en": "Will you come to Foxworth Hall\ntomorrow morning?", "ko": "내일 아침 폭스워스 저택으로\n와 줄래요?", "it": false}, {"s": 4642.289, "e": 4644.465, "en": "Please?", "ko": "부탁해요", "it": false}, {"s": 4644.552, "e": 4645.51, "en": "Yes.", "ko": "네", "it": false}, {"s": 4645.597, "e": 4648.644, "en": "Thank you. Thank you.", "ko": "고마워요, 정말 고마워요", "it": false}, {"s": 4663.528, "e": 4667.575, "en": "It's okay. She's gone.", "ko": "괜찮아, 가셨어", "it": false}, {"s": 4667.706, "e": 4670.1, "en": "Why did you never tell her\nabout me?", "ko": "왜 저에 대해선\n한 번도 말 안 했어요?", "it": false}, {"s": 4670.187, "e": 4672.842, "en": "Well, I didn't want to hurt her.\nShe's my friend.", "ko": "상처 주기 싫었어\n내 친구니까", "it": false}, {"s": 4672.929, "e": 4674.974, "en": "She's not your friend, Mama.", "ko": "친구 아니에요, 엄마", "it": false}, {"s": 4675.061, "e": 4676.672, "en": "And you're not going back\nto that place.", "ko": "그리고 엄만 거기\n다시 안 가요", "it": false}, {"s": 4676.759, "e": 4679.326, "en": "Mind your mouth, Celia.", "ko": "말조심해, 실리아", "it": false}, {"s": 4683.635, "e": 4686.203, "en": "Mrs. Steiner, this lamb\nwas perfection.", "ko": "스타이너 부인, 양고기가\n아주 훌륭했어", "it": false}, {"s": 4686.333, "e": 4688.205, "en": "Tell Cook she has\noutdone herself.", "ko": "요리사한테 이번엔\n정말 잘했다고 전해", "it": false}, {"s": 4688.292, "e": 4689.989, "en": "I was hoping you'd like it.", "ko": "입에 맞으실 줄 알았지요", "it": false}, {"s": 4690.076, "e": 4691.948, "en": "I gave him his\nprized lamb.", "ko": "나는 그가 아끼는\n양고기를 내주었다", "it": true}, {"s": 4692.035, "e": 4695.081, "en": "Before I took everything else.", "ko": "그 밖의 모든 것을\n빼앗기 전에", "it": true}, {"s": 4695.212, "e": 4699.085, "en": "It is a pity Alicia didn't\njoin us this evening.", "ko": "앨리샤가 오늘 저녁에\n같이 안 해서 아쉽군", "it": false}, {"s": 4699.172, "e": 4700.913, "en": "Did she say why?", "ko": "이유를 말했소?", "it": false}, {"s": 4701.0, "e": 4704.7, "en": "I don't think she'll be\njoining us for some time.", "ko": "한동안은 같이\n못 할 것 같아요", "it": false}, {"s": 4705.875, "e": 4709.356, "en": "Mourning. It's a process.", "ko": "애도라는 건\n시간이 걸리니까요", "it": false}, {"s": 4715.319, "e": 4718.452, "en": "Well... I will be\nin the library working.", "ko": "그럼... 난 서재에서\n일하겠소", "it": false}, {"s": 4718.583, "e": 4719.845, "en": "I would prefer not\nto be disturbed.", "ko": "방해받고\n싶지 않소", "it": false}, {"s": 4719.932, "e": 4721.02, "en": "Do you understand?", "ko": "알아들었소?", "it": false}, {"s": 4721.151, "e": 4722.892, "en": "Oh, I certainly do.", "ko": "그럼요, 아주 잘", "it": false}, {"s": 4730.203, "e": 4731.596, "en": "Olivia!!!", "ko": "올리비아!!!", "it": false}, {"s": 4755.663, "e": 4757.883, "en": "You called?", "ko": "불렀어?", "it": false}, {"s": 4757.97, "e": 4760.277, "en": "What the hell is your desk\ndoing here?", "ko": "당신 책상이 왜\n여기 있는 거요?", "it": false}, {"s": 4760.364, "e": 4762.453, "en": "I've made some changes.", "ko": "좀 바꿨어", "it": false}, {"s": 4765.978, "e": 4770.896, "en": "This is my house and I will\nnot tolerate such insolence.", "ko": "여긴 내 집이오\n이런 무례는 용납 못 하오", "it": false}, {"s": 4775.596, "e": 4778.077, "en": "What do you think\nyou're doing?", "ko": "지금 뭐 하는 거요?", "it": false}, {"s": 4778.208, "e": 4780.123, "en": "I'm having a drink.", "ko": "술 한잔하는 중이야", "it": false}, {"s": 4782.081, "e": 4784.04, "en": "But what have you been doing?", "ko": "그런데 당신은\n대체 뭘 하고 다닌 거야?", "it": false}, {"s": 4784.127, "e": 4787.086, "en": "And why have you\nbeen doing it?", "ko": "그리고 왜\n그런 짓을 한 거야?", "it": false}, {"s": 4787.173, "e": 4789.306, "en": "Let's start at the beginning,\nshall we?", "ko": "처음부터 시작해 볼까?", "it": false}, {"s": 4791.525, "e": 4792.613, "en": "What is this all about?", "ko": "이게 다\n무슨 짓이오?", "it": false}, {"s": 4792.744, "e": 4794.702, "en": "It's about how we\nmove forward.", "ko": "우리가 앞으로\n어떻게 할지에 대한 거야", "it": false}, {"s": 4794.79, "e": 4797.444, "en": "If we move forward.", "ko": "앞으로 함께할 수\n있을지에 대한 거고", "it": false}, {"s": 4797.531, "e": 4799.62, "en": "Please, sit.", "ko": "앉아", "it": false}, {"s": 4808.02, "e": 4809.674, "en": "Excellent.", "ko": "좋아", "it": false}, {"s": 4809.805, "e": 4811.197, "en": "Now...", "ko": "자...", "it": false}, {"s": 4811.284, "e": 4812.938, "en": "Why did you marry me?", "ko": "나랑 왜 결혼했어?", "it": false}, {"s": 4813.939, "e": 4815.288, "en": "Oh, don't be ridiculous.", "ko": "웃기는 소리 마시오", "it": false}, {"s": 4815.375, "e": 4818.988, "en": "Oh, we passed ridiculous\nlong ago.", "ko": "웃기는 단계는\n진작에 지났어", "it": false}, {"s": 4819.118, "e": 4822.078, "en": "If all you wanted in a wife was\na member of your staff to abuse,", "ko": "괴롭힐 하인 하나가\n필요했던 거라면", "it": false}, {"s": 4822.208, "e": 4825.429, "en": "you could've picked someone\neasier to silence.", "ko": "입 다물게 하기 쉬운\n여자를 골랐어야지", "it": false}, {"s": 4825.559, "e": 4827.692, "en": "So, why did you marry me?", "ko": "그러니까, 나랑\n왜 결혼했어?", "it": false}, {"s": 4830.042, "e": 4831.0, "en": "Fine.", "ko": "좋소", "it": false}, {"s": 4833.176, "e": 4835.526, "en": "I wanted a woman with a mind\nto manage the house", "ko": "집을 관리할 머리와", "it": false}, {"s": 4835.613, "e": 4838.485, "en": "and a body to produce\nhealthy offspring.", "ko": "건강한 자식을 낳을\n몸을 가진 여자가 필요했소", "it": false}, {"s": 4838.572, "e": 4842.228, "en": "Sadly my observations of your\ntalents were only half correct.", "ko": "안타깝게도 내 판단은\n반만 맞았구려", "it": false}, {"s": 4842.359, "e": 4849.453, "en": "Two children, both boys,\nand weak boys at that.", "ko": "아이는 둘, 둘 다 아들인 데다\n그것도 약해 빠진 놈들이오", "it": false}, {"s": 4849.54, "e": 4851.194, "en": "Now is that all?", "ko": "이제 됐소?", "it": false}, {"s": 4851.324, "e": 4852.195, "en": "No.", "ko": "아니", "it": false}, {"s": 4854.023, "e": 4857.2, "en": "It will be here\nin nine months.", "ko": "9개월 뒤면\n태어날 거야", "it": false}, {"s": 4857.287, "e": 4858.201, "en": "Excuse me?", "ko": "뭐라고?", "it": false}, {"s": 4858.331, "e": 4860.159, "en": "Your child.", "ko": "당신 아이 말이야", "it": false}, {"s": 4860.246, "e": 4862.858, "en": "The child you are having\nwith your stepmother.", "ko": "당신이 새어머니한테서\n얻은 아이", "it": false}, {"s": 4866.47, "e": 4867.732, "en": "-Alicia?\n-She's pregnant.", "ko": "-앨리샤가?\n-임신했어", "it": false}, {"s": 4867.819, "e": 4869.995, "en": "Yes. Congratulations.", "ko": "그래, 축하해", "it": false}, {"s": 4870.082, "e": 4872.955, "en": "You're the father\nand the stepbrother.", "ko": "당신이 아버지이자\n오빠인 셈이네", "it": false}, {"s": 4873.042, "e": 4876.393, "en": "It's all a bit confusing,\nreally.", "ko": "좀 헷갈리긴 하지", "it": false}, {"s": 4876.48, "e": 4877.873, "en": "How wonderful.", "ko": "잘됐군", "it": false}, {"s": 4877.96, "e": 4879.396, "en": "How odd of you to say that.", "ko": "그런 말을 하다니\n별나네", "it": false}, {"s": 4879.483, "e": 4880.876, "en": "It is a girl.\nI know it.", "ko": "딸이오\n난 알아", "it": false}, {"s": 4881.006, "e": 4882.399, "en": "It's a bastard\nis all we know.", "ko": "우리가 아는 건\n사생아라는 것뿐이야", "it": false}, {"s": 4882.486, "e": 4886.446, "en": "Oh wait, I apologize.\nThat's not all we know.", "ko": "아, 미안\n그것뿐만은 아니지", "it": false}, {"s": 4886.533, "e": 4889.841, "en": "We know you have your father's\nblood on your hands.", "ko": "당신 손에 아버지 피가\n묻었다는 것도 알지", "it": false}, {"s": 4889.972, "e": 4891.234, "en": "This conversation is over.", "ko": "얘기 끝났소", "it": false}, {"s": 4891.321, "e": 4894.498, "en": "Oh, Malcolm, this conversation\nis just beginning.", "ko": "맬컴, 이 얘긴\n이제 시작이야", "it": false}, {"s": 4897.022, "e": 4900.243, "en": "Your stepmother is only in the\nearly stages of her pregnancy.", "ko": "새어머니는 이제 겨우\n임신 초기야", "it": false}, {"s": 4900.33, "e": 4902.81, "en": "It will be impossible\nto maintain appearances", "ko": "아이가 갈랜드 아이라고\n우기면서", "it": false}, {"s": 4902.898, "e": 4904.595, "en": "by saying the child\nis Garland's.", "ko": "체면을 지키기는\n불가능해", "it": false}, {"s": 4904.682, "e": 4905.944, "en": "We send her away for a year", "ko": "1년 동안 멀리 보내면", "it": false}, {"s": 4906.031, "e": 4907.815, "en": "and no one will be able\nto tell how old the child is", "ko": "돌아왔을 때\n아이가 몇 살인지", "it": false}, {"s": 4907.946, "e": 4908.425, "en": "when they return.", "ko": "아무도 모를 거야", "it": false}, {"s": 4908.555, "e": 4910.035, "en": "I would.", "ko": "난 알 거요", "it": false}, {"s": 4910.166, "e": 4912.646, "en": "I'd be able to tell.", "ko": "난 알아볼 수 있소", "it": false}, {"s": 4912.777, "e": 4913.821, "en": "You wouldn't.", "ko": "안 그럴걸", "it": false}, {"s": 4913.909, "e": 4915.823, "en": "Well, I wouldn't tell\nthat secret", "ko": "그 비밀은\n나도 말 안 할 거야", "it": false}, {"s": 4915.911, "e": 4918.0, "en": "because that would make me\nlook bad.", "ko": "그러면 나도\n체면이 깎이니까", "it": false}, {"s": 4918.087, "e": 4921.307, "en": "A woman who permits her husband\nto sleep with his stepmother?", "ko": "남편이 새어머니와 자는 걸\n눈감아 준 아내라니", "it": false}, {"s": 4921.394, "e": 4923.44, "en": "Ghastly, really.", "ko": "정말 끔찍하잖아", "it": false}, {"s": 4923.57, "e": 4925.964, "en": "I thought you knew me better\nthan that.", "ko": "날 그 정도로밖에\n모를 줄은 몰랐네", "it": false}, {"s": 4926.051, "e": 4930.534, "en": "But I would tell everyone\nabout how Garland died.", "ko": "하지만 갈랜드가 어떻게\n죽었는지는 다 말할 거야", "it": false}, {"s": 4930.664, "e": 4933.145, "en": "About how you killed him.", "ko": "당신이 죽였다고", "it": false}, {"s": 4933.276, "e": 4934.233, "en": "You lie.", "ko": "거짓말이오", "it": false}, {"s": 4934.32, "e": 4936.757, "en": "You attacked his wife.\nHe found you.", "ko": "당신이 그분 아내를 덮쳤고\n그분한테 들켰지", "it": false}, {"s": 4936.844, "e": 4937.845, "en": "You held him against a wall", "ko": "당신은 그분을\n벽에 밀어붙였어", "it": false}, {"s": 4937.933, "e": 4939.63, "en": "until he could\nno longer breathe.", "ko": "숨이 끊어질 때까지", "it": false}, {"s": 4939.717, "e": 4940.892, "en": "He had a heart attack.", "ko": "심장마비였소", "it": false}, {"s": 4940.979, "e": 4942.72, "en": "He had a heart attack\nbecause I decided he did", "ko": "심장마비가 된 건\n내가 그렇게 정했기 때문이야", "it": false}, {"s": 4942.807, "e": 4946.724, "en": "when I convinced the good doctor\nnot to perform an autopsy.", "ko": "부검하지 말라고\n의사를 설득했을 때", "it": false}, {"s": 4946.811, "e": 4947.812, "en": "What do you want?!", "ko": "원하는 게 뭐요?!", "it": false}, {"s": 4947.899, "e": 4950.684, "en": "I want to destroy you.", "ko": "당신을 망가뜨리는 거", "it": false}, {"s": 4950.771, "e": 4955.124, "en": "I want to ruin your business,\nyour reputation, your name.", "ko": "당신 사업도, 평판도,\n이름도 다 무너뜨리고 싶어", "it": false}, {"s": 4955.254, "e": 4957.387, "en": "But I can't do that, can I?", "ko": "그런데 그럴 순 없잖아?", "it": false}, {"s": 4957.517, "e": 4959.955, "en": "I have the unfortunate privilege\nof sharing that name.", "ko": "불행히도 나도 그 이름을\n쓰는 처지니까", "it": false}, {"s": 4960.085, "e": 4962.783, "en": "A stain on you,\nis a stain on me.", "ko": "당신 오점은\n곧 내 오점이야", "it": false}, {"s": 4962.87, "e": 4964.611, "en": "You should be grateful.", "ko": "고마운 줄 알아", "it": false}, {"s": 4968.267, "e": 4970.269, "en": "Alicia's bags will be packed", "ko": "앨리샤 짐을 싸서", "it": false}, {"s": 4970.356, "e": 4974.099, "en": "and she'll be sent away for\nall the servants to witness.", "ko": "하인들이 다 보는 앞에서\n떠나보낼 거야", "it": false}, {"s": 4974.186, "e": 4977.755, "en": "Once night falls,\nAlicia will return.", "ko": "밤이 되면\n앨리샤가 돌아올 거고", "it": false}, {"s": 4977.885, "e": 4981.193, "en": "We'll keep her here in seclusion\nin the East Wing", "ko": "동쪽 별관에\n숨겨 둘 거야", "it": false}, {"s": 4981.28, "e": 4983.369, "en": "for the duration\nof her pregnancy.", "ko": "임신 기간 내내", "it": false}, {"s": 4983.456, "e": 4986.546, "en": "The servants will not be\npermitted anywhere near her.", "ko": "하인들은 그 근처에\n얼씬도 못 하게 할 거고", "it": false}, {"s": 4986.677, "e": 4988.592, "en": "And while we're on the subject\nof servants,", "ko": "하인 얘기가\n나왔으니 말인데", "it": false}, {"s": 4988.679, "e": 4990.376, "en": "Nella will be returning.", "ko": "넬라가 돌아올 거야", "it": false}, {"s": 4990.463, "e": 4992.074, "en": "Why?", "ko": "왜?", "it": false}, {"s": 4992.161, "e": 4993.989, "en": "Because I like her.", "ko": "내가 좋아하니까", "it": false}, {"s": 4995.947, "e": 4998.254, "en": "Excellent. I'm glad you agree.", "ko": "좋아, 동의해 줘서 기쁘네", "it": false}, {"s": 4998.341, "e": 5002.301, "en": "After all, I'll be needing\nher help when I'm with child.", "ko": "어쨌든 내가 임신했을 때\n넬라 도움이 필요할 테니까", "it": false}, {"s": 5003.781, "e": 5004.695, "en": "Excuse me?", "ko": "뭐라고?", "it": false}, {"s": 5006.001, "e": 5007.872, "en": "I thought you would've\ncaught on by now.", "ko": "이쯤이면\n눈치챘을 줄 알았는데", "it": false}, {"s": 5010.135, "e": 5014.661, "en": "We'll announce to the staff the\nhappy news that I'm expecting.", "ko": "하인들한테 내가 임신했다는\n기쁜 소식을 알릴 거야", "it": false}, {"s": 5014.748, "e": 5018.013, "en": "I'll pretend to be pregnant\nboth in the house and in public.", "ko": "집 안에서도 밖에서도\n임신한 척할 거야", "it": false}, {"s": 5018.1, "e": 5019.536, "en": "When Alicia's child is born", "ko": "앨리샤가 아이를 낳으면", "it": false}, {"s": 5019.623, "e": 5022.147, "en": "we will keep it and raise it\nas our own.", "ko": "우리가 데려다\n친자식처럼 키울 거야", "it": false}, {"s": 5022.278, "e": 5024.671, "en": "No one will be the wiser.", "ko": "아무도 모르겠지", "it": false}, {"s": 5024.758, "e": 5027.196, "en": "And Alicia?", "ko": "앨리샤는?", "it": false}, {"s": 5027.326, "e": 5029.459, "en": "Your stepmother will be\nsent away", "ko": "당신 새어머니는", "it": false}, {"s": 5029.546, "e": 5031.852, "en": "along with young Christopher\nand her inheritance,", "ko": "어린 크리스토퍼와 유산을\n가지고 떠날 거야", "it": false}, {"s": 5031.939, "e": 5034.942, "en": "which you will double\nimmediately following the birth.", "ko": "출산 직후에 그 유산을\n당신이 두 배로 불려 주고", "it": false}, {"s": 5035.03, "e": 5035.726, "en": "How da...", "ko": "감히 어디서...", "it": false}, {"s": 5035.813, "e": 5037.597, "en": "Did I say I was done?!", "ko": "내 말 안 끝났어!", "it": false}, {"s": 5037.684, "e": 5039.251, "en": "You will not be permitted\nin the East Wing", "ko": "새어머니가 지내는 동안", "it": false}, {"s": 5039.338, "e": 5042.037, "en": "for the duration of your\nstepmother's confinement.", "ko": "당신은 동쪽 별관에\n발도 못 들여", "it": false}, {"s": 5042.124, "e": 5043.908, "en": "If news of you breaking this\nrule comes to my attention", "ko": "당신이 이걸 어겼다는 소식이\n내 귀에 들어오면", "it": false}, {"s": 5043.995, "e": 5045.083, "en": "the agreement is off.", "ko": "합의는 끝이야", "it": false}, {"s": 5045.17, "e": 5047.564, "en": "I tell everyone the truth.", "ko": "모두에게 진실을 말할 거야", "it": false}, {"s": 5047.651, "e": 5049.174, "en": "You wouldn't.", "ko": "그러지 못할 거요", "it": false}, {"s": 5049.261, "e": 5051.698, "en": "Oh, Malcolm, I would.", "ko": "아니, 맬컴\n난 할 거야", "it": false}, {"s": 5051.785, "e": 5054.31, "en": "I would burn this place\nto the ground.", "ko": "이 집을\n잿더미로 만들어 버릴 거야", "it": false}, {"s": 5064.102, "e": 5064.798, "en": "Now is that all?", "ko": "이제 됐어?", "it": false}, {"s": 5064.885, "e": 5066.974, "en": "Just one more thing.", "ko": "하나만 더", "it": false}, {"s": 5067.062, "e": 5070.761, "en": "Tomorrow you will set up trusts\nfor the boys.", "ko": "내일 아이들 앞으로\n신탁을 만들어", "it": false}, {"s": 5070.848, "e": 5072.85, "en": "Two million dollars.", "ko": "200만 달러씩", "it": false}, {"s": 5072.937, "e": 5074.504, "en": "Each.", "ko": "한 명당", "it": false}, {"s": 5074.591, "e": 5078.247, "en": "The trusts will be theirs\nto do with as they please", "ko": "그 신탁은 아이들이\n마음대로 쓸 수 있게 할 거야", "it": false}, {"s": 5078.334, "e": 5082.99, "en": "so they may be free of you\nand this godforsaken house.", "ko": "당신과 이 저주받은 집에서\n벗어날 수 있도록", "it": false}, {"s": 5086.559, "e": 5088.213, "en": "That temper!", "ko": "저 성질머리!", "it": false}, {"s": 5088.3, "e": 5090.302, "en": "Now, I see how you must\nhave driven your mother", "ko": "당신 어머니가 왜\n도망쳤는지 알겠네", "it": false}, {"s": 5090.389, "e": 5093.871, "en": "to run away all those\nyears ago.", "ko": "그 옛날에 말이야", "it": false}, {"s": 5093.958, "e": 5094.872, "en": "How dare you?!", "ko": "감히 어디서?!", "it": false}, {"s": 5094.959, "e": 5097.092, "en": "You raped me.\nHow dare you?", "ko": "당신은 날 강간했어\n감히 어디서?", "it": false}, {"s": 5103.315, "e": 5104.403, "en": "I won't do it.", "ko": "그렇게는 못 하오", "it": false}, {"s": 5104.49, "e": 5106.101, "en": "Oh, but you will.", "ko": "아니, 하게 될 거야", "it": false}, {"s": 5107.493, "e": 5109.626, "en": "Do you understand?", "ko": "알아들었어?", "it": false}, {"s": 5113.02, "e": 5114.718, "en": "That's not good enough.", "ko": "그걸로는 부족해", "it": false}, {"s": 5114.848, "e": 5116.198, "en": "Do you understand?!", "ko": "알아들었냐고?!", "it": false}, {"s": 5116.285, "e": 5117.112, "en": "I do!", "ko": "알아들었소!", "it": false}, {"s": 5150.58, "e": 5153.8, "en": "I could not tell\nmy story during my life.", "ko": "살아 있는 동안 나는\n내 이야기를 할 수 없었다", "it": true}, {"s": 5153.887, "e": 5155.889, "en": "But now in death,\nin my will,", "ko": "하지만 이제 죽음 속에서,\n유언을 통해", "it": true}, {"s": 5155.976, "e": 5160.981, "en": "I am finally free to do\nas I choose.", "ko": "마침내 내 뜻대로\n할 자유를 얻었다", "it": true}, {"s": 5161.112, "e": 5168.728, "en": "And so this is my tale of lust,\nmurder, love, and deceit.", "ko": "이것은 욕망과 살인,\n사랑과 기만의 이야기다", "it": true}, {"s": 5168.815, "e": 5171.862, "en": "Judge if you may\nbut always remember.", "ko": "심판하려거든 하라\n하지만 늘 기억하라", "it": true}, {"s": 5171.949, "e": 5174.169, "en": "God may shine his light\nbut you may not see it", "ko": "하나님이 빛을 비추셔도\n보이지 않을 수 있다", "it": true}, {"s": 5174.299, "e": 5178.347, "en": "if the Devil looms overhead,\ncasting its shadow over you.", "ko": "악마가 머리 위에서\n그림자를 드리운다면", "it": true}, {"s": 5180.653, "e": 5186.006, "en": "The Devil, or Foxworth Hall.", "ko": "악마, 혹은 폭스워스 저택이", "it": true}, {"s": 5186.093, "e": 5187.573, "en": "Would my story have\nended here", "ko": "내 이야기가\n여기서 끝났다면", "it": true}, {"s": 5187.66, "e": 5190.837, "en": "I believe I could've\nfound happiness.", "ko": "나는 행복을 찾을 수\n있었을 것이다", "it": true}, {"s": 5190.924, "e": 5193.318, "en": "But it did not end here.", "ko": "하지만 여기서 끝나지 않았다", "it": true}, {"s": 5193.449, "e": 5198.236, "en": "It was, in fact, only just\nthe beginning.", "ko": "사실은 이제 막\n시작일 뿐이었다", "it": true}, {"s": 5198.323, "e": 5203.937, "en": "After all, the best kind\nof revenge takes time.", "ko": "결국 최고의 복수는\n시간이 걸리는 법이니까", "it": true}], "e2": [{"s": 3.729, "e": 4.729, "en": "Control.", "ko": "통제", "it": true}, {"s": 6.674, "e": 9.341, "en": "It's like youth.", "ko": "그건 젊음과 같다", "it": true}, {"s": 9.568, "e": 13.07, "en": "You don't truly appreciate\nit until it's gone.", "ko": "잃고 나서야\n그 소중함을 안다", "it": true}, {"s": 13.163, "e": 16.757, "en": "In my youth I had total\ncontrol of my life.", "ko": "젊은 시절 나는\n내 삶을 온전히 통제했다", "it": true}, {"s": 16.909, "e": 18.742, "en": "I had a vocation.", "ko": "천직이 있었고", "it": true}, {"s": 18.761, "e": 20.668, "en": "I had passion.", "ko": "열정이 있었고", "it": true}, {"s": 20.688, "e": 22.771, "en": "I had hope.", "ko": "희망이 있었다", "it": true}, {"s": 30.256, "e": 35.034, "en": "And then, I met a man", "ko": "그러다 한 남자를 만났다", "it": true}, {"s": 35.645, "e": 37.605, "en": "Who turned out to be a monster.", "ko": "알고 보니 그는 괴물이었다", "it": true}, {"s": 39.373, "e": 41.373, "en": "And he made me a prisoner.", "ko": "그리고 나를\n죄수로 만들었다", "it": true}, {"s": 43.527, "e": 46.879, "en": "I was trapped in my own home", "ko": "나는 내 집에 갇혔다", "it": true}, {"s": 47.473, "e": 50.833, "en": "When he forced himself\non his stepmother.", "ko": "그가 자기 새어머니를\n범했을 때", "it": true}, {"s": 53.029, "e": 57.015, "en": "New life began in her,", "ko": "그녀 안에서\n새 생명이 시작되었고", "it": true}, {"s": 57.04, "e": 60.708, "en": "And for sake of\nappearance, in me.", "ko": "체면을 위해,\n내 안에서도 시작되었다", "it": true}, {"s": 61.306, "e": 63.299, "en": "But now I was back in control", "ko": "하지만 이제 통제권은\n다시 내게 있었다", "it": true}, {"s": 63.324, "e": 67.345, "en": "And I was determined\nnever to lose it again.", "ko": "그리고 다시는\n잃지 않으리라 다짐했다", "it": true}, {"s": 67.96, "e": 71.07, "en": "In case you haven't\nalready noticed,", "ko": "이미 눈치챘겠지만", "it": false}, {"s": 71.297, "e": 73.906, "en": "There will soon be an\naddition to our family.", "ko": "곧 우리 가족에\n새 식구가 생겨요", "it": false}, {"s": 77.803, "e": 80.079, "en": "Congratulations, ma'am.", "ko": "축하드립니다, 마님", "it": false}, {"s": 80.23, "e": 81.869, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 82.566, "e": 86.901, "en": "But as our family grows\nwe also suffer a loss.", "ko": "하지만 식구가 느는 만큼\n잃는 사람도 있어요", "it": false}, {"s": 86.921, "e": 89.496, "en": "I'm saddened to say that\nmrs. Garland foxworth", "ko": "안타깝게도\n갈랜드 폭스워스 부인께서", "it": false}, {"s": 89.59, "e": 93.834, "en": "Will be leaving us to set\nup a new home in pittsburgh.", "ko": "피츠버그에 새 보금자리를\n꾸리러 떠나십니다", "it": false}, {"s": 93.928, "e": 97.337, "en": "Her son, christopher, will\nremain in our hospitality", "ko": "아드님 크리스토퍼는\n데리러 올 때까지", "it": false}, {"s": 97.489, "e": 98.913, "en": "Until he can be sent for.", "ko": "우리가 보살필 거예요", "it": false}, {"s": 98.933, "e": 100.173, "en": "I would like to thank you all", "ko": "여러분 모두에게 감사드려요", "it": false}, {"s": 100.326, "e": 102.993, "en": "For welcoming my late\nhusband and myself, and-", "ko": "돌아가신 남편과 저를\n따뜻하게 맞아 주셔서...", "it": false}, {"s": 103.011, "e": 105.562, "en": "We wouldn't want you\nto miss your train.", "ko": "기차 놓치시면 안 되죠", "it": false}, {"s": 160.068, "e": 162.995, "en": "I think\nthis may be a mistake.", "ko": "아무래도\n잘못하는 것 같아요", "it": false}, {"s": 163.146, "e": 166.072, "en": "You're protecting\nthe foxworth name.", "ko": "폭스워스 가문의 이름을\n지키는 거예요", "it": false}, {"s": 166.167, "e": 168.816, "en": "Christopher's legacy.", "ko": "크리스토퍼의 유산을요", "it": false}, {"s": 168.911, "e": 170.627, "en": "Think of his future.", "ko": "아이 미래를 생각해요", "it": false}, {"s": 197.256, "e": 198.864, "en": "This is it?", "ko": "여기예요?", "it": false}, {"s": 202.852, "e": 205.739, "en": "You have all the\ncreature comforts of home", "ko": "집에서 누리던 편의는\n다 갖춰 놨고", "it": false}, {"s": 205.764, "e": 210.167, "en": "And enough amusements\nthat the time will fly by.", "ko": "시간 가는 줄 모를 만큼\n소일거리도 있어요", "it": false}, {"s": 213.455, "e": 215.214, "en": "Never been much of a reader.", "ko": "책은 별로 안 좋아해요", "it": false}, {"s": 215.497, "e": 217.751, "en": "Well then... Perhaps\nthis can also be a time", "ko": "그럼... 이번 기회에", "it": false}, {"s": 217.776, "e": 219.676, "en": "Of personal growth.", "ko": "자기 계발을 해 보는 것도\n좋겠네요", "it": false}, {"s": 223.449, "e": 226.892, "en": "Just think, once\nthe baby is born", "ko": "생각해 봐요\n아이만 태어나면", "it": false}, {"s": 227.119, "e": 229.97, "en": "You'll get the money\nfrom garland's estate.", "ko": "갈랜드 유산을\n받게 될 거예요", "it": false}, {"s": 230.064, "e": 235.628, "en": "You and christopher will be\nfree of this place forever.", "ko": "그럼 크리스토퍼와 함께\n영영 여길 떠나는 거예요", "it": false}, {"s": 236.112, "e": 237.596, "en": "What about malcolm?", "ko": "맬컴은요?", "it": false}, {"s": 238.239, "e": 240.239, "en": "I'll take care of him.", "ko": "그건 내가 알아서 할게요", "it": false}, {"s": 247.564, "e": 249.414, "en": "I'm scared.", "ko": "무서워요", "it": false}, {"s": 250.751, "e": 253.752, "en": "Fear is like pain.", "ko": "두려움은 고통과 같아요", "it": false}, {"s": 253.979, "e": 257.147, "en": "Endure it long enough and\nyou become numb to it.", "ko": "오래 견디다 보면\n무뎌지죠", "it": false}, {"s": 257.165, "e": 260.175, "en": "Trust me, I know.", "ko": "내 말 믿어요, 겪어 봤으니까", "it": false}, {"s": 263.338, "e": 265.681, "en": "I'll see you in the morning.", "ko": "내일 아침에 봐요", "it": false}, {"s": 294.186, "e": 295.772, "en": "I settled her into the\nold chambermaid's room", "ko": "앨리샤는 동쪽 별관", "it": false}, {"s": 295.796, "e": 297.445, "en": "In the east wing.", "ko": "옛 하녀 방에 들였어", "it": false}, {"s": 297.539, "e": 300.04, "en": "The one with the\nsteps to the attic.", "ko": "다락으로 올라가는\n계단이 있는 방이야", "it": false}, {"s": 300.134, "e": 302.217, "en": "And I have the only key.", "ko": "그리고 열쇠는\n나만 갖고 있어", "it": false}, {"s": 306.227, "e": 310.343, "en": "An authoritative temperament is\na highly unattractive quality", "ko": "여자가 고압적인 건", "it": false}, {"s": 310.368, "e": 312.202, "en": "In the fairer sex.", "ko": "아주 매력 없는\n성질이오", "it": false}, {"s": 312.22, "e": 316.039, "en": "But then again you\nare barely a woman.", "ko": "하긴 당신은\n여자라고 하기도 뭣하지만", "it": false}, {"s": 316.058, "e": 320.319, "en": "Goose down is a poor\nsubstitute for a fertile womb.", "ko": "거위 털 배로는\n아이 밴 배를 대신 못 하오", "it": false}, {"s": 320.546, "e": 324.305, "en": "And mockery is a poor\nsubstitute for masculinity.", "ko": "조롱으로는 남자다움을\n대신 못 하고", "it": false}, {"s": 324.399, "e": 326.158, "en": "You will leave alicia alone.", "ko": "앨리샤는 건드리지 마", "it": false}, {"s": 333.241, "e": 334.833, "en": "You want to be in control?", "ko": "통제하고 싶소?", "it": false}, {"s": 336.912, "e": 339.245, "en": "It's all yours.", "ko": "전부 당신 것이오", "it": false}, {"s": 339.34, "e": 341.84, "en": "But if your plan fails", "ko": "하지만 당신 계획이 틀어져서", "it": false}, {"s": 341.991, "e": 343.878, "en": "And something happens\nto my daughter...", "ko": "내 딸한테\n무슨 일이라도 생기면...", "it": false}, {"s": 343.902, "e": 345.26, "en": "It won't.", "ko": "그럴 일 없어", "it": false}, {"s": 348.015, "e": 349.681, "en": "And it might be a boy.", "ko": "그리고 아들일 수도 있지", "it": false}, {"s": 351.167, "e": 353.243, "en": "Excuse me?", "ko": "뭐라고 했소?", "it": false}, {"s": 353.261, "e": 355.02, "en": "The baby.", "ko": "아이 말이야", "it": false}, {"s": 355.247, "e": 357.08, "en": "You're so sure it's\ngoing to be a girl", "ko": "당신은 딸이라고\n확신하지만", "it": false}, {"s": 357.099, "e": 359.151, "en": "But that's the one\nthing you can't control.", "ko": "그것만큼은 당신 마음대로\n안 되잖아", "it": false}, {"s": 359.175, "e": 360.653, "en": "Darling, when are\nyou going to realize", "ko": "여보, 언제쯤\n깨닫겠소?", "it": false}, {"s": 360.677, "e": 366.698, "en": "That I always get what I\nwant... No matter what?", "ko": "나는 원하는 건\n무슨 수를 써서든 갖는다는 걸", "it": false}, {"s": 422.481, "e": 424.756, "en": "Christopher!", "ko": "크리스토퍼!", "it": false}, {"s": 424.826, "e": 427.185, "en": "It's late, sweetie.\nWhat are you doing up?", "ko": "늦었잖니, 아가\n왜 안 자고 있어?", "it": false}, {"s": 429.488, "e": 431.655, "en": "I know you must miss your mommy,", "ko": "엄마가 보고 싶겠지만", "it": false}, {"s": 431.748, "e": 434.824, "en": "But she'll be back\nfor you. I promise.", "ko": "엄마는 널 데리러\n꼭 돌아오실 거야, 약속해", "it": false}, {"s": 434.843, "e": 436.25, "en": "I have an idea.", "ko": "좋은 생각이 있어", "it": false}, {"s": 436.27, "e": 437.897, "en": "How would you like to\nsleep with me tonight?", "ko": "오늘 밤엔\n나랑 같이 잘래?", "it": false}, {"s": 437.921, "e": 439.896, "en": "Would that make you feel better?", "ko": "그럼 좀 나아질까?", "it": false}, {"s": 473.048, "e": 475.122, "en": "I'm telling you\nsomething isn't right.", "ko": "글쎄 뭔가 이상하다니까\n그러네", "it": false}, {"s": 475.142, "e": 478.025, "en": "Did you hear those noises coming\nfrom the east wing last night?", "ko": "어젯밤에 동쪽 별관에서\n나는 소리 못 들었어?", "it": false}, {"s": 478.05, "e": 480.479, "en": "Sounded like somebody crying.", "ko": "누가 우는 소리 같던데", "it": false}, {"s": 486.32, "e": 488.153, "en": "Mrs. Steiner.", "ko": "스타이너 부인", "it": false}, {"s": 488.38, "e": 489.971, "en": "Nella.", "ko": "넬라", "it": false}, {"s": 489.996, "e": 493.218, "en": "Oh nella, would you be available\nto meet with me later today", "ko": "넬라, 이따가\n나 좀 볼 수 있을까요?", "it": false}, {"s": 493.243, "e": 495.835, "en": "To discuss some changes\nto our produce order?", "ko": "식료품 주문을 좀\n바꿀까 해서요", "it": false}, {"s": 495.86, "e": 497.609, "en": "Well surely, I can\nconsult with the cook", "ko": "그런 거라면 내가\n요리사랑 얘기해서", "it": false}, {"s": 497.634, "e": 499.389, "en": "Regarding any\nissues you may have.", "ko": "알아서 처리할게요", "it": false}, {"s": 499.482, "e": 501.144, "en": "That won't be\npossible, mrs. Steiner,", "ko": "그럴 수 없어요,\n스타이너 부인", "it": false}, {"s": 501.168, "e": 504.894, "en": "As I'll no longer be requiring\nyour services in my home.", "ko": "이제 이 집에선 당신 시중이\n필요 없으니까요", "it": false}, {"s": 504.988, "e": 506.079, "en": "Excuse me?", "ko": "뭐라고요?", "it": false}, {"s": 506.104, "e": 508.144, "en": "Your termination is\neffective immediately.", "ko": "당장 그만둬요", "it": false}, {"s": 510.068, "e": 513.086, "en": "But I've lived at foxworth\nhall my entire life.", "ko": "난 평생을 폭스워스 저택에서\n살았는데요", "it": false}, {"s": 513.18, "e": 514.921, "en": "And now you don't.", "ko": "이젠 아니죠", "it": false}, {"s": 515.015, "e": 517.073, "en": "Do you understand?", "ko": "알아들었어요?", "it": false}, {"s": 517.092, "e": 518.517, "en": "Yes.", "ko": "...알겠어요", "it": false}, {"s": 532.348, "e": 534.836, "en": "If mr. Garland foxworth\nwere still alive", "ko": "갈랜드 주인님이\n살아 계셨으면", "it": false}, {"s": 534.861, "e": 536.851, "en": "He wouldn't stand for this.", "ko": "이런 꼴은 절대\n안 두셨을 거예요", "it": false}, {"s": 536.87, "e": 538.278, "en": "If that be true,", "ko": "그 말이 사실이라면", "it": false}, {"s": 538.372, "e": 541.522, "en": "Then perhaps this is the one\nhappy result of his death.", "ko": "그분이 돌아가셔서 생긴\n유일한 좋은 일이네요", "it": false}, {"s": 541.542, "e": 543.625, "en": "Goodbye, mrs. Steiner.", "ko": "잘 가요, 스타이너 부인", "it": false}, {"s": 557.04, "e": 560.875, "en": "How would you like to be\nthe new head housekeeper?", "ko": "새 가정부장을\n맡아 보지 않을래요?", "it": false}, {"s": 560.969, "e": 563.395, "en": "I would like that very much.", "ko": "정말 하고 싶어요", "it": false}, {"s": 563.546, "e": 564.729, "en": "Thank you.", "ko": "감사합니다", "it": false}, {"s": 566.244, "e": 568.698, "en": "Your next payment will\nreflect your new position.", "ko": "다음 급여부터\n새 직책에 맞춰 줄게요", "it": false}, {"s": 568.794, "e": 571.407, "en": "And your first task is to ensure\nthat the rest of the staff", "ko": "첫 번째 할 일은\n다른 하인들이", "it": false}, {"s": 571.432, "e": 572.781, "en": "Stays out of the east wing.", "ko": "동쪽 별관에 못 들어가게\n하는 거예요", "it": false}, {"s": 572.806, "e": 573.885, "en": "But shouldn't we...", "ko": "하지만 그래도...", "it": false}, {"s": 573.91, "e": 575.069, "en": "No one should enter\nthe east wing.", "ko": "아무도 동쪽 별관에\n들어가선 안 돼요", "it": false}, {"s": 575.093, "e": 577.944, "en": "Not for any reason.\nDo you understand?", "ko": "무슨 일이 있어도요\n알아들었어요?", "it": false}, {"s": 577.969, "e": 578.969, "en": "Yes, ma'am.", "ko": "네, 마님", "it": false}, {"s": 580.08, "e": 581.913, "en": "One thing before you go.", "ko": "가시기 전에 하나만요", "it": false}, {"s": 582.991, "e": 584.808, "en": "I was just in the library", "ko": "방금 서재에 있었는데", "it": false}, {"s": 584.901, "e": 587.234, "en": "And I saw that the door\nto the attic was open.", "ko": "다락방 문이\n열려 있더라고요", "it": false}, {"s": 587.329, "e": 589.07, "en": "Do you need me to\nget you anything?", "ko": "뭐 가져다 드릴까요?", "it": false}, {"s": 589.089, "e": 592.148, "en": "I'd hate for you to go up\nthere in your condition.", "ko": "그 몸으로 거기 올라가시면\n안 될 것 같아서요", "it": false}, {"s": 592.167, "e": 594.241, "en": "There's another\nentrance to the attic?", "ko": "다락방으로 가는\n입구가 또 있어요?", "it": false}, {"s": 594.336, "e": 596.222, "en": "It's the old servant staircase.", "ko": "옛날 하인용 계단이에요", "it": false}, {"s": 596.338, "e": 597.671, "en": "Take me there now.", "ko": "지금 당장 데려가 줘요", "it": false}, {"s": 614.942, "e": 616.162, "en": "Please get one of the carpenters", "ko": "목수를 불러서", "it": false}, {"s": 616.186, "e": 618.116, "en": "To seal up this\ndoor immediately.", "ko": "이 문을 당장\n막아 버리라고 해요", "it": false}, {"s": 618.343, "e": 621.511, "en": "We won't be needing\nthis access anymore.", "ko": "이제 이쪽 통로는\n필요 없어요", "it": false}, {"s": 621.529, "e": 623.288, "en": "Certainly, ma'am.", "ko": "알겠습니다, 마님", "it": false}, {"s": 642.406, "e": 646.252, "en": "You said you would take care\nof him and he came anyway.", "ko": "그 사람은 알아서 하겠다더니\n또 왔잖아요", "it": false}, {"s": 646.371, "e": 647.537, "en": "I know.", "ko": "알아요", "it": false}, {"s": 647.63, "e": 652.058, "en": "I'm truly sorry. I failed you.", "ko": "정말 미안해요\n내가 못 지켰어요", "it": false}, {"s": 652.152, "e": 653.992, "en": "But I know a way to stop him.", "ko": "하지만 그를 막을\n방법이 있어요", "it": false}, {"s": 657.64, "e": 659.157, "en": "Your hair.", "ko": "당신 머리카락이요", "it": false}, {"s": 661.401, "e": 662.401, "en": "What?", "ko": "네?", "it": false}, {"s": 662.426, "e": 664.521, "en": "Malcolm likes things of beauty.", "ko": "맬컴은 아름다운 걸 좋아해요", "it": false}, {"s": 665.724, "e": 668.908, "en": "No, no. I couldn't.\nI couldn't.", "ko": "안 돼요, 안 돼요\n그건 못 해요", "it": false}, {"s": 669.06, "e": 672.711, "en": "Peace of mind is more\nimportant than vanity.", "ko": "허영보다 마음의 평화가\n더 중요해요", "it": false}, {"s": 673.467, "e": 674.89, "en": "It's the only way.", "ko": "이 방법뿐이에요", "it": false}, {"s": 730.121, "e": 731.804, "en": "Now, I'm telling you, celia.", "ko": "정말이라니까, 실리아", "it": false}, {"s": 731.898, "e": 735.716, "en": "Something strange is\ngoing on up in that house.", "ko": "저 집에서 이상한 일이\n벌어지고 있어", "it": false}, {"s": 735.736, "e": 737.31, "en": "Stranger than normal.", "ko": "평소보다 더 이상한 일이", "it": false}, {"s": 737.404, "e": 739.571, "en": "Lord help us then.", "ko": "그럼 주님이\n도와주셔야겠네", "it": false}, {"s": 739.714, "e": 741.961, "en": "Mrs. Foxworth has\nforbidden anyone", "ko": "마님께서 아무도", "it": false}, {"s": 741.986, "e": 743.466, "en": "From going into the east wing.", "ko": "동쪽 별관에 들어가지\n못하게 하셨어", "it": false}, {"s": 743.485, "e": 745.525, "en": "Well, you better\nstay out of it, mama.", "ko": "그럼 엄마도\n가까이 가지 마", "it": false}, {"s": 745.561, "e": 748.877, "en": "Because whatever it is\nit's probably not any good.", "ko": "뭐가 됐든\n좋은 일은 아닐 테니까", "it": false}, {"s": 749.474, "e": 752.083, "en": "- That place...\n- I know.", "ko": "-그 집은...\n-알아", "it": false}, {"s": 752.31, "e": 754.711, "en": "Nothing but evil\ncomes from that house.", "ko": "그 집에선 나쁜 일밖에\n안 생겨", "it": false}, {"s": 756.815, "e": 758.427, "en": "But mrs. Foxworth...", "ko": "그래도 마님은...", "it": false}, {"s": 760.093, "e": 761.742, "en": "She's different.", "ko": "다른 분이야", "it": false}, {"s": 761.762, "e": 765.597, "en": "She's a white person.\nYou don't know her.", "ko": "그 여자도 백인이야\n엄마는 그 여자 몰라", "it": false}, {"s": 765.824, "e": 767.081, "en": "Not really.", "ko": "제대로는 모르잖아", "it": false}, {"s": 767.1, "e": 770.101, "en": "I know enough to know\nthat she's not like him.", "ko": "그 남자와 다르다는 것쯤은\n알 만큼은 알아", "it": false}, {"s": 770.328, "e": 772.253, "en": "Maybe so.", "ko": "그럴지도", "it": false}, {"s": 772.347, "e": 774.019, "en": "But just cause judas\nain't the devil", "ko": "하지만 유다가\n악마는 아니라고 해서", "it": false}, {"s": 774.044, "e": 776.353, "en": "Doesn't make him someone\nyou should trust.", "ko": "믿어도 되는\n사람은 아니잖아", "it": false}, {"s": 783.341, "e": 784.449, "en": "Olivia.", "ko": "올리비아", "it": false}, {"s": 788.346, "e": 789.454, "en": "A moment.", "ko": "잠깐 오시오", "it": false}, {"s": 795.687, "e": 796.61, "en": "Yes?", "ko": "왜?", "it": false}, {"s": 796.63, "e": 798.936, "en": "I would like to\nshow you something.", "ko": "보여 줄 게 있소", "it": false}, {"s": 800.116, "e": 806.529, "en": "A letter to\nwestmoreland sanitarium.", "ko": "웨스트모어랜드 요양원에\n보낼 편지요", "it": false}, {"s": 806.622, "e": 811.1, "en": "All about my poor,\nsad, deluded wife.", "ko": "가엾고 불쌍하고\n망상에 빠진 내 아내 얘기지", "it": false}, {"s": 814.372, "e": 817.54, "en": "My beloved olivia who\nnever quite recovered", "ko": "사랑하는 내 아내 올리비아는", "it": false}, {"s": 817.633, "e": 820.56, "en": "After learning that\nshe was infertile.", "ko": "불임이라는 걸 알고 나서\n끝내 회복하지 못했다", "it": false}, {"s": 820.712, "e": 826.382, "en": "She has even been pretending\nto be with child for months.", "ko": "몇 달째 임신한 척까지\n하고 있다", "it": false}, {"s": 826.401, "e": 829.31, "en": "Surely an extended stay", "ko": "분명 오래 입원하면", "it": false}, {"s": 829.329, "e": 835.575, "en": "Would help her recover\nfrom her psychosis.", "ko": "정신병에서 회복하는 데\n도움이 될 거라고", "it": false}, {"s": 835.669, "e": 837.818, "en": "They would never believe you.", "ko": "아무도 안 믿을 거야", "it": false}, {"s": 837.838, "e": 842.248, "en": "Really? A woman's\nword over mine?", "ko": "그렇소? 여자 말을\n내 말보다 믿겠소?", "it": false}, {"s": 842.342, "e": 847.904, "en": "I did not appreciate that\nlittle gift you left on my desk.", "ko": "내 책상에 두고 간\n그 작은 선물, 불쾌하더군", "it": false}, {"s": 847.922, "e": 852.408, "en": "No more stunts like that\nor I will send this letter.", "ko": "또 그런 짓을 하면\n이 편지를 보내겠소", "it": false}, {"s": 852.427, "e": 854.911, "en": "There's just one problem.", "ko": "문제가 하나 있는데", "it": false}, {"s": 854.929, "e": 857.259, "en": "How will my equally\nbeloved husband", "ko": "똑같이 사랑하는\n내 남편께서", "it": false}, {"s": 857.284, "e": 860.56, "en": "Explain how he came into\npossession of a newborn?", "ko": "갓난아이를 어디서 났는지\n어떻게 설명하려고?", "it": false}, {"s": 860.585, "e": 863.01, "en": "Alicia will never let\nyou raise the baby alone.", "ko": "앨리샤는 당신 혼자\n아이를 키우게 두지 않을 거야", "it": false}, {"s": 863.029, "e": 865.346, "en": "Alicia might not have\na say in the matter.", "ko": "앨리샤한테는\n선택권이 없을지도 모르오", "it": false}, {"s": 865.365, "e": 869.85, "en": "We all know how dangerous\nchildbirth can be.", "ko": "출산이 얼마나 위험한지는\n다들 알잖소", "it": false}, {"s": 869.87, "e": 872.945, "en": "Perhaps you have forgotten\none tiny bit of information.", "ko": "당신이 사소한 사실 하나를\n잊었나 본데", "it": false}, {"s": 873.098, "e": 876.282, "en": "You killed your father\nand raped your stepmother.", "ko": "당신은 아버지를 죽이고\n새어머니를 강간했어", "it": false}, {"s": 876.376, "e": 879.377, "en": "Maybe it's time to share that\ntidbit with the authorities.", "ko": "이제 그 얘길 당국에\n알릴 때가 됐나 보네", "it": false}, {"s": 883.699, "e": 885.712, "en": "I am your authority\nin this house.", "ko": "이 집에선\n내가 곧 당국이오", "it": false}, {"s": 887.203, "e": 889.962, "en": "You can play act you're\nin control all you want.", "ko": "원하는 만큼\n통제하는 척해 보시오", "it": false}, {"s": 890.115, "e": 892.539, "en": "And none of this is real.", "ko": "이건 다 진짜가 아니오", "it": false}, {"s": 892.559, "e": 896.549, "en": "Not your rules.\nNot your threats.", "ko": "당신 규칙도,\n당신 협박도", "it": false}, {"s": 896.574, "e": 898.648, "en": "And the pregnancy,", "ko": "그리고 임신도", "it": false}, {"s": 899.065, "e": 901.048, "en": "You are just a sad woman", "ko": "당신은 그저", "it": false}, {"s": 901.142, "e": 905.478, "en": "With a sour face\nand a dead womb.", "ko": "시큰둥한 얼굴에\n죽은 자궁을 가진 불쌍한 여자요", "it": false}, {"s": 979.295, "e": 981.653, "en": "We don't get many\nladies around here,", "ko": "여기 숙녀분은\n잘 안 오는데", "it": false}, {"s": 981.678, "e": 984.074, "en": "But I'd be happy to\nfigure something out", "ko": "값만 맞으면", "it": false}, {"s": 984.099, "e": 985.319, "en": "For the right price, honey.", "ko": "어떻게든 해 드릴 수 있죠", "it": false}, {"s": 985.405, "e": 987.497, "en": "No, I'm not here for that.", "ko": "아니요, 그런 일로\n온 게 아니에요", "it": false}, {"s": 992.399, "e": 995.234, "en": "Oh. You want to\nget rid of that.", "ko": "아, 그걸\n지우고 싶으신 거구나", "it": false}, {"s": 995.495, "e": 997.043, "en": "Let me fetch miss hazel.", "ko": "헤이즐 언니 불러올게요", "it": false}, {"s": 997.068, "e": 1000.147, "en": "What? No! Goodness no.", "ko": "네? 아니요!\n절대 아니에요", "it": false}, {"s": 1000.241, "e": 1001.958, "en": "Thank you very much.", "ko": "정말 고마워요", "it": false}, {"s": 1010.235, "e": 1013.419, "en": "Since malcolm had found\nother means for release,", "ko": "맬컴이 다른 데서\n욕구를 풀게 되면서", "it": true}, {"s": 1013.571, "e": 1015.513, "en": "Alicia was finally safe", "ko": "앨리샤는 마침내\n안전해졌다", "it": true}, {"s": 1015.74, "e": 1018.832, "en": "And I could focus on\nwhat really mattered...", "ko": "그리고 나는 정말 중요한 것에\n집중할 수 있었다", "it": true}, {"s": 1019.074, "e": 1020.291, "en": "The children.", "ko": "아이들", "it": true}, {"s": 1022.088, "e": 1023.754, "en": "Stop it, mommy!", "ko": "그만해요, 엄마!", "it": false}, {"s": 1025.433, "e": 1027.225, "en": "Can I call you mommy?", "ko": "엄마라고 불러도 돼요?", "it": false}, {"s": 1031.105, "e": 1033.698, "en": "Of course you can, my love.", "ko": "그럼, 되고말고", "it": false}, {"s": 1040.719, "e": 1041.719, "en": "Go.", "ko": "가자", "it": false}, {"s": 1041.744, "e": 1043.233, "en": "What about me?", "ko": "나는요?", "it": false}, {"s": 1049.365, "e": 1051.107, "en": "What's that noise?", "ko": "무슨 소리지?", "it": false}, {"s": 1051.125, "e": 1053.534, "en": "Nothing. Let's all head inside.", "ko": "아무것도 아니야\n다들 들어가자", "it": false}, {"s": 1053.553, "e": 1055.869, "en": "Christopher, christopher!\nPlease look at me!", "ko": "크리스토퍼, 크리스토퍼!\n엄마 좀 봐!", "it": false}, {"s": 1059.571, "e": 1061.288, "en": "You broke my trust.", "ko": "당신이 내 믿음을 저버렸어요", "it": false}, {"s": 1061.313, "e": 1063.39, "en": "You took my son away from me.", "ko": "내 아들을 빼앗아 갔잖아요", "it": false}, {"s": 1063.415, "e": 1066.472, "en": "I'm not the enemy\nhere. Malcolm is.", "ko": "난 적이 아니에요\n적은 맬컴이에요", "it": false}, {"s": 1066.624, "e": 1068.523, "en": "Don't play innocent.", "ko": "모르는 척하지 마요", "it": false}, {"s": 1068.548, "e": 1070.476, "en": "This scheme was all your idea.", "ko": "이건 다 당신 계획이었잖아요", "it": false}, {"s": 1070.57, "e": 1072.812, "en": "Yes. To save our family.", "ko": "맞아요\n우리 가족을 지키려고요", "it": false}, {"s": 1072.837, "e": 1075.265, "en": "To protect the foxworth\nname for our sons.", "ko": "우리 아들들을 위해\n폭스워스 가문 이름을 지키려고요", "it": false}, {"s": 1075.29, "e": 1077.201, "en": "I don't believe you.", "ko": "못 믿겠어요", "it": false}, {"s": 1077.226, "e": 1080.06, "en": "I saw the way that you\nlooked at christopher.", "ko": "크리스토퍼를 보는\n당신 눈빛을 봤어요", "it": false}, {"s": 1080.08, "e": 1082.997, "en": "I know you want more children\nand I know you can't have them.", "ko": "아이를 더 원하는데\n가질 수 없다는 것도 알아요", "it": false}, {"s": 1084.642, "e": 1088.144, "en": "I think you want my baby\njust as much as he does.", "ko": "당신도 그 사람만큼\n내 아이를 원하는 거잖아요", "it": false}, {"s": 1088.237, "e": 1090.07, "en": "Is that what you think of me?", "ko": "날 그렇게 생각해요?", "it": false}, {"s": 1090.09, "e": 1093.135, "en": "You keep me locked up in this\nroom like some kind of prisoner.", "ko": "이 방에 날\n죄수처럼 가둬 두잖아요", "it": false}, {"s": 1093.16, "e": 1095.346, "en": "May I remind you that you\nweren't forced into this.", "ko": "다시 말하지만\n억지로 시킨 거 아니에요", "it": false}, {"s": 1095.371, "e": 1097.055, "en": "You agreed to these terms.", "ko": "당신이 동의한 거예요", "it": false}, {"s": 1098.172, "e": 1099.782, "en": "Well, I don't agree\nto them anymore.", "ko": "이젠 동의 안 해요", "it": false}, {"s": 1103.972, "e": 1105.138, "en": "You can't leave.", "ko": "떠나면 안 돼요", "it": false}, {"s": 1105.163, "e": 1106.604, "en": "Oh, really?", "ko": "그래요?", "it": false}, {"s": 1108.257, "e": 1111.517, "en": "If you go, malcolm won't\ngive you your inheritance.", "ko": "떠나면 맬컴은\n유산을 안 줄 거예요", "it": false}, {"s": 1111.611, "e": 1113.949, "en": "I don't care about the money.", "ko": "돈은 상관없어요", "it": false}, {"s": 1113.974, "e": 1116.918, "en": "I am taking christopher and\nI will manage on my own.", "ko": "크리스토퍼 데리고\n혼자 어떻게든 살 거예요", "it": false}, {"s": 1116.943, "e": 1118.075, "en": "How?", "ko": "어떻게요?", "it": false}, {"s": 1118.1, "e": 1120.629, "en": "You've never worked\na day in your life.", "ko": "평생\n일 한 번 안 해 봤잖아요", "it": false}, {"s": 1120.654, "e": 1122.511, "en": "You can't support yourself.", "ko": "혼자 먹고살 수 없어요", "it": false}, {"s": 1122.605, "e": 1124.605, "en": "And how will you\nhide your pregnancy?", "ko": "임신은 또\n어떻게 숨길 거예요?", "it": false}, {"s": 1124.63, "e": 1127.959, "en": "Everyone will know the\nbaby couldn't be garland's.", "ko": "다들 갈랜드 아이일 리\n없다는 걸 알 거예요", "it": false}, {"s": 1128.077, "e": 1130.396, "en": "But at least I'll\nhave my freedom.", "ko": "그래도 최소한\n자유는 얻잖아요", "it": false}, {"s": 1131.189, "e": 1133.022, "en": "Do you know what\nmalcolm would do to you,", "ko": "당신이 떠나면 맬컴이\n무슨 짓을 할지 알아요?", "it": false}, {"s": 1133.04, "e": 1136.287, "en": "To both of us, if you left?", "ko": "당신한테도,\n나한테도요", "it": false}, {"s": 1137.474, "e": 1138.863, "en": "Whatever he might do", "ko": "무슨 짓을 하든", "it": false}, {"s": 1138.888, "e": 1141.17, "en": "Can't be worse than\nwhat he's already done.", "ko": "이미 한 짓보다\n더 나쁘진 않을 거예요", "it": false}, {"s": 1141.975, "e": 1144.291, "en": "That child belongs here!", "ko": "그 아이는 여기 있어야 해요!", "it": false}, {"s": 1144.385, "e": 1146.869, "en": "My child belongs\nwith his mother!", "ko": "내 아이는\n엄마 곁에 있어야 해요!", "it": false}, {"s": 1146.962, "e": 1148.98, "en": "This is the last\ntime I'll say it.", "ko": "마지막으로 말할게요", "it": false}, {"s": 1150.489, "e": 1155.879, "en": "Get in line or I can make\nthings much worse for you.", "ko": "시키는 대로 해요\n안 그러면 더 힘들어질 거예요", "it": false}, {"s": 1159.842, "e": 1161.754, "en": "You are just as bad as he is.", "ko": "당신도 그 사람이랑\n똑같아요", "it": false}, {"s": 1163.554, "e": 1165.388, "en": "Let me go. Let\nme go! Let me go!", "ko": "놔요, 놔요! 놓으라고요!", "it": false}, {"s": 1165.406, "e": 1166.49, "en": "No!", "ko": "안 돼!", "it": false}, {"s": 1168.059, "e": 1169.059, "en": "Alicia.", "ko": "앨리샤", "it": false}, {"s": 1169.335, "e": 1170.501, "en": "I'm so sorry.", "ko": "정말 미안해요", "it": false}, {"s": 1171.82, "e": 1173.171, "en": "Are you all right?", "ko": "괜찮아요?", "it": false}, {"s": 1173.398, "e": 1174.398, "en": "Ah!", "ko": "아!", "it": false}, {"s": 1178.436, "e": 1179.436, "en": "Ahhhhh!!!", "ko": "아아악!", "it": false}, {"s": 1180.68, "e": 1181.68, "en": "Malcolm!", "ko": "맬컴!", "it": false}, {"s": 1184.923, "e": 1185.923, "en": "Malcolm!", "ko": "맬컴!", "it": false}, {"s": 1191.422, "e": 1193.717, "en": "Malcolm help! Stop her!", "ko": "맬컴, 도와줘!\n앨리샤를 막아!", "it": false}, {"s": 1200.683, "e": 1203.592, "en": "Let go. Let go! Let\ngo of me, let go!!", "ko": "놔요, 놔! 놓으라고요!", "it": false}, {"s": 1203.978, "e": 1204.978, "en": "No!", "ko": "안 돼!", "it": false}, {"s": 1217.618, "e": 1218.618, "en": "Alicia!", "ko": "앨리샤!", "it": false}, {"s": 1235.977, "e": 1236.977, "en": "She's alive.", "ko": "살아 있어", "it": false}, {"s": 1237.052, "e": 1238.454, "en": "The baby? What about the baby?", "ko": "아이는?\n아이는 어떻게 됐소?", "it": false}, {"s": 1238.479, "e": 1239.949, "en": "I don't know, I don't know!", "ko": "몰라, 모른다고!", "it": false}, {"s": 1239.974, "e": 1241.34, "en": "If that baby is\nhurt so help me god", "ko": "그 아이가 다쳤으면\n맹세컨대", "it": false}, {"s": 1241.365, "e": 1243.224, "en": "That letter to westmoreland\nwill be in the post tomorrow", "ko": "웨스트모어랜드에\n그 편지를 내일 부칠 거요", "it": false}, {"s": 1243.248, "e": 1245.164, "en": "And you will spend the rest\nof your days in a padded cell.", "ko": "그리고 당신은 남은 평생을\n독방에서 보내게 될 거요", "it": false}, {"s": 1245.188, "e": 1246.612, "en": "You won't send that letter.", "ko": "그 편지는 못 보낼걸", "it": false}, {"s": 1246.637, "e": 1248.278, "en": "Unless of course you\nwant the foxworth name", "ko": "폭스워스 가문 이름이", "it": false}, {"s": 1248.302, "e": 1250.283, "en": "Splashed all over the\nfront page of the paper.", "ko": "신문 1면을 도배하길\n바라는 게 아니라면", "it": false}, {"s": 1250.308, "e": 1252.566, "en": "\"esteemed businessman\nmalcolm foxworth", "ko": "\"존경받는 사업가\n맬컴 폭스워스", "it": false}, {"s": 1252.591, "e": 1256.312, "en": "\"seen frequenting house of\nill repute.\" I followed you.", "ko": "\"사창가 단골로 목격\"\"\n당신 뒤를 밟았거든", "it": false}, {"s": 1256.405, "e": 1258.113, "en": "Now if you want\nto save this baby", "ko": "이 아이를\n살리고 싶다면", "it": false}, {"s": 1258.138, "e": 1260.902, "en": "You need to stop threatening\nme and start listening.", "ko": "협박은 그만두고\n내 말을 들어", "it": false}, {"s": 1260.927, "e": 1263.591, "en": "We're running out of time.\nWe need to call the doctor.", "ko": "시간이 없어\n의사를 불러야 해", "it": false}, {"s": 1265.008, "e": 1266.394, "en": "How do we explain away all this?", "ko": "이걸 다\n어떻게 설명할 거요?", "it": false}, {"s": 1266.419, "e": 1268.766, "en": "I will handle that. I'll\ncall the doctor now.", "ko": "그건 내가 알아서 해\n지금 의사를 부를게", "it": false}, {"s": 1293.442, "e": 1296.777, "en": "I'll fix myself up and\ngo wait for the doctor.", "ko": "난 옷매무새를 고치고\n의사를 기다릴게", "it": false}, {"s": 1296.802, "e": 1299.196, "en": "Are you sure about this?", "ko": "정말 이렇게 할 거요?", "it": false}, {"s": 1299.857, "e": 1301.257, "en": "Yes.", "ko": "그래", "it": false}, {"s": 1307.249, "e": 1310.176, "en": "Thank you for coming in\nthe middle of the night.", "ko": "한밤중에 와 주셔서\n감사해요", "it": false}, {"s": 1310.201, "e": 1313.385, "en": "Anything for the foxworths.", "ko": "폭스워스 집안 일이라면\n언제든지요", "it": false}, {"s": 1313.538, "e": 1316.889, "en": "I see you are in the\nfamily way. How wonderful.", "ko": "아이를 가지셨군요\n정말 잘됐습니다", "it": false}, {"s": 1316.914, "e": 1318.413, "en": "My apologies.", "ko": "사과드립니다", "it": false}, {"s": 1318.438, "e": 1323.022, "en": "I suppose my diagnosis about\nyour infertility was wrong.", "ko": "불임이라는 제 진단이\n틀렸나 보군요", "it": false}, {"s": 1323.047, "e": 1326.068, "en": "We have been blessed.\nIt's quite a miracle.", "ko": "저희가 축복을 받았죠\n정말 기적이에요", "it": false}, {"s": 1326.093, "e": 1327.093, "en": "Indeed.", "ko": "그렇네요", "it": false}, {"s": 1327.118, "e": 1328.781, "en": "But you're, you're\nfeeling all right?", "ko": "그런데 몸은,\n몸은 괜찮으시고요?", "it": false}, {"s": 1328.806, "e": 1332.343, "en": "Yes. But we didn't\ncall you here for me.", "ko": "네, 하지만 저 때문에\n부른 게 아니에요", "it": false}, {"s": 1332.368, "e": 1334.723, "en": "You see, there's\nsomething rather delicate", "ko": "사실 좀\n민감한 일이 있어서", "it": false}, {"s": 1334.742, "e": 1336.21, "en": "I'd like to share with you.", "ko": "말씀드리려고요", "it": false}, {"s": 1336.235, "e": 1340.509, "en": "And we, of course,\nappreciate your discretion.", "ko": "물론 비밀은\n지켜 주시리라 믿습니다", "it": false}, {"s": 1342.675, "e": 1344.416, "en": "Of course.", "ko": "물론이죠", "it": false}, {"s": 1344.666, "e": 1345.954, "en": "This way.", "ko": "이쪽입니다", "it": false}, {"s": 1353.549, "e": 1355.427, "en": "Mrs. Foxworth will be fine.", "ko": "폭스워스 부인은\n괜찮으실 겁니다", "it": false}, {"s": 1355.452, "e": 1356.951, "en": "And the baby?", "ko": "아이는요?", "it": false}, {"s": 1356.976, "e": 1358.556, "en": "Heartbeat sounds strong.", "ko": "심장 소리가\n힘차게 들립니다", "it": false}, {"s": 1360.195, "e": 1362.315, "en": "Thank you, doctor.\nThat is wonderful news.", "ko": "감사합니다, 선생님\n정말 다행이에요", "it": false}, {"s": 1364.123, "e": 1365.231, "en": "Where am I?", "ko": "여기가 어디예요?", "it": false}, {"s": 1365.256, "e": 1367.013, "en": "You're in your\nbed, mrs. Foxworth.", "ko": "침대에 계십니다,\n폭스워스 부인", "it": false}, {"s": 1367.033, "e": 1369.317, "en": "You had quite the nasty spill.", "ko": "심하게 넘어지셨어요", "it": false}, {"s": 1370.261, "e": 1371.261, "en": "You.", "ko": "당신", "it": false}, {"s": 1375.84, "e": 1377.339, "en": "She's evil.", "ko": "저 여자는 악마예요", "it": false}, {"s": 1377.364, "e": 1381.376, "en": "Now alicia, please.\nIt's me, olivia.", "ko": "앨리샤, 제발\n나예요, 올리비아", "it": false}, {"s": 1381.401, "e": 1382.931, "en": "We're here to help you.", "ko": "우린 도우러 온 거예요", "it": false}, {"s": 1382.956, "e": 1385.274, "en": "No, no, no. They're keeping\nme prisoner here. They...", "ko": "아니, 아니, 아니에요\n저 사람들이 날 가둬 놨어요", "it": false}, {"s": 1385.292, "e": 1386.717, "en": "She's worse than you said.", "ko": "말씀하신 것보다\n상태가 심각하군요", "it": false}, {"s": 1386.742, "e": 1388.876, "en": "Ever since garland died she's\nbeen slowly losing her mind.", "ko": "갈랜드가 죽은 뒤로\n서서히 정신을 놓고 있어요", "it": false}, {"s": 1388.9, "e": 1390.232, "en": "She even did that\nto her own hair.", "ko": "자기 머리카락까지\n저렇게 잘랐어요", "it": false}, {"s": 1390.257, "e": 1391.257, "en": "No, they're lying.", "ko": "아니에요, 다 거짓말이에요", "it": false}, {"s": 1391.282, "e": 1392.517, "en": "You have to... You\nhave to believe me.", "ko": "믿어 주세요...\n제발 믿어 주세요", "it": false}, {"s": 1392.541, "e": 1394.283, "en": "- I believe you.\n- You have to believe me.", "ko": "-믿어요\n-믿어 주셔야 해요", "it": false}, {"s": 1394.301, "e": 1395.596, "en": "She just can't\naccept that her grief", "ko": "슬픔을 못 이겨서", "it": false}, {"s": 1395.62, "e": 1397.039, "en": "Sent her into the arms\nof one of the servants.", "ko": "하인 품에 안긴 걸\n인정하지 못하는 거예요", "it": false}, {"s": 1397.063, "e": 1398.204, "en": "No, no, no, no.", "ko": "아니, 아니, 아니에요", "it": false}, {"s": 1398.229, "e": 1400.234, "en": "It was him. He did it to me.", "ko": "저 남자예요\n저 남자가 그랬어요", "it": false}, {"s": 1400.259, "e": 1401.593, "en": "He forced himself on me.", "ko": "저 사람이 날 강제로...", "it": false}, {"s": 1401.618, "e": 1402.526, "en": "Mrs. Foxworth...", "ko": "폭스워스 부인...", "it": false}, {"s": 1402.551, "e": 1404.568, "en": "that's a new one.", "ko": "그건 또 처음 듣는 말이군", "it": false}, {"s": 1404.795, "e": 1406.365, "en": "There must be some\nsort of sedative", "ko": "신경을 가라앉힐\n진정제 같은 거라도", "it": false}, {"s": 1406.39, "e": 1408.11, "en": "You could give her\nto calm the nerves.", "ko": "좀 놔 주실 수 있을까요?", "it": false}, {"s": 1408.135, "e": 1409.442, "en": "No, no, no, no, no.", "ko": "안 돼, 안 돼, 안 돼요", "it": false}, {"s": 1409.467, "e": 1410.223, "en": "Alicia.", "ko": "앨리샤", "it": false}, {"s": 1410.243, "e": 1411.127, "en": "Hold her down, hold her down!", "ko": "붙잡아, 붙잡아!", "it": false}, {"s": 1411.152, "e": 1413.819, "en": "no, please no!", "ko": "안 돼요, 제발!", "it": false}, {"s": 1413.913, "e": 1414.913, "en": "All right.", "ko": "됐습니다", "it": false}, {"s": 1415.063, "e": 1417.564, "en": "-No, no, no -alright,\nmrs. Foxworth.", "ko": "-안 돼, 안 돼\n-괜찮아요, 부인", "it": false}, {"s": 1417.583, "e": 1419.623, "en": "They're lying! You\nhave to believe me!", "ko": "다 거짓말이에요!\n날 믿어 주셔야 해요!", "it": false}, {"s": 1419.735, "e": 1421.397, "en": "Help me, help me! No!\nYou have to believe me!", "ko": "살려 줘요, 살려 줘!\n날 믿어 주셔야 해요!", "it": false}, {"s": 1421.421, "e": 1422.541, "en": "Alright, just keep calm.", "ko": "자, 진정하세요", "it": false}, {"s": 1422.571, "e": 1425.981, "en": "You have to believe\nme, please no.", "ko": "날 믿어 주세요,\n제발요", "it": false}, {"s": 1426.0, "e": 1427.0, "en": "No.", "ko": "안 돼", "it": false}, {"s": 1438.271, "e": 1441.939, "en": "It was quite the gamble\ncalling the doctor here.", "ko": "의사를 부른 건\n꽤 큰 도박이었소", "it": false}, {"s": 1442.446, "e": 1445.222, "en": "But it appears you\ndid the right thing.", "ko": "하지만 당신이\n잘한 것 같군", "it": false}, {"s": 1449.173, "e": 1454.118, "en": "My daughter is alive and well\nwhich is all that matters.", "ko": "내 딸이 무사하니\n그거면 됐소", "it": false}, {"s": 1459.125, "e": 1460.674, "en": "Well done.", "ko": "잘했소", "it": false}, {"s": 1465.441, "e": 1468.342, "en": "Yes. Thank goodness.", "ko": "그래, 천만다행이야", "it": false}, {"s": 1473.03, "e": 1476.122, "en": "This baby is\nimportant to me too.", "ko": "이 아이는\n나한테도 소중해", "it": false}, {"s": 1476.142, "e": 1478.809, "en": "I won't get the chance\nto have another one.", "ko": "난 다시는 아이를\n가질 수 없으니까", "it": false}, {"s": 1483.465, "e": 1485.446, "en": "I've always wanted a daughter.", "ko": "늘 딸을 갖고 싶었어", "it": false}, {"s": 1488.321, "e": 1493.949, "en": "Yes, well, she won't truly\nbe your daughter, will she?", "ko": "그래, 하지만 진짜 당신 딸은\n아니잖소", "it": false}, {"s": 1500.833, "e": 1503.667, "en": "That ankle will make it\ndifficult to care for alicia.", "ko": "그 발목으로는\n앨리샤를 돌보기 힘들겠군", "it": false}, {"s": 1508.657, "e": 1509.898, "en": "I would offer to help", "ko": "내가 도와줄 수도 있지만", "it": false}, {"s": 1509.917, "e": 1513.177, "en": "But I know how you like\nto maintain control.", "ko": "당신은 뭐든\n직접 쥐고 있어야 직성이 풀리잖소", "it": false}, {"s": 1524.524, "e": 1527.191, "en": "I don't want any part of this.", "ko": "전 이 일에\n끼고 싶지 않아요", "it": false}, {"s": 1527.342, "e": 1530.361, "en": "I was wondering why you\nwere acting so strange.", "ko": "마님께서 왜 그렇게\n이상하게 구시나 했어요", "it": false}, {"s": 1530.512, "e": 1532.029, "en": "Now, I wish I didn't know.", "ko": "이제는 차라리\n몰랐으면 좋겠어요", "it": false}, {"s": 1532.18, "e": 1534.554, "en": "I know it sounds bad.", "ko": "나쁘게 들리는 거 알아요", "it": false}, {"s": 1534.579, "e": 1537.733, "en": "You're keeping a pregnant\nwoman locked up in the attic!", "ko": "임신한 여자를 다락방에\n가둬 두고 계시잖아요!", "it": false}, {"s": 1537.758, "e": 1539.071, "en": "It's for her own good.", "ko": "그게 그분을 위한 거예요", "it": false}, {"s": 1539.096, "e": 1540.279, "en": "Is it?", "ko": "그럴까요?", "it": false}, {"s": 1542.6, "e": 1544.099, "en": "Please.", "ko": "부탁해요", "it": false}, {"s": 1544.192, "e": 1546.21, "en": "I don't know where else to turn.", "ko": "달리 기댈 데가 없어요", "it": false}, {"s": 1567.567, "e": 1569.567, "en": "So, they got you involved now.", "ko": "이제 당신까지 끌어들였군요", "it": false}, {"s": 1571.478, "e": 1573.471, "en": "I'm helping mrs. Foxworth", "ko": "마님께서 발목을 다치셔서", "it": false}, {"s": 1573.496, "e": 1576.746, "en": "While she recovers from\nher sprained ankle.", "ko": "나을 때까지\n제가 돕는 거예요", "it": false}, {"s": 1577.243, "e": 1580.135, "en": "And don't you pull any\nof that fighting with me.", "ko": "그리고 저한텐\n행패 부리지 마세요", "it": false}, {"s": 1580.154, "e": 1581.653, "en": "I hit back.", "ko": "전 맞받아쳐요", "it": false}, {"s": 1581.962, "e": 1582.962, "en": "Hard.", "ko": "세게요", "it": false}, {"s": 1585.326, "e": 1589.66, "en": "Now... Eat.", "ko": "자... 드세요", "it": false}, {"s": 1590.981, "e": 1593.276, "en": "Don't do it because mrs.\nFoxworth told you to", "ko": "마님이 시켜서도 아니고", "it": false}, {"s": 1593.301, "e": 1595.15, "en": "Or because I told you to.", "ko": "제가 시켜서도 아니에요", "it": false}, {"s": 1595.243, "e": 1597.669, "en": "Do it because that\nchild is hungry", "ko": "그 아이가\n배고파서 드시는 거예요", "it": false}, {"s": 1597.822, "e": 1601.637, "en": "And no good mother\nwants to hurt her baby.", "ko": "자기 아이를 해치고 싶은\n엄마는 없으니까요", "it": false}, {"s": 1602.66, "e": 1605.102, "en": "Because no matter\nwhat anyone says,", "ko": "누가 뭐라 하든", "it": false}, {"s": 1605.455, "e": 1607.431, "en": "That there is your baby.", "ko": "그건 부인 아이예요", "it": false}, {"s": 1612.761, "e": 1617.098, "en": "Thank you for\nacknowledging that.", "ko": "그렇게 말해 줘서 고마워요", "it": false}, {"s": 1623.122, "e": 1624.707, "en": "Play their game.", "ko": "저 사람들 장단에 맞춰 주세요", "it": false}, {"s": 1625.349, "e": 1628.378, "en": "Then you can take your\nboy and your money", "ko": "그러면 아들이랑 돈\n챙겨서", "it": false}, {"s": 1628.403, "e": 1630.996, "en": "And be rid of this\nawful place forever.", "ko": "이 끔찍한 곳을\n영영 떠날 수 있어요", "it": false}, {"s": 1631.021, "e": 1633.113, "en": "But it's not a game.", "ko": "하지만 이건 장난이 아니에요", "it": false}, {"s": 1633.258, "e": 1634.591, "en": "It's my life.", "ko": "내 인생이라고요", "it": false}, {"s": 1634.685, "e": 1636.11, "en": "Not if you don't eat.", "ko": "굶으시면 인생이고 뭐고 없어요", "it": false}, {"s": 1636.135, "e": 1638.802, "en": "And something happens\nto that baby of yours,", "ko": "아이한테\n무슨 일이라도 생기면", "it": false}, {"s": 1638.954, "e": 1640.744, "en": "You'll be lucky to\nstill have a life", "ko": "주인님 손에\n목숨이라도 붙어 있으면", "it": false}, {"s": 1640.769, "e": 1643.027, "en": "Once mr. Foxworth\ngets through with you.", "ko": "그나마 다행일 거예요", "it": false}, {"s": 1645.085, "e": 1647.844, "en": "You think I don't\nknow what he does?", "ko": "그분이 무슨 짓을 하는지\n제가 모를 것 같으세요?", "it": false}, {"s": 1649.039, "e": 1650.791, "en": "The only thing\nthat hasn't had me", "ko": "제가 아직", "it": false}, {"s": 1650.816, "e": 1653.684, "en": "Running for the\nhills is my celia.", "ko": "도망치지 않은 이유는\n우리 실리아뿐이에요", "it": false}, {"s": 1654.228, "e": 1656.465, "en": "He paying for her schooling.", "ko": "그분이 실리아 학비를\n대 주시거든요", "it": false}, {"s": 1657.214, "e": 1659.209, "en": "And don't go thinking\nit's charity.", "ko": "자선이라고 생각하진 마세요", "it": false}, {"s": 1659.233, "e": 1661.45, "en": "It's nothing of the sort.", "ko": "전혀 그런 게 아니니까", "it": false}, {"s": 1663.812, "e": 1668.499, "en": "Mr. Foxworth is\nmy celia's father.", "ko": "주인님이\n실리아 아버지예요", "it": false}, {"s": 1671.061, "e": 1674.171, "en": "He did the same thing to\nme that he did to you.", "ko": "부인한테 한 짓을\n저한테도 하셨죠", "it": false}, {"s": 1679.753, "e": 1681.679, "en": "I'm so sorry.", "ko": "정말 안됐어요", "it": false}, {"s": 1683.59, "e": 1686.016, "en": "It was a long time ago.", "ko": "오래전 일이에요", "it": false}, {"s": 1688.595, "e": 1691.763, "en": "If I can make it through all\nthese years working for him,", "ko": "제가 그 세월 동안 그분 밑에서\n일하면서도 버텼는데", "it": false}, {"s": 1691.857, "e": 1695.083, "en": "You can make it a few more\nmonths in this here room.", "ko": "부인도 이 방에서 몇 달쯤은\n버틸 수 있어요", "it": false}, {"s": 1695.102, "e": 1698.362, "en": "Now... Eat.", "ko": "자... 드세요", "it": false}, {"s": 1711.769, "e": 1713.479, "en": "At the time\nI couldn't have known", "ko": "그때 나는\n알 수 없었다", "it": true}, {"s": 1713.504, "e": 1716.246, "en": "How much nella had in\ncommon with alicia.", "ko": "넬라와 앨리샤가\n얼마나 같은 처지였는지", "it": true}, {"s": 1728.635, "e": 1731.259, "en": "How much pain she was in.", "ko": "넬라가 얼마나\n고통받고 있었는지", "it": true}, {"s": 1734.32, "e": 1736.895, "en": "The kind of pain only\na mother could know.", "ko": "엄마만이 알 수 있는\n그런 고통을", "it": true}, {"s": 1739.98, "e": 1742.722, "en": "Because being a mother\nis all about pain.", "ko": "엄마가 된다는 건\n고통 그 자체니까", "it": true}, {"s": 1742.816, "e": 1744.953, "en": "- You hear that?\n- It's time.", "ko": "-들려요?\n-때가 됐어", "it": false}, {"s": 1745.32, "e": 1748.67, "en": "Make it convincing. You need\nto drown out her screams.", "ko": "그럴듯하게 하시오\n저 여자 비명을 덮어야 하니", "it": false}, {"s": 1775.274, "e": 1777.666, "en": "Yes, I see it! I see it!", "ko": "그래요, 보여요! 보여요!", "it": false}, {"s": 1788.695, "e": 1790.173, "en": "I can't!", "ko": "못 하겠어요!", "it": false}, {"s": 1790.219, "e": 1793.457, "en": "You can. You can do this.", "ko": "할 수 있어요\n할 수 있어요", "it": false}, {"s": 1793.608, "e": 1795.35, "en": "Push, now!", "ko": "자, 힘주세요!", "it": false}, {"s": 1825.825, "e": 1827.265, "en": "no.", "ko": "안 돼", "it": false}, {"s": 1827.309, "e": 1829.351, "en": "But she's your baby.", "ko": "그래도 부인 아기잖아요", "it": false}, {"s": 1831.163, "e": 1833.288, "en": "She belongs to them now.", "ko": "이젠 저 사람들 거예요", "it": false}, {"s": 1838.82, "e": 1841.218, "en": "Don't ever forget\nwhat they did to me.", "ko": "그 사람들이 나한테 한 짓\n절대 잊지 마요", "it": false}, {"s": 1842.082, "e": 1843.882, "en": "And to you.", "ko": "당신한테 한 짓도요", "it": false}, {"s": 1844.585, "e": 1847.109, "en": "What they can still do.", "ko": "아직도 할 수 있는 짓도요", "it": false}, {"s": 1848.199, "e": 1850.404, "en": "Don't forget who they are.", "ko": "그 사람들이 누군지 잊지 마요", "it": false}, {"s": 1850.748, "e": 1852.335, "en": "I know who they are.", "ko": "누군지 알아요", "it": false}, {"s": 1855.095, "e": 1857.521, "en": "Then why are you\nstill helping them?", "ko": "그럼 왜 아직도\n그 사람들을 도와요?", "it": false}, {"s": 1868.701, "e": 1870.221, "en": "oh.", "ko": "아", "it": false}, {"s": 1873.372, "e": 1874.854, "en": "She's perfect.", "ko": "완벽하군", "it": false}, {"s": 1878.268, "e": 1879.268, "en": "A girl.", "ko": "딸이오", "it": false}, {"s": 1883.957, "e": 1886.295, "en": "Just as I knew she would be.", "ko": "내 그럴 줄 알았지", "it": false}, {"s": 1887.277, "e": 1895.277, "en": "She is here with us\nbecause your plan worked.", "ko": "이 아이가 우리 곁에 온 건\n당신 계획이 성공한 덕분이오", "it": false}, {"s": 1896.62, "e": 1901.565, "en": "Just as you said it\nwould. Thank you, olivia.", "ko": "당신 말대로 됐소\n고맙소, 올리비아", "it": false}, {"s": 1907.889, "e": 1912.91, "en": "Welcome to the world,\nmy sweet corrine.", "ko": "세상에 온 걸 환영한다\n우리 귀여운 코린", "it": false}, {"s": 1913.137, "e": 1914.785, "en": "Corrine?", "ko": "코린?", "it": false}, {"s": 1916.064, "e": 1918.27, "en": "After my mother.", "ko": "어머니 이름을 땄소", "it": false}, {"s": 1919.81, "e": 1922.324, "en": "I assume you won't have\na problem with that.", "ko": "당신도\n불만 없을 거라 믿소", "it": false}, {"s": 1923.647, "e": 1924.922, "en": "No.", "ko": "아니", "it": false}, {"s": 1924.953, "e": 1927.136, "en": "I won't.", "ko": "없어", "it": false}, {"s": 1927.484, "e": 1930.594, "en": "Everything about her is perfect.", "ko": "이 아이는\n모든 게 완벽해", "it": false}, {"s": 1936.677, "e": 1938.621, "en": "I want to thank you.", "ko": "고마워요", "it": false}, {"s": 1939.421, "e": 1944.274, "en": "Not just for helping with\nalicia but for everything.", "ko": "앨리샤를 도와준 것뿐만 아니라\n전부 다요", "it": false}, {"s": 1944.426, "e": 1947.778, "en": "Ever since I came to this\nplace you've been there for me.", "ko": "내가 여기 온 뒤로\n당신은 늘 내 곁에 있었어요", "it": false}, {"s": 1947.929, "e": 1952.432, "en": "More than any employee,\nmore than any friend.", "ko": "그 어떤 하인보다,\n그 어떤 친구보다요", "it": false}, {"s": 1952.526, "e": 1955.012, "en": "My only friend, really.", "ko": "사실 유일한 친구죠", "it": false}, {"s": 1956.029, "e": 1958.621, "en": "What do you think a friend is?", "ko": "친구가 뭐라고 생각하세요?", "it": false}, {"s": 1959.366, "e": 1963.276, "en": "Well someone you talk to.\nSomeone who understands you.", "ko": "글쎄요, 대화하는 사람\n날 이해해 주는 사람이요", "it": false}, {"s": 1963.37, "e": 1965.778, "en": "And do you understand me?", "ko": "그럼 마님은\n절 이해하세요?", "it": false}, {"s": 1965.872, "e": 1967.631, "en": "I'd like to think I do.", "ko": "이해한다고 생각해요", "it": false}, {"s": 1967.782, "e": 1970.634, "en": "Do you even know\nanything about me?", "ko": "저에 대해 아시는 게\n있긴 하세요?", "it": false}, {"s": 1972.287, "e": 1974.546, "en": "What's my surname?", "ko": "제 성이 뭔지 아세요?", "it": false}, {"s": 1974.64, "e": 1980.051, "en": "Well I, I... I don't\nknow. It's never come up.", "ko": "그게, 그러니까...\n모르겠어요, 물어본 적이 없어서", "it": false}, {"s": 1980.145, "e": 1981.311, "en": "What's this all about?", "ko": "대체 왜 이래요?", "it": false}, {"s": 1981.538, "e": 1985.315, "en": "It's jennings. My name\nis cornelia jennings.", "ko": "제닝스예요\n제 이름은 코닐리아 제닝스예요", "it": false}, {"s": 1985.69, "e": 1986.852, "en": "Is everything all right?", "ko": "무슨 일 있어요?", "it": false}, {"s": 1986.877, "e": 1988.56, "en": "No.", "ko": "네", "it": false}, {"s": 1988.712, "e": 1990.368, "en": "Because if you knew me,", "ko": "마님이 절 아셨다면", "it": false}, {"s": 1990.393, "e": 1991.954, "en": "You would've never\nasked me to help you", "ko": "저한테 그런 일을\n도와 달라고 하지 않으셨을 거예요", "it": false}, {"s": 1991.979, "e": 1993.806, "en": "With the other mrs. Foxworth.", "ko": "다른 폭스워스 부인 일을요", "it": false}, {"s": 1993.826, "e": 1995.05, "en": "Never.", "ko": "절대로요", "it": false}, {"s": 1995.198, "e": 1996.345, "en": "Excuse me?", "ko": "뭐라고요?", "it": false}, {"s": 1996.37, "e": 1998.311, "en": "Look at me and look at you.", "ko": "저를 보시고, 마님을 보세요", "it": false}, {"s": 1998.405, "e": 2001.386, "en": "We're not friends, ma'am.", "ko": "우린 친구가 아니에요, 마님", "it": false}, {"s": 2001.915, "e": 2004.081, "en": "I gave you employment.", "ko": "난 당신한테 일자리를 줬어요", "it": false}, {"s": 2004.319, "e": 2006.664, "en": "I promoted you beyond\nwhat your station in life", "ko": "당신 신분으로는\n꿈도 못 꿀 자리까지", "it": false}, {"s": 2006.689, "e": 2007.855, "en": "Would normally allow.", "ko": "올려 줬고요", "it": false}, {"s": 2007.88, "e": 2009.795, "en": "I earned my job\nand my promotion.", "ko": "일자리도 승진도\n제 힘으로 얻은 거예요", "it": false}, {"s": 2009.991, "e": 2013.532, "en": "All this time I was operating\nunder the gross misapprehension", "ko": "그동안 내가\n크게 착각하고 있었네요", "it": false}, {"s": 2013.557, "e": 2015.052, "en": "That we were friends.", "ko": "우리가 친구라고", "it": false}, {"s": 2015.405, "e": 2017.8, "en": "I assure you that\nwill not happen again.", "ko": "다시는 그런 일\n없을 거예요", "it": false}, {"s": 2018.307, "e": 2019.899, "en": "You may go.", "ko": "가 봐요", "it": false}, {"s": 2036.426, "e": 2041.187, "en": "I've missed you so\nvery much, christopher.", "ko": "정말 많이 보고 싶었어,\n크리스토퍼", "it": false}, {"s": 2041.44, "e": 2043.44, "en": "You're\nnot my mommy.", "ko": "엄마 아니야", "it": true}, {"s": 2046.045, "e": 2047.836, "en": "He'll come around.", "ko": "곧 마음을 열 거예요", "it": false}, {"s": 2048.789, "e": 2050.38, "en": "I know.", "ko": "알아요", "it": false}, {"s": 2055.946, "e": 2058.046, "en": "I should've been kinder to you.", "ko": "당신한테 더 잘해 줬어야 했는데", "it": false}, {"s": 2058.706, "e": 2061.224, "en": "I lost sight of\nour common enemy.", "ko": "우리 공동의 적을\n잊고 있었어요", "it": false}, {"s": 2065.972, "e": 2068.19, "en": "I was hoping for a boy.", "ko": "아들이길 바랐어요", "it": false}, {"s": 2069.459, "e": 2070.459, "en": "Oh?", "ko": "그래요?", "it": false}, {"s": 2071.598, "e": 2073.223, "en": "Promise me something.", "ko": "하나만 약속해 줘요", "it": false}, {"s": 2075.299, "e": 2080.684, "en": "Protect my... Protect\nyour daughter.", "ko": "내... 아니, 당신 딸을\n지켜 줘요", "it": false}, {"s": 2083.342, "e": 2086.118, "en": "Make sure malcolm doesn't do\nto her what he's done to us.", "ko": "맬컴이 우리한테 한 짓을\n그 애한테는 못 하게 해 줘요", "it": false}, {"s": 2096.486, "e": 2100.16, "en": "I would honor my\npromise to alicia at all costs.", "ko": "나는 무슨 대가를 치르더라도\n앨리샤와의 약속을 지킬 생각이었다", "it": true}, {"s": 2105.473, "e": 2109.606, "en": "If only I knew then just how\ngreat that cost would be.", "ko": "그 대가가 얼마나 클지\n그때 알았더라면", "it": true}, {"s": 2128.554, "e": 2131.449, "en": "They say time\nheals all wounds.", "ko": "시간이 모든 상처를\n치유한다고들 한다", "it": true}, {"s": 2139.287, "e": 2141.546, "en": "But 15 years only\nmade them worse.", "ko": "하지만 15년은 상처를\n더 깊게 만들었을 뿐이다", "it": true}, {"s": 2151.817, "e": 2155.185, "en": "Thank you all for\ngathering together", "ko": "이렇게 모여 주셔서\n감사합니다", "it": false}, {"s": 2155.21, "e": 2159.322, "en": "To celebrate our dear\ncorrine's 16th birthday.", "ko": "사랑하는 코린의\n열여섯 번째 생일을 축하해 주세요", "it": false}, {"s": 2159.474, "e": 2163.195, "en": "Her father and I are so proud\nof the young woman she's become.", "ko": "아이 아빠와 저는 이렇게 자란\n딸이 정말 자랑스러워요", "it": false}, {"s": 2163.22, "e": 2167.405, "en": "So, on behalf of her\nfather and her brothers", "ko": "그래서 아이 아빠와\n오빠들을 대신해", "it": false}, {"s": 2167.557, "e": 2172.318, "en": "Joel, mal, and\nhis fiancée helen,", "ko": "조엘, 말,\n그리고 말의 약혼녀 헬렌까지", "it": false}, {"s": 2172.412, "e": 2177.732, "en": "Please join us in wishing\ncorrine a very special day.", "ko": "코린의 특별한 날을\n함께 축하해 주세요", "it": false}, {"s": 2177.757, "e": 2179.256, "en": "To corrine.", "ko": "코린을 위하여", "it": false}, {"s": 2216.715, "e": 2219.198, "en": "May I have this dance?", "ko": "이 춤은\n내가 춰도 되겠지?", "it": false}, {"s": 2219.218, "e": 2221.943, "en": "Of course, daddy. Excuse me.", "ko": "그럼요, 아빠\n실례할게요", "it": false}, {"s": 2231.265, "e": 2234.099, "en": "You've almost survived\nanother foxworth gathering.", "ko": "폭스워스 가족 모임을\n또 한 번 거의 버텼네", "it": false}, {"s": 2234.124, "e": 2236.244, "en": "Your family is always\npleasant to me, mal.", "ko": "너희 가족은 늘\n나한테 잘해 주잖아, 말", "it": false}, {"s": 2236.293, "e": 2238.401, "en": "That's because they're\nnot your family yet.", "ko": "아직 네 가족이\n아니라서 그래", "it": false}, {"s": 2243.483, "e": 2245.65, "en": "Did you know he would be here?", "ko": "저 사람 올 줄 알았어?", "it": false}, {"s": 2245.744, "e": 2247.41, "en": "Mal, stop.", "ko": "말, 그만해", "it": false}, {"s": 2247.637, "e": 2250.321, "en": "- Not now. Can we just dance?\n- Yeah.", "ko": "-지금 말고, 그냥 춤추면 안 돼?\n-그래", "it": false}, {"s": 2250.474, "e": 2252.657, "en": "Please?", "ko": "응?", "it": false}, {"s": 2289.863, "e": 2292.438, "en": "You look about as good as I do.", "ko": "너도 나만큼\n꼴이 말이 아니네", "it": false}, {"s": 2292.532, "e": 2294.44, "en": "I just needed some air.", "ko": "바람 좀 쐬고 싶었어", "it": false}, {"s": 2294.459, "e": 2298.11, "en": "Fawning over corrine\nwas making me a bit ill.", "ko": "코린한테 다들 알랑대는 거\n보니까 속이 좀 안 좋더라", "it": false}, {"s": 2298.13, "e": 2300.596, "en": "Aren't you basking in\nour sister's perfection?", "ko": "우리 여동생의 완벽함에\n흠뻑 취해 있는 거 아니었어?", "it": false}, {"s": 2300.621, "e": 2302.27, "en": "Helen's ex, bill's here.", "ko": "헬렌 전 남자 친구\n빌이 와 있어", "it": false}, {"s": 2302.542, "e": 2304.634, "en": "Bill's a dullard with bad hair.", "ko": "빌은 머리 모양도\n별로인 멍청이잖아", "it": false}, {"s": 2304.861, "e": 2306.452, "en": "I'm pretty sure he wears\nlifts in his shoes.", "ko": "분명 구두에\n깔창도 깔았을걸", "it": false}, {"s": 2306.471, "e": 2311.474, "en": "You know his dad already made\nhim vice president at 23?", "ko": "걔네 아버지가 스물셋에\n벌써 부사장을 시켜 줬대", "it": false}, {"s": 2311.626, "e": 2316.646, "en": "Helen chose you, not\nhim. She loves you.", "ko": "헬렌은 빌 말고 형을 골랐어\n형을 사랑한다고", "it": false}, {"s": 2316.798, "e": 2319.172, "en": "What if that's not enough?", "ko": "그걸로 부족하면?", "it": false}, {"s": 2320.802, "e": 2322.422, "en": "You're my big brother.", "ko": "형은 우리 형이잖아", "it": false}, {"s": 2322.97, "e": 2326.489, "en": "You know I'd jump at the chance\nto knock you down a peg or two.", "ko": "기회만 되면 내가 형 코를\n납작하게 해 주고 싶은 거 알지?", "it": false}, {"s": 2328.493, "e": 2330.493, "en": "That guy's got nothing on you.", "ko": "그런 놈은 형한테\n상대도 안 돼", "it": false}, {"s": 2337.678, "e": 2340.125, "en": "Everything was\nperfect. Thank you.", "ko": "다 완벽했어요\n고마워요", "it": false}, {"s": 2340.839, "e": 2342.339, "en": "Of course, ma'am.", "ko": "별말씀을요, 마님", "it": false}, {"s": 2350.574, "e": 2352.665, "en": "What a lovely party.", "ko": "정말 근사한 파티네요", "it": false}, {"s": 2352.759, "e": 2355.018, "en": "It is not quite over yet.", "ko": "아직 안 끝났어", "it": false}, {"s": 2355.169, "e": 2357.539, "en": "I have one more\ngift left to give.", "ko": "선물이 하나 더 있거든", "it": false}, {"s": 2358.506, "e": 2361.265, "en": "It's too big to\nbe keys to a car.", "ko": "자동차 열쇠라기엔\n너무 크고", "it": false}, {"s": 2361.418, "e": 2362.341, "en": "Mm-hmm.", "ko": "음", "it": false}, {"s": 2362.361, "e": 2364.274, "en": "Too heavy to be jewelry.", "ko": "보석이라기엔 너무 무겁고", "it": false}, {"s": 2366.756, "e": 2368.11, "en": "Oh.", "ko": "어머", "it": false}, {"s": 2368.538, "e": 2370.855, "en": "goodness.", "ko": "세상에", "it": false}, {"s": 2370.88, "e": 2374.307, "en": "A beautiful baby doll\nfor my beautiful baby.", "ko": "아름다운 우리 아기한테\n아름다운 아기 인형을", "it": false}, {"s": 2376.546, "e": 2378.771, "en": "Thank you, daddy.", "ko": "고마워요, 아빠", "it": false}, {"s": 2379.193, "e": 2381.878, "en": "I don't care how old you get,", "ko": "네가 몇 살이 되든", "it": false}, {"s": 2381.903, "e": 2384.846, "en": "You will always\nbe my little girl.", "ko": "넌 언제까지나\n아빠의 어린 딸이야", "it": false}, {"s": 2393.45, "e": 2395.45, "en": "Are you going to tell\nme what's bothering you", "ko": "뭐가 문제인지\n말해 줄래?", "it": false}, {"s": 2395.468, "e": 2397.521, "en": "Or do I have to endure\nyour sulking about", "ko": "아니면 남은 하루 내내", "it": false}, {"s": 2397.545, "e": 2400.805, "en": "For the rest of the day?", "ko": "네가 뚱해 있는 걸\n참아야 하니?", "it": false}, {"s": 2400.899, "e": 2402.732, "en": "My trust fund.", "ko": "제 신탁 기금이요", "it": false}, {"s": 2402.959, "e": 2405.643, "en": "I don't get access\nto it until I'm 25.", "ko": "스물다섯 살이\n돼야 쓸 수 있어요", "it": false}, {"s": 2405.795, "e": 2409.046, "en": "Darling, of course I'd want\nyou to have your trust early.", "ko": "얘야, 나도 당연히 네가\n신탁을 일찍 받길 바라지", "it": false}, {"s": 2409.071, "e": 2410.907, "en": "It's not just for me, no.", "ko": "저 때문만은 아니에요", "it": false}, {"s": 2411.134, "e": 2415.078, "en": "Helen's accustomed to\na certain lifestyle.", "ko": "헬렌은\n누리던 생활 수준이 있어서요", "it": false}, {"s": 2415.305, "e": 2417.385, "en": "All the money in the\nworld means nothing", "ko": "세상 돈을 다 가져도", "it": false}, {"s": 2417.474, "e": 2420.083, "en": "If there isn't true\nlove between two people.", "ko": "두 사람 사이에\n진정한 사랑이 없으면 소용없단다", "it": false}, {"s": 2420.234, "e": 2422.752, "en": "Yes, but I want\nto provide for her", "ko": "네, 하지만\n헬렌이 누리던 대로", "it": false}, {"s": 2422.777, "e": 2424.897, "en": "In the way that she's\naccustomed, and I...", "ko": "해 주고 싶어서요,\n그리고 저는...", "it": false}, {"s": 2425.03, "e": 2427.213, "en": "The trusts are your\nfather's domain.", "ko": "신탁은 네 아버지\n소관이야", "it": false}, {"s": 2427.426, "e": 2431.319, "en": "He set them up so he\nmust approve all changes.", "ko": "아버지가 만드셨으니\n바꾸려면 아버지 승인이 필요해", "it": false}, {"s": 2431.337, "e": 2434.172, "en": "If this is something\nyou really want", "ko": "정말 원한다면", "it": false}, {"s": 2434.324, "e": 2437.024, "en": "You're going to have to\ntake this up with him.", "ko": "아버지께 직접\n말씀드려야 해", "it": false}, {"s": 2438.085, "e": 2441.133, "en": "That's what I was\ntrying to avoid.", "ko": "그걸 피하고\n싶었던 건데요", "it": false}, {"s": 2441.681, "e": 2443.606, "en": "I know he can be difficult.", "ko": "아버지가 까다로운 분인 건 알아", "it": false}, {"s": 2447.614, "e": 2448.614, "en": "Huh.", "ko": "허", "it": false}, {"s": 2451.675, "e": 2453.977, "en": "I don't know how you do it.", "ko": "어머니는 어떻게\n견디셨는지 모르겠어요", "it": false}, {"s": 2455.454, "e": 2457.946, "en": "Put up with him all these years.", "ko": "그 오랜 세월을요", "it": false}, {"s": 2458.94, "e": 2461.938, "en": "I had you. That's how.", "ko": "너희가 있었으니까", "it": false}, {"s": 2465.038, "e": 2467.538, "en": "No. It, it won't be long\nbefore joel gets married", "ko": "아니요, 그게... 조엘도\n곧 결혼할 거고", "it": false}, {"s": 2467.691, "e": 2470.8, "en": "And corrine is halfway\nout the door as it is.", "ko": "코린도 이미 반쯤은\n집을 떠난 거나 다름없잖아요", "it": false}, {"s": 2470.952, "e": 2473.204, "en": "Then what will you do?", "ko": "그럼 어머니는\n어쩌실 거예요?", "it": false}, {"s": 2473.713, "e": 2476.969, "en": "A mother's work is never done.", "ko": "엄마 일엔 끝이 없단다", "it": false}, {"s": 2478.292, "e": 2479.476, "en": "I'll be fine.", "ko": "난 괜찮아", "it": false}, {"s": 2490.989, "e": 2492.78, "en": "May I come in?", "ko": "들어가도 되니?", "it": false}, {"s": 2499.981, "e": 2503.124, "en": "I didn't get to\ngive you my present.", "ko": "아직 선물을\n못 줬거든", "it": false}, {"s": 2513.57, "e": 2516.495, "en": "Every woman needs her own set.", "ko": "여자라면 자기만의\n진주 목걸이 하나쯤은 있어야지", "it": false}, {"s": 2516.589, "e": 2518.923, "en": "oh, mother.", "ko": "어머, 엄마", "it": false}, {"s": 2519.017, "e": 2520.569, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 2522.451, "e": 2525.843, "en": "At least you realize\nI'm not a child anymore.", "ko": "그래도 엄마는\n제가 이제 애가 아닌 걸 아시네요", "it": false}, {"s": 2526.007, "e": 2528.432, "en": "Your father loves you very much.", "ko": "아빠는 널 정말 사랑하셔", "it": false}, {"s": 2528.457, "e": 2530.764, "en": "It's just...", "ko": "다만...", "it": false}, {"s": 2531.437, "e": 2538.159, "en": "Well, it's hard for him to see\nyou growing up, dancing with boys.", "ko": "네가 커서 남자애들이랑\n춤추는 걸 보기 힘드신 거야", "it": false}, {"s": 2539.929, "e": 2541.704, "en": "Rockford.", "ko": "록퍼드", "it": false}, {"s": 2541.856, "e": 2543.781, "en": "Excuse me?", "ko": "뭐?", "it": false}, {"s": 2543.933, "e": 2547.451, "en": "Rockford taylor, the\nboy I was dancing with?", "ko": "록퍼드 테일러요,\n저랑 춤춘 남자애", "it": false}, {"s": 2549.122, "e": 2552.048, "en": "All I can think about is what\nit would be like to kiss him.", "ko": "그 애랑 키스하면 어떨까\n그 생각밖에 안 나요", "it": false}, {"s": 2553.793, "e": 2558.296, "en": "I want nothing more for you\nthan to find a good man to love", "ko": "엄마는 네가 사랑할\n좋은 남자를 찾고", "it": false}, {"s": 2558.39, "e": 2561.54, "en": "And to love you back.", "ko": "그 남자도 널 사랑해 주길\n누구보다 바라", "it": false}, {"s": 2561.634, "e": 2563.685, "en": "But all in due time.", "ko": "하지만 다 때가 있어", "it": false}, {"s": 2566.973, "e": 2568.498, "en": "What about you?", "ko": "엄마는요?", "it": false}, {"s": 2569.216, "e": 2570.647, "en": "What about me?", "ko": "나?", "it": false}, {"s": 2571.144, "e": 2573.399, "en": "Don't you think you\ndeserve that too?", "ko": "엄마도 그럴 자격이\n있다고 생각 안 하세요?", "it": false}, {"s": 2573.967, "e": 2575.892, "en": "A good man to love you?", "ko": "엄마를 사랑해 줄\n좋은 남자요", "it": false}, {"s": 2578.893, "e": 2584.372, "en": "When was the last\ntime... You know?", "ko": "마지막으로\n그거 한 게... 언제예요?", "it": false}, {"s": 2588.069, "e": 2592.088, "en": "What your father and I do or do\nnot do behind closed doors...", "ko": "아빠랑 내가 방문 닫고\n뭘 하든 안 하든...", "it": false}, {"s": 2592.236, "e": 2595.149, "en": "Mother, we all know\nyou don't do anything.", "ko": "엄마, 아무것도 안 하는 거\n다 알아요", "it": false}, {"s": 2596.928, "e": 2598.306, "en": "Don't you miss it?", "ko": "그립지 않으세요?", "it": false}, {"s": 2599.365, "e": 2601.274, "en": "Being touched?", "ko": "누가 만져 주는 거요", "it": false}, {"s": 2602.767, "e": 2604.175, "en": "Corrine...", "ko": "코린...", "it": false}, {"s": 2604.327, "e": 2605.97, "en": "Rock only touched my hand", "ko": "록은 제 손만\n잡았을 뿐인데", "it": false}, {"s": 2605.995, "e": 2609.013, "en": "And it felt like my\nwhole body was on fire.", "ko": "온몸에 불이\n붙는 것 같았어요", "it": false}, {"s": 2609.107, "e": 2613.173, "en": "I can't imagine never being\nable to feel that again.", "ko": "그 느낌을 다시는\n못 느낀다니 상상도 안 돼요", "it": false}, {"s": 2614.687, "e": 2620.099, "en": "Yes well, you will feel\nthat again, I promise.", "ko": "그래, 너는 다시\n느끼게 될 거야, 약속해", "it": false}, {"s": 2620.193, "e": 2622.785, "en": "So, you need not worry.", "ko": "그러니까 걱정하지 마", "it": false}, {"s": 2627.959, "e": 2630.288, "en": "Why did you marry daddy?", "ko": "엄마는 왜\n아빠랑 결혼했어요?", "it": false}, {"s": 2632.355, "e": 2634.053, "en": "Well I...", "ko": "글쎄, 그게...", "it": false}, {"s": 2635.967, "e": 2641.379, "en": "I was in love. I\nthought I was in love.", "ko": "사랑에 빠졌지\n사랑에 빠졌다고 생각했어", "it": false}, {"s": 2641.404, "e": 2643.662, "en": "When I met your father,", "ko": "아빠를 만났을 때", "it": false}, {"s": 2643.883, "e": 2646.476, "en": "He appreciated me for who I was.", "ko": "아빠는 있는 그대로의\n나를 인정해 줬어", "it": false}, {"s": 2646.627, "e": 2650.678, "en": "A businesswoman. Or\nI thought he did.", "ko": "사업하는 여자로서 말이야\n적어도 그런 줄 알았지", "it": false}, {"s": 2651.298, "e": 2654.558, "en": "And life has a way of happening.", "ko": "그리고 살다 보면\n이런저런 일이 생기고", "it": false}, {"s": 2654.711, "e": 2656.802, "en": "And before you know it\nyou've forged a path,", "ko": "정신 차려 보면\n이미 길이 나 있어", "it": false}, {"s": 2656.821, "e": 2664.147, "en": "And once on a path it's\ndifficult to change direction.", "ko": "한번 들어선 길은\n방향을 바꾸기 어려워", "it": false}, {"s": 2665.889, "e": 2670.389, "en": "And would you like that?\nTo change direction?", "ko": "그럼 바꾸고 싶으세요?\n방향을요", "it": false}, {"s": 2672.078, "e": 2677.819, "en": "What I would like is for\nyou to enjoy your youth.", "ko": "엄마가 바라는 건\n네가 젊음을 즐기는 거야", "it": false}, {"s": 2678.843, "e": 2680.418, "en": "Go to college.", "ko": "대학도 가고", "it": false}, {"s": 2680.512, "e": 2681.805, "en": "- Flirt.", "ko": "-연애도 하고", "it": false}, {"s": 2681.829, "e": 2683.587, "en": "- Dance.", "ko": "-춤도 추고", "it": false}, {"s": 2683.74, "e": 2686.061, "en": "But don't rush into anything.", "ko": "하지만 서두르진 마", "it": false}, {"s": 2688.687, "e": 2691.264, "en": "I would've liked\nthat for you too.", "ko": "엄마도 그랬으면\n좋았을 텐데", "it": false}, {"s": 2694.083, "e": 2696.025, "en": "it's getting late.", "ko": "시간이 늦었다", "it": false}, {"s": 2701.533, "e": 2703.533, "en": "Happy birthday.", "ko": "생일 축하해", "it": false}, {"s": 2711.517, "e": 2713.673, "en": "The next day I\ncouldn't shake off the thoughts", "ko": "다음 날에도\n아이들이 일깨운 생각을", "it": true}, {"s": 2713.698, "e": 2715.658, "en": "My children had awakened in me.", "ko": "떨쳐 낼 수가 없었다", "it": true}, {"s": 2717.048, "e": 2719.634, "en": "What was I to do when\nthey all left the house?", "ko": "아이들이 모두 떠나고 나면\n나는 뭘 해야 할까?", "it": true}, {"s": 2721.575, "e": 2723.058, "en": "And how had my daughter", "ko": "그리고 내 딸은 어떻게", "it": true}, {"s": 2723.083, "e": 2726.676, "en": "Grown to become a more\nfulfilled woman than I ever was?", "ko": "나보다 더 충만한 여자로\n자라난 걸까?", "it": true}, {"s": 2731.056, "e": 2732.513, "en": "I was lost.", "ko": "나는 길을 잃었다", "it": true}, {"s": 2735.808, "e": 2738.901, "en": "But in that moment\nsomething else was found.", "ko": "하지만 그 순간\n다른 무언가를 찾았다", "it": true}, {"s": 2741.555, "e": 2743.573, "en": "Something that had\nremained hidden", "ko": "그날 운명이 나를\n그곳으로 이끌기 전까지", "it": true}, {"s": 2743.598, "e": 2745.84, "en": "Until fate brought\nme there that day.", "ko": "숨겨져 있던 무언가를", "it": true}, {"s": 2748.821, "e": 2750.413, "en": "The poison garden.", "ko": "독초 정원", "it": true}, {"s": 2813.961, "e": 2816.191, "en": "Perhaps the key\nto finding myself", "ko": "어쩌면 나 자신을 찾을\n열쇠가", "it": true}, {"s": 2816.216, "e": 2819.649, "en": "Had been right at my\nfingertips all along.", "ko": "줄곧 내 손끝에\n있었는지도 몰랐다", "it": true}, {"s": 2831.793, "e": 2834.369, "en": "How many dresses do you need?", "ko": "드레스가 몇 벌이나 필요해?", "it": false}, {"s": 2834.724, "e": 2838.317, "en": "There's just um, one more\nshop I need to visit.", "ko": "그게, 들를 가게가\n딱 한 군데 더 있어서", "it": false}, {"s": 2838.336, "e": 2840.314, "en": "Look, you're bored to tears.\nWhy don't you go on home?", "ko": "오빠 지루해 죽겠잖아\n먼저 집에 가", "it": false}, {"s": 2840.338, "e": 2841.912, "en": "I can walk back.", "ko": "난 걸어갈게", "it": false}, {"s": 2842.065, "e": 2843.065, "en": "Really?", "ko": "정말?", "it": false}, {"s": 2843.551, "e": 2844.733, "en": "What?", "ko": "뭐?", "it": false}, {"s": 2844.758, "e": 2846.428, "en": "You could have just told\nme you were killing time", "ko": "애인 올 때까지\n시간 때우는 거라고", "it": false}, {"s": 2846.452, "e": 2847.71, "en": "Until lover boy showed up.", "ko": "그냥 말하지 그랬어", "it": false}, {"s": 2848.174, "e": 2850.859, "en": "Get out of here.\nMum's the word.", "ko": "가 봐\n비밀로 해 줄게", "it": false}, {"s": 2852.241, "e": 2853.241, "en": "Have fun!", "ko": "재밌게 놀아!", "it": false}, {"s": 2880.453, "e": 2881.785, "en": "I seem to have a problem.", "ko": "차에 문제가\n좀 생긴 것 같아요", "it": false}, {"s": 2881.88, "e": 2885.956, "en": "Yeah, it don't sound\ngood. Let me take a look.", "ko": "소리가 안 좋네요\n한번 볼게요", "it": false}, {"s": 2898.229, "e": 2900.971, "en": "Yeah, I think it might\nbe one of the air hoses.", "ko": "아무래도 공기 호스\n문제 같아요", "it": false}, {"s": 2901.065, "e": 2903.065, "en": "Yeah. Air hose.", "ko": "네, 공기 호스요", "it": false}, {"s": 2904.81, "e": 2906.569, "en": "So, you can fix it?", "ko": "고칠 수 있어요?", "it": false}, {"s": 2906.594, "e": 2907.944, "en": "I'd have to order a part", "ko": "부품을 주문해야 하는데", "it": false}, {"s": 2907.969, "e": 2910.089, "en": "But it shouldn't take\nmore than a few days.", "ko": "며칠이면 될 거예요", "it": false}, {"s": 2912.004, "e": 2913.004, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 2917.582, "e": 2920.065, "en": "What's that you're listening to?", "ko": "지금 듣는 거 뭐예요?", "it": false}, {"s": 2923.737, "e": 2924.979, "en": "I'm sorry sir. I\ncan turn it off.", "ko": "죄송합니다, 선생님\n끌게요", "it": false}, {"s": 2924.997, "e": 2930.544, "en": "No, no. I like it.\nAnd please, it's joel.", "ko": "아니, 아니에요, 좋아서요\n그리고 그냥 조엘이라고 불러요", "it": false}, {"s": 2931.337, "e": 2933.596, "en": "I've just never heard\nanything like that before.", "ko": "이런 음악은\n처음 들어 봐서요", "it": false}, {"s": 2933.621, "e": 2937.307, "en": "The blues doesn't usually make\nits way to rich folks like you.", "ko": "블루스는 원래 당신 같은\n부자들한텐 잘 안 닿거든요", "it": false}, {"s": 2940.775, "e": 2942.625, "en": "Well, I'm sorry for that.", "ko": "그건 유감이네요", "it": false}, {"s": 2942.687, "e": 2944.687, "en": "It seems to be our loss.", "ko": "우리가 손해 본 거죠", "it": false}, {"s": 2948.02, "e": 2950.947, "en": "There's some pretty interesting\nchord progressions in there.", "ko": "코드 진행이\n꽤 흥미로운데요", "it": false}, {"s": 2953.6, "e": 2958.156, "en": "I write music and\nplay, piano mostly.", "ko": "저도 작곡을 하고\n연주도 해요, 주로 피아노요", "it": false}, {"s": 2958.181, "e": 2961.019, "en": "Though I've done\nsome trumpet dabbling", "ko": "트럼펫도\n조금 건드려 봤고", "it": false}, {"s": 2961.367, "e": 2963.942, "en": "With some light\nclarinet sprinkled in.", "ko": "클라리넷도\n살짝 해 봤어요", "it": false}, {"s": 2969.525, "e": 2971.979, "en": "You can borrow the\nrecord if you want.", "ko": "원하면 그 음반\n빌려 가도 돼요", "it": false}, {"s": 2974.121, "e": 2977.956, "en": "I'd like that very much.", "ko": "그럼 정말 좋죠", "it": false}, {"s": 2985.11, "e": 2987.518, "en": "I'm an adult now.\nI'm getting married.", "ko": "저도 이제 어른이에요\n결혼도 하고요", "it": false}, {"s": 2987.543, "e": 2989.819, "en": "If I had access to more\ncapital to invest, I...", "ko": "투자할 자금만\n더 있으면, 저는...", "it": false}, {"s": 2989.97, "e": 2992.213, "en": "Is that what this is?", "ko": "결국 이거였어?", "it": false}, {"s": 2992.231, "e": 2994.973, "en": "Some elaborate scheme to\nget your hands on my money?", "ko": "내 돈을 손에 넣으려고\n공들여 짠 계획이야?", "it": false}, {"s": 2994.993, "e": 2997.142, "en": "That's not what I meant.", "ko": "그런 뜻이 아니에요", "it": false}, {"s": 2997.236, "e": 3001.29, "en": "The reason you have that trust\nis your mother insisted on it.", "ko": "네가 그 신탁을 받은 건\n네 어머니가 고집해서야", "it": false}, {"s": 3001.79, "e": 3004.458, "en": "Had it been up to me you would\nbe getting nothing at all.", "ko": "내 뜻대로 했으면\n넌 한 푼도 못 받았어", "it": false}, {"s": 3004.483, "e": 3005.961, "en": "Please father.", "ko": "제발요, 아버지", "it": false}, {"s": 3005.986, "e": 3007.986, "en": "Look, I do not\nrespond to begging.", "ko": "나는 애원에\n넘어가지 않는다", "it": false}, {"s": 3008.011, "e": 3010.157, "en": "It is unbecoming of a man.", "ko": "사내답지 못한 짓이야", "it": false}, {"s": 3011.992, "e": 3013.211, "en": "I think you should leave", "ko": "더 망신당하기 전에", "it": false}, {"s": 3013.236, "e": 3016.012, "en": "Before you embarrass\nyourself any further.", "ko": "나가는 게 좋겠구나", "it": false}, {"s": 3041.781, "e": 3043.281, "en": "Thank you for the ride.", "ko": "태워 줘서 고마워", "it": false}, {"s": 3043.306, "e": 3044.828, "en": "You saved my loafers for sure.", "ko": "덕분에 내 구두 살았어", "it": false}, {"s": 3044.876, "e": 3046.433, "en": "Any time.", "ko": "언제든지", "it": false}, {"s": 3046.452, "e": 3048.602, "en": "I'll see you next Saturday?", "ko": "다음 주 토요일에 볼까?", "it": false}, {"s": 3048.621, "e": 3050.004, "en": "I'll come around about 7:00.", "ko": "7시쯤 데리러 갈게", "it": false}, {"s": 3056.462, "e": 3057.582, "en": "I don't want to see you", "ko": "다시는 네가 저 녀석이랑", "it": false}, {"s": 3057.613, "e": 3060.447, "en": "Cavorting with that\nboy ever again,", "ko": "어울려 다니는 꼴\n보고 싶지 않다", "it": false}, {"s": 3060.466, "e": 3062.892, "en": "Or any boy for that matter.", "ko": "아니, 어떤 녀석이든", "it": false}, {"s": 3062.917, "e": 3065.302, "en": "But he's invited me\nto a dance next week.", "ko": "하지만 다음 주 댄스파티에\n같이 가자고 했어요", "it": false}, {"s": 3065.396, "e": 3067.207, "en": "All my friends are going\nand he's from a good family.", "ko": "친구들도 다 가고\n좋은 집안 애예요", "it": false}, {"s": 3067.231, "e": 3068.282, "en": "Please, daddy.", "ko": "제발요, 아빠", "it": false}, {"s": 3068.307, "e": 3071.474, "en": "I don't care who he is\nor who his family is.", "ko": "그 녀석이 누구든\n집안이 어떻든 상관없어", "it": false}, {"s": 3071.673, "e": 3074.295, "en": "You are too young to\nbe going to dances.", "ko": "넌 댄스파티에 가기엔\n너무 어려", "it": false}, {"s": 3074.313, "e": 3076.463, "en": "And you are most certainly too\nyoung to be spreading your legs", "ko": "오토바이 뒤에 앉아\n다리를 벌리고 다니기엔", "it": false}, {"s": 3076.482, "e": 3078.501, "en": "On the back of a motorcycle.", "ko": "더더욱 어리고", "it": false}, {"s": 3080.078, "e": 3082.82, "en": "If you would just meet him\nmaybe you would reconsider.", "ko": "한 번만 만나 보시면\n생각이 바뀌실 거예요", "it": false}, {"s": 3082.972, "e": 3085.117, "en": "I don't need to meet\nhim. I already know him.", "ko": "만날 필요 없다\n이미 다 알아", "it": false}, {"s": 3085.141, "e": 3088.475, "en": "He is a boy, and boys\nonly want one thing.", "ko": "그 녀석은 남자고,\n남자들이 원하는 건 딱 하나야", "it": false}, {"s": 3088.494, "e": 3090.419, "en": "- But daddy!\n- No, enough!", "ko": "-하지만 아빠!\n-그만, 됐어!", "it": false}, {"s": 3092.315, "e": 3094.072, "en": "No dance!", "ko": "댄스파티는 안 돼!", "it": false}, {"s": 3094.166, "e": 3096.025, "en": "End of discussion!", "ko": "얘기 끝났어!", "it": false}, {"s": 3105.127, "e": 3107.345, "en": "Wasn't that a bit harsh?", "ko": "좀 심하지 않았어?", "it": false}, {"s": 3108.388, "e": 3110.796, "en": "Corrine is a child. It\nis my job to protect her.", "ko": "코린은 어린애요\n그 앨 지키는 게 내 일이오", "it": false}, {"s": 3110.942, "e": 3113.517, "en": "She's growing up. Mal\nalready is grown up.", "ko": "그 애는 크고 있어\n말은 이미 다 컸고", "it": false}, {"s": 3113.669, "e": 3115.853, "en": "Maybe it's time to accept that.", "ko": "이제 받아들일 때도 됐어", "it": false}, {"s": 3115.947, "e": 3118.781, "en": "So, he sent you in here\nto fight his battles.", "ko": "그래, 그 녀석이 자기 싸움을\n당신한테 대신 시켰군", "it": false}, {"s": 3118.932, "e": 3121.342, "en": "You're right, he is\ngrowing up into a weak man", "ko": "당신 말이 맞소, 그 녀석은\n나약한 남자로 크고 있소", "it": false}, {"s": 3121.435, "e": 3123.602, "en": "Because you have coddled him.", "ko": "당신이 오냐오냐\n키웠으니 말이오", "it": false}, {"s": 3123.621, "e": 3125.788, "en": "He will not get early\naccess to that trust.", "ko": "신탁은 일찍\n못 쓰게 할 거요", "it": false}, {"s": 3125.939, "e": 3127.899, "en": "What difference does\na few years make?", "ko": "몇 년 차이가\n무슨 상관이야?", "it": false}, {"s": 3128.017, "e": 3129.774, "en": "You're doing this to hurt him.", "ko": "그 애를 상처 주려고\n이러는 거잖아", "it": false}, {"s": 3129.794, "e": 3133.945, "en": "Well, maybe a few bruises will\nmake a man out of him after all.", "ko": "글쎄, 멍 좀 들어 봐야\n사내가 될지 누가 알겠소", "it": false}, {"s": 3133.965, "e": 3135.592, "en": "So, to be a man one\nneeds to be bruised,", "ko": "그러니까 남자가 되려면\n멍이 들어야 하고", "it": false}, {"s": 3135.616, "e": 3137.185, "en": "To be a woman one\nneeds to be protected.", "ko": "여자가 되려면\n보호받아야 한다는 거네", "it": false}, {"s": 3137.209, "e": 3138.617, "en": "Corrine is a girl.", "ko": "코린은 아직 소녀요", "it": false}, {"s": 3138.711, "e": 3140.711, "en": "She is a young woman", "ko": "그 애는 이제 숙녀야", "it": false}, {"s": 3140.805, "e": 3144.531, "en": "And it's our job to teach\nher how to be an adult.", "ko": "어른이 되는 법을 가르치는 게\n우리 일이고", "it": false}, {"s": 3144.625, "e": 3146.102, "en": "You can't stop her growing up,", "ko": "그 애가 크는 건\n못 막아", "it": false}, {"s": 3146.126, "e": 3148.811, "en": "No matter how many\ndolls you buy her.", "ko": "인형을 아무리\n사다 줘도", "it": false}, {"s": 3152.541, "e": 3154.441, "en": "I see the way you look at her.", "ko": "당신이 그 애를\n보는 눈빛을 봤어", "it": false}, {"s": 3157.971, "e": 3160.972, "en": "And what exactly is\nthat supposed to mean?", "ko": "그게 대체\n무슨 뜻이오?", "it": false}, {"s": 3160.992, "e": 3163.308, "en": "Not how a father should.", "ko": "아버지가 딸을 보는\n눈빛이 아니라는 거야", "it": false}, {"s": 3163.402, "e": 3164.66, "en": "And what do you know", "ko": "그럼 당신이", "it": false}, {"s": 3164.685, "e": 3167.571, "en": "About how men are\nsupposed to look at women?", "ko": "남자가 여자를 어떻게 봐야 하는지\n뭘 안다는 거요?", "it": false}, {"s": 3167.723, "e": 3173.06, "en": "A mother, jealous of her\nown daughter's beauty.", "ko": "딸의 미모를 질투하는\n어미 주제에", "it": false}, {"s": 3173.153, "e": 3175.729, "en": "And yet you point\nthe finger at me.", "ko": "나한테 손가락질을 하오?", "it": false}, {"s": 3175.754, "e": 3179.089, "en": "I'm not jealous. I'm scared.", "ko": "질투하는 게 아니야\n무서운 거지", "it": false}, {"s": 3179.177, "e": 3182.827, "en": "I'm scared of how her beauty\ncould entice certain men.", "ko": "그 애 미모가 어떤 남자들을\n꾀어낼까 봐 무서워", "it": false}, {"s": 3182.847, "e": 3185.422, "en": "The wrong men.", "ko": "나쁜 남자들을", "it": false}, {"s": 3185.574, "e": 3188.742, "en": "Which is why she needs\nexperience with them,", "ko": "그러니까 남자를\n겪어 봐야 해", "it": false}, {"s": 3188.835, "e": 3190.215, "en": "So she doesn't just say yes", "ko": "처음 다가와서 청혼하는\n남자한테", "it": false}, {"s": 3190.24, "e": 3192.591, "en": "To the first man who\ncomes along and proposes.", "ko": "덜컥 승낙하지 않도록", "it": false}, {"s": 3196.168, "e": 3200.642, "en": "Well, that was your\nmistake and mine.", "ko": "그건 당신 실수였소\n내 실수이기도 하고", "it": false}, {"s": 3203.019, "e": 3205.996, "en": "Maybe we're not so\ndifferent after all.", "ko": "결국 우리도\n그렇게 다르진 않은가 보오", "it": false}, {"s": 3220.104, "e": 3222.27, "en": "I don't understand why\nhe has to be so strict.", "ko": "아빠가 왜 그렇게\n엄하게 구는지 모르겠어요", "it": false}, {"s": 3222.294, "e": 3225.036, "en": "I'm going to be the only girl\nin town not at that dance.", "ko": "마을에서 댄스파티에\n못 가는 여자애는 나 하나일 거예요", "it": false}, {"s": 3225.056, "e": 3226.371, "en": "My life is over.", "ko": "내 인생은 끝났어요", "it": false}, {"s": 3226.39, "e": 3228.298, "en": "I know it might seem that way.", "ko": "그렇게 느껴질 수도 있겠지", "it": false}, {"s": 3228.451, "e": 3230.726, "en": "It's like he wants to be\nthe only man in my life.", "ko": "아빠는 자기만\n내 인생의 유일한 남자이길 바라나 봐요", "it": false}, {"s": 3232.913, "e": 3235.821, "en": "I guess I'm going to be\ndaddy's little girl forever.", "ko": "난 평생 아빠의\n어린 딸로 살아야 하나 봐요", "it": false}, {"s": 3241.739, "e": 3243.572, "en": "I think you should go.", "ko": "가렴", "it": false}, {"s": 3243.724, "e": 3247.743, "en": "What? Really?\nBut daddy said...", "ko": "네? 정말요?\n하지만 아빠가...", "it": false}, {"s": 3247.768, "e": 3249.728, "en": "Your father doesn't\nneed to know.", "ko": "아빠는\n모르셔도 돼", "it": false}, {"s": 3249.753, "e": 3251.368, "en": "It will be our secret.", "ko": "우리 둘만의 비밀이야", "it": false}, {"s": 3252.163, "e": 3253.254, "en": "Oh, mother!", "ko": "엄마!", "it": false}, {"s": 3253.734, "e": 3254.939, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 3283.781, "e": 3287.741, "en": "Malcolm was right.\nMen only want one thing.", "ko": "맬컴 말이 맞았다\n남자들이 원하는 건 딱 하나였다", "it": true}, {"s": 3289.954, "e": 3291.62, "en": "I'm pregnant.", "ko": "임신했어요", "it": false}, {"s": 3295.341, "e": 3298.496, "en": "Rock was so sweet and kind.", "ko": "록은 정말 다정하고 착했어요", "it": false}, {"s": 3298.521, "e": 3301.522, "en": "I didn't really even\nmean for it to happen.", "ko": "정말 그럴 생각은\n없었는데", "it": false}, {"s": 3301.54, "e": 3303.632, "en": "I just got so caught\nup with things.", "ko": "그냥 분위기에\n휩쓸려 버렸어요", "it": false}, {"s": 3306.782, "e": 3308.114, "en": "Are you mad?", "ko": "화나셨어요?", "it": false}, {"s": 3309.188, "e": 3310.629, "en": "Not at you.", "ko": "너한테는 아니야", "it": false}, {"s": 3314.127, "e": 3317.98, "en": "I just wish I told you\nmore about the ways of men.", "ko": "남자들에 대해 너한테\n더 많이 알려 줬어야 했는데", "it": false}, {"s": 3318.005, "e": 3320.96, "en": "You asked for my guidance\nand I failed you.", "ko": "네가 조언을 구했는데\n엄마가 실망시켰구나", "it": false}, {"s": 3320.985, "e": 3323.152, "en": "I won't let that happen again.", "ko": "다시는 그러지 않을게", "it": false}, {"s": 3326.855, "e": 3328.815, "en": "what\nam I going to do?", "ko": "나 이제\n어떡해요?", "it": false}, {"s": 3329.051, "e": 3332.977, "en": "We, you mean. What\nare we going to do.", "ko": "우리지\n우리가 어떡할지", "it": false}, {"s": 3333.002, "e": 3335.094, "en": "You're not in this alone.", "ko": "너 혼자가 아니야", "it": false}, {"s": 3339.078, "e": 3340.461, "en": "There is something.", "ko": "방법이 하나 있어", "it": false}, {"s": 3341.747, "e": 3343.672, "en": "It may be our only option.", "ko": "유일한 방법일지도 몰라", "it": false}, {"s": 3359.582, "e": 3361.69, "en": "Are you the one\nwanting miss hazel?", "ko": "헤이즐 언니 찾는\n분이 아가씨예요?", "it": false}, {"s": 3363.694, "e": 3365.694, "en": "On the bed, honey.", "ko": "침대에 누워요, 아가씨", "it": false}, {"s": 3367.256, "e": 3368.697, "en": "You gotta lay back.", "ko": "등을 대고 누워야 해요", "it": false}, {"s": 3372.761, "e": 3375.537, "en": "this is\nall just so awful.", "ko": "이건\n너무 끔찍해요", "it": false}, {"s": 3378.934, "e": 3381.877, "en": "It's all right.\nIt's all right.", "ko": "괜찮아, 괜찮아", "it": false}, {"s": 3404.643, "e": 3409.238, "en": "Tomorrow, it will be\nlike this never happened.", "ko": "내일이면 아무 일도\n없었던 것처럼 될 거야", "it": false}, {"s": 3410.908, "e": 3413.3, "en": "Are you really just going\nto sweep this under the rug", "ko": "정말 이것도 그냥\n덮어 버릴 거예요?", "it": false}, {"s": 3413.318, "e": 3415.869, "en": "Like you do everything else?", "ko": "다른 일들처럼요?", "it": false}, {"s": 3417.72, "e": 3421.447, "en": "I can't pretend that\nthat didn't just happen.", "ko": "방금 있었던 일을 없었던 척은\n못 하겠어요", "it": false}, {"s": 3421.735, "e": 3425.904, "en": "I know it happened\nand I'm glad it did,", "ko": "있었던 일이라는 거 알아\n그리고 엄만 다행이라고 생각해", "it": false}, {"s": 3425.923, "e": 3428.649, "en": "Because now you have\nthe life you deserve.", "ko": "이제 넌 네가 누려야 할\n인생을 살 수 있으니까", "it": false}, {"s": 3428.667, "e": 3433.929, "en": "But this, here tonight,\nthis is between you and me.", "ko": "하지만 오늘 밤 여기서 있었던 일은\n너랑 나만 아는 거야", "it": false}, {"s": 3434.156, "e": 3437.081, "en": "Everywhere else\nwith everyone else,", "ko": "다른 어디서든,\n다른 누구 앞에서든", "it": false}, {"s": 3437.101, "e": 3439.221, "en": "This was just a night\nlike all the others.", "ko": "오늘은 그냥\n평소랑 똑같은 밤이었어", "it": false}, {"s": 3439.328, "e": 3441.511, "en": "You went to bed\nmad at your father.", "ko": "넌 아빠한테 화난 채로\n잠자리에 들었고", "it": false}, {"s": 3441.605, "e": 3443.588, "en": "So, did I.", "ko": "엄마도 그랬어", "it": false}, {"s": 3443.682, "e": 3445.774, "en": "Do you understand?", "ko": "알아들었니?", "it": false}, {"s": 3449.28, "e": 3450.72, "en": "yes.", "ko": "네", "it": false}, {"s": 3454.952, "e": 3456.743, "en": "mommy.", "ko": "엄마", "it": false}, {"s": 3461.775, "e": 3463.459, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 3496.175, "e": 3498.526, "en": "It is awfully\nquiet this morning.", "ko": "오늘 아침은\n유난히 조용하군", "it": false}, {"s": 3501.165, "e": 3503.907, "en": "Scrambled eggs and grapefruit,\nit's your favorite.", "ko": "스크램블드에그에 자몽이야\n네가 제일 좋아하는 거지", "it": false}, {"s": 3504.059, "e": 3506.818, "en": "And yet you have barely\ntouched your plate.", "ko": "그런데 거의\n손도 안 댔구나", "it": false}, {"s": 3506.837, "e": 3508.802, "en": "Are you feeling all\nright this morning?", "ko": "오늘 아침\n어디 안 좋니?", "it": false}, {"s": 3510.174, "e": 3517.904, "en": "Just a little tired, daddy.\nI was up late reading.", "ko": "좀 피곤해서요, 아빠\n늦게까지 책을 읽었거든요", "it": false}, {"s": 3517.923, "e": 3518.923, "en": "Hmm.", "ko": "흠", "it": false}, {"s": 3520.759, "e": 3524.168, "en": "What about you? Were you\nup late last night as well.", "ko": "당신은?\n당신도 어젯밤 늦게까지 안 잤소?", "it": false}, {"s": 3524.188, "e": 3526.58, "en": "I was reading too.", "ko": "나도 책을 읽었어", "it": false}, {"s": 3526.598, "e": 3527.764, "en": "Well...", "ko": "그래...", "it": false}, {"s": 3527.858, "e": 3533.028, "en": "They must have been some\nawfully engaging novels", "ko": "둘 다 밤늦게까지\n잠도 못 잘 만큼", "it": false}, {"s": 3533.053, "e": 3535.554, "en": "To keep you both awake\nso late last night.", "ko": "아주 재미있는\n소설이었나 보군", "it": false}, {"s": 3535.774, "e": 3537.607, "en": "Yes daddy. Mine was about...", "ko": "네, 아빠, 제 건\n어떤 내용이냐면...", "it": false}, {"s": 3540.351, "e": 3541.625, "en": "Enough.", "ko": "그만", "it": false}, {"s": 3541.82, "e": 3543.86, "en": "I will not be lied\nto at my own table.", "ko": "내 식탁에서\n거짓말은 용납 못 해", "it": false}, {"s": 3546.262, "e": 3547.262, "en": "Leave us.", "ko": "나가 있어", "it": false}, {"s": 3551.273, "e": 3555.609, "en": "How dare you take our\ndaughter to that place?", "ko": "어떻게 감히 우리 딸을\n그런 데 데려갔소?", "it": false}, {"s": 3555.702, "e": 3557.179, "en": "Yeah, that is right, I saw you.", "ko": "그렇소, 내가 봤소", "it": false}, {"s": 3557.203, "e": 3561.205, "en": "You are a filthy whore\njust like the rest of them.", "ko": "당신도 다른 계집들처럼\n더러운 창녀요", "it": false}, {"s": 3561.225, "e": 3564.634, "en": "Taking our daughter\nto get that procedure.", "ko": "우리 딸한테\n그런 수술을 받게 하다니", "it": false}, {"s": 3564.787, "e": 3566.598, "en": "I should have you both arrested.", "ko": "둘 다 체포되게\n만들어야 하는 건데", "it": false}, {"s": 3566.622, "e": 3567.971, "en": "It was the only option.", "ko": "그 방법밖에 없었어", "it": false}, {"s": 3568.065, "e": 3571.146, "en": "It was the best thing to\ndo for her, for the family.", "ko": "그 애한테도, 가족한테도\n그게 최선이었어", "it": false}, {"s": 3571.288, "e": 3574.382, "en": "I know what is best\nfor this family.", "ko": "이 가족한테 뭐가 최선인지는\n내가 정하오", "it": false}, {"s": 3581.745, "e": 3583.912, "en": "No more boys. No more parties.", "ko": "이제 남자도 안 되고\n파티도 안 된다", "it": false}, {"s": 3584.064, "e": 3586.226, "en": "No more parading around town\nlike a cheap little hussy.", "ko": "싸구려 계집처럼\n동네를 쏘다니는 것도 안 돼", "it": false}, {"s": 3586.25, "e": 3589.751, "en": "From now on you will stay\nhere on these grounds.", "ko": "이제부터 넌\n이 저택 안에서만 지낸다", "it": false}, {"s": 3589.776, "e": 3590.776, "en": "What?", "ko": "네?", "it": false}, {"s": 3590.801, "e": 3592.715, "en": "You're going to keep\nme here a prisoner?", "ko": "절 여기\n죄수처럼 가둬 두시겠다고요?", "it": false}, {"s": 3592.739, "e": 3594.481, "en": "Until I believe you have\nlearned your lesson, yes.", "ko": "네가 정신 차렸다고\n내가 믿을 때까지는, 그래", "it": false}, {"s": 3594.499, "e": 3596.983, "en": "If you so much as\nthink of setting foot", "ko": "저 대문 밖으로\n한 발짝이라도 나갈 생각을 하면", "it": false}, {"s": 3597.072, "e": 3598.404, "en": "Outside of those gates I will-", "ko": "내가 그냥...", "it": false}, {"s": 3598.429, "e": 3600.076, "en": "Or you'll what?!", "ko": "그냥 뭐?!", "it": false}, {"s": 3600.656, "e": 3603.056, "en": "Can't you see she's\nsuffered enough already?!", "ko": "이미 충분히 고생한 게\n안 보여?!", "it": false}, {"s": 3605.396, "e": 3606.493, "en": "Go to your room.", "ko": "네 방으로 가", "it": false}, {"s": 3606.511, "e": 3607.327, "en": "But daddy.", "ko": "하지만 아빠", "it": false}, {"s": 3607.346, "e": 3608.346, "en": "Now!", "ko": "당장!", "it": false}, {"s": 3617.692, "e": 3619.433, "en": "I don't regret my decision.", "ko": "난 내 결정을 후회 안 해", "it": false}, {"s": 3619.691, "e": 3622.509, "en": "It was not your\ndecision to make.", "ko": "그건 당신이\n결정할 일이 아니었소", "it": false}, {"s": 3622.534, "e": 3625.11, "en": "Well, it certainly wasn't yours.", "ko": "당신이 결정할 일도\n분명 아니었지", "it": false}, {"s": 3625.197, "e": 3625.846, "en": "I oughta...", "ko": "내가 확...", "it": false}, {"s": 3625.864, "e": 3626.85, "en": "Hit me?", "ko": "때리려고?", "it": false}, {"s": 3626.875, "e": 3628.995, "en": "Will that make you\nfeel better? Go ahead.", "ko": "그러면 속이 좀 풀리겠어?\n때려 봐", "it": false}, {"s": 3629.275, "e": 3630.506, "en": "The back of your hand", "ko": "당신 손등 한 대쯤은", "it": false}, {"s": 3630.531, "e": 3633.347, "en": "Is well worth corrine\nhaving a chance at life.", "ko": "코린이 제대로 살 기회를 얻은\n값으로 충분히 싸", "it": false}, {"s": 3643.474, "e": 3646.308, "en": "I will find a way to\nmake you regret this.", "ko": "반드시 이 일을\n후회하게 만들어 주겠소", "it": false}, {"s": 3657.842, "e": 3659.858, "en": "I would've had it\nfinished for you sooner", "ko": "더 빨리 고쳐 드릴 수\n있었는데", "it": false}, {"s": 3659.882, "e": 3661.472, "en": "But I had to wait for\na part from richmond.", "ko": "리치먼드에서 부품이\n올 때까지 기다려야 해서요", "it": false}, {"s": 3661.492, "e": 3663.066, "en": "No, it's fine.", "ko": "아니에요, 괜찮아요", "it": false}, {"s": 3663.091, "e": 3665.942, "en": "Not having wheels forced me to\nstay home and work on my music.", "ko": "차가 없으니 집에 틀어박혀서\n음악 작업만 했어요", "it": false}, {"s": 3666.221, "e": 3669.389, "en": "That record you lent\nme sort of inspired me.", "ko": "빌려준 음반이\n영감을 좀 줬거든요", "it": false}, {"s": 3669.408, "e": 3670.367, "en": "Oh, yeah?", "ko": "그래요?", "it": false}, {"s": 3670.392, "e": 3671.912, "en": "Yeah.", "ko": "네", "it": false}, {"s": 3671.937, "e": 3673.313, "en": "Scrapped what I was working on", "ko": "하던 건 다 버리고", "it": false}, {"s": 3673.337, "e": 3675.745, "en": "And started something\ncompletely different.", "ko": "완전히 다른 걸\n시작했어요", "it": false}, {"s": 3675.839, "e": 3678.581, "en": "More freeform.", "ko": "좀 더 자유로운 걸로요", "it": false}, {"s": 3678.606, "e": 3680.548, "en": "I'm... I'm happy to help.", "ko": "도움이 됐다니...\n기쁘네요", "it": false}, {"s": 3684.089, "e": 3686.014, "en": "Well, thanks again.", "ko": "그럼, 다시 한번 고마워요", "it": false}, {"s": 3688.018, "e": 3693.58, "en": "Before you go, I got the new\nsonny boy williamson in town.", "ko": "가기 전에, 소니 보이 윌리엄슨\n새 음반이 들어왔어요", "it": false}, {"s": 3693.598, "e": 3697.359, "en": "No one does the blues\nharp like he does.", "ko": "블루스 하모니카는\n그 사람이 최고예요", "it": false}, {"s": 3697.51, "e": 3699.586, "en": "You gotta take a listen.", "ko": "꼭 들어 봐요", "it": false}, {"s": 3699.679, "e": 3701.027, "en": "You ever try playing yourself?", "ko": "직접 연주해 본 적은 있어요?", "it": false}, {"s": 3702.107, "e": 3703.347, "en": "The playing's not for me.", "ko": "연주는 제 일이 아니에요", "it": false}, {"s": 3703.367, "e": 3705.543, "en": "I just like where\nthe tunes take me.", "ko": "그냥 음악이 날\n데려가는 곳이 좋아요", "it": false}, {"s": 3705.568, "e": 3708.945, "en": "Just gotta do something to break\nup the days in this garage.", "ko": "이 정비소에서 지루한 하루를\n버티려면 뭐라도 해야죠", "it": false}, {"s": 3709.097, "e": 3710.152, "en": "Yeah.", "ko": "그렇죠", "it": false}, {"s": 3711.783, "e": 3713.709, "en": "Do you get out much?", "ko": "밖에 자주 나가요?", "it": false}, {"s": 3716.104, "e": 3718.304, "en": "I mean, do you have time\noff? For travel or...", "ko": "그러니까, 쉬는 날은 있어요?\n여행이라든가...", "it": false}, {"s": 3718.364, "e": 3719.881, "en": "Yeah, I get Sunday mornings off.", "ko": "일요일 아침엔 쉬어요", "it": false}, {"s": 3720.108, "e": 3722.148, "en": "My pa travels me all\nthe way to church.", "ko": "아버지가 저를\n교회까지 멀리 여행시켜 주시죠", "it": false}, {"s": 3723.887, "e": 3729.277, "en": "Of course. That makes sense.", "ko": "아, 그렇겠네요", "it": false}, {"s": 3729.634, "e": 3730.784, "en": "I'm sorry.", "ko": "미안해요", "it": false}, {"s": 3730.802, "e": 3732.118, "en": "It's all right.", "ko": "괜찮아요", "it": false}, {"s": 3732.137, "e": 3735.397, "en": "But yeah, that's the dream.", "ko": "그래도 그게 꿈이에요", "it": false}, {"s": 3735.422, "e": 3736.68, "en": "Just get out of here,", "ko": "여길 벗어나서", "it": false}, {"s": 3736.705, "e": 3739.598, "en": "See something besides these\nwalls and those trees.", "ko": "이 벽이랑 저 나무들 말고\n다른 걸 보는 거요", "it": false}, {"s": 3739.811, "e": 3742.738, "en": "I understand wanting to\nescape the walls we live in.", "ko": "사는 곳의 벽에서 벗어나고\n싶은 마음은 알아요", "it": false}, {"s": 3744.908, "e": 3747.15, "en": "Your walls look a lot\ndifferent than mine.", "ko": "당신네 벽은 우리 벽이랑\n많이 다르게 생겼을걸요", "it": false}, {"s": 3747.302, "e": 3748.302, "en": "Harry?", "ko": "해리?", "it": true}, {"s": 3752.249, "e": 3753.64, "en": "Mr. Foxworth.", "ko": "폭스워스 도련님", "it": false}, {"s": 3753.658, "e": 3754.658, "en": "Hello celia.", "ko": "안녕하세요, 실리아", "it": false}, {"s": 3756.094, "e": 3757.98, "en": "Make sure you take\na lunch break.", "ko": "점심은 꼭 챙겨 먹어", "it": false}, {"s": 3758.146, "e": 3759.146, "en": "Mm-hmm.", "ko": "네", "it": false}, {"s": 3766.864, "e": 3769.014, "en": "Not sure your mother\nlikes me very much.", "ko": "어머님이 절\n별로 안 좋아하시나 봐요", "it": false}, {"s": 3769.039, "e": 3771.223, "en": "My momma died when I was three.", "ko": "친엄마는 제가 세 살 때\n돌아가셨어요", "it": false}, {"s": 3771.584, "e": 3773.769, "en": "Celia's my stepmother.", "ko": "실리아는 새어머니예요", "it": false}, {"s": 3773.92, "e": 3776.105, "en": "It's pretty obvious\nwe aren't kin.", "ko": "피가 안 섞인 건\n딱 봐도 알잖아요", "it": false}, {"s": 3776.516, "e": 3778.082, "en": "Oh?", "ko": "그래요?", "it": false}, {"s": 3780.927, "e": 3783.278, "en": "You can't tell her\ndaddy's a white man?", "ko": "실리아 아버지가 백인인 거\n모르시겠어요?", "it": false}, {"s": 3787.973, "e": 3790.04, "en": "What are you trying to tell me?", "ko": "무슨 말을 하려는 거예요?", "it": false}, {"s": 3795.394, "e": 3796.662, "en": "Thank you.", "ko": "고마워", "it": false}, {"s": 3808.38, "e": 3810.454, "en": "Oh, god I need this.", "ko": "세상에, 이게 필요했어", "it": false}, {"s": 3811.832, "e": 3813.09, "en": "Where'd you get it?", "ko": "어디서 났어?", "it": false}, {"s": 3813.115, "e": 3814.761, "en": "My friend betsy's brother\nhas been growing it", "ko": "친구 베시 오빠가\n마구간 뒤에서", "it": false}, {"s": 3814.785, "e": 3816.284, "en": "Behind their stable.", "ko": "키우고 있거든", "it": false}, {"s": 3816.411, "e": 3818.129, "en": "But this could be\nthe last of it,", "ko": "그래도 이게\n마지막일지도 몰라", "it": false}, {"s": 3818.148, "e": 3820.557, "en": "Given as I'm now housebound\nfor the rest of my adult life.", "ko": "이제 평생 집 밖에도\n못 나가는 신세가 됐으니까", "it": false}, {"s": 3820.709, "e": 3822.324, "en": "Yeah. I can't believe\nit's all just because", "ko": "그러게, 그게 다\n그 녀석을", "it": false}, {"s": 3822.348, "e": 3824.293, "en": "You met up with that guy again.", "ko": "또 만났다는 이유라니\n믿기지가 않아", "it": false}, {"s": 3824.318, "e": 3828.988, "en": "I mean sure, dad's an ass, but\nthat's excessive even for him.", "ko": "아버지가 개자식인 건 맞지만\n그래도 그건 너무했어", "it": false}, {"s": 3829.55, "e": 3830.769, "en": "I know.", "ko": "그러니까", "it": false}, {"s": 3831.611, "e": 3833.675, "en": "So, do you think\nthere's any chance", "ko": "오빠는 신탁을\n일찍 받을 가능성이", "it": false}, {"s": 3833.7, "e": 3835.989, "en": "You'll get your trust early?", "ko": "좀 있을 것 같아?", "it": false}, {"s": 3836.727, "e": 3839.744, "en": "Not a chance in hell, no.", "ko": "어림도 없지", "it": false}, {"s": 3839.889, "e": 3841.969, "en": "Helen keeps telling\nme it doesn't matter.", "ko": "헬렌은 계속\n상관없다고 하는데", "it": false}, {"s": 3841.994, "e": 3844.678, "en": "I just want to give her\nthe best life possible.", "ko": "난 그냥\n최고의 삶을 주고 싶어", "it": false}, {"s": 3845.067, "e": 3846.174, "en": "You will.", "ko": "그렇게 될 거야", "it": false}, {"s": 3846.199, "e": 3847.724, "en": "And not because of\nwhen you get your trust", "ko": "신탁을 언제 받느냐 때문이 아니라", "it": false}, {"s": 3847.748, "e": 3849.231, "en": "But because you're you.", "ko": "오빠가 오빠니까", "it": false}, {"s": 3849.421, "e": 3851.921, "en": "Exactly. Me.", "ko": "그러니까, 나니까 문제지", "it": false}, {"s": 3852.015, "e": 3854.591, "en": "With a family straight\nout of the house of usher.", "ko": "무슨 어셔 가의 몰락에서\n튀어나온 집안이잖아", "it": false}, {"s": 3858.93, "e": 3860.522, "en": "You started without me?", "ko": "나 빼고 시작했어?", "it": false}, {"s": 3861.917, "e": 3863.007, "en": "Here.", "ko": "자", "it": false}, {"s": 3863.026, "e": 3864.693, "en": "You can catch up.", "ko": "따라잡아", "it": false}, {"s": 3870.092, "e": 3872.258, "en": "There's something I've\nbeen wondering about dad.", "ko": "아버지 일로\n궁금한 게 있었는데", "it": false}, {"s": 3872.277, "e": 3874.202, "en": "Oh lord. Where do you start?", "ko": "세상에, 어디서부터\n얘기해야 하나", "it": false}, {"s": 3877.766, "e": 3879.766, "en": "I think he might\nbe celia's father.", "ko": "아버지가 실리아\n친아버지인 것 같아", "it": false}, {"s": 3883.269, "e": 3885.286, "en": "Well yeah.", "ko": "그야 그렇지", "it": false}, {"s": 3885.607, "e": 3888.884, "en": "We've heard those rumors\nin town for years.", "ko": "그 소문은 마을에서\n몇 년째 돌았어", "it": false}, {"s": 3888.909, "e": 3890.418, "en": "How did I not know this?", "ko": "난 어떻게 그걸 몰랐지?", "it": false}, {"s": 3890.443, "e": 3894.091, "en": "Because you always have your\nhead stuck in the piano.", "ko": "맨날 피아노에\n코 박고 있으니까", "it": false}, {"s": 3894.116, "e": 3895.949, "en": "Stop.", "ko": "그만해", "it": false}, {"s": 3895.974, "e": 3898.158, "en": "You never noticed\nthe resemblance?", "ko": "닮은 거\n못 알아챘어?", "it": false}, {"s": 3900.731, "e": 3902.479, "en": "What do you think?", "ko": "어떻게 생각해?", "it": false}, {"s": 3904.309, "e": 3906.735, "en": "I think you're a\nflipping genius.", "ko": "진짜 천재다", "it": false}, {"s": 3907.979, "e": 3909.001, "en": "Ow.", "ko": "아야", "it": false}, {"s": 3912.225, "e": 3914.558, "en": "I know about celia.", "ko": "실리아 일 알고 있어요", "it": false}, {"s": 3914.578, "e": 3916.698, "en": "And unless you want\nmother to know as well", "ko": "어머니도 알게 되길\n원하지 않으시면", "it": false}, {"s": 3916.747, "e": 3921.015, "en": "I suggest you do as I say.\nI want access to my trust.", "ko": "제 말대로 하세요\n신탁을 쓰게 해 주세요", "it": false}, {"s": 3928.091, "e": 3930.091, "en": "I like this side of you.", "ko": "네 이런 면이 마음에 드는구나", "it": false}, {"s": 3932.429, "e": 3934.93, "en": "Well, it's settled then.", "ko": "그럼 된 거죠", "it": false}, {"s": 3935.081, "e": 3939.342, "en": "I'll have the lawyers draw\nup the transfer papers.", "ko": "제가 변호사한테\n이전 서류를 만들라고 할게요", "it": false}, {"s": 3939.494, "e": 3940.843, "en": "Why wait?", "ko": "기다릴 게 뭐 있나?", "it": false}, {"s": 3940.938, "e": 3942.086, "en": "Excuse me?", "ko": "네?", "it": false}, {"s": 3942.105, "e": 3944.013, "en": "- Olivia!\n- What?", "ko": "-올리비아!\n-왜?", "it": false}, {"s": 3944.107, "e": 3945.941, "en": "Why are you calling her?", "ko": "어머니는 왜 부르세요?", "it": false}, {"s": 3950.596, "e": 3953.597, "en": "Son, why don't you tell your\nmother what you have discovered?", "ko": "아들아, 네가 알아낸 걸\n어머니께 말씀드리지 그러냐?", "it": false}, {"s": 3953.617, "e": 3956.618, "en": "No, that's... She\ndoesn't need to know.", "ko": "아니요, 그건...\n어머니는 몰라도 돼요", "it": false}, {"s": 3956.769, "e": 3960.157, "en": "No. You came into my office and\nthreatened to tell her something", "ko": "아니지, 넌 내 서재에 와서\n신탁을 내놓지 않으면", "it": false}, {"s": 3960.182, "e": 3962.606, "en": "If I did not give you\naccess to your trust.", "ko": "어머니한테 뭔가 알리겠다고\n협박했잖아", "it": false}, {"s": 3962.626, "e": 3965.685, "en": "Well you are not getting\naccess to your trust,", "ko": "그런데 신탁은\n못 준다", "it": false}, {"s": 3965.778, "e": 3970.09, "en": "So be a man and\ntell your mother.", "ko": "그러니 사내답게\n어머니께 말씀드려", "it": false}, {"s": 3971.802, "e": 3975.47, "en": "Please don't do this,\nokay? Just, just forget it.", "ko": "제발 이러지 마세요\n그냥, 그냥 잊어 주세요", "it": false}, {"s": 3977.14, "e": 3981.142, "en": "Your son wanted you to know\nthat I am celia's father.", "ko": "당신 아들은 내가 실리아 아버지라는 걸\n당신한테 알리고 싶었다오", "it": false}, {"s": 3987.876, "e": 3988.876, "en": "Why?", "ko": "왜요?", "it": false}, {"s": 3991.137, "e": 3993.356, "en": "Why do you do things like that?!", "ko": "왜 이런 짓을\n하시는 거예요?!", "it": false}, {"s": 3993.381, "e": 3997.002, "en": "Mal, it's fine. Go have\na drink, cool down.", "ko": "말, 괜찮아\n가서 한잔하고 머리 좀 식혀", "it": false}, {"s": 3997.477, "e": 3999.052, "en": "You'd have to crawl\nover my dead body", "ko": "그 돈에 손대려면", "it": false}, {"s": 3999.07, "e": 4001.054, "en": "To get access to that money.", "ko": "내 시체를 넘어가야 할 거다", "it": false}, {"s": 4001.072, "e": 4003.164, "en": "Oh, we should all be so lucky.", "ko": "그거참\n다들 손꼽아 기다릴 일이네요", "it": false}, {"s": 4019.58, "e": 4021.016, "en": "Mother, I'm so sorry, okay?", "ko": "어머니, 정말 죄송해요", "it": false}, {"s": 4021.041, "e": 4022.553, "en": "I never meant for\nyou to find out.", "ko": "어머니가 알게 되길\n바란 건 아니었어요", "it": false}, {"s": 4022.577, "e": 4024.577, "en": "I just thought that he would\ngive me the money and...", "ko": "그냥 아버지가 돈을\n주실 줄 알고...", "it": false}, {"s": 4024.596, "e": 4025.979, "en": "It's all right!", "ko": "괜찮아!", "it": false}, {"s": 4032.587, "e": 4035.196, "en": "Your father's indiscretions\nare not your cross to bear.", "ko": "아버지의 추문은\n네가 짊어질 십자가가 아니야", "it": false}, {"s": 4035.423, "e": 4037.774, "en": "-But if it weren't for\nme... listen to me.", "ko": "-하지만 저 때문에...\n-엄마 말 들어", "it": false}, {"s": 4037.828, "e": 4039.477, "en": "Remember this day", "ko": "오늘을 기억해", "it": false}, {"s": 4039.536, "e": 4042.853, "en": "So you will always treat\nyour wife and children", "ko": "그래서 네 아내와 아이들을\n늘 존중하고", "it": false}, {"s": 4042.947, "e": 4045.782, "en": "With respect and kindness.", "ko": "다정하게 대해", "it": false}, {"s": 4045.934, "e": 4047.054, "en": "I'll never be like him.", "ko": "전 절대 아버지처럼\n안 될 거예요", "it": false}, {"s": 4047.102, "e": 4048.494, "en": "Good.", "ko": "그래야지", "it": false}, {"s": 4049.305, "e": 4052.571, "en": "Your big day is just\naround the corner.", "ko": "네 결혼식이\n코앞이잖니", "it": false}, {"s": 4052.596, "e": 4057.276, "en": "Please don't let your\nfather spoil things.", "ko": "아버지가 망치게\n두지 마", "it": false}, {"s": 4059.13, "e": 4062.131, "en": "Thank you, mother.", "ko": "고마워요, 어머니", "it": false}, {"s": 4062.225, "e": 4064.117, "en": "Promise me something.", "ko": "하나만 약속해 줘", "it": false}, {"s": 4064.21, "e": 4066.953, "en": "I want you and helen\nto get as far away", "ko": "너랑 헬렌은", "it": false}, {"s": 4067.046, "e": 4069.23, "en": "From this place as you can.", "ko": "최대한 여기서\n멀리 떠나", "it": false}, {"s": 4075.238, "e": 4076.238, "en": "Okay.", "ko": "알겠어요", "it": false}, {"s": 4084.247, "e": 4085.247, "en": "Nella.", "ko": "넬라", "it": false}, {"s": 4086.471, "e": 4088.279, "en": "Mrs. Foxworth?", "ko": "마님?", "it": false}, {"s": 4089.837, "e": 4092.701, "en": "I'm sorry to bother you.\nDo you have a moment?", "ko": "방해해서 미안해요\n잠깐 시간 돼요?", "it": false}, {"s": 4092.726, "e": 4094.919, "en": "Um, not right now.", "ko": "지금은 좀...", "it": false}, {"s": 4094.944, "e": 4096.984, "en": "I know that malcolm\nis celia's father.", "ko": "맬컴이 실리아 아버지라는 거\n알아요", "it": false}, {"s": 4099.337, "e": 4100.537, "en": "I'm sorry, I can't do this.", "ko": "죄송하지만,\n이 얘긴 못 하겠어요", "it": false}, {"s": 4100.58, "e": 4102.505, "en": "Why didn't you ever tell me?", "ko": "왜 한 번도\n말 안 했어요?", "it": false}, {"s": 4102.657, "e": 4104.059, "en": "Tell my employer\nthat her husband", "ko": "안주인한테\n남편분이", "it": false}, {"s": 4104.083, "e": 4106.509, "en": "Is the father of my daughter?", "ko": "제 딸 아버지라고요?", "it": false}, {"s": 4106.603, "e": 4109.771, "en": "That's not something\nthat's easy to tell anyone,", "ko": "누구한테도 쉽게\n할 수 있는 말이 아니에요", "it": false}, {"s": 4109.998, "e": 4112.273, "en": "Let alone the\nmistress of the house.", "ko": "더구나 이 집 안주인한테는요", "it": false}, {"s": 4112.425, "e": 4115.092, "en": "I'd like to think\nI'm not just anyone.", "ko": "난 그냥 아무나는\n아니었으면 했는데", "it": false}, {"s": 4115.112, "e": 4118.521, "en": "I know you don't\nconsider me a friend.", "ko": "날 친구로 생각 안 하는 거\n알아요", "it": false}, {"s": 4118.615, "e": 4121.616, "en": "But despite everything I\nstill consider you one.", "ko": "그래도 난 그 모든 일에도\n여전히 당신을 친구로 생각해요", "it": false}, {"s": 4123.62, "e": 4125.745, "en": "Does celia know?", "ko": "실리아도 알아요?", "it": false}, {"s": 4130.012, "e": 4132.588, "en": "Oh, what happened with alicia.", "ko": "앨리샤 일", "it": false}, {"s": 4132.848, "e": 4134.331, "en": "What I asked you to do.", "ko": "내가 당신한테 시킨 일", "it": false}, {"s": 4134.356, "e": 4137.039, "en": "Had I known I never\nwould have involved you.", "ko": "알았더라면 절대 당신을\n끌어들이지 않았을 거예요", "it": false}, {"s": 4137.134, "e": 4138.633, "en": "I know.", "ko": "알아요", "it": false}, {"s": 4138.86, "e": 4143.196, "en": "It all makes sense\nwhy you were so upset.", "ko": "그래서 그렇게\n화를 냈던 거군요", "it": false}, {"s": 4143.221, "e": 4145.146, "en": "Is that how you got the scars?", "ko": "그 흉터도 그때 생긴 거예요?", "it": false}, {"s": 4145.171, "e": 4147.688, "en": "That was a long time ago.", "ko": "오래전 일이에요", "it": false}, {"s": 4148.036, "e": 4152.463, "en": "But the hurt you must have felt.", "ko": "그래도 얼마나\n아팠을까요", "it": false}, {"s": 4152.557, "e": 4155.041, "en": "That doesn't just go away.", "ko": "그런 상처는\n그냥 없어지지 않죠", "it": false}, {"s": 4155.059, "e": 4157.393, "en": "No.", "ko": "네", "it": false}, {"s": 4157.545, "e": 4161.581, "en": "And I will hate mr. Foxworth\nuntil the day I die.", "ko": "전 죽는 날까지\n주인님을 미워할 거예요", "it": false}, {"s": 4162.498, "e": 4165.542, "en": "But you, well, you and me.", "ko": "하지만 마님은, 그러니까\n마님이랑 저는", "it": false}, {"s": 4166.905, "e": 4171.148, "en": "I always felt like there was\nsomething different between us.", "ko": "우리 사이엔 늘 뭔가\n다른 게 있다고 느꼈어요", "it": false}, {"s": 4171.242, "e": 4177.154, "en": "I fought it, but I felt it.\nI still do if I'm honest.", "ko": "애써 외면했지만 느꼈어요\n솔직히 지금도 그래요", "it": false}, {"s": 4177.174, "e": 4180.341, "en": "And after 16 years", "ko": "16년이나 지났으니", "it": false}, {"s": 4180.568, "e": 4183.347, "en": "Maybe it's time to let\nbygones be bygones.", "ko": "이제 지난 일은\n묻어 둘 때도 됐죠", "it": false}, {"s": 4187.166, "e": 4188.683, "en": "I'd like that.", "ko": "나도 그러고 싶어요", "it": false}, {"s": 4193.339, "e": 4200.028, "en": "so, um, as friends\nmay I ask one thing of you?", "ko": "그럼, 친구로서\n하나만 부탁해도 될까요?", "it": false}, {"s": 4206.367, "e": 4207.883, "en": "Is that you, momma?", "ko": "엄마예요?", "it": false}, {"s": 4208.114, "e": 4210.539, "en": "Set a plate up for your supper.", "ko": "엄마 저녁\n차려 놨어", "it": false}, {"s": 4210.564, "e": 4213.023, "en": "There's someone here\nwho wants to see you.", "ko": "너 보고 싶다는\n분이 오셨어", "it": false}, {"s": 4218.855, "e": 4221.005, "en": "Good evening, mrs. Foxworth.", "ko": "안녕하세요, 폭스워스 부인", "it": false}, {"s": 4221.03, "e": 4226.675, "en": "I'm sorry to barge\nin like this, um.", "ko": "이렇게 불쑥 찾아와서\n미안해요", "it": false}, {"s": 4227.373, "e": 4230.783, "en": "I was hoping... I wanted to...", "ko": "그러니까... 하고 싶었던 건...", "it": false}, {"s": 4230.802, "e": 4232.518, "en": "She knows.", "ko": "다 아셔", "it": false}, {"s": 4235.047, "e": 4236.397, "en": "All right.", "ko": "그렇구나", "it": false}, {"s": 4244.202, "e": 4245.934, "en": "I'm so sorry.", "ko": "정말 미안해요", "it": false}, {"s": 4247.151, "e": 4248.849, "en": "I'm sorry for you.", "ko": "저도 부인이 안됐어요", "it": false}, {"s": 4250.396, "e": 4254.749, "en": "Men like that, they never stop.", "ko": "그런 남자들은\n절대 멈추지 않아요", "it": false}, {"s": 4275.68, "e": 4277.605, "en": "What are you doing?", "ko": "뭐 하는 거야?", "it": false}, {"s": 4282.227, "e": 4284.502, "en": "I thought I heard\ncorrine calling for me.", "ko": "코린이 날 부르는 것 같았소", "it": false}, {"s": 4289.527, "e": 4292.011, "en": "Celia was right.", "ko": "실리아의 말이 맞았다", "it": true}, {"s": 4292.104, "e": 4294.789, "en": "Men like malcolm never stop.", "ko": "맬컴 같은 남자는\n절대 멈추지 않는다", "it": true}, {"s": 4296.941, "e": 4298.866, "en": "Unless you stop them.", "ko": "누군가 멈추게 하지 않는 한", "it": true}, {"s": 4326.23, "e": 4328.99, "en": "Uh, corrine, I saw\nbellman's is having a sale.", "ko": "코린, 벨먼스 백화점에서\n세일을 하더라", "it": false}, {"s": 4329.015, "e": 4330.568, "en": "We should go to\ntown this weekend.", "ko": "이번 주말에\n시내에 같이 가자", "it": false}, {"s": 4330.593, "e": 4333.005, "en": "Could use some things\nfor the honeymoon.", "ko": "신혼여행 준비할 게\n좀 있어서", "it": false}, {"s": 4333.83, "e": 4335.302, "en": "I could drive you.", "ko": "내가 태워 줄게", "it": false}, {"s": 4335.816, "e": 4338.168, "en": "Is your car up\nand working again?", "ko": "네 차 이제 다 고쳤니?", "it": false}, {"s": 4338.364, "e": 4339.696, "en": "It is.", "ko": "네", "it": false}, {"s": 4339.852, "e": 4342.376, "en": "Harry did an\nexcellent job with it.", "ko": "해리가 아주\n잘 고쳐 줬어요", "it": false}, {"s": 4343.398, "e": 4344.398, "en": "Who?", "ko": "누구?", "it": false}, {"s": 4346.343, "e": 4348.343, "en": "Celia's stepson.", "ko": "실리아 의붓아들이요", "it": false}, {"s": 4355.927, "e": 4358.686, "en": "Well, I would love to\ntake you up on the offer", "ko": "저도 정말\n같이 가고 싶은데", "it": false}, {"s": 4358.838, "e": 4361.764, "en": "But I'm not allowed\nto go to town.", "ko": "누구 덕분에\n시내엔 못 나가는 몸이라서요", "it": false}, {"s": 4384.381, "e": 4385.213, "en": "Daddy!", "ko": "아빠!", "it": false}, {"s": 4392.28, "e": 4393.28, "en": "Malcolm!", "ko": "맬컴!", "it": false}, {"s": 4406.296, "e": 4408.538, "en": "I gave him a\nsedative to calm him.", "ko": "진정제를 놨습니다", "it": false}, {"s": 4408.975, "e": 4410.993, "en": "He should wake up\nin a few hours.", "ko": "몇 시간 뒤면\n깨어나실 겁니다", "it": false}, {"s": 4411.299, "e": 4412.965, "en": "Will he be well enough\nto attend the wedding", "ko": "결혼식에 참석할 수\n있을까요?", "it": false}, {"s": 4412.984, "e": 4415.392, "en": "Or should we postpone\nthe festivities?", "ko": "아니면 식을\n미뤄야 할까요?", "it": false}, {"s": 4415.412, "e": 4419.58, "en": "He'll be groggy but certainly\nno need to cancel the nuptials.", "ko": "좀 멍하시겠지만\n결혼식을 취소할 필요는 없습니다", "it": false}, {"s": 4423.253, "e": 4426.979, "en": "He was eating one minute and\nthen on the floor the next.", "ko": "식사하다가 갑자기\n바닥에 쓰러졌어요", "it": false}, {"s": 4426.998, "e": 4432.71, "en": "His reaction could be to\nan allergen or to a poison.", "ko": "알레르기 반응일 수도,\n독일 수도 있습니다", "it": false}, {"s": 4433.838, "e": 4435.988, "en": "I'm sorry. I didn't\nmean to alarm you.", "ko": "죄송합니다\n놀라게 해 드릴 생각은 없었어요", "it": false}, {"s": 4436.007, "e": 4439.267, "en": "I'm sure it's just\nsomething he ate.", "ko": "분명 드신 음식 때문일 겁니다", "it": false}, {"s": 4439.292, "e": 4442.552, "en": "In any event, he's\nlucky to be alive.", "ko": "어쨌든\n살아 계신 게 천운입니다", "it": false}, {"s": 4442.83, "e": 4445.731, "en": "Yes. Very lucky indeed.", "ko": "그래요, 정말 천운이네요", "it": false}, {"s": 4461.458, "e": 4465.609, "en": "How did you find out\nabout the poison garden?", "ko": "독초 정원은\n어떻게 알았니?", "it": false}, {"s": 4465.703, "e": 4468.704, "en": "Mother... You startled me.", "ko": "엄마... 깜짝 놀랐잖아요", "it": false}, {"s": 4468.856, "e": 4471.04, "en": "Answer the question.", "ko": "대답해", "it": false}, {"s": 4471.192, "e": 4475.47, "en": "I have no earthly clue\nwhat you're talking about.", "ko": "무슨 말씀인지\n하나도 모르겠는데요", "it": false}, {"s": 4475.697, "e": 4479.882, "en": "I found this near the\nwoodpile to be incinerated.", "ko": "태우려고 쌓아 둔\n장작더미 옆에서 찾았어", "it": false}, {"s": 4479.976, "e": 4487.44, "en": "I believe these are your gloves,\nstained green by a plant.", "ko": "네 장갑이지?\n풀물이 들었네", "it": false}, {"s": 4495.233, "e": 4500.661, "en": "I was on a walk\nand I... Saw you.", "ko": "산책하다가\n엄마를... 봤어요", "it": false}, {"s": 4502.073, "e": 4504.406, "en": "I didn't mean to give\ndaddy so much, I swear.", "ko": "아빠한테 그렇게 많이 줄\n생각은 없었어요, 맹세해요", "it": false}, {"s": 4504.431, "e": 4506.764, "en": "I just wanted to go to a\nparty with some friends.", "ko": "그냥 친구들이랑\n파티에 가고 싶었어요", "it": false}, {"s": 4506.911, "e": 4510.229, "en": "You poisoned your father\nso you could go to a party.", "ko": "파티에 가려고\n아빠한테 독을 먹였다고?", "it": false}, {"s": 4510.248, "e": 4512.898, "en": "After everything that\nhappened with rockford", "ko": "록퍼드 일을\n겪고도", "it": false}, {"s": 4512.923, "e": 4515.52, "en": "I thought you\nlearned your lesson.", "ko": "정신 차린 줄 알았는데", "it": false}, {"s": 4516.571, "e": 4518.306, "en": "I, I just wanted him\nout of it for a bit.", "ko": "그, 그냥 잠깐\n정신 못 차리게 하려던 거예요", "it": false}, {"s": 4518.33, "e": 4519.641, "en": "Just long enough\nso I could go out.", "ko": "제가 나갔다 올 동안만요", "it": false}, {"s": 4519.665, "e": 4522.395, "en": "Daddy's got me locked up here.", "ko": "아빠가 절 여기\n가둬 놨잖아요", "it": false}, {"s": 4522.852, "e": 4526.231, "en": "I was just so mad at him", "ko": "아빠한테 너무 화가 났어요", "it": false}, {"s": 4527.098, "e": 4531.526, "en": "For how he treats\nme and mal and joel.", "ko": "아빠가 저랑 말 오빠,\n조엘 오빠를 대하는 거", "it": false}, {"s": 4533.363, "e": 4534.779, "en": "And you.", "ko": "그리고 엄마를 대하는 거요", "it": false}, {"s": 4537.592, "e": 4539.77, "en": "Is he going to be all right?", "ko": "아빠 괜찮아질까요?", "it": false}, {"s": 4540.848, "e": 4543.199, "en": "The doctor said he\nwill recover, yes.", "ko": "의사 선생님 말로는\n회복하실 거래", "it": false}, {"s": 4549.451, "e": 4552.618, "en": "Please, please don't tell him.", "ko": "제발, 제발 아빠한테\n말하지 마세요", "it": false}, {"s": 4552.94, "e": 4554.382, "en": "I won't.", "ko": "말 안 할게", "it": false}, {"s": 4556.1, "e": 4558.338, "en": "Thank you, mother.", "ko": "고마워요, 엄마", "it": false}, {"s": 4559.038, "e": 4561.705, "en": "But anything else,\none more time...", "ko": "하지만 한 번만 더\n이런 일이 생기면...", "it": false}, {"s": 4561.799, "e": 4563.057, "en": "There won't be another time.", "ko": "다음은 없을 거예요", "it": false}, {"s": 4563.082, "e": 4565.87, "en": "Because you aren't like\nhim. You can't be like him.", "ko": "넌 아빠랑 다르니까\n아빠처럼 돼선 안 돼", "it": false}, {"s": 4565.895, "e": 4567.108, "en": "I'm not.", "ko": "안 그래요", "it": false}, {"s": 4567.379, "e": 4569.522, "en": "It was a mistake, I swear.", "ko": "실수였어요, 맹세해요", "it": false}, {"s": 4573.537, "e": 4574.811, "en": "I love you.", "ko": "사랑해", "it": false}, {"s": 4584.787, "e": 4586.303, "en": "He's awake.", "ko": "깨어나셨어요", "it": false}, {"s": 4586.328, "e": 4587.917, "en": "Thank goodness!", "ko": "다행이다!", "it": false}, {"s": 4595.908, "e": 4596.999, "en": "What happened?", "ko": "무슨 일이오?", "it": false}, {"s": 4597.093, "e": 4600.761, "en": "You had an attack of\nsorts, mr. Foxworth.", "ko": "일종의 발작을\n일으키셨습니다", "it": false}, {"s": 4600.913, "e": 4602.171, "en": "An attack.", "ko": "발작이라", "it": false}, {"s": 4602.265, "e": 4604.414, "en": "Just an allergic reaction.\nNothing to worry about.", "ko": "그냥 알레르기 반응이야\n걱정할 거 없어", "it": false}, {"s": 4604.434, "e": 4606.75, "en": "I'm not so sure anymore.", "ko": "이젠 확신이\n안 서는데요", "it": false}, {"s": 4606.769, "e": 4611.23, "en": "It's highly likely\nthat you were poisoned.", "ko": "독에 중독됐을\n가능성이 아주 높습니다", "it": false}, {"s": 4616.17, "e": 4617.837, "en": "Go get mal.", "ko": "말 데려오시오", "it": false}, {"s": 4617.855, "e": 4619.188, "en": "Oh, you can't possibly think...", "ko": "설마 그 애가...", "it": false}, {"s": 4619.282, "e": 4620.84, "en": "That our son is lazy?", "ko": "우리 아들이 게으르다는 것 말이오?", "it": false}, {"s": 4620.858, "e": 4622.738, "en": "That he wants money, my money,", "ko": "돈을, 내 돈을 원하면서", "it": false}, {"s": 4622.768, "e": 4624.154, "en": "But isn't willing\nto work for it?", "ko": "일해서 벌 생각은\n없다는 것?", "it": false}, {"s": 4624.178, "e": 4625.823, "en": "All he's been talking\nabout is getting his hands", "ko": "그 녀석은 맨날\n그 잘난 신탁에", "it": false}, {"s": 4625.847, "e": 4627.916, "en": "On his precious trust which\nwould be a hell of a lot easier", "ko": "손댈 생각뿐이오\n내가 막지만 않으면", "it": false}, {"s": 4627.94, "e": 4630.124, "en": "If I wasn't around to stop him!", "ko": "훨씬 쉬워질 테니까!", "it": false}, {"s": 4632.099, "e": 4634.767, "en": "Thank you, doctor. We\nappreciate your discretion.", "ko": "감사합니다, 선생님\n비밀은 지켜 주세요", "it": false}, {"s": 4634.792, "e": 4635.792, "en": "Of course.", "ko": "물론입니다", "it": false}, {"s": 4640.862, "e": 4641.969, "en": "Good day.", "ko": "안녕히 계세요", "it": false}, {"s": 4648.115, "e": 4649.77, "en": "This is utter nonsense.", "ko": "말도 안 되는 소리야", "it": false}, {"s": 4649.795, "e": 4651.522, "en": "You know mal\nwouldn't hurt anyone,", "ko": "말은 누굴 해칠\n애가 아니야", "it": false}, {"s": 4651.547, "e": 4653.722, "en": "No matter how hateful\nyou've been to him.", "ko": "당신이 그 애한테\n아무리 모질게 굴었어도", "it": false}, {"s": 4653.875, "e": 4655.224, "en": "Then who?", "ko": "그럼 누구요?", "it": false}, {"s": 4655.318, "e": 4656.942, "en": "What if it was me?", "ko": "나라면?", "it": false}, {"s": 4658.229, "e": 4659.712, "en": "You don't have the nerve.", "ko": "당신은 그럴 배짱이 없소", "it": false}, {"s": 4659.805, "e": 4661.624, "en": "Perhaps you should\nstart drawing up a list", "ko": "가능한 용의자 명단이라도", "it": false}, {"s": 4661.649, "e": 4663.565, "en": "Of potential assailants.", "ko": "만들어 보지 그래?", "it": false}, {"s": 4663.718, "e": 4665.178, "en": "I would think the\nnumber of enemies", "ko": "당신이 그동안 쌓아 온\n적들 명단은", "it": false}, {"s": 4665.203, "e": 4668.329, "en": "You've acquired over the\nyears is quite lengthy.", "ko": "꽤 길 것 같은데", "it": false}, {"s": 4668.48, "e": 4670.581, "en": "We should dress for the wedding.", "ko": "결혼식 갈 준비 해야지", "it": false}, {"s": 4675.73, "e": 4677.93, "en": "Should I call for someone\nto help you get ready?", "ko": "준비 도와줄 사람\n불러 줄까?", "it": false}, {"s": 4678.065, "e": 4680.841, "en": "I'll manage perfectly\nwell by myself, thank you.", "ko": "나 혼자서도 아주 잘하오\n고맙군", "it": false}, {"s": 4689.001, "e": 4690.075, "en": "Mr. Foxworth.", "ko": "폭스워스 씨", "it": false}, {"s": 4690.169, "e": 4692.049, "en": "Glad to see you're\nfeeling better.", "ko": "나아지셔서 다행이에요", "it": false}, {"s": 4692.079, "e": 4694.48, "en": "I just wanted to come\ncheck in on the bride.", "ko": "신부가 어떤지\n보러 왔어", "it": false}, {"s": 4698.343, "e": 4700.194, "en": "You look beautiful, helen.", "ko": "아름답구나, 헬렌", "it": false}, {"s": 4700.345, "e": 4701.696, "en": "Thank you.", "ko": "감사합니다", "it": false}, {"s": 4706.761, "e": 4708.994, "en": "Please, sit.", "ko": "앉아", "it": false}, {"s": 4712.783, "e": 4717.102, "en": "I just wanted to\napologize personally", "ko": "직접 사과하고\n싶었단다", "it": false}, {"s": 4717.196, "e": 4722.216, "en": "For not giving mal early\naccess to his trust.", "ko": "말한테 신탁을\n일찍 안 준 거 말이야", "it": false}, {"s": 4722.367, "e": 4725.368, "en": "Oh, I really don't\nknow much about it.", "ko": "아, 전 그런 건\n잘 몰라요", "it": false}, {"s": 4725.463, "e": 4728.055, "en": "Those kinds of matters aren't\nfor women to nosey around in.", "ko": "그런 일에 여자가\n참견하면 안 되죠", "it": false}, {"s": 4730.618, "e": 4734.119, "en": "Beautiful and smart.\nMal chose well.", "ko": "예쁜 데다 똑똑하기까지\n말이 잘 골랐군", "it": false}, {"s": 4734.213, "e": 4735.73, "en": "Thank you.", "ko": "감사합니다", "it": false}, {"s": 4737.056, "e": 4741.533, "en": "Did mal explain that\nthis family operates", "ko": "말이 얘기해 줬니?\n이 집안은", "it": false}, {"s": 4741.558, "e": 4746.131, "en": "Under a very specific\nset of rules?", "ko": "아주 분명한 규칙대로\n돌아간다는 걸", "it": false}, {"s": 4746.15, "e": 4751.912, "en": "I don't understand\nwhat you mean. Rules?", "ko": "무슨 말씀이신지...\n규칙이요?", "it": false}, {"s": 4752.139, "e": 4760.139, "en": "Well, I make 'em. Everyone\nelse follows them.", "ko": "규칙은 내가 만들고\n다른 사람들은 따르지", "it": false}, {"s": 4760.831, "e": 4765.394, "en": "And when they follow\nthem precisely,", "ko": "그리고 규칙을\n정확히 따르면", "it": false}, {"s": 4766.471, "e": 4769.138, "en": "Everybody gets what they want.", "ko": "모두가 원하는 걸 얻어", "it": false}, {"s": 4771.498, "e": 4777.502, "en": "Now, mal wants that money", "ko": "말은 그 돈을 원하지", "it": false}, {"s": 4777.94, "e": 4782.067, "en": "And you want him to get\nwhat he wants, don't you?", "ko": "너도 말이 원하는 걸\n얻길 바라잖아, 그렇지?", "it": false}, {"s": 4785.673, "e": 4787.506, "en": "I love mal.", "ko": "전 말을 사랑해요", "it": false}, {"s": 4787.525, "e": 4789.099, "en": "Hmm.", "ko": "흠", "it": false}, {"s": 4789.193, "e": 4790.951, "en": "I want him to be happy.", "ko": "그이가 행복하길 바라요", "it": false}, {"s": 4791.178, "e": 4792.269, "en": "Mm-hmm.", "ko": "음", "it": false}, {"s": 4792.288, "e": 4794.538, "en": "To get what he wants.", "ko": "원하는 걸 얻길요", "it": false}, {"s": 4809.305, "e": 4810.387, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 4830.217, "e": 4832.379, "en": "Where are you going?\nEverybody's looking for you.", "ko": "어디 가?\n다들 오빠 찾고 있어", "it": false}, {"s": 4832.403, "e": 4833.788, "en": "Your wedding's about to start.", "ko": "곧 결혼식 시작이잖아", "it": false}, {"s": 4833.812, "e": 4835.456, "en": "There isn't going\nto be a wedding.", "ko": "결혼식 같은 건\n없을 거야", "it": false}, {"s": 4835.48, "e": 4836.572, "en": "What? Why?", "ko": "뭐? 왜?", "it": false}, {"s": 4836.666, "e": 4838.833, "en": "Get in. I'll explain.", "ko": "타\n설명해 줄게", "it": false}, {"s": 4851.316, "e": 4853.501, "en": "I just walked in\non dad and helen.", "ko": "방금 아버지랑 헬렌이\n같이 있는 걸 봤어", "it": false}, {"s": 4855.349, "e": 4856.527, "en": "Where did you get this?", "ko": "이거 어디서 났어?", "it": false}, {"s": 4856.552, "e": 4857.743, "en": "The dressing table.", "ko": "화장대에서", "it": false}, {"s": 4857.836, "e": 4859.164, "en": "Did you hear what\nI said about dad?", "ko": "내가 아버지 얘기\n한 거 들었어?", "it": false}, {"s": 4859.188, "e": 4861.021, "en": "Mal, this isn't...", "ko": "오빠, 이건...", "it": false}, {"s": 4861.248, "e": 4862.248, "en": "Oh, my god.", "ko": "세상에", "it": false}, {"s": 4864.602, "e": 4866.026, "en": "What's happening?", "ko": "왜 이러지?", "it": false}, {"s": 4866.863, "e": 4868.696, "en": "Mal, no! Hold on, mal!", "ko": "오빠, 안 돼!\n정신 차려, 오빠!", "it": false}, {"s": 4869.348, "e": 4871.282, "en": "- Look out!!!", "ko": "-조심해!!!", "it": false}, {"s": 4881.86, "e": 4883.285, "en": "Where have you been?", "ko": "어디 갔었어?", "it": false}, {"s": 4883.31, "e": 4885.811, "en": "Settling some business.", "ko": "볼일 좀 봤소", "it": false}, {"s": 4885.956, "e": 4890.125, "en": "Mrs. Foxworth! Mr. Foxworth!", "ko": "마님! 주인님!", "it": false}, {"s": 4890.277, "e": 4892.421, "en": "Something terrible has happened.", "ko": "큰일 났어요", "it": false}, {"s": 4895.558, "e": 4897.799, "en": "Are you all right?", "ko": "괜찮니?", "it": false}, {"s": 4897.894, "e": 4899.134, "en": "I'm fine.", "ko": "전 괜찮아요", "it": false}, {"s": 4899.286, "e": 4900.786, "en": "It's mal!", "ko": "말 오빠예요!", "it": false}, {"s": 4900.804, "e": 4901.932, "en": "The poison from the garden,", "ko": "정원에 있던 독초를", "it": false}, {"s": 4901.956, "e": 4903.283, "en": "He thought it was\nsomething to smoke.", "ko": "오빠는 피우는 건 줄\n알았어요", "it": false}, {"s": 4903.307, "e": 4905.882, "en": "mal! Mal!", "ko": "말! 말!", "it": false}, {"s": 4905.976, "e": 4907.55, "en": "Somebody call the doctor!", "ko": "누가 의사 좀 불러요!", "it": false}, {"s": 4907.645, "e": 4909.461, "en": "He's not breathing.", "ko": "숨을 안 쉬어", "it": false}, {"s": 4982.76, "e": 4985.289, "en": "I was so worried\nabout protecting my daughter", "ko": "딸을 지키는 데만\n급급한 나머지", "it": true}, {"s": 4985.314, "e": 4987.062, "en": "That I lost my son.", "ko": "나는 아들을 잃었다", "it": true}, {"s": 4991.579, "e": 4994.672, "en": "The family dealt with their\ngrief in different ways.", "ko": "가족은 저마다 다른 방식으로\n슬픔을 견뎠다", "it": true}, {"s": 4999.685, "e": 5003.032, "en": "Some sought comfort in others.", "ko": "누군가는 다른 사람에게서\n위안을 찾았고", "it": true}, {"s": 5020.688, "e": 5023.948, "en": "Some found comfort in a\ndifferent kind of release.", "ko": "누군가는 다른 방식의\n해방에서 위안을 찾았다", "it": true}, {"s": 5046.893, "e": 5050.609, "en": "But me? I didn't\ndeserve comfort.", "ko": "하지만 나는?\n나는 위안받을 자격이 없었다", "it": true}, {"s": 5052.489, "e": 5056.275, "en": "Our son is dead because of you!", "ko": "당신 때문에\n우리 아들이 죽었소!", "it": false}, {"s": 5056.3, "e": 5058.167, "en": "You hid that garden from me!", "ko": "그 정원을 나한테 숨겼소!", "it": false}, {"s": 5058.192, "e": 5061.704, "en": "You dragged corrine\ninto all of this mess!", "ko": "코린을 이 난장판에\n끌어들였고!", "it": false}, {"s": 5061.724, "e": 5065.784, "en": "You have destroyed this family!", "ko": "당신이 이 가족을 망쳤소!", "it": false}, {"s": 5065.803, "e": 5069.304, "en": "And then I did something\nI never thought I'd do.", "ko": "그리고 나는\n생각지도 못한 일을 했다", "it": true}, {"s": 5069.329, "e": 5070.829, "en": "You're right.", "ko": "당신 말이 맞아요", "it": false}, {"s": 5071.125, "e": 5074.551, "en": "I surrendered control\nto my husband.", "ko": "남편에게\n통제권을 넘겨준 것이다", "it": true}, {"s": 5074.576, "e": 5076.468, "en": "I'm sorry.", "ko": "미안해요", "it": false}, {"s": 5077.406, "e": 5081.909, "en": "I'm so very, very sorry.", "ko": "정말, 정말 미안해요", "it": false}, {"s": 5081.934, "e": 5083.814, "en": "You do not deserve\nmy forgiveness.", "ko": "당신은 용서받을\n자격이 없소", "it": false}, {"s": 5084.138, "e": 5085.703, "en": "I know.", "ko": "알아요", "it": false}, {"s": 5086.086, "e": 5088.807, "en": "You abused the freedom\nthat I gave to you.", "ko": "당신은 내가 준 자유를\n남용했소", "it": false}, {"s": 5088.832, "e": 5091.166, "en": "So, now today that\nfreedom is gone.", "ko": "그러니 오늘부로\n그 자유는 끝이오", "it": false}, {"s": 5091.328, "e": 5093.736, "en": "You will respect me!", "ko": "날 존중하시오!", "it": false}, {"s": 5093.756, "e": 5095.566, "en": "You will obey me!", "ko": "내 말에 복종하시오!", "it": false}, {"s": 5095.591, "e": 5099.015, "en": "You will listen to me!", "ko": "내 말을 들으시오!", "it": false}, {"s": 5099.653, "e": 5101.483, "en": "Do you understand?!", "ko": "알아들었소?!", "it": false}, {"s": 5103.157, "e": 5104.157, "en": "Yes.", "ko": "네", "it": false}, {"s": 5106.102, "e": 5107.967, "en": "Whatever you say.", "ko": "당신 뜻대로 할게요", "it": false}, {"s": 5108.821, "e": 5111.798, "en": "You should be\nashamed of yourself.", "ko": "부끄러운 줄 아시오", "it": false}, {"s": 5114.505, "e": 5117.914, "en": "I realized I never\nhad control of anything.", "ko": "나는 깨달았다\n내가 통제한 건 아무것도 없었다는 걸", "it": true}, {"s": 5117.939, "e": 5121.506, "en": "Not my future, not my\nchildren, not even the staff.", "ko": "내 미래도, 내 아이들도,\n하인들조차도", "it": true}, {"s": 5121.531, "e": 5124.716, "en": "Something else\ncontrolled all of us.", "ko": "다른 무언가가\n우리 모두를 지배하고 있었다", "it": true}, {"s": 5124.91, "e": 5127.019, "en": "Something we couldn't escape.", "ko": "우리가 벗어날 수 없는 것", "it": true}, {"s": 5128.29, "e": 5129.915, "en": "Foxworth hall.", "ko": "폭스워스 저택", "it": true}, {"s": 5140.674, "e": 5144.583, "en": "And in that moment, it was\nbringing more horror upon us.", "ko": "그 순간에도 저택은\n또 다른 공포를 불러오고 있었다", "it": true}, {"s": 5145.799, "e": 5149.058, "en": "Someone who would\nbring us new pain,", "ko": "우리에게 새로운 고통과", "it": true}, {"s": 5149.311, "e": 5154.13, "en": "New tears, and new tragedy.", "ko": "새로운 눈물, 새로운 비극을\n안겨 줄 사람", "it": true}, {"s": 5161.087, "e": 5163.029, "en": "She had returned.", "ko": "그녀가 돌아왔다", "it": true}, {"s": 5165.402, "e": 5168.442, "en": "And with her, the\nfire had been lit.", "ko": "그리고 그녀와 함께\n불이 붙었다", "it": true}, {"s": 5176.806, "e": 5181.21, "en": "It was just a matter of time\nuntil we all went up in flames.", "ko": "우리 모두가 불길에 휩싸이는 건\n시간문제였다", "it": true}], "e3": [{"s": 9.159, "e": 13.253, "en": "They tell you\nwhen one door closes", "ko": "문 하나가 닫히면", "it": true}, {"s": 13.347, "e": 15.014, "en": "Another opens.", "ko": "다른 문이 열린다고들 한다", "it": true}, {"s": 21.338, "e": 23.605, "en": "But what if you can't say\ngoodbye to the past?", "ko": "하지만 과거와 작별할 수\n없다면 어떻게 될까?", "it": true}, {"s": 51.794, "e": 54.553, "en": "Because it's always\nstaring back at you.", "ko": "과거는 늘\n나를 마주 보고 있으니까", "it": true}, {"s": 57.224, "e": 59.058, "en": "Haunting you.", "ko": "나를 따라다니며", "it": true}, {"s": 80.973, "e": 83.5, "en": "I would like to speak\nwith Olivia alone.", "ko": "올리비아랑\n단둘이 얘기하고 싶어요", "it": false}, {"s": 83.584, "e": 88.587, "en": "You do not get to make requests\nafter breaking our agreement.", "ko": "약속을 깨 놓고\n부탁할 자격은 없소", "it": false}, {"s": 88.738, "e": 94.344, "en": "Knocking on my door,\nthreatening to wake my family.", "ko": "문을 두드려 대서\n내 가족을 깨우겠다고 협박하고", "it": false}, {"s": 94.428, "e": 95.836, "en": "You do not get to see\nmy daughter,", "ko": "내 딸은 못 보오", "it": false}, {"s": 95.93, "e": 97.888, "en": "Not tonight, not ever.", "ko": "오늘 밤도, 앞으로도", "it": false}, {"s": 99.491, "e": 100.34, "en": "You must believe me,", "ko": "믿어 줘요", "it": false}, {"s": 100.492, "e": 101.992, "en": "I am not here to exhume\nour past.", "ko": "우리 과거를 파헤치러\n온 게 아니에요", "it": false}, {"s": 102.085, "e": 103.66, "en": "I am here to put it\nto rest.", "ko": "묻어 버리려고 온 거예요", "it": false}, {"s": 103.753, "e": 104.937, "en": "Well then why come at all?", "ko": "그럼 대체\n뭐 하러 왔소?", "it": false}, {"s": 108.109, "e": 109.775, "en": "Because I have cancer.", "ko": "암이래요", "it": false}, {"s": 115.932, "e": 118.933, "en": "And Christopher...", "ko": "그리고 크리스토퍼가...", "it": false}, {"s": 119.027, "e": 121.011, "en": "He's in medical school now.", "ko": "이제 의대에 다녀요", "it": false}, {"s": 121.104, "e": 124.197, "en": "Can you believe it,\nmy son the doctor.", "ko": "믿어져요?\n내 아들이 의사가 된대요", "it": false}, {"s": 124.35, "e": 126.199, "en": "You must realize how dire\nthings are for me", "ko": "내가 당신 집 문 앞까지\n왔을 정도면", "it": false}, {"s": 126.352, "e": 128.953, "en": "To be on your doorstep.", "ko": "얼마나 절박한지\n알 거예요", "it": false}, {"s": 129.037, "e": 130.295, "en": "I have little time left", "ko": "남은 시간이 얼마 없어요", "it": false}, {"s": 130.522, "e": 133.216, "en": "And even less of the inheritance\ngarland left me.", "ko": "갈랜드가 남긴 유산은\n그보다 더 없고요", "it": false}, {"s": 133.3, "e": 135.542, "en": "It was all lost\nin the crash.", "ko": "대공황 때\n다 날렸어요", "it": false}, {"s": 135.636, "e": 139.471, "en": "And when I'm gone, Christopher\nwill have nowhere to go.", "ko": "내가 죽으면 크리스토퍼는\n갈 데가 없어요", "it": false}, {"s": 139.698, "e": 141.531, "en": "No means to finish\nhis schooling,", "ko": "학업을 마칠\n돈도 없고", "it": false}, {"s": 141.625, "e": 144.384, "en": "No other family\nto support him.", "ko": "기댈 가족도 없어요", "it": false}, {"s": 144.536, "e": 147.896, "en": "I gave you my daughter\nby choice.", "ko": "난 내 딸을\n내 손으로 내줬어요", "it": false}, {"s": 150.209, "e": 153.71, "en": "Tonight I am asking you\nto take my son.", "ko": "오늘 밤엔 내 아들을\n맡아 달라고 부탁하는 거예요", "it": false}, {"s": 153.803, "e": 155.32, "en": "I had followed\nmy instincts", "ko": "나는 늘\n내 직감을 따랐다", "it": true}, {"s": 155.547, "e": 157.781, "en": "But that had led straight\nto mal's death.", "ko": "하지만 그 직감이 결국\n말을 죽음으로 몰았다", "it": true}, {"s": 159.401, "e": 160.975, "en": "Olivia, please.", "ko": "올리비아, 제발요", "it": false}, {"s": 161.069, "e": 162.736, "en": "And so it began.", "ko": "그렇게 시작되었다", "it": true}, {"s": 162.888, "e": 166.331, "en": "For one dark year I pushed back\nagainst my instincts.", "ko": "암흑 같은 1년 동안\n나는 내 직감을 억눌렀다", "it": true}, {"s": 166.558, "e": 168.792, "en": "This is Malcolm's decision\nto make.", "ko": "그건 맬컴이\n정할 일이에요", "it": false}, {"s": 172.339, "e": 175.132, "en": "And learn to follow\nMalcolm's instead.", "ko": "대신 맬컴의 뜻을\n따르는 법을 배웠다", "it": true}, {"s": 177.661, "e": 182.739, "en": "Nothing will be free\nfor him here.", "ko": "여기선 아무것도\n공짜로 주지 않을 거요", "it": false}, {"s": 182.832, "e": 185.475, "en": "He will have to work\nfor his education.", "ko": "학비는\n일해서 벌어야 할 거요", "it": false}, {"s": 192.359, "e": 193.777, "en": "But I don't need\na tutor, daddy.", "ko": "하지만 전 가정교사\n필요 없어요, 아빠", "it": false}, {"s": 193.861, "e": 195.353, "en": "I just want to go back to school\nand see my friends.", "ko": "그냥 학교로 돌아가서\n친구들 보고 싶어요", "it": false}, {"s": 195.437, "e": 196.437, "en": "Sit.", "ko": "앉아", "it": false}, {"s": 198.515, "e": 200.991, "en": "I became an observer\nin my own home.", "ko": "나는 내 집에서\n구경꾼이 되었다", "it": true}, {"s": 205.039, "e": 207.355, "en": "None of this goddamn\npiano music!", "ko": "그 망할 피아노 소리\n그만두지 못해!", "it": true}, {"s": 207.449, "e": 209.292, "en": "You know what I want\nfor Christmas?!", "ko": "크리스마스 선물로\n뭘 원하는지 알아?!", "it": false}, {"s": 209.376, "e": 211.601, "en": "Silence!", "ko": "조용히 하는 거다!", "it": false}, {"s": 211.695, "e": 213.688, "en": "I told myself that I did it for the safety\nof my children.", "ko": "아이들의 안전을 위해서라고\n나 자신을 다독였다", "it": true}, {"s": 213.772, "e": 215.721, "en": "...In here,\nday in and day out.", "ko": "...여기서 매일같이 말이야", "it": true}, {"s": 234.58, "e": 236.81, "en": "Alicia has died.", "ko": "앨리샤가\n세상을 떠났대요", "it": false}, {"s": 237.223, "e": 240.977, "en": "I thought that as long\nas I obeyed Malcolm...", "ko": "맬컴에게 복종하기만 하면...", "it": true}, {"s": 241.467, "e": 243.051, "en": "Where do you think Christopher\nwould like", "ko": "크리스토퍼가 부모 사진을", "it": false}, {"s": 243.135, "e": 244.719, "en": "This picture of his parents?", "ko": "어디에 두고 싶어 할까요?", "it": false}, {"s": 244.803, "e": 247.739, "en": "One thing could\nremain certain.", "ko": "한 가지만큼은\n확실하리라 믿었다", "it": true}, {"s": 247.823, "e": 252.004, "en": "That what happened to mal would\nnever happen again in my home.", "ko": "말에게 일어난 일이\n다시는 이 집에서 일어나지 않으리라고", "it": true}, {"s": 253.645, "e": 255.321, "en": "Mother?", "ko": "엄마?", "it": false}, {"s": 255.405, "e": 257.399, "en": "I thought perhaps\nI could ride my horse", "ko": "오늘 오후에\n말 타고 시내에", "it": false}, {"s": 257.483, "e": 258.733, "en": "Into town this afternoon.", "ko": "좀 다녀올까 하는데요", "it": false}, {"s": 258.817, "e": 260.402, "en": "If this is about your debutante\nball dress,", "ko": "사교계 데뷔 무도회\n드레스 때문이라면", "it": false}, {"s": 260.486, "e": 262.328, "en": "I already have appointments\nset for seamstresses", "ko": "다음 주에 재봉사들이\n집으로 오기로", "it": false}, {"s": 262.412, "e": 264.347, "en": "To come to the house\nnext week.", "ko": "이미 약속을 잡아 놨어", "it": false}, {"s": 264.431, "e": 266.241, "en": "Then shouldn't I know what\nthe latest fashions are", "ko": "그럼 재봉사들이 오기 전에", "it": false}, {"s": 266.325, "e": 267.592, "en": "Before they arrive?", "ko": "요즘 유행이 뭔지\n알아야 하지 않을까요?", "it": false}, {"s": 269.103, "e": 271.095, "en": "You can't keep me locked up\nin this house forever.", "ko": "평생 저를 이 집에\n가둬 둘 순 없어요", "it": false}, {"s": 271.179, "e": 272.859, "en": "It's up to your father.", "ko": "그건 아빠가 정할 일이야", "it": false}, {"s": 286.453, "e": 287.687, "en": "Daddy...", "ko": "아빠...", "it": false}, {"s": 287.771, "e": 289.539, "en": "With my debutante ball\ncoming up", "ko": "이제 데뷔 무도회도\n다가오는데", "it": false}, {"s": 289.623, "e": 292.45, "en": "I really need to have the best\ndress, don't you think?", "ko": "제일 예쁜 드레스가\n꼭 있어야 하잖아요, 그쵸?", "it": false}, {"s": 292.534, "e": 294.377, "en": "Well, only the best\nfor my daughter", "ko": "그럼, 버지니아 사교계에\n처음 나서는 날인데", "it": false}, {"s": 294.461, "e": 297.881, "en": "On the night she introduces\nherself to virginian society.", "ko": "우리 딸한텐\n최고만 줘야지", "it": false}, {"s": 297.965, "e": 300.217, "en": "So, maybe you could give me\nthe key to the swan room", "ko": "그럼 백조의 방 열쇠를\n주시면 안 돼요?", "it": false}, {"s": 300.301, "e": 302.052, "en": "And I could have a look through\ngrandmother's old things", "ko": "할머니 옛날 물건들을\n좀 둘러보면서", "it": false}, {"s": 302.136, "e": 304.268, "en": "For some inspiration.", "ko": "영감을 얻고 싶어서요", "it": false}, {"s": 306.365, "e": 310.118, "en": "Why don't you visit the shops\nin town instead?", "ko": "그러지 말고 시내\n가게들을 둘러보는 게 어떠니?", "it": false}, {"s": 310.202, "e": 311.711, "en": "I don't know, daddy.", "ko": "글쎄요, 아빠", "it": false}, {"s": 311.795, "e": 313.788, "en": "It just doesn't sound very fun\nto go all the way there", "ko": "거기까지 가서", "it": false}, {"s": 313.872, "e": 316.124, "en": "And look at all those\ntantalizing things", "ko": "그 예쁜 것들을\n실컷 구경만 하고", "it": false}, {"s": 316.208, "e": 319.477, "en": "And not have any means to bring\nany of them home.", "ko": "하나도 못 사 오면\n별로 재미없을 것 같아서요", "it": false}, {"s": 319.561, "e": 323.993, "en": "Well, what is to be done\nabout that, hmm?", "ko": "그럼 그건\n어떻게 해야 할까?", "it": false}, {"s": 341.658, "e": 343.927, "en": "I guess I could ask Joel\nto stop playing his piano", "ko": "조엘 오빠한테\n피아노 좀 그만 치고", "it": false}, {"s": 344.011, "e": 345.595, "en": "For a bit and take me.", "ko": "저 좀 태워 달라고 할까 봐요", "it": false}, {"s": 345.679, "e": 348.518, "en": "Wouldn't that be a gift\nto us all.", "ko": "그럼 우리 모두한테\n선물이겠구나", "it": false}, {"s": 368.202, "e": 370.345, "en": "I've already lost my closest\nfriendships from school", "ko": "학교 친구들이랑은\n벌써 다 멀어졌어", "it": false}, {"s": 370.429, "e": 372.514, "en": "Since no one writes anymore.", "ko": "이제 아무도 편지를 안 해", "it": false}, {"s": 372.598, "e": 374.699, "en": "When they show up to my ball,\nif they even do,", "ko": "무도회에 오더라도,\n오기나 할지 모르지만", "it": false}, {"s": 374.783, "e": 376.034, "en": "I'll be a complete stranger.", "ko": "난 완전히\n남이 돼 있을 거야", "it": false}, {"s": 376.118, "e": 377.869, "en": "How am I going to have\nany fun?", "ko": "그러니 무슨 재미가 있겠어?", "it": false}, {"s": 377.953, "e": 379.704, "en": "Well, hopefully this Christopher\nfellow coming to stay", "ko": "그래도 크리스토퍼라는\n사람이 와서 지내면", "it": false}, {"s": 379.788, "e": 381.706, "en": "Will make father look up.", "ko": "아버지 기분이\n좀 나아지시겠지", "it": false}, {"s": 381.79, "e": 383.949, "en": "It's easy for you to see\nthe positives.", "ko": "오빠는 좋게만 보면\n그만이지", "it": false}, {"s": 384.033, "e": 386.619, "en": "They actually let you leave\nfor school", "ko": "오빠는 학교도\n보내 주잖아", "it": false}, {"s": 386.703, "e": 388.379, "en": "And get away with a life\nfull of secret dalliances", "ko": "비밀 연애도 실컷 하면서\n자유롭게 살고", "it": false}, {"s": 388.463, "e": 389.714, "en": "While I'm stuck at home", "ko": "난 집에 갇혀서", "it": false}, {"s": 389.798, "e": 391.533, "en": "Listening to the world\non the radio.", "ko": "라디오로만 세상을\n듣고 있는데", "it": false}, {"s": 391.617, "e": 394.23, "en": "No, that's just because\nsince mal died.", "ko": "아니야, 그건 그냥\n말 형이 죽은 뒤로...", "it": false}, {"s": 396.121, "e": 398.873, "en": "Well, father's the only one\nmaking decisions these days", "ko": "요즘은 아버지 혼자\n다 결정하시잖아", "it": false}, {"s": 398.957, "e": 401.709, "en": "And he doesn't give a fig\nwhat happens to me.", "ko": "내가 어떻게 되든\n눈곱만큼도 신경 안 쓰셔", "it": false}, {"s": 401.793, "e": 403.711, "en": "And it's dalliance.", "ko": "그리고 연애는", "it": false}, {"s": 403.795, "e": 405.322, "en": "Singular.", "ko": "하나야", "it": false}, {"s": 405.406, "e": 407.215, "en": "You're cruel.", "ko": "오빠 너무해", "it": false}, {"s": 407.299, "e": 409.662, "en": "Why won't you tell me\nabout her?", "ko": "그 여자 얘기\n왜 안 해 줘?", "it": false}, {"s": 411.987, "e": 413.83, "en": "This is more fun.", "ko": "이게 더 재밌잖아", "it": false}, {"s": 421.088, "e": 422.914, "en": "Just tell me this.", "ko": "이것만 말해 줘", "it": false}, {"s": 422.998, "e": 424.657, "en": "Is it because I know her?", "ko": "내가 아는 사람이라서 그래?", "it": false}, {"s": 424.741, "e": 427.352, "en": "You can keep trying but you're\nnot getting anything out of me.", "ko": "아무리 캐물어도\n나한테선 아무것도 못 알아내", "it": false}, {"s": 431.265, "e": 434.017, "en": "Mrs. Steiner.\nGood afternoon.", "ko": "스타이너 부인\n안녕하세요", "it": false}, {"s": 434.101, "e": 437.503, "en": "Why Mr. Joel foxworth.", "ko": "어머나, 조엘 폭스워스\n도련님 아니세요", "it": false}, {"s": 437.587, "e": 441.504, "en": "All grown up and pretty\nas a peacock.", "ko": "다 컸네\n공작새처럼 번드르르하게", "it": false}, {"s": 441.718, "e": 443.223, "en": "If you'll excuse me,", "ko": "그럼 난 이만", "it": false}, {"s": 443.34, "e": 445.587, "en": "some of us don't have time\nto dawdle in the streets", "ko": "누구는 길바닥에서\n빈둥거릴 시간이 없어서요", "it": false}, {"s": 445.671, "e": 449.785, "en": "Contributing absolutely nothing\nto the workforce.", "ko": "세상에 보탬 하나\n안 되면서 말이에요", "it": false}, {"s": 456.105, "e": 458.19, "en": "And who was that bucket\nof joy?", "ko": "저 기쁨 덩어리는 누구야?", "it": false}, {"s": 458.274, "e": 460.543, "en": "A bucket and a mop\nfull of joy.", "ko": "기쁨이 아주\n넘쳐흐르시더라", "it": false}, {"s": 460.627, "e": 463.121, "en": "She used to be our housekeeper,\nMrs. Steiner.", "ko": "예전 우리 집\n가정부장이었어, 스타이너 부인", "it": false}, {"s": 463.205, "e": 466.216, "en": "Mother fired her\nbefore you were born.", "ko": "네가 태어나기 전에\n어머니가 해고하셨어", "it": false}, {"s": 466.3, "e": 468.126, "en": "Mal always told me how much\nhe hated her.", "ko": "말 형이 그 여자를\n얼마나 싫어했는지 몰라", "it": false}, {"s": 468.21, "e": 470.553, "en": "Hmm, I can't imagine why.", "ko": "왜 그랬는지\n알 것 같다", "it": false}, {"s": 470.637, "e": 473.056, "en": "Do you want to come with me\nand help pick out a dress?", "ko": "나랑 같이 드레스\n고르러 갈래?", "it": false}, {"s": 473.14, "e": 475.811, "en": "Tempting, but I have\nmy own shopping to do.", "ko": "끌리긴 하는데\n나도 살 게 있어서", "it": false}, {"s": 487.303, "e": 490.648, "en": "Oh, miss foxworth,\nyour stockings.", "ko": "어머, 폭스워스 아가씨\n스타킹이", "it": false}, {"s": 490.732, "e": 492.133, "en": "Ugh.", "ko": "으", "it": false}, {"s": 492.217, "e": 494.226, "en": "Just another thing falling apart\nin my world.", "ko": "내 세상에서\n또 하나가 망가지네", "it": false}, {"s": 494.31, "e": 495.97, "en": "Do you have any\nfor purchase?", "ko": "스타킹 파는 거 있어요?", "it": false}, {"s": 496.054, "e": 498.084, "en": "Well, only paint on.", "ko": "그려 넣는 것밖에 없어요", "it": false}, {"s": 517.851, "e": 519.939, "en": "Looking for something?", "ko": "뭐 찾으세요?", "it": false}, {"s": 523.582, "e": 525.925, "en": "Not anymore.", "ko": "이젠 아니에요", "it": false}, {"s": 526.009, "e": 528.853, "en": "Sir, I'm helping\nthe young lady.", "ko": "손님, 지금 이 아가씨를\n응대하는 중이라서요", "it": false}, {"s": 528.937, "e": 530.866, "en": "That's quite all right.", "ko": "괜찮아요", "it": false}, {"s": 533.7, "e": 535.176, "en": "The top button seems\nto have caught", "ko": "맨 위 단추가\n걸렸는지", "it": false}, {"s": 535.26, "e": 538.437, "en": "As I was unloading my luggage\non the train.", "ko": "기차에서 짐을 내리다가\n떨어졌어요", "it": false}, {"s": 538.521, "e": 540.623, "en": "Normally I wouldn't mind\nbeing one button short,", "ko": "평소 같으면 단추 하나쯤\n없어도 신경 안 쓰는데", "it": false}, {"s": 540.707, "e": 544.461, "en": "But first impressions\nbeing what they are.", "ko": "첫인상이란 게\n중요하잖아요", "it": false}, {"s": 544.545, "e": 548.539, "en": "If the lady will allow, I can\nmend it in just a moment.", "ko": "아가씨만 괜찮으시면\n금방 달아 드릴게요", "it": false}, {"s": 548.623, "e": 550.858, "en": "Go right ahead.", "ko": "그렇게 해 주세요", "it": false}, {"s": 550.942, "e": 552.555, "en": "And take your time.", "ko": "천천히 하세요", "it": false}, {"s": 560.727, "e": 563.721, "en": "We seem to have stumbled upon\neach other indisposed, miss.", "ko": "우리 둘 다\n곤란한 꼴로 만났네요, 아가씨", "it": false}, {"s": 563.805, "e": 568.818, "en": "And exposed, sir.", "ko": "그리고 다 드러난 꼴로요", "it": false}, {"s": 568.902, "e": 571.713, "en": "I'll forgive your bad impression\nif you forgive mine.", "ko": "내 첫인상을 용서해 주면\n당신 첫인상도 용서할게요", "it": false}, {"s": 571.797, "e": 572.968, "en": "Deal.", "ko": "좋아요", "it": false}, {"s": 576.243, "e": 578.828, "en": "Those were my last silk pair.", "ko": "마지막 남은\n실크 스타킹이었는데", "it": false}, {"s": 578.912, "e": 580.555, "en": "Were?", "ko": "였다고요?", "it": false}, {"s": 580.639, "e": 582.39, "en": "They ripped.", "ko": "찢어졌어요", "it": false}, {"s": 582.474, "e": 584.483, "en": "I guess I am to become\none of the many women", "ko": "이제 나도 맨다리 뒤에", "it": false}, {"s": 584.567, "e": 586.669, "en": "Parading about town\nwith painted seams", "ko": "솔기를 그려 넣고\n돌아다니는", "it": false}, {"s": 586.753, "e": 589.154, "en": "On the back of\ntheir bare legs.", "ko": "수많은 여자들 중\n하나가 되겠네요", "it": false}, {"s": 589.238, "e": 594.01, "en": "It's unladylike\nand uncomfortable.", "ko": "숙녀답지도 않고\n불편하고요", "it": false}, {"s": 594.094, "e": 596.161, "en": "Well, I may not be able to\nsoothe the issue of comfort", "ko": "불편한 건 제가\n어떻게 해 드릴 수 없지만", "it": false}, {"s": 596.245, "e": 597.68, "en": "But I can assure you\nthat no gentleman", "ko": "이건 장담하죠\n그 어떤 신사도", "it": false}, {"s": 597.764, "e": 600.394, "en": "Will be staring\nat your legs.", "ko": "아가씨 다리를\n쳐다보진 않을 거예요", "it": false}, {"s": 603.586, "e": 606.525, "en": "So, you're saying\nyou're no gentleman?", "ko": "그 말은 당신은\n신사가 아니라는 거네요?", "it": false}, {"s": 615.949, "e": 617.286, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 626.868, "e": 628.878, "en": "I'm forever in your debt.", "ko": "이 은혜 평생\n못 잊을 거예요", "it": false}, {"s": 630.522, "e": 633.383, "en": "Better watch out.\nI might keep you to that.", "ko": "조심해요\n정말 갚으라고 할지도 몰라요", "it": false}, {"s": 696.588, "e": 701.934, "en": "There you are. I have\na present for you,", "ko": "여기 있었네\n선물이 있어", "it": false}, {"s": 702.018, "e": 704.123, "en": "So you know what time it is\nto come to see me.", "ko": "날 보러 올 시간을\n알 수 있게", "it": false}, {"s": 710.285, "e": 713.037, "en": "But I like listening\nfor your music.", "ko": "난 네 피아노 소리\n기다리는 게 좋은데", "it": false}, {"s": 713.121, "e": 716.132, "en": "It reminds me of when nella\nused to sing to me at night.", "ko": "넬라 아줌마가 밤에\n노래 불러 주던 게 생각나거든", "it": false}, {"s": 716.216, "e": 720.222, "en": "You can still listen with a very\nhandsome watch on your arm.", "ko": "팔에 근사한 시계를 차고도\n들을 수 있잖아", "it": false}, {"s": 722.222, "e": 725.366, "en": "You sure this isn't just some\nway to hold me over longer?", "ko": "이걸로 나 좀 더\n붙잡아 두려는 거 아니지?", "it": false}, {"s": 725.45, "e": 727.459, "en": "You know my father.", "ko": "우리 아버지 알잖아", "it": false}, {"s": 727.543, "e": 729.795, "en": "There's no way I'm getting\nmy trust till I turn 25.", "ko": "스물다섯 되기 전엔\n신탁은 꿈도 못 꿔", "it": false}, {"s": 729.879, "e": 731.372, "en": "I don't need some\nrich man's fortune", "ko": "부잣집 재산 때문에", "it": false}, {"s": 731.456, "e": 734.709, "en": "Making me wait to go see\nthe world.", "ko": "세상 구경을\n기다릴 필요 없어", "it": false}, {"s": 734.793, "e": 737.153, "en": "I'll go out\nand grab it myself.", "ko": "내가 직접\n나가서 잡을 거야", "it": false}, {"s": 737.237, "e": 739.304, "en": "Okay.", "ko": "그래", "it": false}, {"s": 739.388, "e": 741.491, "en": "Where is it you truly\nwant to go?", "ko": "진짜 가고 싶은 데가 어디야?", "it": false}, {"s": 741.575, "e": 743.493, "en": "North.", "ko": "북쪽", "it": false}, {"s": 746.321, "e": 748.331, "en": "What does that mean?", "ko": "그게 무슨 뜻이야?", "it": false}, {"s": 748.415, "e": 752.894, "en": "New York? Chicago?", "ko": "뉴욕? 시카고?", "it": false}, {"s": 752.978, "e": 755.413, "en": "Nova Scotia?", "ko": "노바스코샤?", "it": false}, {"s": 755.497, "e": 759.658, "en": "You can't just traipse the globe\nwithout any direction.", "ko": "방향도 없이 세상을\n떠돌 순 없잖아", "it": false}, {"s": 759.742, "e": 763.662, "en": "I'll be happy anywhere\nwithout automobiles to work on.", "ko": "자동차 고칠 일만 없으면\n어디든 좋아", "it": false}, {"s": 763.746, "e": 766.924, "en": "Anywhere I can make\nmy own decisions,", "ko": "내 일을 내가\n정할 수 있는 곳이면", "it": false}, {"s": 767.008, "e": 770.002, "en": "Just anywhere but here.", "ko": "여기만 아니면 어디든", "it": false}, {"s": 770.086, "e": 772.43, "en": "Traveling costs money.", "ko": "여행은 돈이 들어", "it": false}, {"s": 772.514, "e": 774.916, "en": "I can take odd jobs.", "ko": "막일이라도 하면 돼", "it": false}, {"s": 775.0, "e": 777.86, "en": "You can always play your music\nfor money.", "ko": "넌 연주해서\n돈을 벌 수도 있잖아", "it": false}, {"s": 777.944, "e": 781.105, "en": "Everyone needs music.", "ko": "음악은 누구한테나 필요하니까", "it": false}, {"s": 781.189, "e": 783.925, "en": "I can't take my piano\nwith me.", "ko": "피아노를 들고\n갈 순 없잖아", "it": false}, {"s": 784.009, "e": 786.277, "en": "There's plenty of places\ngot pianos", "ko": "피아노 있는 곳은\n얼마든지 있어", "it": false}, {"s": 786.361, "e": 790.039, "en": "And you're plenty pretty\nto get a job playing on them.", "ko": "넌 그런 데서 연주할 만큼\n충분히 예쁘고", "it": false}, {"s": 790.123, "e": 791.877, "en": "Aren't you kind.", "ko": "다정하기도 하지", "it": false}, {"s": 807.048, "e": 809.645, "en": "Would you please quit\nthat racket?!!", "ko": "그 시끄러운 소리\n좀 그만두지 못해?!!", "it": false}, {"s": 820.061, "e": 822.783, "en": "Go, go, go.", "ko": "가, 가, 어서", "it": false}, {"s": 829.329, "e": 831.822, "en": "I told you all that piano\nplaying would make him soft.", "ko": "그 피아노 때문에\n애가 물러질 거라고 했잖소", "it": false}, {"s": 831.906, "e": 833.398, "en": "What are you talking about?", "ko": "무슨 소리예요?", "it": false}, {"s": 833.482, "e": 836.586, "en": "I found that negro garage boy", "ko": "그 흑인 정비소 녀석이", "it": false}, {"s": 836.67, "e": 839.071, "en": "Doing improper things\nto your son.", "ko": "당신 아들한테\n해괴한 짓을 하는 걸 봤소", "it": false}, {"s": 839.155, "e": 840.572, "en": "Oh my god,\nis he hurt?", "ko": "세상에,\n애가 다쳤어요?", "it": false}, {"s": 840.656, "e": 843.012, "en": "Worse. He was enjoying it.", "ko": "더 나쁘오\n그 녀석은 즐기고 있었소", "it": false}, {"s": 847.589, "e": 849.34, "en": "I'll talk to him.", "ko": "내가 얘기해 볼게요", "it": false}, {"s": 849.424, "e": 852.604, "en": "I will take care of it.\nYou've already done enough.", "ko": "내가 처리하겠소\n당신은 이미 할 만큼 했소", "it": false}, {"s": 860.768, "e": 862.336, "en": "Hey, hey, what's going on?", "ko": "이봐요, 뭐 하는 거예요?", "it": false}, {"s": 862.42, "e": 865.84, "en": "Hey! Hey!", "ko": "이봐요! 이봐요!", "it": false}, {"s": 865.924, "e": 866.616, "en": "What's happening?", "ko": "무슨 일이야?", "it": true}, {"s": 866.7, "e": 869.51, "en": "No! You gotta have\na reason!", "ko": "안 돼요! 이유가 있어야죠!", "it": false}, {"s": 869.594, "e": 873.514, "en": "- Just tell us why!\n- Mom, they're hurting him.", "ko": "-이유라도 말해 줘요!\n-엄마, 쟤를 때리고 있어", "it": false}, {"s": 873.598, "e": 875.774, "en": "You can't just break\nin our home!", "ko": "남의 집에\n함부로 쳐들어오면 어떡해요!", "it": false}, {"s": 875.858, "e": 877.627, "en": "You get your hands off\nmy boy.", "ko": "내 아들한테서\n손 떼!", "it": false}, {"s": 877.711, "e": 880.021, "en": "- You gotta have a reason!\n- Mom, where are they taking him?", "ko": "-이유가 있어야죠!\n-엄마, 쟤를 어디로 데려가?", "it": false}, {"s": 880.105, "e": 881.446, "en": "Get off him!", "ko": "놔!", "it": false}, {"s": 881.53, "e": 884.303, "en": "Let's go. Get in the truck.\nWe'll follow them!", "ko": "가자, 트럭에 타\n따라가야 해!", "it": false}, {"s": 889.205, "e": 891.06, "en": "Come on, come on!\nGet in, get in!", "ko": "어서, 어서!\n타, 타!", "it": false}, {"s": 909.242, "e": 911.914, "en": "Oh, my god! Harry!", "ko": "세상에! 해리!", "it": false}, {"s": 917.475, "e": 919.06, "en": "You get your hands off me!\nDon't touch me!", "ko": "손 치워요!\n건드리지 마요!", "it": false}, {"s": 922.647, "e": 923.818, "en": "Get off me!", "ko": "놔요!", "it": true}, {"s": 924.315, "e": 925.594, "en": "Is this him?", "ko": "이 녀석입니까?", "it": false}, {"s": 932.748, "e": 934.408, "en": "That's him all right.\nThat's the thief.", "ko": "틀림없소\n저놈이 도둑이오", "it": false}, {"s": 934.492, "e": 936.335, "en": "I ain't no thief. I didn't\nsteal nothing.", "ko": "난 도둑 아니에요\n아무것도 안 훔쳤어요", "it": false}, {"s": 936.419, "e": 939.021, "en": "You shut your month.\nNot another word.", "ko": "입 닥쳐\n한마디도 하지 마", "it": false}, {"s": 939.105, "e": 941.84, "en": "Our Harry,\nhe is no thief.", "ko": "우리 해리는\n도둑이 아니에요", "it": false}, {"s": 941.924, "e": 943.342, "en": "Then how do you explain\nthis spiffy little piece", "ko": "그럼 저 녀석 손목에\n찬 근사한 물건은", "it": false}, {"s": 943.426, "e": 945.114, "en": "On his wrist then?", "ko": "어떻게 설명할 거지?", "it": false}, {"s": 946.095, "e": 947.771, "en": "Mrs. Foxworth,\nyou know our Harry", "ko": "마님, 우리 해리를\n아시잖아요", "it": false}, {"s": 947.855, "e": 950.349, "en": "Would never steal\nfrom anyone.", "ko": "남의 물건을 훔칠\n애가 아니에요", "it": false}, {"s": 950.433, "e": 953.11, "en": "She can speak\nto his character.", "ko": "마님이 이 애가 어떤 앤지\n말해 주실 거예요", "it": false}, {"s": 953.194, "e": 954.537, "en": "Please.", "ko": "제발요", "it": false}, {"s": 954.621, "e": 956.188, "en": "I don't think we know this boy\nwell enough", "ko": "우리는 이 아이를\n그렇게 잘 알지 못해서", "it": false}, {"s": 956.272, "e": 957.615, "en": "To speak to his character.", "ko": "어떤 아이인지\n말할 수가 없네요", "it": false}, {"s": 957.699, "e": 958.541, "en": "Oh, come on!", "ko": "이러지 마세요!", "it": false}, {"s": 958.625, "e": 959.542, "en": "Samuel don't!", "ko": "새뮤얼, 안 돼!", "it": false}, {"s": 959.626, "e": 962.131, "en": "Mrs. Foxworth, please!", "ko": "마님, 제발요!", "it": false}, {"s": 966.466, "e": 968.442, "en": "I didn't do anything!", "ko": "난 아무것도 안 했어요!", "it": false}, {"s": 968.526, "e": 969.443, "en": "Harry, stop moving.", "ko": "해리, 가만있어", "it": false}, {"s": 969.527, "e": 970.294, "en": "No, no, no!", "ko": "안 돼, 안 돼, 안 돼!", "it": false}, {"s": 971.137, "e": 972.889, "en": "No!!!", "ko": "안 돼!!!", "it": false}, {"s": 972.973, "e": 976.392, "en": "No, Harry! Please no!", "ko": "안 돼, 해리! 제발!", "it": false}, {"s": 979.22, "e": 981.15, "en": "Harry!", "ko": "해리!", "it": false}, {"s": 986.377, "e": 987.548, "en": "Get inside.", "ko": "들어가", "it": true}, {"s": 991.64, "e": 993.162, "en": "Well done.", "ko": "잘했소", "it": false}, {"s": 1014.255, "e": 1016.602, "en": "Let's go, let's go.\nLet's go.", "ko": "가자, 가자\n어서 가", "it": false}, {"s": 1031.031, "e": 1034.692, "en": "Does anyone want to tell me\nwhat really happened last night?", "ko": "어젯밤에 무슨 일이 있었는지\n누가 말 좀 해 줄래요?", "it": false}, {"s": 1034.776, "e": 1036.455, "en": "Drop it, corrine.", "ko": "그만해, 코린", "it": false}, {"s": 1037.945, "e": 1039.708, "en": "I hate it here.", "ko": "여기 정말 싫어", "it": false}, {"s": 1042.191, "e": 1045.964, "en": "Mr. And Mrs. Foxworth.\nYour guest has arrived.", "ko": "주인님, 마님\n손님이 도착하셨습니다", "it": false}, {"s": 1055.947, "e": 1057.559, "en": "Christopher.", "ko": "크리스토퍼", "it": false}, {"s": 1063.212, "e": 1066.874, "en": "Welcome back to foxworth hall.", "ko": "폭스워스 저택에\n다시 온 걸 환영한다", "it": false}, {"s": 1066.958, "e": 1071.406, "en": "Corrine, Joel, I'd like you\nto meet your uncle Christopher.", "ko": "코린, 조엘, 인사하렴\n너희 삼촌 크리스토퍼야", "it": false}, {"s": 1075.8, "e": 1080.332, "en": "Pleasure to finally meet you,\nuncle Christopher.", "ko": "드디어 뵙네요,\n크리스토퍼 삼촌", "it": false}, {"s": 1082.64, "e": 1084.408, "en": "Uh, yes.", "ko": "아, 네", "it": false}, {"s": 1084.492, "e": 1086.088, "en": "Pleasure.", "ko": "반가워요", "it": false}, {"s": 1100.158, "e": 1103.26, "en": "Christopher, we're delighted\nto have you here.", "ko": "크리스토퍼, 이렇게 와 줘서\n정말 기뻐", "it": false}, {"s": 1103.344, "e": 1105.274, "en": "Isn't that right?", "ko": "그렇지?", "it": false}, {"s": 1106.664, "e": 1108.277, "en": "Yes. Right.", "ko": "네, 그럼요", "it": false}, {"s": 1112.094, "e": 1115.031, "en": "Please excuse Joel's silence.", "ko": "조엘이 말이 없어도\n이해해 주렴", "it": false}, {"s": 1115.115, "e": 1117.682, "en": "He often plays the piano\ntoo late into the night", "ko": "밤늦게까지\n피아노를 치느라", "it": false}, {"s": 1117.766, "e": 1118.759, "en": "And tires himself.", "ko": "피곤해서 그래", "it": false}, {"s": 1118.843, "e": 1121.428, "en": "He's a very dedicated musician.", "ko": "아주 열정적인 음악가란다", "it": false}, {"s": 1121.512, "e": 1123.43, "en": "Piano.", "ko": "피아노라", "it": false}, {"s": 1123.514, "e": 1125.099, "en": "Something I've always wanted\nto learn.", "ko": "저도 늘 배우고\n싶었던 건데요", "it": false}, {"s": 1125.183, "e": 1129.361, "en": "Actually, you already know how.\nOr you did.", "ko": "사실 넌 칠 줄 알아\n적어도 예전엔 그랬지", "it": false}, {"s": 1129.445, "e": 1133.791, "en": "I taught you along with both\nof the boys ages ago.", "ko": "오래전에 우리 아이들이랑\n같이 가르쳤거든", "it": false}, {"s": 1133.875, "e": 1135.776, "en": "Well now...", "ko": "저런...", "it": false}, {"s": 1135.86, "e": 1138.22, "en": "So Joel, tell me.\nIs it like muscle memory?", "ko": "그럼 조엘, 하나만 물어볼게요\n몸이 기억하는 건가요?", "it": false}, {"s": 1138.304, "e": 1139.463, "en": "Will I immediately\nbecome Beethoven", "ko": "건반에 손가락만 다시 올리면", "it": false}, {"s": 1139.547, "e": 1142.391, "en": "If I just return my fingers\nto the keys?", "ko": "당장 베토벤이\n될 수 있을까요?", "it": false}, {"s": 1142.475, "e": 1144.479, "en": "Piano's not a bicycle.", "ko": "피아노는 자전거가 아니에요", "it": false}, {"s": 1149.056, "e": 1150.307, "en": "I'm so grateful", "ko": "여기서 지내게\n해 주셔서", "it": false}, {"s": 1150.391, "e": 1152.626, "en": "That you're allowing me\nto stay here with you.", "ko": "정말 감사드려요", "it": false}, {"s": 1152.71, "e": 1154.478, "en": "Your charity in providing me\na home,", "ko": "이렇게 제게 집을\n내주시는 자비를 베풀어 주셔서", "it": false}, {"s": 1154.562, "e": 1157.147, "en": "I can't thank you enough.", "ko": "뭐라 감사해야 할지 모르겠어요", "it": false}, {"s": 1157.231, "e": 1159.742, "en": "Is that what you think this is?", "ko": "이걸 그렇게 생각하나?", "it": false}, {"s": 1159.826, "e": 1161.302, "en": "Charity?", "ko": "자비라고?", "it": false}, {"s": 1161.386, "e": 1162.578, "en": "Malcolm.", "ko": "맬컴", "it": false}, {"s": 1162.662, "e": 1164.396, "en": "Of course not.", "ko": "물론 아닙니다", "it": false}, {"s": 1164.48, "e": 1167.732, "en": "I hope you are prepared to work\nin exchange for your tuition.", "ko": "학비 대신 일할\n각오는 돼 있겠지", "it": false}, {"s": 1167.816, "e": 1169.919, "en": "That is the arrangement\nas I've understood it.", "ko": "그렇게 하기로 한 걸로\n알고 있습니다", "it": false}, {"s": 1170.003, "e": 1171.495, "en": "And I am more than happy\nto serve your office", "ko": "사무실 일이라면\n뭐든 기꺼이", "it": false}, {"s": 1171.579, "e": 1172.904, "en": "In any way it requires.", "ko": "돕겠습니다", "it": false}, {"s": 1172.988, "e": 1174.498, "en": "You will not be working\nin the office.", "ko": "넌 사무실에서\n일하지 않는다", "it": false}, {"s": 1174.582, "e": 1179.014, "en": "You will be helping out with the\nyard-work here at foxworth hall.", "ko": "폭스워스 저택\n마당 일을 돕게 될 거다", "it": false}, {"s": 1179.995, "e": 1182.656, "en": "I'd be happy to, sir.", "ko": "기꺼이 하겠습니다", "it": false}, {"s": 1182.74, "e": 1185.342, "en": "Daddy, surely you can't\nexpect him to work", "ko": "아빠, 설마\n삼촌한테 넬라네 가족이랑", "it": false}, {"s": 1185.426, "e": 1188.345, "en": "Alongside nella's family\nand the rest of the servants.", "ko": "다른 하인들 틈에서\n일하라는 건 아니죠?", "it": false}, {"s": 1188.429, "e": 1190.439, "en": "What's wrong with him working\nalongside nella's family?", "ko": "넬라네 가족이랑 같이\n일하는 게 뭐가 어때서?", "it": false}, {"s": 1190.523, "e": 1191.923, "en": "Joel.", "ko": "조엘", "it": false}, {"s": 1192.007, "e": 1194.259, "en": "You know mother?\nYou were right...", "ko": "어머니, 그거 아세요?\n어머니 말이 맞아요...", "it": false}, {"s": 1194.343, "e": 1196.112, "en": "I didn't get much rest\nlast night.", "ko": "어젯밤에\n잠을 제대로 못 잤어요", "it": false}, {"s": 1196.196, "e": 1197.824, "en": "Excuse me.", "ko": "실례할게요", "it": false}, {"s": 1199.699, "e": 1201.203, "en": "It's for the best.", "ko": "그게 다\n잘된 일이야", "it": false}, {"s": 1202.535, "e": 1204.206, "en": "I'm late for work.", "ko": "출근이 늦었군", "it": false}, {"s": 1207.707, "e": 1211.171, "en": "Corrine darling, why don't you\nshow your uncle to his room?", "ko": "코린, 삼촌한테\n방 좀 안내해 드리렴", "it": false}, {"s": 1214.38, "e": 1217.374, "en": "I, um, haven't quite finished\nmy breakfast yet.", "ko": "저, 아직 아침을\n다 못 먹어서요", "it": false}, {"s": 1217.458, "e": 1219.526, "en": "I can surely find it myself.", "ko": "혼자서도\n찾아갈 수 있어요", "it": false}, {"s": 1219.61, "e": 1221.556, "en": "Come. I'll show you.", "ko": "가자, 내가 안내하마", "it": false}, {"s": 1254.587, "e": 1256.821, "en": "Taylard residence.\nRockford speaking.", "ko": "테일러드가입니다\n록퍼드예요", "it": false}, {"s": 1256.905, "e": 1261.068, "en": "Rock? It's corrine. Foxworth.", "ko": "록? 나 코린이야, 폭스워스", "it": false}, {"s": 1261.152, "e": 1264.18, "en": "And to what do I owe\nthe pleasure?", "ko": "이게 웬일이야?", "it": false}, {"s": 1264.264, "e": 1269.0, "en": "How do you feel about\nsneaking out this afternoon?", "ko": "오늘 오후에\n몰래 빠져나올래?", "it": false}, {"s": 1269.084, "e": 1272.671, "en": "I must say I did not expect this\nhouse to be quite what it is,", "ko": "솔직히 이 집이 이런 곳일 줄은\n몰랐어요", "it": false}, {"s": 1272.755, "e": 1274.581, "en": "Or for you to be\nwho you are.", "ko": "부인이 이런 분일 줄도요", "it": false}, {"s": 1274.665, "e": 1276.266, "en": "Oh?", "ko": "그래?", "it": false}, {"s": 1276.35, "e": 1279.862, "en": "Did your mother tell you\nvery much about her time here?", "ko": "어머니가 여기서 지낸 얘기를\n많이 해 주셨니?", "it": false}, {"s": 1279.946, "e": 1283.424, "en": "Almost nothing at all.", "ko": "거의 아무것도요", "it": false}, {"s": 1283.508, "e": 1285.609, "en": "Is the piano the only instrument\nI can play?", "ko": "제가 칠 줄 아는 악기가\n피아노뿐이에요?", "it": false}, {"s": 1293.518, "e": 1294.859, "en": "I can't believe you're\nallowing this.", "ko": "이걸 그냥 두고\n보신다니 믿을 수가 없어요", "it": false}, {"s": 1294.943, "e": 1296.378, "en": "This isn't the place.", "ko": "여기서 할 얘기가 아니야", "it": false}, {"s": 1296.462, "e": 1298.772, "en": "You have to know what the police\nwould do to a black man", "ko": "경찰이 흑인 남자를\n어떻게 하는지 아시잖아요", "it": false}, {"s": 1298.856, "e": 1301.442, "en": "They think stole from\na white man like father.", "ko": "아버지 같은 백인 물건을\n훔쳤다고 생각하면요", "it": false}, {"s": 1301.526, "e": 1302.534, "en": "Keep your voice down.", "ko": "목소리 낮춰", "it": false}, {"s": 1302.618, "e": 1305.295, "en": "How can I when Harry\ncould be dead?", "ko": "해리가 죽었을지도 모르는데\n어떻게 그래요?", "it": false}, {"s": 1305.379, "e": 1308.282, "en": "You saw what they did to him in\nfull view on our own front lawn.", "ko": "우리 집 앞마당에서 그 애한테\n무슨 짓을 했는지 다 보셨잖아요", "it": false}, {"s": 1308.366, "e": 1312.711, "en": "Just imagine what they're doing\nto him in jail.", "ko": "감옥에선 무슨 짓을 하고 있을지\n생각해 보세요", "it": false}, {"s": 1312.795, "e": 1315.714, "en": "We have to do something.", "ko": "뭐라도 해야 해요", "it": false}, {"s": 1315.798, "e": 1318.901, "en": "This wasn't Harry's fault.", "ko": "해리 잘못이 아니에요", "it": false}, {"s": 1318.985, "e": 1323.48, "en": "It's something we came to\ntogether, willingly.", "ko": "우리가 서로 원해서\n함께한 거예요", "it": false}, {"s": 1323.564, "e": 1325.327, "en": "It's what we both want.", "ko": "우리 둘 다 원하는 거라고요", "it": false}, {"s": 1329.162, "e": 1330.832, "en": "Where are you?", "ko": "어머니는 어느 편이세요?", "it": false}, {"s": 1333.891, "e": 1337.569, "en": "Someone you love\nis pleading with you", "ko": "어머니가 사랑하는 사람이", "it": false}, {"s": 1337.653, "e": 1341.906, "en": "That someone they love\nis hurting.", "ko": "자기가 사랑하는 사람이\n다치고 있다고 애원하는데", "it": false}, {"s": 1341.99, "e": 1344.485, "en": "You won't do anything.", "ko": "아무것도 안 하시잖아요", "it": false}, {"s": 1344.569, "e": 1345.972, "en": "Love?", "ko": "사랑?", "it": false}, {"s": 1348.739, "e": 1351.686, "en": "This isn't up to me.\nIt's up to your father.", "ko": "이건 내가 정할 일이 아니야\n네 아버지가 정할 일이야", "it": false}, {"s": 1356.414, "e": 1358.86, "en": "This is fine.\nDon't go any further.", "ko": "여기면 돼\n더 가지 마", "it": false}, {"s": 1360.418, "e": 1362.594, "en": "Thanks for giving me a way\nout of the house.", "ko": "집에서 빼내 줘서 고마워", "it": false}, {"s": 1362.678, "e": 1365.114, "en": "That was the most exciting\nafternoon I've had in weeks.", "ko": "몇 주 만에 제일\n신나는 오후였어", "it": false}, {"s": 1365.198, "e": 1366.431, "en": "Yeah. Yep.", "ko": "그래, 그렇지", "it": false}, {"s": 1366.515, "e": 1368.617, "en": "Movies always make me\nfeel better,", "ko": "영화 보면 항상\n기분이 좋아지는데", "it": false}, {"s": 1368.701, "e": 1372.195, "en": "Except when you make me wait\nthrough the whole thing.", "ko": "네가 영화 끝날 때까지\n애태우게 하면 얘기가 다르지", "it": false}, {"s": 1372.279, "e": 1377.626, "en": "I guess first year of business\nschool doesn't teach Patience.", "ko": "경영학교 1학년엔\n인내심은 안 가르치나 봐", "it": false}, {"s": 1377.71, "e": 1379.87, "en": "Patience, no.", "ko": "인내심은 안 가르쳐", "it": false}, {"s": 1379.954, "e": 1382.372, "en": "Persistence, yes.", "ko": "끈기는 가르치고", "it": false}, {"s": 1382.456, "e": 1387.861, "en": "I really do have to go.\nI've been away for too long.", "ko": "나 진짜 가야 해\n너무 오래 나와 있었어", "it": false}, {"s": 1387.945, "e": 1390.806, "en": "I'm real glad you called me\nup, corrine.", "ko": "전화해 줘서\n정말 좋았어, 코린", "it": false}, {"s": 1390.89, "e": 1392.727, "en": "See you soon.", "ko": "또 봐", "it": false}, {"s": 1409.15, "e": 1411.309, "en": "Corrine.\nWhat you doing?", "ko": "코린\n뭐 하는 거야?", "it": false}, {"s": 1411.393, "e": 1415.722, "en": "Shh! It is none\nof your business.", "ko": "쉿! 삼촌이\n상관할 일 아니에요", "it": false}, {"s": 1415.806, "e": 1417.315, "en": "But will you please,\nplease don't mention", "ko": "그런데 제발, 제발", "it": false}, {"s": 1417.399, "e": 1419.379, "en": "That you saw me to either\nof my parents.", "ko": "저 봤다는 거\n엄마 아빠한테 말하지 말아 주세요", "it": false}, {"s": 1421.421, "e": 1423.172, "en": "As long as you tell me\nwhere you were.", "ko": "어디 갔었는지\n말해 주면", "it": false}, {"s": 1423.256, "e": 1424.427, "en": "Why do you care?", "ko": "삼촌이 왜 신경 써요?", "it": false}, {"s": 1426.317, "e": 1428.263, "en": "Just concerned\nfor my niece.", "ko": "그냥 조카가 걱정돼서", "it": false}, {"s": 1431.989, "e": 1434.257, "en": "So, my father has you\nworking already?", "ko": "아빠가 벌써\n일을 시키셨네요?", "it": false}, {"s": 1434.341, "e": 1436.668, "en": "Who am I to reject the call\nof my new vocation?", "ko": "새로운 천직의 부름을\n내가 어떻게 거절하겠어", "it": false}, {"s": 1436.752, "e": 1438.336, "en": "It does look as though\nyou'll be needing", "ko": "아무래도 재봉사한테", "it": false}, {"s": 1438.42, "e": 1440.247, "en": "To pay another visit\nto the seamstress.", "ko": "한 번 더 가야\n할 것 같은데요", "it": false}, {"s": 1441.682, "e": 1443.692, "en": "Hey. Careful who you're\nlaughing at.", "ko": "이봐, 누굴 보고\n웃는지 조심해", "it": false}, {"s": 1443.776, "e": 1445.602, "en": "See, I was just about\nto tell you", "ko": "사실 막\n말해 주려던 참이었거든", "it": false}, {"s": 1445.686, "e": 1447.029, "en": "That your father's still\nat the office", "ko": "네 아버지는\n아직 사무실에 계시고", "it": false}, {"s": 1447.113, "e": 1450.032, "en": "And your mother is getting\nher dress fitted.", "ko": "어머니는 드레스\n가봉하는 중이라고", "it": false}, {"s": 1450.116, "e": 1451.85, "en": "So, if you're looking\nfor a way to sneak in", "ko": "그러니까 몰래 들어갈\n길을 찾는 거라면", "it": false}, {"s": 1451.934, "e": 1455.095, "en": "You might try through\nthe kitchen.", "ko": "부엌 쪽으로 가 보라고", "it": false}, {"s": 1455.179, "e": 1457.948, "en": "But now maybe I won't\ntell you that.", "ko": "그런데 이제 말해 주지\n말까 봐", "it": false}, {"s": 1458.032, "e": 1459.419, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 1466.524, "e": 1468.867, "en": "May I ask who this\nis regarding?", "ko": "무슨 일로 그러시는지\n여쭤봐도 될까요?", "it": false}, {"s": 1468.951, "e": 1471.306, "en": "Not if you want to keep\nyour practice.", "ko": "병원 문 닫고 싶지\n않으면 묻지 마시오", "it": false}, {"s": 1474.307, "e": 1479.814, "en": "And Curtis, make it the most\neffective treatment available.", "ko": "그리고 커티스, 가장 효과가\n확실한 치료로 해 주시오", "it": false}, {"s": 1509.066, "e": 1511.485, "en": "Are you going to do\nsomething about Harry?", "ko": "해리 일은\n어떻게 하실 거예요?", "it": true}, {"s": 1511.569, "e": 1512.928, "en": "We are.", "ko": "할 거다", "it": false}, {"s": 1513.012, "e": 1514.307, "en": "Good.", "ko": "다행이네요", "it": false}, {"s": 1515.33, "e": 1516.598, "en": "I'll come with you\nto the station", "ko": "저도 경찰서에\n같이 갈게요", "it": false}, {"s": 1516.682, "e": 1519.25, "en": "And you can drop the charges\nagainst him immediately.", "ko": "해리 고소는 지금 당장\n취하하시면 돼요", "it": false}, {"s": 1519.334, "e": 1521.178, "en": "You will be leaving\nto spend some time", "ko": "넌 웨스트모어랜드에 있는", "it": false}, {"s": 1521.262, "e": 1524.94, "en": "At a professional facility\nin west more land.", "ko": "전문 시설에 가서\n한동안 지내게 될 거다", "it": false}, {"s": 1525.024, "e": 1529.778, "en": "Now you will say nothing\nto your sister about this.", "ko": "이 일은 동생한테\n한마디도 하지 마라", "it": false}, {"s": 1529.862, "e": 1535.099, "en": "You will pack one bag and I will\ntake you tonight after dark", "ko": "가방 하나만 싸라\n오늘 밤 어두워지면 데려가마", "it": false}, {"s": 1535.183, "e": 1537.694, "en": "So nobody sees us.", "ko": "아무도 못 보게", "it": false}, {"s": 1537.778, "e": 1543.867, "en": "Now the professionals there\nwill... Get it out of you.", "ko": "거기 전문가들이\n그걸... 빼내 줄 거다", "it": false}, {"s": 1543.951, "e": 1548.964, "en": "And you will recover.\nAnd then you will return.", "ko": "그러면 넌 나아질 거고\n그다음에 돌아오는 거다", "it": false}, {"s": 1549.048, "e": 1555.787, "en": "And we will never speak\nof this again.", "ko": "그리고 다시는 이 얘기\n꺼내지 않을 거다", "it": false}, {"s": 1555.871, "e": 1557.288, "en": "What if I don't want to go?", "ko": "안 가겠다면요?", "it": false}, {"s": 1557.372, "e": 1559.975, "en": "That is not your decision\nto make.", "ko": "그건 네가 정할 일이 아니야", "it": false}, {"s": 1560.059, "e": 1561.23, "en": "It's my life.", "ko": "제 인생이에요", "it": false}, {"s": 1562.562, "e": 1564.566, "en": "It is my name.", "ko": "내 이름이다", "it": false}, {"s": 1567.567, "e": 1569.07, "en": "And you're on board\nwith this?", "ko": "어머니도\n이게 괜찮으세요?", "it": false}, {"s": 1572.22, "e": 1574.151, "en": "When are you going to tell me\nwhat you want?!", "ko": "어머니 생각은\n대체 언제 말해 주실 거예요?!", "it": false}, {"s": 1576.967, "e": 1578.705, "en": "I am aligned\nwith your father.", "ko": "난 아버지와\n같은 생각이야", "it": false}, {"s": 1584.992, "e": 1588.047, "en": "I'll go if you drop the charges\nagainst Harry.", "ko": "해리 고소를 취하해 주시면\n갈게요", "it": false}, {"s": 1609.442, "e": 1612.01, "en": "I know your father's plan\nseems extreme.", "ko": "아버지 계획이\n극단적으로 보이는 건 알아", "it": false}, {"s": 1612.094, "e": 1614.437, "en": "Your plan.\nIt's your plan too.", "ko": "어머니 계획이기도 하잖아요", "it": false}, {"s": 1614.521, "e": 1617.366, "en": "You agreed to it.", "ko": "어머니도 동의하셨잖아요", "it": false}, {"s": 1617.45, "e": 1620.594, "en": "If you go get it fixed then\nyour father wouldn't hurt you.", "ko": "그걸 고치면\n아버지도 널 해치지 않으실 거야", "it": false}, {"s": 1620.678, "e": 1622.29, "en": "It's a little late for that.", "ko": "그러기엔 좀 늦었네요", "it": false}, {"s": 1623.364, "e": 1625.96, "en": "Thank you for doing this.", "ko": "이렇게 해 줘서 고마워", "it": false}, {"s": 1627.685, "e": 1629.631, "en": "I'm not doing this for you.", "ko": "어머니를 위해서\n하는 거 아니에요", "it": false}, {"s": 1636.785, "e": 1639.599, "en": "The least you could do is\ngive this to Harry for me.", "ko": "최소한 이건\n해리한테 전해 주세요", "it": false}, {"s": 1654.228, "e": 1656.658, "en": "- I was just heading...\n- Getting a glass of water.", "ko": "-그냥 가던 길이었는데...\n-물 마시러요", "it": false}, {"s": 1658.732, "e": 1664.971, "en": "Because it's just so... Hot.", "ko": "날이 너무... 더워서요", "it": false}, {"s": 1665.055, "e": 1667.749, "en": "Yes, it is.", "ko": "그러네", "it": false}, {"s": 1667.833, "e": 1671.172, "en": "Exceptionally hot.", "ko": "유난히 덥네", "it": false}, {"s": 1675.824, "e": 1678.179, "en": "Well um... Goodnight.", "ko": "그럼... 잘 자요", "it": false}, {"s": 1682.831, "e": 1685.019, "en": "- That's not my room.\n- That's my room.", "ko": "-여긴 내 방이 아니네\n-거긴 제 방이에요", "it": false}, {"s": 1687.669, "e": 1691.498, "en": "I will just go to\nmy actual room.", "ko": "진짜 내 방으로\n가야겠다", "it": false}, {"s": 1691.582, "e": 1696.445, "en": "Which is apparently\nright next door to yours.", "ko": "네 방 바로 옆인가 보네", "it": false}, {"s": 1700.107, "e": 1701.278, "en": "Goodnight.", "ko": "잘 자", "it": false}, {"s": 1839.229, "e": 1841.423, "en": "How did you sleep last night?", "ko": "어젯밤엔 잘 잤어?", "it": false}, {"s": 1841.507, "e": 1843.592, "en": "- I was a bit restless.\n- Not well at all.", "ko": "-좀 뒤척였어요\n-전혀 못 잤어요", "it": false}, {"s": 1843.676, "e": 1846.428, "en": "Of course. Sorry.", "ko": "그렇구나, 미안", "it": false}, {"s": 1846.512, "e": 1849.155, "en": "No, it's okay.", "ko": "아니에요, 괜찮아요", "it": false}, {"s": 1849.239, "e": 1853.435, "en": "I slept just fine.\nThank you for asking.", "ko": "전 잘 잤어요\n물어봐 주셔서 고마워요", "it": false}, {"s": 1853.519, "e": 1854.77, "en": "Where's Joel?", "ko": "조엘 오빠는요?", "it": false}, {"s": 1854.854, "e": 1856.438, "en": "He left for Montreal.", "ko": "몬트리올로 떠났어", "it": false}, {"s": 1856.522, "e": 1857.693, "en": "What?", "ko": "네?", "it": false}, {"s": 1858.582, "e": 1859.861, "en": "Montreal?", "ko": "몬트리올이요?", "it": false}, {"s": 1861.251, "e": 1863.67, "en": "He received a telegram yesterday", "ko": "어제 전보가 왔는데", "it": false}, {"s": 1863.754, "e": 1866.114, "en": "Inviting him to study\nwith a top musician there,", "ko": "거기 유명한 음악가 밑에서\n공부하라고 초대했대", "it": false}, {"s": 1866.198, "e": 1870.343, "en": "But he had to leave right away\nin order to accept.", "ko": "수락하려면 바로\n떠나야 했어", "it": false}, {"s": 1870.427, "e": 1872.862, "en": "This is ridiculous.\nWhy wouldn't he tell me?", "ko": "말도 안 돼요\n왜 나한테 말을 안 해요?", "it": false}, {"s": 1872.946, "e": 1875.198, "en": "Who's the musician?", "ko": "그 음악가가 누군데요?", "it": false}, {"s": 1875.282, "e": 1877.35, "en": "A composer at the philharmonic\nthere.", "ko": "거기 교향악단\n작곡가래", "it": false}, {"s": 1877.434, "e": 1880.128, "en": "He was really very torn\nabout it.", "ko": "그 애도 정말\n많이 고민했어", "it": false}, {"s": 1880.212, "e": 1882.705, "en": "He didn't want to upset you that\nhe'd be gone for the summer.", "ko": "여름 내내 떠나 있게 돼서\n네가 속상할까 봐", "it": false}, {"s": 1882.789, "e": 1886.026, "en": "He's not going to be back\nin time for my ball?", "ko": "그럼 무도회 때까지\n못 돌아온다는 거예요?", "it": false}, {"s": 1886.11, "e": 1887.803, "en": "But he was supposed to be\nmy first dance.", "ko": "첫 춤은 오빠랑 추기로\n했는데", "it": false}, {"s": 1887.887, "e": 1893.308, "en": "Your ball will be just as good\nwithout him.", "ko": "조엘이 없어도 무도회는\n충분히 근사할 거야", "it": false}, {"s": 1893.392, "e": 1894.854, "en": "Maybe better.", "ko": "더 근사할지도 모르지", "it": false}, {"s": 1931.597, "e": 1933.601, "en": "Miss foxworth.", "ko": "폭스워스 아가씨", "it": false}, {"s": 1937.603, "e": 1940.004, "en": "Corrine, please.", "ko": "그냥 코린이라고 불러 줘", "it": false}, {"s": 1940.088, "e": 1942.068, "en": "Glad to see you're home.", "ko": "돌아왔다니 다행이에요", "it": false}, {"s": 1945.611, "e": 1948.741, "en": "I stopped reading when I\nrealized what they were.", "ko": "무슨 편지인지 알고 나서\n읽기를 멈췄어요", "it": false}, {"s": 1951.675, "e": 1953.621, "en": "Oh, it's all right.", "ko": "아, 괜찮아", "it": false}, {"s": 1962.035, "e": 1964.862, "en": "I know you must be hurting.", "ko": "많이 힘들지?", "it": false}, {"s": 1964.946, "e": 1967.531, "en": "I just want to know\nwhere he is.", "ko": "오빠가 어디 있는지\n알고 싶을 뿐이야", "it": false}, {"s": 1967.615, "e": 1969.804, "en": "Did he tell you?", "ko": "오빠가 말 안 해 줬어?", "it": false}, {"s": 1993.808, "e": 1999.822, "en": "What do you know about a place\ncalled west more land sanitarium?", "ko": "웨스트모어랜드 요양원이라는 데\n혹시 알아요?", "it": false}, {"s": 1999.906, "e": 2003.234, "en": "Some physicians call\nwest more land experimental,", "ko": "어떤 의사들은\n웨스트모어랜드를 실험적이라고 하는데", "it": false}, {"s": 2003.318, "e": 2008.423, "en": "But experimental is too kind\nof a word for a place like that.", "ko": "그런 곳엔 실험적이라는 말도\n너무 점잖은 표현이야", "it": false}, {"s": 2008.507, "e": 2010.511, "en": "What's happened?", "ko": "무슨 일이야?", "it": false}, {"s": 2012.16, "e": 2014.015, "en": "Over here, if you would be\nso kind.", "ko": "이쪽으로\n좀 와 주시겠어요?", "it": false}, {"s": 2015.848, "e": 2017.076, "en": "Mrs. Foxworth.", "ko": "폭스워스 부인", "it": false}, {"s": 2017.85, "e": 2020.268, "en": "Do you have a moment?\nWe need to speak to you.", "ko": "잠깐 시간 되세요?\n드릴 말씀이 있어요", "it": false}, {"s": 2020.352, "e": 2021.344, "en": "It's important.", "ko": "중요한 일이에요", "it": false}, {"s": 2021.428, "e": 2023.357, "en": "I know about Joel and Harry.", "ko": "조엘 오빠랑 해리 일 알아요", "it": false}, {"s": 2024.672, "e": 2026.027, "en": "You may leave.", "ko": "가 봐요", "it": false}, {"s": 2033.681, "e": 2036.025, "en": "Just what are you\nboth imagining?", "ko": "둘이 대체 무슨 상상을\n하는 거야?", "it": false}, {"s": 2036.109, "e": 2038.511, "en": "Forget imagination.", "ko": "상상이 아니에요", "it": false}, {"s": 2038.595, "e": 2040.68, "en": "Any serious professional\nwill tell you", "ko": "제대로 된 전문가라면\n누구나 말할 거예요", "it": false}, {"s": 2040.764, "e": 2044.534, "en": "That westmoreland's methods\nare extreme and unverified.", "ko": "웨스트모어랜드의 방식은\n극단적이고 검증도 안 됐다고요", "it": false}, {"s": 2044.618, "e": 2046.869, "en": "They have consequences.", "ko": "부작용도 있어요", "it": false}, {"s": 2046.953, "e": 2049.613, "en": "The approach they're known\nfor uses shocks of electricity", "ko": "거기선 환자 뇌에\n전기 충격을 주는 걸로 유명해요", "it": false}, {"s": 2049.697, "e": 2053.042, "en": "In patients' brains for every\ncondition you can imagine,", "ko": "상상할 수 있는\n온갖 증상에 다요", "it": false}, {"s": 2053.126, "e": 2057.138, "en": "From nervousness to venereal\ndisease to homo...", "ko": "신경과민부터 성병,\n그리고 동성...", "it": false}, {"s": 2057.222, "e": 2058.893, "en": "Homosexuality.", "ko": "동성애까지요", "it": false}, {"s": 2060.801, "e": 2062.563, "en": "But it doesn't work.", "ko": "하지만 효과는 없어요", "it": false}, {"s": 2066.565, "e": 2068.069, "en": "Mother, please.", "ko": "엄마, 제발요", "it": false}, {"s": 2070.569, "e": 2072.406, "en": "Joel needs you.", "ko": "조엘 오빠한텐\n엄마가 필요해요", "it": false}, {"s": 2083.974, "e": 2085.225, "en": "I might have been\nmourning mal", "ko": "나는 말을\n애도하고 있었는지 몰라도", "it": true}, {"s": 2085.309, "e": 2087.393, "en": "But I had closed the door\non my Joel", "ko": "조엘에게는\n문을 닫아 버렸다", "it": true}, {"s": 2087.477, "e": 2089.337, "en": "Because I couldn't face\nwhat was inside.", "ko": "그 안에 있는 걸\n마주할 수가 없어서", "it": true}, {"s": 2089.421, "e": 2092.415, "en": "But it was seeing him there,\nwhat was left of him,", "ko": "하지만 그곳에서 그 애를,\n그 애의 남은 모습을 보았을 때", "it": true}, {"s": 2092.499, "e": 2094.567, "en": "I remembered who I was.", "ko": "나는 내가 누구인지 기억해 냈다", "it": true}, {"s": 2097.429, "e": 2099.058, "en": "His provider.", "ko": "그 애를 먹여 살리는 사람", "it": true}, {"s": 2102.509, "e": 2104.105, "en": "His protector.", "ko": "그 애를 지키는 사람", "it": true}, {"s": 2104.995, "e": 2106.003, "en": "Ma'am?", "ko": "부인?", "it": false}, {"s": 2106.087, "e": 2107.004, "en": "His parent.", "ko": "그 애의 부모", "it": true}, {"s": 2107.088, "e": 2108.581, "en": "What are you doing?", "ko": "뭐 하시는 겁니까?", "it": false}, {"s": 2108.665, "e": 2110.841, "en": "Getting my son\nout of this place.", "ko": "내 아들을\n여기서 데려가는 거예요", "it": false}, {"s": 2110.925, "e": 2113.239, "en": "Only your husband\ncan sign him out.", "ko": "퇴원 서명은\n남편분만 하실 수 있습니다", "it": false}, {"s": 2118.283, "e": 2120.851, "en": "My husband doesn't need\nto know anything about this.", "ko": "남편은 이 일을\n알 필요 없어요", "it": false}, {"s": 2120.935, "e": 2124.625, "en": "I am his mother and I'm\ntaking him home.", "ko": "난 이 애 엄마고\n이 애를 집에 데려갈 거예요", "it": false}, {"s": 2126.959, "e": 2129.435, "en": "Why do you think\nthey're taking so long?", "ko": "왜 이렇게\n오래 걸리죠?", "it": false}, {"s": 2129.519, "e": 2131.632, "en": "Everything's going to be\nall right.", "ko": "다 괜찮을 거야", "it": false}, {"s": 2134.691, "e": 2136.367, "en": "If that place is what\nI think it is,", "ko": "그곳이 내가 생각하는\n그런 곳이라면", "it": false}, {"s": 2136.451, "e": 2139.932, "en": "As soon as your mother sees Joel\nshe'll know exactly what to do.", "ko": "네 어머니가 조엘을 보자마자\n어떻게 해야 할지 아실 거야", "it": false}, {"s": 2152.893, "e": 2154.064, "en": "She's back.", "ko": "오셨다", "it": false}, {"s": 2164.738, "e": 2166.581, "en": "It's Joel.", "ko": "조엘이에요", "it": false}, {"s": 2166.665, "e": 2168.249, "en": "He's sick.", "ko": "아파요", "it": false}, {"s": 2168.333, "e": 2170.234, "en": "I can't take care of him\nin the house.", "ko": "집에서는\n돌볼 수가 없어요", "it": false}, {"s": 2170.318, "e": 2172.587, "en": "Awful big house, though.", "ko": "그렇게 큰 집인데도요?", "it": false}, {"s": 2172.671, "e": 2175.59, "en": "I know how heavy this is\nfor me to show up like this.", "ko": "이렇게 찾아오는 게\n얼마나 염치없는 일인지 알아요", "it": false}, {"s": 2175.674, "e": 2177.908, "en": "You don't know the first thing\nabout heavy.", "ko": "염치가 뭔지\n하나도 모르시면서", "it": false}, {"s": 2177.992, "e": 2180.095, "en": "I should have done\nmore than I did.", "ko": "그때 내가\n더 했어야 했어요", "it": false}, {"s": 2180.179, "e": 2181.671, "en": "I wasn't myself.", "ko": "그땐 내가\n나 자신이 아니었어요", "it": false}, {"s": 2181.755, "e": 2184.265, "en": "But I'm working on\nfinding that person again,", "ko": "하지만 그런 나를\n다시 찾으려고 애쓰고 있어요", "it": false}, {"s": 2184.349, "e": 2186.935, "en": "And right now that person\nis here at your door", "ko": "그리고 지금 그 내가\n이 문 앞에 서서", "it": false}, {"s": 2187.019, "e": 2189.023, "en": "Asking for your help.", "ko": "도와 달라고\n부탁하는 거예요", "it": false}, {"s": 2193.358, "e": 2195.335, "en": "I just want us all to sleep\nbetter tonight.", "ko": "오늘 밤엔 우리 모두\n좀 더 편히 잤으면 해요", "it": false}, {"s": 2195.419, "e": 2198.095, "en": "You want us to help\nyour boy.", "ko": "마님 아들을\n도와 달라고요?", "it": false}, {"s": 2198.179, "e": 2201.616, "en": "What work did you do\nto help ours?", "ko": "우리 애를 위해선\n뭘 하셨는데요?", "it": false}, {"s": 2201.7, "e": 2203.676, "en": "She got him back for us.", "ko": "이분이 해리를\n데려와 주셨어", "it": false}, {"s": 2203.76, "e": 2205.511, "en": "Beaten bad.", "ko": "그래, 죽도록\n두들겨 맞은 채로", "it": false}, {"s": 2205.595, "e": 2206.454, "en": "Alive.", "ko": "그래도 살아서 왔잖니", "it": false}, {"s": 2206.538, "e": 2208.957, "en": "No, I didn't.", "ko": "아니에요, 내가 한 게 아니에요", "it": false}, {"s": 2209.041, "e": 2212.185, "en": "I was too much of a coward.\nThat was Joel.", "ko": "난 겁쟁이였어요\n그건 조엘이 한 거예요", "it": false}, {"s": 2212.269, "e": 2213.795, "en": "Joel brought your son\nback to you.", "ko": "조엘이 당신 아들을\n돌려보낸 거예요", "it": false}, {"s": 2213.879, "e": 2218.886, "en": "So, if you won't do this for me,\nwould you do it for him?", "ko": "나를 위해선 못 하겠다면\n그 애를 위해서라도 해 줄래요?", "it": false}, {"s": 2226.132, "e": 2228.626, "en": "Where's your boy?", "ko": "아드님은 어디 있어요?", "it": false}, {"s": 2228.71, "e": 2231.371, "en": "He's laid out in the car.\nI need a hand.", "ko": "차에 눕혀 놨어요\n도와줘요", "it": false}, {"s": 2231.455, "e": 2234.026, "en": "Malcolm can never know.", "ko": "맬컴은 절대 알면 안 돼요", "it": false}, {"s": 2254.902, "e": 2256.424, "en": "Oh, dear lord.", "ko": "세상에, 주님", "it": false}, {"s": 2259.332, "e": 2260.503, "en": "I'll take the legs.", "ko": "내가 다리를 들게", "it": false}, {"s": 2276.349, "e": 2278.279, "en": "What did you do to him?", "ko": "저 애한테\n무슨 짓을 한 거예요?", "it": false}, {"s": 2323.897, "e": 2325.965, "en": "Has anyone heard from Joel?", "ko": "조엘 소식 들은 사람 있어요?", "it": false}, {"s": 2326.049, "e": 2329.83, "en": "I'd just like to make sure\nhe arrived in Montreal safely.", "ko": "몬트리올에 잘 도착했는지\n확인하고 싶어서요", "it": false}, {"s": 2333.573, "e": 2337.252, "en": "I'm sure he has.\nIsn't that right, Malcolm?", "ko": "분명 잘 도착했겠지\n그렇죠, 맬컴?", "it": false}, {"s": 2337.336, "e": 2339.298, "en": "I should get to work.", "ko": "일하러 가야겠군", "it": false}, {"s": 2342.065, "e": 2344.011, "en": "As should I.", "ko": "저도요", "it": false}, {"s": 2357.689, "e": 2359.107, "en": "If you can't keep\nthis a secret...", "ko": "비밀을 못 지키겠으면...", "it": false}, {"s": 2359.191, "e": 2361.258, "en": "He was barely conscious.", "ko": "오빠는 의식도\n거의 없었어요", "it": false}, {"s": 2361.342, "e": 2365.28, "en": "He needs to be in our home with\na real nurse or in a hospital.", "ko": "집에서 제대로 된 간호사가 보든지\n병원에 있어야 해요", "it": false}, {"s": 2365.364, "e": 2368.702, "en": "Do you want your father\nto put him through a window?", "ko": "아빠가 오빠를 창밖으로\n던져 버리길 바라니?", "it": false}, {"s": 2369.943, "e": 2372.194, "en": "You let this happen.", "ko": "엄마가 이렇게 만들었어요", "it": false}, {"s": 2372.278, "e": 2373.529, "en": "You lied to me.", "ko": "저한테 거짓말했잖아요", "it": false}, {"s": 2373.613, "e": 2375.29, "en": "To protect you.", "ko": "널 지키려고 그랬어", "it": false}, {"s": 2375.374, "e": 2377.959, "en": "You have no idea what's gone on\nin this house,", "ko": "이 집에서 무슨 일이\n있었는지 넌 몰라", "it": false}, {"s": 2378.043, "e": 2379.127, "en": "What I've done to shield you.", "ko": "내가 널 감싸려고\n무슨 짓까지 했는지", "it": false}, {"s": 2379.211, "e": 2381.779, "en": "I have never asked\nto be shielded!", "ko": "감싸 달라고 한 적\n한 번도 없어요!", "it": false}, {"s": 2381.863, "e": 2383.689, "en": "When have you ever asked\nwhat I wanted?!", "ko": "엄마가 언제\n내가 뭘 원하는지 물어본 적 있어요?!", "it": false}, {"s": 2383.773, "e": 2386.192, "en": "Everything I've done\nwas for you.", "ko": "내가 한 건 다\n너를 위해서였어", "it": false}, {"s": 2386.276, "e": 2388.18, "en": "And look at what we've lost.", "ko": "그 결과 우리가\n뭘 잃었는지 보세요", "it": false}, {"s": 2423.738, "e": 2425.247, "en": "I'm worried about corrine.", "ko": "코린이 걱정돼요", "it": false}, {"s": 2425.331, "e": 2426.841, "en": "We had a fight.", "ko": "우리가 다퉜어요", "it": false}, {"s": 2426.925, "e": 2430.753, "en": "She rode off on her horse\njust before the storm hit.", "ko": "폭풍이 몰아치기 직전에\n말을 타고 나갔어요", "it": false}, {"s": 2430.837, "e": 2432.572, "en": "I thought she'd be back\nbefore dark.", "ko": "어두워지기 전엔\n돌아올 줄 알았는데", "it": false}, {"s": 2432.656, "e": 2434.101, "en": "What were you thinking?", "ko": "대체 무슨 생각이었소?", "it": false}, {"s": 2447.187, "e": 2449.922, "en": "Search the entire estate!", "ko": "저택을 전부 뒤져!", "it": true}, {"s": 2450.006, "e": 2454.038, "en": "That night, horrors\nrained down on our home.", "ko": "그날 밤, 공포가\n우리 집에 쏟아졌다", "it": true}, {"s": 2456.27, "e": 2457.947, "en": "You, head out\nto the lake.", "ko": "너, 호수 쪽으로 가", "it": true}, {"s": 2458.031, "e": 2460.266, "en": "Let's get on with it.", "ko": "어서 움직여", "it": true}, {"s": 2460.35, "e": 2463.631, "en": "No one rests until\nwe find my corrine.", "ko": "내 코린을 찾을 때까지\n아무도 쉬지 마", "it": true}, {"s": 2469.968, "e": 2472.056, "en": "Some we had\nalready imagined.", "ko": "어떤 공포는\n이미 짐작하던 것이었고", "it": true}, {"s": 2486.376, "e": 2488.614, "en": "Some we had hidden\nfrom view.", "ko": "어떤 공포는\n우리가 숨겨 온 것이었고", "it": true}, {"s": 2501.558, "e": 2504.338, "en": "And others we couldn't\neven dream of.", "ko": "또 어떤 공포는\n상상조차 못 한 것이었다", "it": true}, {"s": 2516.998, "e": 2519.353, "en": "They would come\nto haunt us later.", "ko": "그것들은 나중에\n우리를 찾아와 괴롭힐 터였다", "it": true}, {"s": 2522.412, "e": 2525.848, "en": "But in that moment\nthere was only silence.", "ko": "하지만 그 순간엔\n침묵뿐이었다", "it": true}, {"s": 2525.932, "e": 2527.92, "en": "My own.", "ko": "나의 침묵", "it": true}, {"s": 2528.026, "e": 2529.197, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 2530.695, "e": 2531.866, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 2538.87, "e": 2540.041, "en": "Harry?", "ko": "해리?", "it": false}, {"s": 2542.282, "e": 2544.002, "en": "What did they do to you?", "ko": "대체 무슨 짓을 당한 거야?", "it": true}, {"s": 2548.713, "e": 2552.633, "en": "Don't you worry about me.\nI'll be all right.", "ko": "내 걱정은 하지 마\n난 괜찮을 거야", "it": false}, {"s": 2552.717, "e": 2555.711, "en": "I should have told the cops\nI gave you the watch.", "ko": "내가 시계 줬다고\n경찰한테 말했어야 했는데", "it": false}, {"s": 2555.795, "e": 2558.806, "en": "That would've made things worse\nfor the both of us.", "ko": "그랬으면 우리 둘 다\n더 곤란해졌을 거야", "it": false}, {"s": 2558.89, "e": 2560.728, "en": "Worse than this?", "ko": "이것보다 더?", "it": false}, {"s": 2563.286, "e": 2564.815, "en": "Look at us.", "ko": "우리 꼴 좀 봐", "it": false}, {"s": 2567.29, "e": 2569.153, "en": "I miss your playing.", "ko": "네 연주가 그리워", "it": false}, {"s": 2574.239, "e": 2576.215, "en": "It'll come back.", "ko": "다시 칠 수 있을 거야", "it": false}, {"s": 2576.299, "e": 2578.217, "en": "What if it doesn't?", "ko": "못 치면?", "it": false}, {"s": 2578.301, "e": 2579.472, "en": "Hey.", "ko": "이봐", "it": false}, {"s": 2580.97, "e": 2582.479, "en": "You just sleep now.", "ko": "지금은 그냥 자", "it": false}, {"s": 2582.563, "e": 2584.668, "en": "We'll worry about\nall that later.", "ko": "그런 걱정은\n나중에 하자", "it": false}, {"s": 2596.82, "e": 2597.991, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 2611.61, "e": 2612.863, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 2616.948, "e": 2618.119, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 2626.273, "e": 2627.878, "en": "Can you stand?", "ko": "일어설 수 있겠어?", "it": false}, {"s": 2630.52, "e": 2632.09, "en": "Where does it hurt?", "ko": "어디가 아파?", "it": false}, {"s": 2634.19, "e": 2637.051, "en": "My horse got spooked\nand I fell off.", "ko": "말이 놀라서\n떨어졌어요", "it": false}, {"s": 2637.135, "e": 2639.22, "en": "I need to look at the wound\nbut we're too far out.", "ko": "상처를 봐야 하는데\n너무 멀리 나왔어", "it": false}, {"s": 2639.304, "e": 2640.963, "en": "We have to find shelter.", "ko": "비를 피할 데를 찾아야 해", "it": false}, {"s": 2641.047, "e": 2645.226, "en": "There's a chapel\njust down that trail.", "ko": "저 길 따라 내려가면\n예배당이 있어요", "it": false}, {"s": 2645.31, "e": 2648.148, "en": "Okay, hold on.", "ko": "알았어, 꽉 잡아", "it": false}, {"s": 2682.18, "e": 2683.339, "en": "If no one sees\nthe beacon outside,", "ko": "밖에 켜 둔 불을\n아무도 못 보면", "it": false}, {"s": 2683.423, "e": 2685.185, "en": "We'll have to sleep here.", "ko": "여기서 밤을\n새워야 할 거야", "it": false}, {"s": 2690.504, "e": 2692.181, "en": "I'm going to do\nthe best I can", "ko": "최선을 다하겠지만", "it": false}, {"s": 2692.265, "e": 2694.5, "en": "But you'll have to be treated by\na doctor as soon as we get back.", "ko": "돌아가자마자 의사한테\n제대로 치료받아야 해", "it": false}, {"s": 2694.584, "e": 2696.168, "en": "I thought you were a doctor.", "ko": "삼촌이 의사 아니었어요?", "it": false}, {"s": 2696.252, "e": 2697.781, "en": "A qualified trainee.", "ko": "자격 있는 수련생이지", "it": false}, {"s": 2708.54, "e": 2710.21, "en": "Relax.", "ko": "긴장 풀어", "it": false}, {"s": 2711.71, "e": 2713.338, "en": "Breathe.", "ko": "숨 쉬어", "it": false}, {"s": 2719.551, "e": 2722.953, "en": "Why don't you tell me how\nyou knew about this place?", "ko": "여기는 어떻게 알았는지\n얘기해 줄래?", "it": false}, {"s": 2723.037, "e": 2725.622, "en": "I used to come here\nwith my brothers.", "ko": "오빠들이랑\n자주 왔었어요", "it": false}, {"s": 2725.706, "e": 2728.643, "en": "Are you trying\nto distract me?", "ko": "지금 제 정신\n딴 데 팔리게 하려는 거죠?", "it": false}, {"s": 2728.727, "e": 2730.564, "en": "Is it working?", "ko": "효과 있어?", "it": false}, {"s": 2734.381, "e": 2737.634, "en": "We used to race our horses all\nthe way from the house to here.", "ko": "집에서 여기까지\n말 타고 경주하곤 했어요", "it": false}, {"s": 2737.718, "e": 2741.046, "en": "And who would win,\nyou or Joel?", "ko": "누가 이겼는데?\n너야, 조엘이야?", "it": false}, {"s": 2741.13, "e": 2742.701, "en": "Not Joel.", "ko": "조엘 오빠는 아니었어요", "it": false}, {"s": 2744.968, "e": 2746.371, "en": "Mal.", "ko": "말 오빠였죠", "it": false}, {"s": 2750.248, "e": 2751.832, "en": "Ever since he died", "ko": "오빠가 죽은 뒤로", "it": false}, {"s": 2751.916, "e": 2754.922, "en": "It's like we're not allowed\nto talk about him anymore.", "ko": "이젠 오빠 얘기를\n하면 안 되는 것 같아요", "it": false}, {"s": 2757.738, "e": 2761.008, "en": "It's like we might break\nif we do.", "ko": "얘기하면 우리가\n무너져 버릴 것처럼요", "it": false}, {"s": 2761.092, "e": 2762.418, "en": "People don't truly break", "ko": "사람은 쉽게\n무너지지 않아", "it": false}, {"s": 2762.502, "e": 2764.765, "en": "If someone's there\nto help them heal.", "ko": "곁에서 낫게 도와줄\n누군가가 있다면", "it": false}, {"s": 2771.102, "e": 2774.413, "en": "I'm done. You can relax.", "ko": "다 됐어, 이제 힘 빼도 돼", "it": false}, {"s": 2777.776, "e": 2783.346, "en": "So, the debt is paid.", "ko": "그럼 빚은 갚은 거네요", "it": false}, {"s": 2783.43, "e": 2787.109, "en": "I saved your shirt,\nyou saved my life.", "ko": "난 삼촌 셔츠를 구했고,\n삼촌은 내 목숨을 구했으니까", "it": false}, {"s": 2787.193, "e": 2790.779, "en": "Actually, you ruined\nmy shirt.", "ko": "사실 넌 내 셔츠를\n망쳤어", "it": false}, {"s": 2790.863, "e": 2793.04, "en": "It's wrapped around\nyour leg.", "ko": "네 다리에\n감겨 있잖아", "it": false}, {"s": 2793.124, "e": 2795.768, "en": "So, I guess I owe you.", "ko": "그럼 제가\n빚진 거네요", "it": false}, {"s": 2795.852, "e": 2798.882, "en": "For some reason I still\nfeel like I owe you.", "ko": "왠지 아직도 내가\n빚진 기분인데", "it": false}, {"s": 2822.895, "e": 2824.241, "en": "Corrine!", "ko": "코린!", "it": false}, {"s": 2826.049, "e": 2827.619, "en": "Corrine!", "ko": "코린!", "it": true}, {"s": 2829.16, "e": 2831.579, "en": "She's in here!", "ko": "여기 있어요!", "it": false}, {"s": 2852.925, "e": 2854.751, "en": "Oh, thank goodness.", "ko": "세상에, 다행이다", "it": false}, {"s": 2854.835, "e": 2856.678, "en": "Are you all right?\nCan you walk?", "ko": "괜찮니?\n걸을 수 있겠어?", "it": false}, {"s": 2856.762, "e": 2858.755, "en": "Put me down please, daddy.", "ko": "내려 주세요, 아빠", "it": false}, {"s": 2858.839, "e": 2861.016, "en": "Just a few scrapes.\nShe was lucky.", "ko": "좀 긁혔을 뿐이에요\n운이 좋았어요", "it": false}, {"s": 2861.1, "e": 2862.184, "en": "Lucky you found me.", "ko": "삼촌이 날 찾은 게 운이죠", "it": false}, {"s": 2862.268, "e": 2865.595, "en": "It was you?\nThank you.", "ko": "네가 찾았구나?\n고마워", "it": false}, {"s": 2865.679, "e": 2867.356, "en": "I'm so sorry.", "ko": "정말 죄송해요", "it": false}, {"s": 2867.44, "e": 2869.525, "en": "As you should be.", "ko": "미안해야지", "it": false}, {"s": 2869.609, "e": 2872.164, "en": "I'll call the doctor\nin the morning.", "ko": "아침에 의사를\n부르마", "it": false}, {"s": 2873.872, "e": 2876.181, "en": "I know you don't agree with\nall of my choices as a mother,", "ko": "엄마로서 내 선택에\n네가 다 동의하지 않는다는 거 알아", "it": false}, {"s": 2876.265, "e": 2878.959, "en": "And many days neither do I.", "ko": "나도 동의 못 하는 날이\n많고", "it": false}, {"s": 2879.043, "e": 2881.629, "en": "But I'm doing my best.", "ko": "그래도 엄마는\n최선을 다하고 있어", "it": false}, {"s": 2881.713, "e": 2884.217, "en": "Joel will get better\nif we let him.", "ko": "우리가 내버려 두면\n조엘 오빠는 나을 거예요", "it": false}, {"s": 2889.445, "e": 2892.714, "en": "I think I've had enough of\nthe world outside for one day.", "ko": "오늘은 바깥세상 구경은\n이걸로 충분해요", "it": false}, {"s": 2892.798, "e": 2894.624, "en": "Just want to go to bed.", "ko": "그냥 자고 싶어요", "it": false}, {"s": 2894.708, "e": 2896.035, "en": "Of course.", "ko": "그래", "it": false}, {"s": 2896.119, "e": 2898.646, "en": "Do you need some help\ngetting up the stairs?", "ko": "계단 올라가는 거\n도와줄까?", "it": false}, {"s": 2898.73, "e": 2900.734, "en": "I think I can manage.", "ko": "혼자 할 수 있어요", "it": false}, {"s": 2903.459, "e": 2904.905, "en": "Good night.", "ko": "잘 자", "it": false}, {"s": 2907.554, "e": 2909.159, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 2910.891, "e": 2912.159, "en": "How can we ever thank you?", "ko": "이 은혜를\n어떻게 갚아야 할지", "it": false}, {"s": 2912.243, "e": 2913.476, "en": "There's no need.", "ko": "그러실 필요 없어요", "it": false}, {"s": 2913.56, "e": 2916.163, "en": "Corrine's safety's\nall I care about.", "ko": "저는 코린이 무사한 것만\n신경 쓰였어요", "it": false}, {"s": 2916.247, "e": 2917.406, "en": "Well, good night.", "ko": "그럼, 안녕히 주무세요", "it": false}, {"s": 2917.49, "e": 2918.833, "en": "I have an early start tomorrow.", "ko": "내일 일찍 일어나야 해서요", "it": false}, {"s": 2918.917, "e": 2921.151, "en": "No, you don't.", "ko": "아니, 그럴 필요 없어", "it": false}, {"s": 2921.235, "e": 2923.987, "en": "You no longer work for me.", "ko": "넌 더 이상\n나를 위해 일하지 않는다", "it": false}, {"s": 2924.071, "e": 2926.156, "en": "You have more than paid\nyour debt.", "ko": "빚은 충분하고도\n남게 갚았어", "it": false}, {"s": 2926.24, "e": 2929.513, "en": "From now on your education\nis paid for in full.", "ko": "이제부터 네 학비는\n내가 전부 대마", "it": false}, {"s": 2937.009, "e": 2940.079, "en": "You should be lying down.", "ko": "누워 있어야지", "it": false}, {"s": 2940.163, "e": 2942.172, "en": "I couldn't lie still\nif I tried.", "ko": "누워 있으려고 해도\n가만히 못 있겠어요", "it": false}, {"s": 2942.256, "e": 2944.083, "en": "I thought you were done\nwith the world for today.", "ko": "오늘 바깥세상은\n이걸로 충분하다며?", "it": false}, {"s": 2944.167, "e": 2945.362, "en": "I am.", "ko": "맞아요", "it": false}, {"s": 2947.186, "e": 2948.573, "en": "That one.", "ko": "그쪽 세상 말이에요", "it": false}, {"s": 2952.858, "e": 2954.535, "en": "What we stumbled into\nin that storm...", "ko": "폭풍 속에서\n우리가 어쩌다 빠져든 그 일은...", "it": false}, {"s": 2954.619, "e": 2955.852, "en": "Words like stumbled...", "ko": "어쩌다라니...", "it": false}, {"s": 2955.936, "e": 2957.596, "en": "It can never happen again.", "ko": "다시는 있어선 안 돼", "it": false}, {"s": 2957.68, "e": 2960.374, "en": "You make it sound like\nit was an accident.", "ko": "무슨 사고였던 것처럼\n말하네요", "it": false}, {"s": 2960.458, "e": 2961.524, "en": "I'm your uncle.", "ko": "난 네 삼촌이야", "it": false}, {"s": 2961.608, "e": 2964.798, "en": "Half... Uncle.", "ko": "반쪽... 삼촌이죠", "it": false}, {"s": 2968.374, "e": 2971.552, "en": "We lost ourselves.\nI was worried about you.", "ko": "우리가 정신이 나갔던 거야\n네가 걱정돼서", "it": false}, {"s": 2971.636, "e": 2974.099, "en": "I was just trying to make sure\nyou were all right.", "ko": "네가 괜찮은지\n확인하려던 거였어", "it": false}, {"s": 2977.216, "e": 2978.875, "en": "That wasn't a worried kiss.", "ko": "그건 걱정돼서 한\n키스가 아니었어요", "it": false}, {"s": 2978.959, "e": 2981.064, "en": "It wasn't a proper one either.", "ko": "그렇다고\n해서도 안 되는 키스였어", "it": false}, {"s": 2987.318, "e": 2991.964, "en": "You're right.\nUm, then it never happened.", "ko": "삼촌 말이 맞아요\n그럼 없던 일로 해요", "it": false}, {"s": 2992.048, "e": 2993.556, "en": "I apologize.", "ko": "죄송해요", "it": false}, {"s": 2993.64, "e": 2996.652, "en": "You're not the only one\nwho feels sorry about it.", "ko": "미안한 건\n너만이 아니야", "it": false}, {"s": 2996.736, "e": 3000.656, "en": "If you want to be dancing\nin time for your ball,", "ko": "무도회 때까지\n춤출 수 있으려면", "it": false}, {"s": 3000.74, "e": 3002.752, "en": "You should get some rest.", "ko": "좀 쉬어야 해", "it": false}, {"s": 3009.398, "e": 3011.833, "en": "What about Christopher?", "ko": "크리스토퍼는 어때요?", "it": false}, {"s": 3011.917, "e": 3015.32, "en": "Many debutants have used their\nuncles for their first dance.", "ko": "데뷔하는 아가씨들은 삼촌과\n첫 춤을 추기도 하잖아요", "it": false}, {"s": 3015.404, "e": 3017.489, "en": "Or fathers.", "ko": "아니면 아버지와\n추기도 하오", "it": false}, {"s": 3017.573, "e": 3020.083, "en": "It should be someone closer\nto her own age.", "ko": "비슷한 또래랑\n추는 게 좋겠죠", "it": false}, {"s": 3020.167, "e": 3021.268, "en": "Since you two have become\nso close", "ko": "둘이 그렇게\n가까워졌으니", "it": false}, {"s": 3021.352, "e": 3023.345, "en": "I think it's only appropriate.", "ko": "딱 어울릴 것 같은데요", "it": false}, {"s": 3023.429, "e": 3025.497, "en": "Christopher is a part\nof our family now.", "ko": "크리스토퍼도 이제\n우리 가족이잖아요", "it": false}, {"s": 3025.581, "e": 3026.999, "en": "Surely my Princess,", "ko": "설마 우리 공주님이", "it": false}, {"s": 3027.083, "e": 3030.444, "en": "You wouldn't mind if I gave you\nthat first dance.", "ko": "첫 춤을 아빠랑 추는 걸\n싫어하진 않겠지", "it": false}, {"s": 3030.528, "e": 3033.005, "en": "Christopher, would you do\ncorrine the honor?", "ko": "크리스토퍼, 코린과\n첫 춤을 춰 주겠니?", "it": false}, {"s": 3033.089, "e": 3035.115, "en": "Actually, I was thinking\nmy friend rockford", "ko": "사실 저는\n제 친구 록퍼드랑", "it": false}, {"s": 3035.199, "e": 3037.509, "en": "Could be my first dance.", "ko": "첫 춤을 추고 싶어요", "it": false}, {"s": 3037.593, "e": 3039.511, "en": "Your friend?", "ko": "친구?", "it": false}, {"s": 3039.595, "e": 3041.121, "en": "You have a male friend.", "ko": "남자 친구가 있다고", "it": false}, {"s": 3041.205, "e": 3042.667, "en": "Rockford taylard.", "ko": "록퍼드 테일러드요", "it": false}, {"s": 3044.024, "e": 3046.213, "en": "You knew about this male friend\nof hers?", "ko": "당신은 얘한테 그런 남자 친구가\n있는 걸 알았소?", "it": false}, {"s": 3050.03, "e": 3051.614, "en": "Oh, daddy.", "ko": "아이참, 아빠", "it": false}, {"s": 3051.698, "e": 3053.525, "en": "Who doesn't know of\nthe taylards?", "ko": "테일러드 집안을\n모르는 사람이 어디 있어요?", "it": false}, {"s": 3053.609, "e": 3056.545, "en": "Mr. Taylard owns the textile\nmills just outside of town,", "ko": "테일러드 씨는 시 외곽에\n방직 공장을 갖고 있고", "it": false}, {"s": 3056.629, "e": 3058.864, "en": "And his son rockford", "ko": "아들 록퍼드는", "it": false}, {"s": 3058.948, "e": 3062.292, "en": "Is just a very sweet\nand disciplined young man", "ko": "그냥 아주 다정하고\n반듯한 청년이에요", "it": false}, {"s": 3062.376, "e": 3064.386, "en": "Who I happen to have\ncrossed paths with", "ko": "여기저기 행사에서", "it": false}, {"s": 3064.47, "e": 3066.816, "en": "At events here and there.", "ko": "우연히 마주쳤을 뿐이고요", "it": false}, {"s": 3070.126, "e": 3071.634, "en": "And plus he has just finished\nhis first year", "ko": "게다가 블랙스버그 경영학교", "it": false}, {"s": 3071.718, "e": 3073.879, "en": "At the blacksburg school\nof business.", "ko": "1학년을 막\n마쳤대요", "it": false}, {"s": 3073.963, "e": 3075.397, "en": "Are you sure you want to share\nyour first dance", "ko": "첫 춤을 거의\n모르는 사람이랑", "it": false}, {"s": 3075.481, "e": 3077.14, "en": "With a relative stranger?", "ko": "정말 추고 싶니?", "it": false}, {"s": 3077.224, "e": 3079.412, "en": "Rockford's not a stranger.", "ko": "록퍼드는 모르는 사람이\n아니에요", "it": false}, {"s": 3090.088, "e": 3091.488, "en": "Corrine.", "ko": "코린", "it": false}, {"s": 3091.572, "e": 3093.899, "en": "You do realize what\nyou're doing here.", "ko": "네가 지금\n뭘 하는지 알고 있니?", "it": false}, {"s": 3093.983, "e": 3095.4, "en": "Mother...", "ko": "엄마...", "it": false}, {"s": 3095.484, "e": 3098.161, "en": "I know why you're hesitant,\nbut rock's changed.", "ko": "엄마가 왜 망설이는지 알아요\n하지만 록은 변했어요", "it": false}, {"s": 3098.245, "e": 3100.756, "en": "You don't yet know\nwhat changes a man.", "ko": "남자를 무엇이 변하게 하는지\n넌 아직 몰라", "it": false}, {"s": 3100.84, "e": 3104.184, "en": "He is still the same person\nthat defiled you.", "ko": "그 애는 여전히\n널 더럽힌 그 녀석이야", "it": false}, {"s": 3104.268, "e": 3105.853, "en": "Remember that.", "ko": "그걸 기억해", "it": false}, {"s": 3105.937, "e": 3109.081, "en": "And remember what we had\nto do because of it.", "ko": "그리고 그 일 때문에 우리가\n무슨 일을 해야 했는지도", "it": false}, {"s": 3109.165, "e": 3112.195, "en": "Mrs. Foxworth,\na visitor for you.", "ko": "마님, 손님이\n찾아오셨습니다", "it": false}, {"s": 3119.6, "e": 3122.369, "en": "Mrs. Steiner?\nWhat a surprise.", "ko": "스타이너 부인?\n이게 웬일이에요", "it": false}, {"s": 3122.453, "e": 3125.539, "en": "I'm going to make this brief\nMrs. Foxworth,", "ko": "길게 얘기 안 할게요,\n폭스워스 부인", "it": false}, {"s": 3125.623, "e": 3126.932, "en": "Since I don't much enjoy", "ko": "나도 별로거든요", "it": false}, {"s": 3127.016, "e": 3130.693, "en": "Being in the company\nof a person like you", "ko": "당신 같은 사람이랑\n같이 있는 거", "it": false}, {"s": 3130.777, "e": 3136.441, "en": "Who stains the honor of\na great house like this.", "ko": "이 훌륭한 저택 이름에\n먹칠이나 하는 사람이랑은", "it": false}, {"s": 3136.525, "e": 3139.887, "en": "I know about\nyour son's problem.", "ko": "아드님 문제, 다 알아요", "it": false}, {"s": 3139.971, "e": 3141.224, "en": "What problem?", "ko": "무슨 문제요?", "it": false}, {"s": 3143.215, "e": 3146.479, "en": "The west more land sanitarium.", "ko": "웨스트모어랜드 요양원", "it": false}, {"s": 3157.88, "e": 3159.631, "en": "Three grand.", "ko": "3천", "it": false}, {"s": 3159.715, "e": 3163.302, "en": "I'll come by to collect it\nnext weekend.", "ko": "다음 주말에\n받으러 올게요", "it": false}, {"s": 3163.386, "e": 3166.246, "en": "Unless, of course, you want\nthe whole world to find out", "ko": "아드님이... 동성애자라는 걸", "it": false}, {"s": 3166.33, "e": 3170.659, "en": "That your boy is a...\nHomosexual.", "ko": "온 세상이 알았으면 좋겠다면\n몰라도요", "it": false}, {"s": 3191.505, "e": 3192.664, "en": "How does she know?", "ko": "그 여자가 어떻게 알았지?", "it": false}, {"s": 3192.748, "e": 3194.333, "en": "The important thing\nis that she does", "ko": "중요한 건\n그 여자가 안다는 거고", "it": false}, {"s": 3194.417, "e": 3196.443, "en": "And that she's threatening\nto ruin our son.", "ko": "우리 아들을 망치겠다고\n협박한다는 거예요", "it": false}, {"s": 3196.527, "e": 3198.854, "en": "Joel is in the hospital\ntrying to get better.", "ko": "조엘은 낫기 위해\n병원에 있어요", "it": false}, {"s": 3198.938, "e": 3201.281, "en": "If we don't pay her off\nit will all be for nothing.", "ko": "그 여자 입을 막지 않으면\n다 소용없어져요", "it": false}, {"s": 3205.11, "e": 3207.707, "en": "We can't have your\nreputation ruined.", "ko": "당신 평판을\n망칠 순 없죠", "it": false}, {"s": 3209.69, "e": 3212.108, "en": "I'll arrange for the money.", "ko": "돈은 내가\n마련하겠소", "it": false}, {"s": 3212.192, "e": 3215.02, "en": "...And you care for him?", "ko": "...그럼 넌\n그 사람을 아끼는 거야?", "it": false}, {"s": 3215.104, "e": 3216.63, "en": "He's exactly what I need.", "ko": "나한테 꼭 필요한\n사람이야", "it": false}, {"s": 3216.714, "e": 3219.8, "en": "The complete opposite to\nour overly-complicated family.", "ko": "복잡하기 짝이 없는\n우리 가족이랑은 정반대고", "it": false}, {"s": 3219.884, "e": 3221.693, "en": "No one can change\nwho they care for,", "ko": "누굴 아끼는지는\n바꿀 수 없지", "it": false}, {"s": 3221.777, "e": 3223.348, "en": "Not for anything\nin the world.", "ko": "세상 그 무엇을\n준다 해도", "it": false}, {"s": 3227.225, "e": 3229.701, "en": "What about me?", "ko": "그럼 나는?", "it": false}, {"s": 3229.785, "e": 3231.478, "en": "Well, of course I care\nabout you.", "ko": "당연히 오빠도 아끼지", "it": false}, {"s": 3231.562, "e": 3233.372, "en": "Could you from far away?", "ko": "멀리 있어도\n그럴 수 있어?", "it": false}, {"s": 3233.456, "e": 3235.891, "en": "What are you talking about?", "ko": "무슨 소리야?", "it": false}, {"s": 3235.975, "e": 3237.237, "en": "I'm leaving.", "ko": "나 떠날 거야", "it": false}, {"s": 3238.552, "e": 3240.154, "en": "What? Why?\nYou're getting better.", "ko": "뭐? 왜?\n오빠 좋아지고 있잖아", "it": false}, {"s": 3240.238, "e": 3241.713, "en": "And if I stay here\nthat won't happen.", "ko": "여기 있으면\n안 좋아질 거야", "it": false}, {"s": 3241.797, "e": 3243.243, "en": "Not really.", "ko": "진짜로는 아니야", "it": false}, {"s": 3247.152, "e": 3248.748, "en": "What about Harry?", "ko": "해리는?", "it": false}, {"s": 3252.25, "e": 3254.379, "en": "I don't know.", "ko": "모르겠어", "it": false}, {"s": 3411.133, "e": 3413.079, "en": "I thought you'd still be\nat the office.", "ko": "아직 사무실에\n계실 줄 알았는데요", "it": false}, {"s": 3414.987, "e": 3416.416, "en": "I'm leaving.", "ko": "저 떠나요", "it": false}, {"s": 3420.476, "e": 3423.337, "en": "How did you get out of\nthe hospital?", "ko": "병원에서는\n어떻게 나왔어?", "it": false}, {"s": 3423.421, "e": 3428.508, "en": "I don't want anything and\nI'll never bother you again.", "ko": "아무것도 바라지 않아요\n다시는 귀찮게 안 할게요", "it": false}, {"s": 3428.592, "e": 3433.588, "en": "If you run, you will never be\nwelcome back here again.", "ko": "도망치면 다시는\n이 집에 발 못 들인다", "it": false}, {"s": 3433.672, "e": 3435.073, "en": "I know.", "ko": "알아요", "it": false}, {"s": 3435.157, "e": 3437.242, "en": "I will say that you are\nno longer my son.", "ko": "넌 더 이상\n내 아들이 아니라고 할 거다", "it": false}, {"s": 3437.326, "e": 3439.669, "en": "Well, you were never much\nof a father to me anyway.", "ko": "어차피 아버지도 저한테\n아버지 노릇 한 적 없잖아요", "it": false}, {"s": 3439.753, "e": 3443.19, "en": "And I will write you out\nof my will.", "ko": "유언장에서도\n네 이름은 지울 거다", "it": false}, {"s": 3443.274, "e": 3446.279, "en": "I don't want your money if\nit'd give me a life like yours.", "ko": "아버지 같은 인생을 살게 될 돈이라면\n필요 없어요", "it": false}, {"s": 3451.023, "e": 3453.033, "en": "I'll ask you one last time.", "ko": "마지막으로 묻겠다", "it": false}, {"s": 3453.117, "e": 3454.684, "en": "How did you get out\nof that hospital?", "ko": "그 병원에서\n어떻게 나왔어?", "it": false}, {"s": 3454.768, "e": 3458.291, "en": "It was me.\nI brought him home.", "ko": "나야\n내가 데려왔어", "it": false}, {"s": 3468.949, "e": 3470.366, "en": "You took him out of\nthe sanitarium", "ko": "요양원에서 그 애를\n데리고 나왔다고?", "it": false}, {"s": 3470.45, "e": 3472.46, "en": "Without consulting me!", "ko": "나랑 상의도 없이!", "it": false}, {"s": 3472.544, "e": 3473.973, "en": "Wait for me.", "ko": "기다려", "it": false}, {"s": 3477.808, "e": 3482.287, "en": "I went to visit him.\nHe was unrecognizable.", "ko": "면회 갔었어\n알아볼 수도 없더라", "it": false}, {"s": 3482.371, "e": 3484.38, "en": "- We were fixing him.\n- We were breaking him.", "ko": "-우린 그 앨 고치는 중이었소\n-우린 그 앨 망가뜨리고 있었어", "it": false}, {"s": 3484.464, "e": 3486.549, "en": "No, you already did.", "ko": "아니, 그 앤\n당신이 이미 망가뜨렸소", "it": false}, {"s": 3486.633, "e": 3488.81, "en": "Just like you broke\nour other son!", "ko": "다른 아들을\n망가뜨린 것처럼!", "it": false}, {"s": 3488.894, "e": 3490.404, "en": "Mal's death was\nan accident.", "ko": "말의 죽음은\n사고였어", "it": false}, {"s": 3490.488, "e": 3492.221, "en": "Was it?", "ko": "그랬소?", "it": false}, {"s": 3492.305, "e": 3495.057, "en": "You are a curse\non this family.", "ko": "당신은 이 집안의 저주요", "it": false}, {"s": 3495.141, "e": 3497.986, "en": "You meddle and our son dies!", "ko": "당신이 참견하면\n아들이 죽고!", "it": false}, {"s": 3498.07, "e": 3501.306, "en": "You meddle and our other son\nbecomes an invert!", "ko": "당신이 참견하면 다른 아들은\n변태가 되고!", "it": false}, {"s": 3501.39, "e": 3503.308, "en": "You meddle and corrine\ngets pregnant!", "ko": "당신이 참견하면\n코린이 임신을 하고!", "it": false}, {"s": 3503.392, "e": 3505.16, "en": "Alicia falls down the stairs!", "ko": "앨리샤는 계단에서 떨어지고!", "it": false}, {"s": 3505.244, "e": 3507.737, "en": "I get poisoned, and now\nthat godforsaken housekeeper", "ko": "난 독을 먹고, 이제는\n그 망할 가정부장 년이", "it": false}, {"s": 3507.821, "e": 3509.314, "en": "Has come back\nto blackmail me!", "ko": "돌아와서\n날 협박하고 있어!", "it": false}, {"s": 3509.398, "e": 3510.757, "en": "Why?!", "ko": "왜?!", "it": false}, {"s": 3510.841, "e": 3515.014, "en": "Because everything that\nyou touch, it turns to ash!", "ko": "당신 손에 닿는 건\n전부 재가 되니까!", "it": false}, {"s": 3517.515, "e": 3521.02, "en": "And I know you wanted that storm\nto take corrine away from me.", "ko": "그 폭풍이 내게서 코린을\n빼앗아 가길 바랐던 거 다 아오", "it": false}, {"s": 3526.915, "e": 3531.656, "en": "Mal died because you assaulted\nhis fiancée.", "ko": "말이 죽은 건 당신이\n그 애 약혼녀를 범했기 때문이야", "it": false}, {"s": 3533.513, "e": 3538.343, "en": "Joel was tortured because you\ncouldn't love him for who he is.", "ko": "조엘이 고문당한 건 당신이\n그 애를 있는 그대로 사랑할 줄 몰라서고", "it": false}, {"s": 3538.427, "e": 3539.953, "en": "Corrine fell into the arms\nof another man", "ko": "코린이 다른 남자 품에\n안긴 건", "it": false}, {"s": 3540.037, "e": 3542.605, "en": "Because she was running\nfrom yours!", "ko": "당신 품에서\n도망치려고 그런 거야!", "it": false}, {"s": 3542.689, "e": 3545.837, "en": "You are the curse, Malcolm!\nYou are the storm!", "ko": "저주는 당신이야, 맬컴!\n폭풍은 당신이라고!", "it": false}, {"s": 3554.218, "e": 3556.889, "en": "Everything you touch.", "ko": "손에 닿는 건 전부", "it": false}, {"s": 3580.244, "e": 3581.581, "en": "What?", "ko": "뭐?", "it": false}, {"s": 3587.751, "e": 3590.214, "en": "I went looking for it\nthe day after they took you.", "ko": "그 사람들이 널 끌고 간\n다음 날 찾으러 갔었어", "it": false}, {"s": 3591.922, "e": 3594.341, "en": "I found it beside\nthe driveway.", "ko": "진입로 옆에\n떨어져 있더라", "it": false}, {"s": 3594.425, "e": 3596.568, "en": "The face is busted\nbut you can pawn it.", "ko": "유리는 깨졌지만\n전당포에 맡길 순 있을 거야", "it": false}, {"s": 3596.652, "e": 3599.846, "en": "Get yourself some money so you\ncan properly get out of here.", "ko": "그 돈으로 여길\n제대로 떠나", "it": false}, {"s": 3599.93, "e": 3601.589, "en": "With you?", "ko": "너랑 같이?", "it": false}, {"s": 3601.673, "e": 3603.561, "en": "On your own.", "ko": "너 혼자", "it": false}, {"s": 3605.418, "e": 3607.687, "en": "Thank you for being there\nwith me.", "ko": "곁에 있어 줘서 고마워", "it": false}, {"s": 3607.771, "e": 3610.265, "en": "For everything.", "ko": "전부 다", "it": false}, {"s": 3610.349, "e": 3614.419, "en": "I can't make you go through\nthis next part with me.", "ko": "이다음 길까지\n너한테 같이 가자고 할 순 없어", "it": false}, {"s": 3614.503, "e": 3616.588, "en": "You deserve a life without\nmemories of this place", "ko": "넌 이곳 기억 없이\n살 자격이 있어", "it": false}, {"s": 3616.672, "e": 3618.106, "en": "And all I'll do is make you\nreturn to it", "ko": "나랑 있으면\n넌 자꾸만 이곳으로", "it": false}, {"s": 3618.19, "e": 3620.775, "en": "Over and over again.", "ko": "되돌아오게 될 거야", "it": false}, {"s": 3620.859, "e": 3622.761, "en": "Harry, think about\neverything being with me\nhas put you through.", "ko": "해리, 나랑 있으면서 네가\n무슨 일을 겪었는지 생각해 봐", "it": false}, {"s": 3622.845, "e": 3625.597, "en": "I have.", "ko": "생각해 봤어", "it": false}, {"s": 3625.681, "e": 3627.432, "en": "You know, I've been\nkicked before.", "ko": "나 전에도\n걷어차여 봤어", "it": false}, {"s": 3627.516, "e": 3629.209, "en": "It's not the first time\nI pushed to the ground.", "ko": "바닥에 나동그라진 게\n처음도 아니고", "it": false}, {"s": 3629.293, "e": 3631.861, "en": "I'm, I'm not better yet\nbut neither are you.", "ko": "나 아직 다 낫진 않았어\n하지만 너도 마찬가지잖아", "it": false}, {"s": 3631.945, "e": 3633.271, "en": "We get through this together", "ko": "우린 같이 이겨 낼 거야", "it": false}, {"s": 3633.355, "e": 3634.381, "en": "Just like we got through\nlast year.", "ko": "작년을 같이 버텨 냈던 것처럼", "it": false}, {"s": 3634.465, "e": 3636.135, "en": "That's the point.", "ko": "그게 핵심이야", "it": false}, {"s": 3637.801, "e": 3639.368, "en": "I'm not going to throw\nthe towel in on you", "ko": "네가 무섭다고 해서", "it": false}, {"s": 3639.452, "e": 3641.098, "en": "Just 'cause you're scared.", "ko": "내가 포기할 것 같아?", "it": false}, {"s": 3645.476, "e": 3650.608, "en": "I've got a world to see,\nand I got you to see it with.", "ko": "난 볼 세상이 있고,\n같이 볼 사람도 있어", "it": false}, {"s": 3652.816, "e": 3656.614, "en": "Well, where should we\nstart then?", "ko": "그럼 어디부터 갈까?", "it": false}, {"s": 3659.564, "e": 3660.74, "en": "New York.", "ko": "뉴욕", "it": false}, {"s": 3660.824, "e": 3666.137, "en": "If it's with you,\nI was thinking just...", "ko": "너랑 같이라면,\n그냥 생각했던 대로...", "it": false}, {"s": 3666.221, "e": 3667.392, "en": "\"north.\"", "ko": "\"북쪽\"", "it": false}, {"s": 3685.257, "e": 3688.688, "en": "I wish I could force him to\nhand over your trust right now.", "ko": "당장이라도 아버지가 네 신탁을\n내놓게 만들 수 있으면 좋겠는데", "it": false}, {"s": 3692.597, "e": 3694.515, "en": "This is more than enough.", "ko": "이걸로도 충분하고 남아요", "it": false}, {"s": 3694.599, "e": 3697.944, "en": "Just promise me\nyou'll live with no regrets.", "ko": "후회 없이 산다고만\n약속해 줘", "it": false}, {"s": 3698.028, "e": 3700.199, "en": "Only if you do the same.", "ko": "어머니도 그러신다면요", "it": false}, {"s": 3701.273, "e": 3702.782, "en": "This is going to end\nwith someone dying.", "ko": "이러다 결국 누군가는\n죽을 거예요", "it": false}, {"s": 3702.866, "e": 3706.453, "en": "Get out of this place.\nSave yourself.", "ko": "여길 떠나세요\n어머니 자신을 구하세요", "it": false}, {"s": 3706.537, "e": 3708.207, "en": "Leave him.", "ko": "아버지를 떠나세요", "it": false}, {"s": 3726.465, "e": 3727.894, "en": "Bye, baby.", "ko": "잘 가, 아가", "it": false}, {"s": 3782.446, "e": 3784.439, "en": "Mr. Foxworth.", "ko": "폭스워스 씨", "it": false}, {"s": 3784.523, "e": 3789.202, "en": "A pleasure to work together\nagain after all these years.", "ko": "오랜만에 또\n같이 일하게 됐네요", "it": false}, {"s": 3789.286, "e": 3790.704, "en": "I'm assuming.", "ko": "그래야 할 텐데 말이에요", "it": false}, {"s": 3790.788, "e": 3792.688, "en": "Mrs. Steiner.", "ko": "스타이너 부인", "it": false}, {"s": 3792.772, "e": 3795.95, "en": "What you fail to understand\nabout threatening my name", "ko": "내 이름을 걸고 협박하면서\n당신이 모르는 게 있는데", "it": false}, {"s": 3796.034, "e": 3798.603, "en": "Is I no longer have a son.", "ko": "난 이제 아들이 없소", "it": false}, {"s": 3798.687, "e": 3803.699, "en": "So, you can blab to whomever\nyou'd like.", "ko": "그러니 누구한테든\n실컷 떠벌리시오", "it": false}, {"s": 3803.783, "e": 3805.471, "en": "Very well.", "ko": "알겠어요", "it": false}, {"s": 3807.12, "e": 3811.725, "en": "I can only imagine how important\ntonight's party must be to you.", "ko": "오늘 밤 파티가 얼마나\n중요하신지 짐작이 가네요", "it": false}, {"s": 3811.809, "e": 3815.648, "en": "I hope it goes off\nwithout a hitch.", "ko": "부디 아무 탈 없이\n끝나야 할 텐데요", "it": false}, {"s": 3832.404, "e": 3833.972, "en": "Daddy, where is my dress?", "ko": "아빠, 제 드레스 어디 있어요?", "it": false}, {"s": 3834.056, "e": 3836.565, "en": "It was supposed\nto arrive yesterday.", "ko": "어제 도착하기로\n했는데", "it": false}, {"s": 3836.649, "e": 3839.586, "en": "I have bad news,\nmy darling.", "ko": "안 좋은 소식이 있단다,\n우리 딸", "it": false}, {"s": 3839.67, "e": 3842.071, "en": "Your mother...", "ko": "네 엄마가...", "it": false}, {"s": 3842.155, "e": 3843.757, "en": "...Ruined it.", "ko": "...망쳐 버렸어", "it": false}, {"s": 3843.841, "e": 3847.26, "en": "Ruined?! How?", "ko": "망쳤다고요?! 어떻게요?", "it": false}, {"s": 3847.344, "e": 3850.263, "en": "Don't you worry,", "ko": "걱정하지 마라", "it": false}, {"s": 3850.347, "e": 3853.352, "en": "Because I have one last surprise\nfor your big night.", "ko": "네 특별한 밤을 위해\n아빠가 마지막 깜짝 선물을 준비했거든", "it": false}, {"s": 3868.681, "e": 3869.852, "en": "Thank you.", "ko": "고마워요", "it": false}, {"s": 3892.781, "e": 3893.973, "en": "Mother!", "ko": "엄마!", "it": false}, {"s": 3894.057, "e": 3895.475, "en": "Daddy told me what you did\nwith the dress,", "ko": "엄마가 드레스를 어떻게 했는지\n아빠한테 들었어요", "it": false}, {"s": 3895.559, "e": 3896.81, "en": "But don't worry.\nI'm not mad at you.", "ko": "그래도 걱정 마세요\n화 안 났어요", "it": false}, {"s": 3896.894, "e": 3898.219, "en": "Well, I had it fixed.", "ko": "그 드레스\n내가 수선시켰는데", "it": false}, {"s": 3898.303, "e": 3899.37, "en": "Daddy said I could wear", "ko": "아빠가 대신\n할머니 드레스를", "it": false}, {"s": 3899.454, "e": 3901.067, "en": "One of grandmother's\ndresses instead.", "ko": "입어도 된대요", "it": false}, {"s": 3912.725, "e": 3915.311, "en": "You brought that down\nfrom the attic?", "ko": "그걸 다락에서\n가지고 내려왔어?", "it": false}, {"s": 3915.395, "e": 3917.831, "en": "This is our daughter's night.", "ko": "오늘은 우리 딸의 밤이야", "it": false}, {"s": 3946.168, "e": 3949.949, "en": "She looks even more beautiful.", "ko": "훨씬 더 아름답구나", "it": false}, {"s": 3950.839, "e": 3951.772, "en": "You look...", "ko": "너...", "it": false}, {"s": 3951.856, "e": 3952.757, "en": "Incredible.", "ko": "정말 근사하다", "it": false}, {"s": 3952.841, "e": 3954.033, "en": "Stunning.", "ko": "눈부셔", "it": false}, {"s": 3954.117, "e": 3955.61, "en": "You're a vision.", "ko": "꿈에서 본 것 같아", "it": false}, {"s": 3955.694, "e": 3958.29, "en": "No one will be able to tear\ntheir eyes from you.", "ko": "아무도 너한테서\n눈을 떼지 못할 거야", "it": false}, {"s": 3960.29, "e": 3962.283, "en": "You're right.", "ko": "당신 말이 맞소", "it": false}, {"s": 3962.367, "e": 3966.465, "en": "Nothing must distract\nfrom my corrine.", "ko": "아무것도\n내 코린을 가려선 안 되오", "it": false}, {"s": 3970.525, "e": 3972.304, "en": "Not tonight.", "ko": "오늘 밤만큼은", "it": false}, {"s": 3982.312, "e": 3984.316, "en": "Take this back\nupstairs.", "ko": "이걸 다시\n위층에 갖다 놔", "it": true}, {"s": 3988.059, "e": 3989.23, "en": "Go on, now.", "ko": "어서", "it": false}, {"s": 4001.498, "e": 4003.474, "en": "You sure you know\nexactly how to do it?", "ko": "어떻게 해야 하는지\n확실히 알지?", "it": false}, {"s": 4003.558, "e": 4005.493, "en": "I think the timing\nwill be important.", "ko": "타이밍이 중요할 것 같아", "it": false}, {"s": 4005.577, "e": 4008.755, "en": "You just calm down and you have\nyourself a good time.", "ko": "넌 마음 편히\n즐기기만 하면 돼", "it": false}, {"s": 4008.839, "e": 4011.09, "en": "I know how to talk\nto your father.", "ko": "아버님한테 어떻게 말할지는\n내가 알아", "it": false}, {"s": 4011.174, "e": 4013.971, "en": "We'll show him how great\nwe are on the dance floor.", "ko": "플로어에서 우리가 얼마나\n멋진지 보여 드리자", "it": false}, {"s": 4031.936, "e": 4033.107, "en": "Thank you.", "ko": "감사합니다", "it": false}, {"s": 4033.421, "e": 4034.592, "en": "Welcome.", "ko": "어서 오세요", "it": false}, {"s": 4093.164, "e": 4095.249, "en": "Mrs. Steiner...", "ko": "스타이너 부인...", "it": false}, {"s": 4095.333, "e": 4099.012, "en": "I thought you and Mr. Foxworth\nhad come to an understanding.", "ko": "남편과 얘기가\n끝난 걸로 알았는데요", "it": false}, {"s": 4099.096, "e": 4104.759, "en": "Lest there be any confusion,\nyou are not welcome here.", "ko": "헷갈리실까 봐 말하는데\n당신은 초대받지 않았어요", "it": false}, {"s": 4104.843, "e": 4108.354, "en": "We did, about your son.", "ko": "얘기 끝났지요,\n아드님 일은", "it": false}, {"s": 4108.438, "e": 4112.416, "en": "But I'm not here about him.\nI'm here about your daughter.", "ko": "근데 그 일로 온 게 아니라\n따님 일로 왔어요", "it": false}, {"s": 4112.5, "e": 4117.755, "en": "Or should I say Mrs. Alicia\nfoxworth's daughter.", "ko": "아니지, 앨리샤 폭스워스 부인\n따님이라고 해야 하나?", "it": false}, {"s": 4125.789, "e": 4128.524, "en": "What a secret to hold.", "ko": "대단한 비밀이네요, 참", "it": false}, {"s": 4128.608, "e": 4132.879, "en": "If this gets out, it'll\nstain your life forever.", "ko": "이게 새어 나가면\n평생 오점으로 남겠지요", "it": false}, {"s": 4132.963, "e": 4138.943, "en": "Everything you've worked so hard\nto build will come to pieces.", "ko": "그렇게 애써 쌓아 온 게\n다 산산조각 날 거고요", "it": false}, {"s": 4139.027, "e": 4140.72, "en": "But something tells me\nyou're more worried about", "ko": "근데 어째 당신은", "it": false}, {"s": 4140.804, "e": 4144.223, "en": "What will happen to her.", "ko": "저 애가 어찌 될지를\n더 걱정하는 것 같네요", "it": false}, {"s": 4144.307, "e": 4148.647, "en": "You don't want her to know\nwho she is, do you?", "ko": "저 애가 자기가 누군지\n알게 되는 건 싫으시죠?", "it": false}, {"s": 4150.48, "e": 4153.066, "en": "Oh, hello again,\nMrs. Steiner.", "ko": "어머, 또 뵙네요,\n스타이너 부인", "it": false}, {"s": 4153.15, "e": 4154.55, "en": "Miss foxworth.", "ko": "폭스워스 아가씨", "it": false}, {"s": 4154.634, "e": 4156.235, "en": "Corrine, where is your father?", "ko": "코린, 아빠는 어디 계시니?", "it": false}, {"s": 4156.319, "e": 4159.313, "en": "I haven't seen him\nsince the guests arrived.", "ko": "손님들 오신 뒤로\n못 봤어요", "it": false}, {"s": 4159.397, "e": 4160.573, "en": "I hope you enjoy yourself.", "ko": "즐거운 시간 보내세요", "it": false}, {"s": 4160.657, "e": 4163.162, "en": "Oh, I intend to.", "ko": "어머, 그럼요", "it": false}, {"s": 4166.997, "e": 4168.917, "en": "Right this way.", "ko": "이쪽으로 오세요", "it": false}, {"s": 4182.012, "e": 4184.338, "en": "Oh, Mr. Foxworth, sir.", "ko": "아, 폭스워스 씨", "it": false}, {"s": 4184.422, "e": 4185.823, "en": "I've been looking for you.", "ko": "찾고 있었습니다", "it": false}, {"s": 4185.907, "e": 4187.658, "en": "Mr. Taylard.", "ko": "테일러드 군", "it": false}, {"s": 4187.742, "e": 4191.679, "en": "I have something very important\nto discuss with you, sir.", "ko": "아주 중요하게 드릴\n말씀이 있습니다", "it": false}, {"s": 4191.763, "e": 4194.777, "en": "I would like to ask for your\ndaughter's hand in marriage.", "ko": "따님과 결혼하도록\n허락해 주십시오", "it": false}, {"s": 4197.009, "e": 4198.336, "en": "Let's discuss this in private,\nshall we?", "ko": "조용한 데서\n얘기해 볼까?", "it": false}, {"s": 4198.42, "e": 4199.782, "en": "Yeah, sure.", "ko": "네, 물론이죠", "it": false}, {"s": 4206.778, "e": 4209.789, "en": "A gesture of settling\nthis amicably.", "ko": "좋게 해결하자는\n뜻이에요", "it": false}, {"s": 4209.873, "e": 4211.958, "en": "I've learned through the years\nthat this is one of", "ko": "오랜 세월 지내 보니", "it": false}, {"s": 4212.042, "e": 4217.112, "en": "The best places for delicate\nconversations like these.", "ko": "이런 민감한 얘기엔\n여기가 제일 좋더군요", "it": false}, {"s": 4217.196, "e": 4220.219, "en": "It's how I even kept some\nconversations from you.", "ko": "당신 몰래 나눈 얘기도\n여기서 했죠", "it": false}, {"s": 4230.969, "e": 4234.63, "en": "How did you hear about\nsuch awful rumors?", "ko": "그런 끔찍한 소문은\n어디서 들었어요?", "it": false}, {"s": 4234.714, "e": 4237.391, "en": "Doctor Curtis keeps\ndetailed records.", "ko": "커티스 박사가 기록을\n아주 꼼꼼히 하거든요", "it": false}, {"s": 4237.475, "e": 4238.985, "en": "You work for doctor Curtis now.", "ko": "이제 커티스 박사 밑에서\n일하는군요", "it": false}, {"s": 4239.069, "e": 4241.379, "en": "His notes go all the way back\nto the night", "ko": "그 양반 기록이\n그날 밤까지 거슬러 올라가요", "it": false}, {"s": 4241.463, "e": 4244.139, "en": "You called him to the house\nto look at a pregnant woman", "ko": "당신이 임신한 여자 좀 봐 달라고\n그 양반을 불렀던 밤", "it": false}, {"s": 4244.223, "e": 4247.142, "en": "Who fell down the stairs\nfor example,", "ko": "계단에서 굴러떨어진\n여자 말이에요", "it": false}, {"s": 4247.226, "e": 4251.164, "en": "Where he recorded the woman's\ndelusional rantings", "ko": "자기가 갇혀 있다고\n헛소리하던 것까지", "it": false}, {"s": 4251.248, "e": 4253.224, "en": "For being kept prisoner.", "ko": "다 적어 놨더라고요", "it": false}, {"s": 4253.308, "e": 4255.668, "en": "Doctor Curtis doesn't suspect\nanything, does he?", "ko": "커티스 박사는\n아무것도 눈치 못 챘죠?", "it": false}, {"s": 4255.752, "e": 4256.985, "en": "Oh, don't worry.", "ko": "아이고, 걱정 마요", "it": false}, {"s": 4257.921, "e": 4260.564, "en": "He's a bit thick.", "ko": "좀 둔한 양반이라", "it": false}, {"s": 4260.648, "e": 4264.326, "en": "But the real tip of the scale,\nMrs. Foxworth.", "ko": "근데 결정적인 건요,\n폭스워스 부인", "it": false}, {"s": 4264.41, "e": 4269.924, "en": "I mean, look at your daughter\nthen look at you.", "ko": "따님 보고\n당신 얼굴 좀 보세요", "it": false}, {"s": 4270.008, "e": 4274.565, "en": "She's gorgeous\nand you're a monster.", "ko": "따님은 저리 고운데\n당신은 괴물이잖아요", "it": false}, {"s": 4279.834, "e": 4281.194, "en": "Three thousand then.", "ko": "그럼 3천 달러", "it": false}, {"s": 4281.278, "e": 4282.781, "en": "Five.", "ko": "5천", "it": false}, {"s": 4285.84, "e": 4287.453, "en": "I'll get your money.", "ko": "돈은 마련할게요", "it": false}, {"s": 4314.202, "e": 4314.952, "en": "Mother...", "ko": "엄마...", "it": false}, {"s": 4315.036, "e": 4316.454, "en": "Corrine darling, not now.", "ko": "코린, 지금은 안 돼", "it": false}, {"s": 4316.538, "e": 4317.563, "en": "I have something very important\nI need to discuss", "ko": "아빠랑 아주 중요하게", "it": false}, {"s": 4317.647, "e": 4318.714, "en": "With your father.", "ko": "할 얘기가 있어", "it": false}, {"s": 4318.798, "e": 4319.881, "en": "But I can't find\nrockford anywhere", "ko": "그런데 록퍼드가\n어디에도 안 보여요", "it": false}, {"s": 4319.965, "e": 4321.883, "en": "And the first dance\nis about to begin.", "ko": "곧 첫 춤이 시작될 텐데", "it": false}, {"s": 4321.967, "e": 4325.824, "en": "Christopher. Thank goodness.\nWould you be so kind?", "ko": "크리스토퍼, 다행이다\n부탁 좀 들어줄래?", "it": false}, {"s": 4328.491, "e": 4330.662, "en": "It would be my honor.", "ko": "영광이에요", "it": false}, {"s": 4340.411, "e": 4342.146, "en": "- We have a problem.\n- Not now.", "ko": "-문제가 생겼어\n-지금은 안 되오", "it": false}, {"s": 4342.23, "e": 4344.51, "en": "Not during corrine's\nfirst dance.", "ko": "코린 첫 춤\n추는 동안엔 안 되오", "it": false}, {"s": 4377.523, "e": 4379.441, "en": "I believe congratulations\nare in order.", "ko": "축하할 일이\n생겼다며?", "it": false}, {"s": 4379.525, "e": 4381.443, "en": "You heard.", "ko": "들었어요?", "it": false}, {"s": 4381.527, "e": 4384.63, "en": "He's a lucky man,\nwherever he is.", "ko": "그 녀석 운도 좋지,\n어디 있는진 몰라도", "it": false}, {"s": 4384.714, "e": 4386.19, "en": "Don't do that.", "ko": "그러지 마요", "it": false}, {"s": 4386.274, "e": 4388.025, "en": "You're not allowed\nto be jealous.", "ko": "삼촌은 질투하면\n안 되잖아요", "it": false}, {"s": 4392.222, "e": 4393.197, "en": "He stood you up.", "ko": "널 바람맞혔구나", "it": false}, {"s": 4393.281, "e": 4394.715, "en": "Not after what we agreed.", "ko": "우리가 약속한 뒤로는\n안 되잖아요", "it": false}, {"s": 4394.799, "e": 4397.051, "en": "You're my uncle, remember?", "ko": "삼촌은 내 삼촌이잖아요,\n기억 안 나요?", "it": false}, {"s": 4402.548, "e": 4404.558, "en": "And as your uncle\nI wouldn't want you", "ko": "그래, 삼촌으로서", "it": false}, {"s": 4404.642, "e": 4407.302, "en": "To rush into something that\nyou'll almost certainly regret.", "ko": "네가 분명 후회할 일에\n서둘러 뛰어들지 않았으면 해", "it": false}, {"s": 4407.386, "e": 4411.215, "en": "I'm more than capable\nof making my own choices.", "ko": "내 일은 내가\n충분히 알아서 정할 수 있어요", "it": false}, {"s": 4411.299, "e": 4413.067, "en": "I thought much the same\nof myself until...", "ko": "나도 그렇게 생각했지\n그러다...", "it": false}, {"s": 4419.641, "e": 4422.335, "en": "Until I realized otherwise.", "ko": "아니라는 걸 깨달았어", "it": false}, {"s": 4422.419, "e": 4425.654, "en": "There is no worse pain than\nbeing stuck in a life of regret.", "ko": "후회 속에 갇혀 사는 것만큼\n큰 고통은 없어", "it": false}, {"s": 4425.738, "e": 4426.655, "en": "The gentleman he sounds\nas though", "ko": "이 신사분 말을 들어 보니", "it": false}, {"s": 4426.739, "e": 4429.675, "en": "He speaks from experience.", "ko": "겪어 본 사람 같네요", "it": false}, {"s": 4429.759, "e": 4431.902, "en": "Do you have any regrets?", "ko": "후회하는 거 있어요?", "it": false}, {"s": 4435.339, "e": 4436.893, "en": "With you?", "ko": "나랑?", "it": false}, {"s": 4440.678, "e": 4441.762, "en": "Yes.", "ko": "그래", "it": false}, {"s": 4460.014, "e": 4462.858, "en": "I have never been so proud\nof you in all my life,", "ko": "살면서 네가 이렇게\n자랑스러운 적이 없었다", "it": false}, {"s": 4462.942, "e": 4466.712, "en": "And you look so\nravishing tonight.", "ko": "그리고 오늘 밤\n넋이 나갈 만큼 아름답구나", "it": false}, {"s": 4466.796, "e": 4468.789, "en": "- Daddy...\n- Hmm.", "ko": "-아빠...\n-응", "it": false}, {"s": 4468.873, "e": 4470.883, "en": "Has rockford spoken\nto you tonight?", "ko": "오늘 밤 록퍼드가\n아빠한테 얘기했어요?", "it": false}, {"s": 4470.967, "e": 4477.297, "en": "He made his intentions clear\nand I made mine clearer.", "ko": "그 녀석은 자기 뜻을 밝혔고\n나는 내 뜻을 더 분명히 밝혔지", "it": false}, {"s": 4477.381, "e": 4479.133, "en": "Did you hurt him?", "ko": "그 사람을 다치게 했어요?", "it": false}, {"s": 4479.217, "e": 4481.543, "en": "Daddy, what did you do?", "ko": "아빠, 무슨 짓을 한 거예요?", "it": false}, {"s": 4481.627, "e": 4484.455, "en": "He won't bother you again.", "ko": "다시는 널 귀찮게\n하지 않을 거다", "it": false}, {"s": 4484.539, "e": 4488.234, "en": "He abandoned you tonight,\ncorrine", "ko": "그 녀석은 오늘 밤\n널 버렸어, 코린", "it": false}, {"s": 4488.318, "e": 4492.98, "en": "And I will never\nabandon you.", "ko": "하지만 난 절대\n널 버리지 않아", "it": false}, {"s": 4493.064, "e": 4497.317, "en": "Because you...\nBelong to me.", "ko": "넌...\n내 것이니까", "it": false}, {"s": 4516.087, "e": 4517.821, "en": "Corrine, you were incredible", "ko": "코린, 정말 멋졌어", "it": false}, {"s": 4517.905, "e": 4519.765, "en": "But I really must speak\nwith your father.", "ko": "그런데 엄마가 아빠랑\n꼭 할 얘기가 있어서", "it": false}, {"s": 4519.849, "e": 4522.101, "en": "Rockford asked daddy\nfor permission to marry me", "ko": "록퍼드가 아빠한테\n나랑 결혼하게 해 달라고 했대요", "it": false}, {"s": 4522.185, "e": 4525.162, "en": "And he scared him away or,\nor hurt him, or...", "ko": "그런데 아빠가 겁을 줘서\n쫓아냈거나, 다치게 했거나...", "it": false}, {"s": 4525.246, "e": 4527.164, "en": "Please mother,\nyou have to talk to him.", "ko": "제발요, 엄마\n아빠한테 말 좀 해 줘요", "it": false}, {"s": 4527.248, "e": 4528.419, "en": "Uh...", "ko": "어...", "it": false}, {"s": 4531.343, "e": 4532.686, "en": "Do you love him?", "ko": "그 애를 사랑하니?", "it": false}, {"s": 4532.77, "e": 4533.941, "en": "Rockford?", "ko": "록퍼드를?", "it": false}, {"s": 4535.256, "e": 4536.493, "en": "Yes.", "ko": "네", "it": false}, {"s": 4537.367, "e": 4538.784, "en": "You don't really.", "ko": "사랑하지 않아", "it": false}, {"s": 4538.868, "e": 4541.287, "en": "You think you do,\nyou really think you do,", "ko": "사랑한다고 생각하겠지,\n정말 그렇다고 믿겠지만", "it": false}, {"s": 4541.371, "e": 4543.104, "en": "But you don't.", "ko": "아니야", "it": false}, {"s": 4543.188, "e": 4546.959, "en": "He's just a door to a life\nyou think you want.", "ko": "그 애는 네가 원한다고 생각하는\n삶으로 가는 문일 뿐이야", "it": false}, {"s": 4547.043, "e": 4552.614, "en": "But trust me, behind it\nis no life at all.", "ko": "하지만 엄마 말 믿어\n그 문 뒤엔 아무 삶도 없어", "it": false}, {"s": 4552.698, "e": 4554.208, "en": "How can you be sure?", "ko": "엄마가 어떻게 알아요?", "it": false}, {"s": 4554.292, "e": 4557.711, "en": "I can see it in your eyes.\nYou're not in love with him.", "ko": "네 눈을 보면 보여\n넌 그 애를 사랑하지 않아", "it": false}, {"s": 4557.795, "e": 4559.213, "en": "But when you really know,", "ko": "하지만 네가 정말 확신할 때", "it": false}, {"s": 4559.297, "e": 4561.456, "en": "When you find someone\nyou really love,", "ko": "정말 사랑하는\n사람을 찾았을 때", "it": false}, {"s": 4561.54, "e": 4564.977, "en": "I will support you\nno matter what.", "ko": "그땐 엄마가 무슨 일이 있어도\n네 편이 되어 줄게", "it": false}, {"s": 4565.061, "e": 4567.232, "en": "This was supposed\nto be my night.", "ko": "오늘은 내 밤이어야\n했는데", "it": false}, {"s": 4571.067, "e": 4572.238, "en": "Excuse me.", "ko": "실례할게요", "it": false}, {"s": 4575.905, "e": 4577.305, "en": "Mrs. Steiner is here.", "ko": "스타이너 부인이 왔어", "it": false}, {"s": 4577.389, "e": 4579.808, "en": "I've locked her\nin the library.", "ko": "서재에\n가둬 놨어", "it": false}, {"s": 4579.892, "e": 4581.235, "en": "Why would you do that?", "ko": "왜 그런 짓을 했소?", "it": false}, {"s": 4581.319, "e": 4583.996, "en": "Because she knows\nabout corrine.", "ko": "그 여자가 코린 일을\n알고 있으니까", "it": false}, {"s": 4584.08, "e": 4585.584, "en": "Knows about what?", "ko": "뭘 안다는 거요?", "it": false}, {"s": 4600.004, "e": 4601.496, "en": "You're an animal.", "ko": "짐승 같은 사람", "it": false}, {"s": 4601.58, "e": 4603.331, "en": "I apologize for resorting\nto these methods", "ko": "이런 방법까지 써서\n미안해요", "it": false}, {"s": 4603.415, "e": 4604.683, "en": "But you left me no choice.", "ko": "하지만 당신이\n선택의 여지를 안 줬잖아요", "it": false}, {"s": 4604.767, "e": 4605.926, "en": "A wild animal.", "ko": "사나운 짐승 같으니", "it": false}, {"s": 4606.01, "e": 4607.52, "en": "I had to find my husband.", "ko": "남편을 찾아야 했어요", "it": false}, {"s": 4607.604, "e": 4609.913, "en": "He's on his way now with\nyour money, I can assure you.", "ko": "남편이 지금 돈을 가지고\n오고 있어요, 장담해요", "it": false}, {"s": 4609.997, "e": 4611.857, "en": "Exactly how do you expect me\nto trust you", "ko": "벽장에다 한 시간이나\n가둬 놓고서", "it": false}, {"s": 4611.941, "e": 4615.194, "en": "After you kept me locked\nin that closet for an hour?", "ko": "날더러 믿으라고요?", "it": false}, {"s": 4615.278, "e": 4617.679, "en": "And what's to stop me\nfrom going out there right now", "ko": "지금 당장 나가서", "it": false}, {"s": 4617.763, "e": 4619.681, "en": "To make a little toast\nof my own?", "ko": "건배사라도 한마디 하면\n어쩌려고요?", "it": false}, {"s": 4619.765, "e": 4621.85, "en": "Just know, Mrs. Steiner,", "ko": "이것만 알아 둬요,\n스타이너 부인", "it": false}, {"s": 4621.934, "e": 4624.703, "en": "What you seek to destroy,\nit's all I have.", "ko": "당신이 무너뜨리려는 그거,\n그게 내가 가진 전부예요", "it": false}, {"s": 4624.787, "e": 4626.539, "en": "A life built on lies.", "ko": "거짓말로 쌓아 올린\n인생이지요", "it": false}, {"s": 4626.623, "e": 4628.207, "en": "Maybe.", "ko": "그럴지도 모르죠", "it": false}, {"s": 4628.291, "e": 4630.209, "en": "But it's all I could manage\ngiven the circumstances.", "ko": "하지만 그런 상황에서\n내가 할 수 있는 건 그게 다였어요", "it": false}, {"s": 4630.293, "e": 4632.936, "en": "Everything I've done,\nevery choice I've made,", "ko": "내가 한 모든 일,\n내가 내린 모든 선택은", "it": false}, {"s": 4633.02, "e": 4637.775, "en": "Good, bad, or somewhere\nin between.", "ko": "좋든 나쁘든,\n그 중간이든", "it": false}, {"s": 4637.859, "e": 4639.2, "en": "It's all been\nfor my children.", "ko": "전부 내 아이들을\n위한 거였어요", "it": false}, {"s": 4639.284, "e": 4641.87, "en": "Corrine is not your child.", "ko": "코린은 당신 자식도\n아니잖아요", "it": false}, {"s": 4641.954, "e": 4644.723, "en": "She may not be of my flesh\nbut she is of my heart.", "ko": "내 배로 낳진 않았어도\n내 마음으로 낳은 아이예요", "it": false}, {"s": 4648.311, "e": 4650.637, "en": "Who do you think\nyou're fooling.", "ko": "누굴 속이려고 그래요?", "it": false}, {"s": 4650.721, "e": 4652.547, "en": "People talk.", "ko": "사람들 입이 있는데", "it": false}, {"s": 4652.631, "e": 4654.382, "en": "Everyone knows that deep down", "ko": "다들 알아요", "it": false}, {"s": 4654.466, "e": 4660.297, "en": "You're jealous of corrine\nfor her beauty, for her charm.", "ko": "당신이 속으로는 코린 얼굴이랑\n매력을 샘낸다는 거", "it": false}, {"s": 4660.381, "e": 4666.061, "en": "For the fact that she'll have\na love in her life unlike you.", "ko": "당신하곤 달리 그 애는\n평생 사랑받고 살 테니까", "it": false}, {"s": 4666.145, "e": 4669.248, "en": "What do you know about love?", "ko": "당신이 사랑에 대해\n뭘 알아요?", "it": false}, {"s": 4669.332, "e": 4672.918, "en": "Do you think garland\never loved you in return?", "ko": "갈랜드가 당신을\n사랑했다고 생각해요?", "it": false}, {"s": 4673.002, "e": 4676.997, "en": "Oh, my apologies, you knew him\nas Mr. Foxworth", "ko": "아, 미안해요, 당신한텐\n폭스워스 주인어른이었죠", "it": false}, {"s": 4677.081, "e": 4680.926, "en": "And he knew you as the woman\nwho cleaned his chamber pot.", "ko": "그분한테 당신은 요강이나\n비우는 여자였고요", "it": false}, {"s": 4681.01, "e": 4682.486, "en": "How dare you?", "ko": "어디서 감히!", "it": false}, {"s": 4682.57, "e": 4685.489, "en": "This is my house.\nI'll dare to do as I please.", "ko": "여긴 내 집이에요\n감히 내 마음대로 할 거예요", "it": false}, {"s": 4685.573, "e": 4688.767, "en": "I think I'll go find\nMr. Foxworth on my own.", "ko": "폭스워스 씨는\n내가 직접 찾아봐야겠네요", "it": false}, {"s": 4688.851, "e": 4690.022, "en": "Stop!", "ko": "멈춰요!", "it": false}, {"s": 4701.847, "e": 4704.858, "en": "She was going\nto tell everyone.", "ko": "다 말해 버리려고 했어", "it": false}, {"s": 4704.942, "e": 4706.705, "en": "We have to call a doctor.", "ko": "의사를 불러야 해", "it": false}, {"s": 4710.765, "e": 4711.936, "en": "Shh.", "ko": "쉿", "it": false}, {"s": 4776.998, "e": 4779.11, "en": "Our guests are waiting.", "ko": "손님들이 기다리고 있소", "it": false}, {"s": 4781.502, "e": 4783.114, "en": "Shall we?", "ko": "자, 함께 가시겠소, 부인?", "it": false}, {"s": 4893.797, "e": 4895.226, "en": "- Oh.\n- Sorry.", "ko": "-아\n-미안해요", "it": false}, {"s": 4896.45, "e": 4899.46, "en": "What are you doing?", "ko": "뭐 하는 거야?", "it": false}, {"s": 4899.544, "e": 4903.131, "en": "Never mind. It's none\nof my business.", "ko": "아니다, 내가\n상관할 일 아니지", "it": false}, {"s": 4903.215, "e": 4905.984, "en": "Enjoy the rest\nof your evening.", "ko": "남은 밤 즐겁게 보내", "it": false}, {"s": 4906.068, "e": 4907.906, "en": "The engagement's off.", "ko": "약혼은 깨졌어요", "it": false}, {"s": 4911.966, "e": 4914.401, "en": "I'm not really sure it was\never really on, but...", "ko": "애초에 약혼이긴 했는지도\n모르겠지만요", "it": false}, {"s": 4914.485, "e": 4915.914, "en": "I'm sorry.", "ko": "유감이야", "it": false}, {"s": 4916.746, "e": 4918.374, "en": "Are you?", "ko": "그래요?", "it": false}, {"s": 4921.492, "e": 4923.56, "en": "Not at all.", "ko": "전혀", "it": false}, {"s": 4923.644, "e": 4927.506, "en": "I have tried so hard\nto make it work.", "ko": "정말 애썼어요\n잘해 보려고", "it": false}, {"s": 4927.59, "e": 4929.761, "en": "To move on,\nto forget about-", "ko": "잊고 앞으로 나아가려고...", "it": false}, {"s": 4932.002, "e": 4933.253, "en": "But fighting what I feel inside", "ko": "그런데 마음속 감정과\n싸우는 게", "it": false}, {"s": 4933.337, "e": 4935.558, "en": "Has become more difficult\nthan facing it.", "ko": "마주하는 것보다\n더 힘들어졌어요", "it": false}, {"s": 4940.494, "e": 4941.353, "en": "You.", "ko": "삼촌이요", "it": false}, {"s": 4941.437, "e": 4943.096, "en": "Stop.", "ko": "그만해", "it": false}, {"s": 4943.18, "e": 4944.581, "en": "You're what I feel inside.", "ko": "내 마음속에 있는 건\n삼촌이에요", "it": false}, {"s": 4944.665, "e": 4945.749, "en": "Please.", "ko": "제발", "it": false}, {"s": 4945.833, "e": 4947.175, "en": "You're what I want.", "ko": "내가 원하는 건 삼촌이에요", "it": false}, {"s": 4947.259, "e": 4948.026, "en": "Don't.", "ko": "그러지 마", "it": false}, {"s": 4948.11, "e": 4949.781, "en": "You're who I love.", "ko": "내가 사랑하는 사람은\n삼촌이에요", "it": false}, {"s": 4950.947, "e": 4952.617, "en": "Do you love me?", "ko": "나 사랑해요?", "it": false}, {"s": 4961.94, "e": 4963.795, "en": "Of course I love you.", "ko": "당연히 사랑하지", "it": false}, {"s": 4968.447, "e": 4970.635, "en": "So, what do we do now?", "ko": "그럼 우리 이제 어떡해요?", "it": false}, {"s": 4992.046, "e": 4994.659, "en": "Keeping up an illusion\nis hard work.", "ko": "환상을 유지하는 건\n고된 일이다", "it": true}, {"s": 5002.147, "e": 5003.793, "en": "Back-breaking work.", "ko": "허리가 부러질 듯한 일", "it": true}, {"s": 5012.991, "e": 5015.013, "en": "Heartbreaking work.", "ko": "가슴이 찢어지는 일", "it": true}, {"s": 5018.405, "e": 5020.185, "en": "Teamwork.", "ko": "함께 해야 하는 일", "it": true}, {"s": 5024.762, "e": 5027.358, "en": "At breakfast you want\nto kill your husband.", "ko": "아침 식탁에선\n남편을 죽이고 싶다가도", "it": true}, {"s": 5033.103, "e": 5036.868, "en": "By bedtime you're helping\nhim Bury someone else's body.", "ko": "잠들 무렵엔 남편이\n다른 사람의 시체를 묻는 걸 돕는다", "it": true}, {"s": 5053.457, "e": 5056.012, "en": "But something keeps you\ngoing through it.", "ko": "그래도 무언가가\n나를 버티게 했다", "it": true}, {"s": 5076.721, "e": 5078.743, "en": "Get some rest.", "ko": "가서 쉬시오", "it": false}, {"s": 5095.574, "e": 5099.586, "en": "The thought that all of\nthe blood and dirt and lies", "ko": "그 모든 피와 흙과\n거짓말이", "it": true}, {"s": 5099.67, "e": 5101.599, "en": "Would be worth it.", "ko": "그럴 만한 가치가\n있으리라는 생각", "it": true}, {"s": 5107.845, "e": 5111.109, "en": "But in the end,\nbecause of everything I did...", "ko": "결국 내가 한\n모든 일 덕분에...", "it": true}, {"s": 5114.168, "e": 5116.614, "en": "Their lives will be better\nthan mine.", "ko": "그 애들의 삶은\n나보다 나으리라는 생각", "it": true}, {"s": 5123.786, "e": 5125.623, "en": "My children.", "ko": "내 아이들", "it": true}, {"s": 5139.969, "e": 5143.371, "en": "Joel got out of\nfoxworth hall alive.", "ko": "조엘은 살아서\n폭스워스 저택을 떠났다", "it": true}, {"s": 5143.455, "e": 5145.977, "en": "Surely corrine could too.", "ko": "코린도 분명\n그럴 수 있으리라", "it": true}, {"s": 5161.398, "e": 5165.121, "en": "But I was learning the hard way\nthat my home had too many doors.", "ko": "하지만 나는 뼈저리게 배우고 있었다\n내 집엔 문이 너무 많다는 것을", "it": true}, {"s": 5171.316, "e": 5174.13, "en": "Old ones. New ones.", "ko": "오래된 문, 새로운 문", "it": true}, {"s": 5181.993, "e": 5184.807, "en": "Behind each a place to hide.", "ko": "그 뒤엔 저마다\n숨을 곳이 있었다", "it": true}, {"s": 5192.413, "e": 5196.274, "en": "That night, each and every one\nof foxworth hall's doors", "ko": "그날 밤, 폭스워스 저택의\n문이란 문은", "it": true}, {"s": 5196.358, "e": 5198.196, "en": "Would fly open.", "ko": "전부 활짝 열렸다", "it": true}, {"s": 5200.787, "e": 5203.573, "en": "And there would be\nno hiding anymore.", "ko": "그리고 더는\n숨을 곳이 없었다", "it": true}]};